window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["宪法相关法"] = {"zhuanshujingjiquhedalujiafa":[{"i":1,"n":"第一条","txt":"为保障中华人民共和国对专属经济区和大陆架行使主权权利和管辖权，维护国家海洋权益，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国的专属经济区，为中华人民共和国领海以外并邻接领海的区域，从测算领海宽度的基线量起延至二百海里。"},{"i":3,"n":"第三条","txt":"中华人民共和国在专属经济区为勘查、开发、养护和管理海床上覆水域、海床及其底土的自然资源，以及进行其他经济性开发和勘查，如利用海水、海流和风力生产能等活动，行使主权权利。"},{"i":4,"n":"第四条","txt":"中华人民共和国为勘查大陆架和开发大陆架的自然资源，对大陆架行使主权权利。"},{"i":5,"n":"第五条","txt":"任何国际组织、外国的组织或者个人进入中华人民共和国的专属经济区从事渔业活动，必须经中华人民共和国主管机关批准，并遵守中华人民共和国的法律、法规及中华人民共和国与有关国家签订的条约、协定。"},{"i":6,"n":"第六条","txt":"中华人民共和国主管机关有权对专属经济区的跨界种群、高度洄游鱼种、海洋哺乳动物、源自中华人民共和国河流的溯河产卵种群、在中华人民共和国水域内度过大部分生命周期的降河产卵鱼种，进行养护和管理。"},{"i":7,"n":"第七条","txt":"任何国际组织、外国的组织或者个人对中华人民共和国的专属经济区和大陆架的自然资源进行勘查、开发活动或者在中华人民共和国的大陆架上为任何目的进行钻探，必须经中华人民共和国主管机关批准，并遵守中华人民共和国的法律、法规。"},{"i":8,"n":"第八条","txt":"中华人民共和国在专属经济区和大陆架有专属权利建造并授权和管理建造、操作和使用人工岛屿、设施和结构。"},{"i":9,"n":"第九条","txt":"任何国际组织、外国的组织或者个人在中华人民共和国的专属经济区和大陆架进行海洋科学研究，必须经中华人民共和国主管机关批准，并遵守中华人民共和国的法律、法规。"},{"i":10,"n":"第十条","txt":"中华人民共和国主管机关有权采取必要的措施，防止、减少和控制海洋环境的污染，保护和保全专属经济区和大陆架的海洋环境。"},{"i":11,"n":"第十一条","txt":"任何国家在遵守国际法和中华人民共和国的法律、法规的前提下，在中华人民共和国的专属经济区享有航行、飞越的自由，在中华人民共和国的专属经济区和大陆架享有铺设海底电缆和管道的自由，以及与上述自由有关的其他合法使用海洋的便利。铺设海底电缆和管道的路线，必须经中华人民共和国主管机关同意。"},{"i":12,"n":"第十二条","txt":"中华人民共和国在行使勘查、开发、养护和管理专属经济区的生物资源的主权权利时，为确保中华人民共和国的法律、法规得到遵守，可以采取登临、检查、逮捕、扣留和进行司法程序等必要的措施。"},{"i":13,"n":"第十三条","txt":"中华人民共和国在专属经济区和大陆架享有的权利，本法未作规定的，根据国际法和中华人民共和国其他有关法律、法规行使。"},{"i":14,"n":"第十四条","txt":"本法的规定不影响中华人民共和国享有的历史性权利。"},{"i":15,"n":"第十五条","txt":"中华人民共和国政府可以根据本法制定有关规定。"},{"i":16,"n":"第十六条","txt":"本法自公布之日起施行。"}],"renminjianchayuanzuzhifa":[{"i":1,"n":"第一条","txt":"为了规范人民检察院的设置、组织和职权，保障人民检察院依法履行职责，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"人民检察院是国家的法律监督机关。"},{"i":3,"n":"第三条","txt":"人民检察院依照宪法、法律和全国人民代表大会常务委员会的决定设置。"},{"i":4,"n":"第四条","txt":"人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。"},{"i":5,"n":"第五条","txt":"人民检察院行使检察权在适用法律上一律平等，不允许任何组织和个人有超越法律的特权，禁止任何形式的歧视。"},{"i":6,"n":"第六条","txt":"人民检察院坚持司法公正，以事实为根据，以法律为准绳，遵守法定程序，尊重和保障人权。"},{"i":7,"n":"第七条","txt":"人民检察院实行司法公开，法律另有规定的除外。"},{"i":8,"n":"第八条","txt":"人民检察院实行司法责任制，建立健全权责统一的司法权力运行机制。"},{"i":9,"n":"第九条","txt":"最高人民检察院对全国人民代表大会及其常务委员会负责并报告工作。地方各级人民检察院对本级人民代表大会及其常务委员会负责并报告工作。"},{"i":10,"n":"第十条","txt":"最高人民检察院是最高检察机关。"},{"i":11,"n":"第十一条","txt":"人民检察院应当接受人民群众监督，保障人民群众对人民检察院工作依法享有知情权、参与权和监督权。"},{"i":12,"n":"第十二条","txt":"人民检察院分为："},{"i":13,"n":"第十三条","txt":"地方各级人民检察院分为："},{"i":14,"n":"第十四条","txt":"在新疆生产建设兵团设立的人民检察院的组织、案件管辖范围和检察官任免，依照全国人民代表大会常务委员会的有关规定。"},{"i":15,"n":"第十五条","txt":"专门人民检察院的设置、组织、职权和检察官任免，由全国人民代表大会常务委员会规定。"},{"i":16,"n":"第十六条","txt":"省级人民检察院和设区的市级人民检察院根据检察工作需要，经最高人民检察院和省级有关部门同意，并提请本级人民代表大会常务委员会批准，可以在辖区内特定区域设立人民检察院，作为派出机构。"},{"i":17,"n":"第十七条","txt":"人民检察院根据检察工作需要，可以在监狱、看守所等场所设立检察室，行使派出它的人民检察院的部分职权，也可以对上述场所进行巡回检察。"},{"i":18,"n":"第十八条","txt":"人民检察院根据检察工作需要，设必要的业务机构。检察官员额较少的设区的市级人民检察院和基层人民检察院，可以设综合业务机构。"},{"i":19,"n":"第十九条","txt":"人民检察院根据工作需要，可以设必要的检察辅助机构和行政管理机构。"},{"i":20,"n":"第二十条","txt":"人民检察院行使下列职权："},{"i":21,"n":"第二十一条","txt":"人民检察院行使本法第二十条规定的法律监督职权，可以进行调查核实，并依法提出抗诉、纠正意见、检察建议。有关单位应当予以配合，并及时将采纳纠正意见、检察建议的情况书面回复人民检察院。"},{"i":22,"n":"第二十二条","txt":"最高人民检察院对最高人民法院的死刑复核活动实行监督；对报请核准追诉的案件进行审查，决定是否追诉。"},{"i":23,"n":"第二十三条","txt":"最高人民检察院可以对属于检察工作中具体应用法律的问题进行解释。"},{"i":24,"n":"第二十四条","txt":"上级人民检察院对下级人民检察院行使下列职权："},{"i":25,"n":"第二十五条","txt":"下级人民检察院应当执行上级人民检察院的决定；有不同意见的，可以在执行的同时向上级人民检察院报告。"},{"i":26,"n":"第二十六条","txt":"人民检察院检察长或者检察长委托的副检察长，可以列席同级人民法院审判委员会会议。"},{"i":27,"n":"第二十七条","txt":"人民监督员依照规定对人民检察院的办案活动实行监督。"},{"i":28,"n":"第二十八条","txt":"人民检察院办理案件，根据案件情况可以由一名检察官独任办理，也可以由两名以上检察官组成办案组办理。"},{"i":29,"n":"第二十九条","txt":"检察官在检察长领导下开展工作，重大办案事项由检察长决定。检察长可以将部分职权委托检察官行使，可以授权检察官签发法律文书。"},{"i":30,"n":"第三十条","txt":"各级人民检察院设检察委员会。检察委员会由检察长、副检察长和若干资深检察官组成，成员应当为单数。"},{"i":31,"n":"第三十一条","txt":"检察委员会履行下列职能："},{"i":32,"n":"第三十二条","txt":"检察委员会召开会议，应当有其组成人员的过半数出席。"},{"i":33,"n":"第三十三条","txt":"检察官可以就重大案件和其他重大问题，提请检察长决定。检察长可以根据案件情况，提交检察委员会讨论决定。"},{"i":34,"n":"第三十四条","txt":"人民检察院实行检察官办案责任制。检察官对其职权范围内就案件作出的决定负责。检察长、检察委员会对案件作出决定的，承担相应责任。"},{"i":35,"n":"第三十五条","txt":"人民检察院的检察人员由检察长、副检察长、检察委员会委员和检察员等人员组成。"},{"i":36,"n":"第三十六条","txt":"人民检察院检察长领导本院检察工作，管理本院行政事务。人民检察院副检察长协助检察长工作。"},{"i":37,"n":"第三十七条","txt":"最高人民检察院检察长由全国人民代表大会选举和罢免，副检察长、检察委员会委员和检察员由检察长提请全国人民代表大会常务委员会任免。"},{"i":38,"n":"第三十八条","txt":"地方各级人民检察院检察长由本级人民代表大会选举和罢免，副检察长、检察委员会委员和检察员由检察长提请本级人民代表大会常务委员会任免。"},{"i":39,"n":"第三十九条","txt":"人民检察院检察长任期与产生它的人民代表大会每届任期相同。"},{"i":40,"n":"第四十条","txt":"人民检察院的检察官、检察辅助人员和司法行政人员实行分类管理。"},{"i":41,"n":"第四十一条","txt":"检察官实行员额制。检察官员额根据案件数量、经济社会发展情况、人口数量和人民检察院层级等因素确定。"},{"i":42,"n":"第四十二条","txt":"检察官从取得法律职业资格并且具备法律规定的其他条件的人员中选任。初任检察官应当由检察官遴选委员会进行专业能力审核。上级人民检察院的检察官一般从下级人民检察院的检察官中择优遴选。"},{"i":43,"n":"第四十三条","txt":"人民检察院的检察官助理在检察官指导下负责审查案件材料、草拟法律文书等检察辅助事务。"},{"i":44,"n":"第四十四条","txt":"人民检察院的书记员负责案件记录等检察辅助事务。"},{"i":45,"n":"第四十五条","txt":"人民检察院的司法警察负责办案场所警戒、人员押解和看管等警务事项。"},{"i":46,"n":"第四十六条","txt":"人民检察院根据检察工作需要，可以设检察技术人员，负责与检察工作有关的事项。"},{"i":47,"n":"第四十七条","txt":"任何单位或者个人不得要求检察官从事超出法定职责范围的事务。"},{"i":48,"n":"第四十八条","txt":"人民检察院采取必要措施，维护办案安全。对妨碍人民检察院依法行使职权的违法犯罪行为，依法追究法律责任。"},{"i":49,"n":"第四十九条","txt":"人民检察院实行培训制度，检察官、检察辅助人员和司法行政人员应当接受理论和业务培训。"},{"i":50,"n":"第五十条","txt":"人民检察院人员编制实行专项管理。"},{"i":51,"n":"第五十一条","txt":"人民检察院的经费按照事权划分的原则列入财政预算，保障检察工作需要。"},{"i":52,"n":"第五十二条","txt":"人民检察院应当加强信息化建设，运用现代信息技术，促进司法公开，提高工作效率。"},{"i":53,"n":"第五十三条","txt":"本法自2019年1月1日起施行。"}],"renminfayuanzuzhifa":[{"i":1,"n":"第一条","txt":"为了规范人民法院的设置、组织和职权，保障人民法院依法履行职责，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"人民法院是国家的审判机关。"},{"i":3,"n":"第三条","txt":"人民法院依照宪法、法律和全国人民代表大会常务委员会的决定设置。"},{"i":4,"n":"第四条","txt":"人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。"},{"i":5,"n":"第五条","txt":"人民法院审判案件在适用法律上一律平等，不允许任何组织和个人有超越法律的特权，禁止任何形式的歧视。"},{"i":6,"n":"第六条","txt":"人民法院坚持司法公正，以事实为根据，以法律为准绳，遵守法定程序，依法保护个人和组织的诉讼权利和其他合法权益，尊重和保障人权。"},{"i":7,"n":"第七条","txt":"人民法院实行司法公开，法律另有规定的除外。"},{"i":8,"n":"第八条","txt":"人民法院实行司法责任制，建立健全权责统一的司法权力运行机制。"},{"i":9,"n":"第九条","txt":"最高人民法院对全国人民代表大会及其常务委员会负责并报告工作。地方各级人民法院对本级人民代表大会及其常务委员会负责并报告工作。"},{"i":10,"n":"第十条","txt":"最高人民法院是最高审判机关。"},{"i":11,"n":"第十一条","txt":"人民法院应当接受人民群众监督，保障人民群众对人民法院工作依法享有知情权、参与权和监督权。"},{"i":12,"n":"第十二条","txt":"人民法院分为："},{"i":13,"n":"第十三条","txt":"地方各级人民法院分为高级人民法院、中级人民法院和基层人民法院。"},{"i":14,"n":"第十四条","txt":"在新疆生产建设兵团设立的人民法院的组织、案件管辖范围和法官任免，依照全国人民代表大会常务委员会的有关规定。"},{"i":15,"n":"第十五条","txt":"专门人民法院包括军事法院和海事法院、知识产权法院、金融法院等。"},{"i":16,"n":"第十六条","txt":"最高人民法院审理下列案件："},{"i":17,"n":"第十七条","txt":"死刑除依法由最高人民法院判决的以外，应当报请最高人民法院核准。"},{"i":18,"n":"第十八条","txt":"最高人民法院可以对属于审判工作中具体应用法律的问题进行解释。"},{"i":19,"n":"第十九条","txt":"最高人民法院可以设巡回法庭，审理最高人民法院依法确定的案件。"},{"i":20,"n":"第二十条","txt":"高级人民法院包括："},{"i":21,"n":"第二十一条","txt":"高级人民法院审理下列案件："},{"i":22,"n":"第二十二条","txt":"中级人民法院包括："},{"i":23,"n":"第二十三条","txt":"中级人民法院审理下列案件："},{"i":24,"n":"第二十四条","txt":"基层人民法院包括："},{"i":25,"n":"第二十五条","txt":"基层人民法院审理第一审案件，法律另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"基层人民法院根据地区、人口和案件情况，可以设立若干人民法庭。"},{"i":27,"n":"第二十七条","txt":"人民法院根据审判工作需要，可以设必要的专业审判庭。法官员额较少的中级人民法院和基层人民法院，可以设综合审判庭或者不设审判庭。"},{"i":28,"n":"第二十八条","txt":"人民法院根据工作需要，可以设必要的审判辅助机构和行政管理机构。"},{"i":29,"n":"第二十九条","txt":"人民法院审理案件，由合议庭或者法官一人独任审理。"},{"i":30,"n":"第三十条","txt":"合议庭由法官组成，或者由法官和人民陪审员组成，成员为三人以上单数。"},{"i":31,"n":"第三十一条","txt":"合议庭评议案件应当按照多数人的意见作出决定，少数人的意见应当记入笔录。评议案件笔录由合议庭全体组成人员签名。"},{"i":32,"n":"第三十二条","txt":"合议庭或者法官独任审理案件形成的裁判文书，经合议庭组成人员或者独任法官签署，由人民法院发布。"},{"i":33,"n":"第三十三条","txt":"合议庭审理案件，法官对案件的事实认定和法律适用负责；法官独任审理案件，独任法官对案件的事实认定和法律适用负责。"},{"i":34,"n":"第三十四条","txt":"人民陪审员依照法律规定参加合议庭审理案件。"},{"i":35,"n":"第三十五条","txt":"中级以上人民法院设赔偿委员会，依法审理国家赔偿案件。"},{"i":36,"n":"第三十六条","txt":"各级人民法院设审判委员会。审判委员会由院长、副院长和若干资深法官组成，成员应当为单数。"},{"i":37,"n":"第三十七条","txt":"审判委员会履行下列职能："},{"i":38,"n":"第三十八条","txt":"审判委员会召开全体会议和专业委员会会议，应当有其组成人员的过半数出席。"},{"i":39,"n":"第三十九条","txt":"合议庭认为案件需要提交审判委员会讨论决定的，由审判长提出申请，院长批准。"},{"i":40,"n":"第四十条","txt":"人民法院的审判人员由院长、副院长、审判委员会委员和审判员等人员组成。"},{"i":41,"n":"第四十一条","txt":"人民法院院长负责本院全面工作，监督本院审判工作，管理本院行政事务。人民法院副院长协助院长工作。"},{"i":42,"n":"第四十二条","txt":"最高人民法院院长由全国人民代表大会选举，副院长、审判委员会委员、庭长、副庭长和审判员由院长提请全国人民代表大会常务委员会任免。"},{"i":43,"n":"第四十三条","txt":"地方各级人民法院院长由本级人民代表大会选举，副院长、审判委员会委员、庭长、副庭长和审判员由院长提请本级人民代表大会常务委员会任免。"},{"i":44,"n":"第四十四条","txt":"人民法院院长任期与产生它的人民代表大会每届任期相同。"},{"i":45,"n":"第四十五条","txt":"人民法院的法官、审判辅助人员和司法行政人员实行分类管理。"},{"i":46,"n":"第四十六条","txt":"法官实行员额制。法官员额根据案件数量、经济社会发展情况、人口数量和人民法院审级等因素确定。"},{"i":47,"n":"第四十七条","txt":"法官从取得法律职业资格并且具备法律规定的其他条件的人员中选任。初任法官应当由法官遴选委员会进行专业能力审核。上级人民法院的法官一般从下级人民法院的法官中择优遴选。"},{"i":48,"n":"第四十八条","txt":"人民法院的法官助理在法官指导下负责审查案件材料、草拟法律文书等审判辅助事务。"},{"i":49,"n":"第四十九条","txt":"人民法院的书记员负责法庭审理记录等审判辅助事务。"},{"i":50,"n":"第五十条","txt":"人民法院的司法警察负责法庭警戒、人员押解和看管等警务事项。"},{"i":51,"n":"第五十一条","txt":"人民法院根据审判工作需要，可以设司法技术人员，负责与审判工作有关的事项。"},{"i":52,"n":"第五十二条","txt":"任何单位或者个人不得要求法官从事超出法定职责范围的事务。"},{"i":53,"n":"第五十三条","txt":"人民法院作出的判决、裁定等生效法律文书，义务人应当依法履行；拒不履行的，依法追究法律责任。"},{"i":54,"n":"第五十四条","txt":"人民法院采取必要措施，维护法庭秩序和审判权威。对妨碍人民法院依法行使职权的违法犯罪行为，依法追究法律责任。"},{"i":55,"n":"第五十五条","txt":"人民法院实行培训制度，法官、审判辅助人员和司法行政人员应当接受理论和业务培训。"},{"i":56,"n":"第五十六条","txt":"人民法院人员编制实行专项管理。"},{"i":57,"n":"第五十七条","txt":"人民法院的经费按照事权划分的原则列入财政预算，保障审判工作需要。"},{"i":58,"n":"第五十八条","txt":"人民法院应当加强信息化建设，运用现代信息技术，促进司法公开，提高工作效率。"},{"i":59,"n":"第五十九条","txt":"本法自2019年1月1日起施行。"}],"renminpeishenyuanfa":[{"i":1,"n":"第一条","txt":"为了保障公民依法参加审判活动，促进司法公正，提升司法公信，制定本法。"},{"i":2,"n":"第二条","txt":"公民有依法担任人民陪审员的权利和义务。"},{"i":3,"n":"第三条","txt":"人民陪审员依法享有参加审判活动、独立发表意见、获得履职保障等权利。"},{"i":4,"n":"第四条","txt":"人民陪审员依法参加审判活动，受法律保护。"},{"i":5,"n":"第五条","txt":"公民担任人民陪审员，应当具备下列条件："},{"i":6,"n":"第六条","txt":"下列人员不能担任人民陪审员："},{"i":7,"n":"第七条","txt":"有下列情形之一的，不得担任人民陪审员："},{"i":8,"n":"第八条","txt":"人民陪审员的名额，由基层人民法院根据审判案件的需要，提请同级人民代表大会常务委员会确定。"},{"i":9,"n":"第九条","txt":"司法行政机关会同基层人民法院、公安机关，从辖区内的常住居民名单中随机抽选拟任命人民陪审员数五倍以上的人员作为人民陪审员候选人，对人民陪审员候选人进行资格审查，征求候选人意见。"},{"i":10,"n":"第十条","txt":"司法行政机关会同基层人民法院，从通过资格审查的人民陪审员候选人名单中随机抽选确定人民陪审员人选，由基层人民法院院长提请同级人民代表大会常务委员会任命。"},{"i":11,"n":"第十一条","txt":"因审判活动需要，可以通过个人申请和所在单位、户籍所在地或者经常居住地的基层群众性自治组织、人民团体推荐的方式产生人民陪审员候选人，经司法行政机关会同基层人民法院、公安机关进行资格审查，确定人民陪审员人选，由基层人民法院院长提请同级人民代表大会常务委员会任命。"},{"i":12,"n":"第十二条","txt":"人民陪审员经人民代表大会常务委员会任命后，应当公开进行就职宣誓。宣誓仪式由基层人民法院会同司法行政机关组织。"},{"i":13,"n":"第十三条","txt":"人民陪审员的任期为五年，一般不得连任。"},{"i":14,"n":"第十四条","txt":"人民陪审员和法官组成合议庭审判案件，由法官担任审判长，可以组成三人合议庭，也可以由法官三人与人民陪审员四人组成七人合议庭。"},{"i":15,"n":"第十五条","txt":"人民法院审判第一审刑事、民事、行政案件，有下列情形之一的，由人民陪审员和法官组成合议庭进行："},{"i":16,"n":"第十六条","txt":"人民法院审判下列第一审案件，由人民陪审员和法官组成七人合议庭进行："},{"i":17,"n":"第十七条","txt":"第一审刑事案件被告人、民事案件原告或者被告、行政案件原告申请由人民陪审员参加合议庭审判的，人民法院可以决定由人民陪审员和法官组成合议庭审判。"},{"i":18,"n":"第十八条","txt":"人民陪审员的回避，适用审判人员回避的法律规定。"},{"i":19,"n":"第十九条","txt":"基层人民法院审判案件需要由人民陪审员参加合议庭审判的，应当在人民陪审员名单中随机抽取确定。"},{"i":20,"n":"第二十条","txt":"审判长应当履行与案件审判相关的指引、提示义务，但不得妨碍人民陪审员对案件的独立判断。"},{"i":21,"n":"第二十一条","txt":"人民陪审员参加三人合议庭审判案件，对事实认定、法律适用，独立发表意见，行使表决权。"},{"i":22,"n":"第二十二条","txt":"人民陪审员参加七人合议庭审判案件，对事实认定，独立发表意见，并与法官共同表决；对法律适用，可以发表意见，但不参加表决。"},{"i":23,"n":"第二十三条","txt":"合议庭评议案件，实行少数服从多数的原则。人民陪审员同合议庭其他组成人员意见分歧的，应当将其意见写入笔录。"},{"i":24,"n":"第二十四条","txt":"人民法院应当结合本辖区实际情况，合理确定每名人民陪审员年度参加审判案件的数量上限，并向社会公告。"},{"i":25,"n":"第二十五条","txt":"人民陪审员的培训、考核和奖惩等日常管理工作，由基层人民法院会同司法行政机关负责。"},{"i":26,"n":"第二十六条","txt":"对于在审判工作中有显著成绩或者有其他突出事迹的人民陪审员，依照有关规定给予表彰和奖励。"},{"i":27,"n":"第二十七条","txt":"人民陪审员有下列情形之一，经所在基层人民法院会同司法行政机关查证属实的，由院长提请同级人民代表大会常务委员会免除其人民陪审员职务："},{"i":28,"n":"第二十八条","txt":"人民陪审员的人身和住所安全受法律保护。任何单位和个人不得对人民陪审员及其近亲属打击报复。"},{"i":29,"n":"第二十九条","txt":"人民陪审员参加审判活动期间，所在单位不得克扣或者变相克扣其工资、奖金及其他福利待遇。"},{"i":30,"n":"第三十条","txt":"人民陪审员参加审判活动期间，由人民法院依照有关规定按实际工作日给予补助。"},{"i":31,"n":"第三十一条","txt":"人民陪审员因参加审判活动应当享受的补助，人民法院和司法行政机关为实施人民陪审员制度所必需的开支，列入人民法院和司法行政机关业务经费，由相应政府财政予以保障。具体办法由最高人民法院、国务院司法行政部门会同国务院财政部门制定。"},{"i":32,"n":"第三十二条","txt":"本法自公布之日起施行。2004年8月28日第十届全国人民代表大会常务委员会第十一次会议通过的《全国人民代表大会常务委员会关于完善人民陪审员制度的决定》同时废止。"}],"quanguorenmindaibiaodahuihedifanggejirenmindaibiaof29552":[{"i":1,"n":"第一条","txt":"为保证全国人民代表大会和地方各级人民代表大会代表依法行使代表的职权，履行代表的义务，发挥代表作用，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"全国人民代表大会和地方各级人民代表大会代表依照法律规定选举产生。"},{"i":3,"n":"第三条","txt":"全国人民代表大会和地方各级人民代表大会代表应当坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚定不移走中国特色社会主义政治发展道路，依照宪法和法律赋予本级人民代表大会的各项职权，遵循民主集中制原则，参加行使国家权力。"},{"i":4,"n":"第四条","txt":"全国人民代表大会和地方各级人民代表大会代表应当以坚持好、完善好、运行好人民代表大会制度为己任，做到政治坚定、服务人民、尊崇法治、发扬民主、勤勉尽责，为各级人民代表大会及其常务委员会建设自觉坚持中国共产党领导的政治机关、保证人民当家作主的国家权力机关、全面担负宪法法律赋予的各项职责的工作机关、始终同人民群众保持密切联系的代表机关而积极履职。"},{"i":5,"n":"第五条","txt":"全国人民代表大会和地方各级人民代表大会代表应当坚持以人民为中心，践行全过程人民民主，始终同人民群众保持密切联系，忠实代表人民的利益和意志，自觉接受人民监督。"},{"i":6,"n":"第六条","txt":"全国人民代表大会和地方各级人民代表大会代表应当忠于宪法，弘扬宪法精神，维护宪法权威，维护社会主义法制的统一和尊严，为推进全面依法治国、建设更高水平的社会主义法治国家贡献力量。"},{"i":7,"n":"第七条","txt":"代表享有下列权利："},{"i":8,"n":"第八条","txt":"代表应当履行下列义务："},{"i":9,"n":"第九条","txt":"代表依照本法的规定在本级人民代表大会会议期间的工作和在本级人民代表大会闭会期间的活动，都是执行代表职务。"},{"i":10,"n":"第十条","txt":"代表受原选区选民或者原选举单位的监督。"},{"i":11,"n":"第十一条","txt":"县级以上的各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当密切同代表的联系，丰富代表联系人民群众的内容和形式，加强代表工作能力建设，支持和保障代表依法履职，充分发挥代表作用。"},{"i":12,"n":"第十二条","txt":"县级以上的各级人民代表大会常务委员会设立代表工作委员会，作为常务委员会的工作机构。"},{"i":13,"n":"第十三条","txt":"代表应当按时出席本级人民代表大会会议。代表因健康等特殊原因不能出席会议的，应当按照规定请假。"},{"i":14,"n":"第十四条","txt":"县级以上的各级人民代表大会代表按照选举单位、行政区域等组成代表团。乡、民族乡、镇的人民代表大会代表根据实际需要，可以组成代表团。"},{"i":15,"n":"第十五条","txt":"代表有权依照法律规定的程序向本级人民代表大会提出属于本级人民代表大会职权范围内的议案。议案应当有案由、案据和方案。"},{"i":16,"n":"第十六条","txt":"全国人民代表大会代表，有权依照宪法规定的程序向全国人民代表大会提出修改宪法的议案。"},{"i":17,"n":"第十七条","txt":"代表参加本级人民代表大会的各项选举。"},{"i":18,"n":"第十八条","txt":"全国人民代表大会代表参加决定国务院组成人员和中央军事委员会副主席、委员的人选。"},{"i":19,"n":"第十九条","txt":"代表在审议议案和报告时，可以向本级有关国家机关提出询问。有关国家机关应当派负责人或者负责人员回答询问。"},{"i":20,"n":"第二十条","txt":"全国人民代表大会会议期间，一个代表团或者三十名以上的代表联名，有权书面提出对国务院和国务院各部门、国家监察委员会、最高人民法院、最高人民检察院的质询案。"},{"i":21,"n":"第二十一条","txt":"全国人民代表大会代表有权依照法律规定的程序提出对全国人民代表大会常务委员会组成人员，中华人民共和国主席、副主席，国务院组成人员，中央军事委员会组成人员，国家监察委员会主任，最高人民法院院长，最高人民检察院检察长的罢免案。"},{"i":22,"n":"第二十二条","txt":"县级以上的各级人民代表大会代表有权依法提议组织关于特定问题的调查委员会。"},{"i":23,"n":"第二十三条","txt":"代表参加本级人民代表大会表决，可以表示赞成，可以表示反对，也可以表示弃权。"},{"i":24,"n":"第二十四条","txt":"代表有权向本级人民代表大会提出对各方面工作的建议、批评和意见。建议、批评和意见应当明确具体，注重反映实际情况和问题。"},{"i":25,"n":"第二十五条","txt":"县级以上的各级人民代表大会常务委员会组织本级人民代表大会代表开展闭会期间的活动。"},{"i":26,"n":"第二十六条","txt":"代表在闭会期间的活动以集体活动为主，以代表小组活动为基本形式。代表可以通过多种方式听取、反映原选区选民或者原选举单位的意见和要求。"},{"i":27,"n":"第二十七条","txt":"县级以上的各级人民代表大会代表，在本级或者下级人民代表大会常务委员会协助下，可以按照便于组织和开展活动的原则，根据地域、领域等组成代表小组。"},{"i":28,"n":"第二十八条","txt":"县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团按照就地就近的原则，定期组织和协助本行政区域内的代表开展联系人民群众的活动，听取和反映人民群众的意见和要求。"},{"i":29,"n":"第二十九条","txt":"县级以上的各级人民代表大会代表根据本级人民代表大会常务委员会的安排，对本级或者下级国家机关和有关单位的工作进行视察。乡、民族乡、镇的人民代表大会代表根据本级人民代表大会主席团的安排，对本级人民政府和有关单位的工作进行视察。根据安排，设区的市级以上的各级人民代表大会代表也可以在本行政区域内跨原选举单位进行视察。"},{"i":30,"n":"第三十条","txt":"代表根据本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团的安排，围绕经济社会发展和关系人民群众切身利益、社会普遍关注的重大问题、重大事项，以及本级人民代表大会常务委员会重点工作，开展专题调研。根据安排，设区的市级以上的各级人民代表大会代表也可以在本行政区域内跨原选举单位开展专题调研。"},{"i":31,"n":"第三十一条","txt":"代表参加视察、专题调研活动形成的报告，由本级人民代表大会常务委员会办事机构、工作机构或者乡、民族乡、镇的人民代表大会主席团转交有关机关、组织。有关机关、组织对报告中提出的意见和建议的研究处理情况应当及时向代表反馈。"},{"i":32,"n":"第三十二条","txt":"代表有权依照法律规定的程序提议临时召集本级人民代表大会会议。"},{"i":33,"n":"第三十三条","txt":"县级以上的各级人民代表大会代表可以应邀列席本级人民代表大会常务委员会会议、本级人民代表大会各专门委员会会议，并可以应邀参加本级人民代表大会常务委员会、各专门委员会和常务委员会办事机构、工作机构组织的有关会议；根据安排参加本级人民代表大会常务委员会组织的执法检查、专题询问和其他活动。"},{"i":34,"n":"第三十四条","txt":"全国人民代表大会代表，省、自治区、直辖市、自治州、设区的市的人民代表大会代表可以列席原选举单位的人民代表大会会议，并可以应邀列席原选举单位的人民代表大会常务委员会会议。"},{"i":35,"n":"第三十五条","txt":"县级以上的各级人民代表大会代表根据本级人民代表大会或者本级人民代表大会常务委员会的决定，参加关于特定问题的调查委员会。"},{"i":36,"n":"第三十六条","txt":"代表在本级人民代表大会闭会期间，有权向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团提出对各方面工作的建议、批评和意见。建议、批评和意见应当明确具体，注重反映实际情况和问题。"},{"i":37,"n":"第三十七条","txt":"乡、民族乡、镇的人民代表大会代表在本级人民代表大会闭会期间，根据统一安排，开展调研等活动；组成代表小组，分工联系选民，反映人民群众的意见和要求。"},{"i":38,"n":"第三十八条","txt":"代表在人民代表大会各种会议上的发言和表决，不受法律追究。"},{"i":39,"n":"第三十九条","txt":"县级以上的各级人民代表大会代表，非经本级人民代表大会主席团许可，在本级人民代表大会闭会期间，非经本级人民代表大会常务委员会许可，不受逮捕或者刑事审判。如果因为是现行犯被拘留，执行拘留的机关应当立即向该级人民代表大会主席团或者人民代表大会常务委员会报告。"},{"i":40,"n":"第四十条","txt":"代表在本级人民代表大会闭会期间，参加统一组织和安排的代表履职活动，代表所在单位必须给予时间保障。"},{"i":41,"n":"第四十一条","txt":"代表依法执行代表职务，其所在单位按正常出勤对待，享受所在单位的工资和其他待遇。"},{"i":42,"n":"第四十二条","txt":"代表的活动经费，应当列入本级财政预算予以保障，专款专用。"},{"i":43,"n":"第四十三条","txt":"县级以上的各级人民代表大会常务委员会制定年度代表工作计划，依法统筹组织和安排代表履职活动，增强代表履职活动的计划性、组织性和规范性。"},{"i":44,"n":"第四十四条","txt":"县级以上的各级人民代表大会常务委员会应当采取多种方式同本级人民代表大会代表保持联系，建立健全常务委员会组成人员、各专门委员会和常务委员会办事机构、工作机构联系代表的工作机制，扩大代表对立法、监督等各项工作的参与。"},{"i":45,"n":"第四十五条","txt":"县级以上的地方各级人民代表大会常务委员会应当加强同本行政区域内的代表的联系，为代表依法履职提供必要的条件。"},{"i":46,"n":"第四十六条","txt":"县级以上的各级人民代表大会常务委员会和各级人民政府及其所属各部门、监察委员会、人民法院、人民检察院，应当及时向本级人民代表大会代表通报工作情况，提供信息资料，保障代表的知情权。"},{"i":47,"n":"第四十七条","txt":"县级以上的各级人民代表大会常务委员会应当有计划地组织代表参加履职学习培训和交流，提高代表履职能力。"},{"i":48,"n":"第四十八条","txt":"县级以上的各级人民代表大会常务委员会的办事机构和工作机构是代表执行代表职务的集体服务机构，为代表执行代表职务提供服务保障。"},{"i":49,"n":"第四十九条","txt":"为了便于代表执行代表职务，各级人民代表大会应当为本级人民代表大会代表制发代表证。"},{"i":50,"n":"第五十条","txt":"县级以上的各级人民代表大会专门委员会审议本级人民代表大会主席团交付的代表议案，应当与代表联系沟通，充分听取意见，并及时通报情况。"},{"i":51,"n":"第五十一条","txt":"代表对各方面工作提出的建议、批评和意见，由本级人民代表大会常务委员会办事机构、工作机构或者乡、民族乡、镇的人民代表大会主席团交有关机关、组织研究办理。"},{"i":52,"n":"第五十二条","txt":"县级以上的各级人民代表大会有关专门委员会和常务委员会办事机构、工作机构，乡、民族乡、镇的人民代表大会主席团，应当加强对代表建议、批评和意见的督促办理。"},{"i":53,"n":"第五十三条","txt":"少数民族代表执行代表职务时，有关部门应当在语言文字、生活习惯等方面给予必要的帮助和照顾。"},{"i":54,"n":"第五十四条","txt":"身体残疾或者其他行动不便的代表执行代表职务时，有关部门应当根据需要给予必要的帮助和照顾。"},{"i":55,"n":"第五十五条","txt":"一切组织和个人都必须尊重代表的权利，支持代表执行代表职务。"},{"i":56,"n":"第五十六条","txt":"县级以上的各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当通过多种方式宣传代表依法履职、发挥作用的典型事迹，展现代表践行全过程人民民主的生动实践。"},{"i":57,"n":"第五十七条","txt":"代表应当坚定政治立场，履行政治责任，加强思想作风建设，自觉接受监督，自觉维护代表形象。"},{"i":58,"n":"第五十八条","txt":"代表应当采取多种方式经常听取人民群众对代表履职的意见，回答原选区选民或者原选举单位对代表工作和代表活动的询问，接受监督。"},{"i":59,"n":"第五十九条","txt":"代表应当正确处理从事个人职业活动与执行代表职务的关系，不得利用执行代表职务干预具体执法、司法案件，插手招标投标等经济活动或者变相从事商业活动牟取个人利益。"},{"i":60,"n":"第六十条","txt":"选民或者选举单位有权依法罢免自己选出的代表。被提出罢免的代表有权出席罢免该代表的会议提出申辩意见，或者书面提出申辩意见。"},{"i":61,"n":"第六十一条","txt":"代表有下列情形之一的，暂时停止执行代表职务，由代表资格审查委员会向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会报告："},{"i":62,"n":"第六十二条","txt":"代表有下列情形之一的，其代表资格终止："},{"i":63,"n":"第六十三条","txt":"县级以上的各级人民代表大会代表资格的终止，由代表资格审查委员会报本级人民代表大会常务委员会，由本级人民代表大会常务委员会予以公告。"},{"i":64,"n":"第六十四条","txt":"省、自治区、直辖市的人民代表大会及其常务委员会可以根据本法和本行政区域的实际情况，制定实施办法。"},{"i":65,"n":"第六十五条","txt":"本法自公布之日起施行。"}],"quanguorenmindaibiaodahuihedifanggejirenmindaibiaoc1fb0f":[{"i":1,"n":"第一条","txt":"根据中华人民共和国宪法，制定全国人民代表大会和地方各级人民代表大会选举法。"},{"i":2,"n":"第二条","txt":"全国人民代表大会和地方各级人民代表大会代表的选举工作，坚持中国共产党的领导，坚持充分发扬民主，坚持严格依法办事。"},{"i":3,"n":"第三条","txt":"全国人民代表大会的代表，省、自治区、直辖市、设区的市、自治州的人民代表大会的代表，由下一级人民代表大会选举。"},{"i":4,"n":"第四条","txt":"中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况和居住期限，都有选举权和被选举权。"},{"i":5,"n":"第五条","txt":"每一选民在一次选举中只有一个投票权。"},{"i":6,"n":"第六条","txt":"人民解放军单独进行选举，选举办法另订。"},{"i":7,"n":"第七条","txt":"全国人民代表大会和地方各级人民代表大会的代表应当具有广泛的代表性，应当有适当数量的基层代表，特别是工人、农民和知识分子代表；应当有适当数量的妇女代表，并逐步提高妇女代表的比例。"},{"i":8,"n":"第八条","txt":"全国人民代表大会和地方各级人民代表大会的选举经费，列入财政预算，由国库开支。"},{"i":9,"n":"第九条","txt":"全国人民代表大会常务委员会主持全国人民代表大会代表的选举。省、自治区、直辖市、设区的市、自治州的人民代表大会常务委员会主持本级人民代表大会代表的选举。"},{"i":10,"n":"第十条","txt":"不设区的市、市辖区、县、自治县的选举委员会的组成人员由本级人民代表大会常务委员会任命。乡、民族乡、镇的选举委员会的组成人员由不设区的市、市辖区、县、自治县的人民代表大会常务委员会任命。"},{"i":11,"n":"第十一条","txt":"选举委员会履行下列职责："},{"i":12,"n":"第十二条","txt":"地方各级人民代表大会的代表名额，按照下列规定确定："},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市的人民代表大会代表的具体名额，由全国人民代表大会常务委员会依照本法确定。设区的市、自治州和县级的人民代表大会代表的具体名额，由省、自治区、直辖市的人民代表大会常务委员会依照本法确定，报全国人民代表大会常务委员会备案。乡级的人民代表大会代表的具体名额，由县级的人民代表大会常务委员会依照本法确定，报上一级人民代表大会常务委员会备案。"},{"i":14,"n":"第十四条","txt":"地方各级人民代表大会的代表总名额经确定后，不再变动。如果由于行政区划变动或者由于重大工程建设等原因造成人口较大变动的，该级人民代表大会的代表总名额依照本法的规定重新确定。"},{"i":15,"n":"第十五条","txt":"地方各级人民代表大会代表名额，由本级人民代表大会常务委员会或者本级选举委员会根据本行政区域所辖的下一级各行政区域或者各选区的人口数，按照每一代表所代表的城乡人口数相同的原则，以及保证各地区、各民族、各方面都有适当数量代表的要求进行分配。在县、自治县的人民代表大会中，人口特少的乡、民族乡、镇，至少应有代表一人。"},{"i":16,"n":"第十六条","txt":"全国人民代表大会的代表，由省、自治区、直辖市的人民代表大会和人民解放军选举产生。"},{"i":17,"n":"第十七条","txt":"全国人民代表大会代表名额，由全国人民代表大会常务委员会根据各省、自治区、直辖市的人口数，按照每一代表所代表的城乡人口数相同的原则，以及保证各地区、各民族、各方面都有适当数量代表的要求进行分配。"},{"i":18,"n":"第十八条","txt":"全国少数民族应选全国人民代表大会代表，由全国人民代表大会常务委员会参照各少数民族的人口数和分布等情况，分配给各省、自治区、直辖市的人民代表大会选出。人口特少的民族，至少应有代表一人。"},{"i":19,"n":"第十九条","txt":"有少数民族聚居的地方，每一聚居的少数民族都应有代表参加当地的人民代表大会。"},{"i":20,"n":"第二十条","txt":"自治区、自治州、自治县和有少数民族聚居的乡、民族乡、镇的人民代表大会，对于聚居在境内的其他少数民族和汉族代表的选举，适用本法第十九条的规定。"},{"i":21,"n":"第二十一条","txt":"散居的少数民族应选当地人民代表大会的代表，每一代表所代表的人口数可以少于当地人民代表大会每一代表所代表的人口数。"},{"i":22,"n":"第二十二条","txt":"有少数民族聚居的不设区的市、市辖区、县、乡、民族乡、镇的人民代表大会代表的产生，按照当地的民族关系和居住状况，各少数民族选民可以单独选举或者联合选举。"},{"i":23,"n":"第二十三条","txt":"自治区、自治州、自治县制定或者公布的选举文件、选民名单、选民证、代表候选人名单、代表当选证书和选举委员会的印章等，都应当同时使用当地通用的民族文字。"},{"i":24,"n":"第二十四条","txt":"少数民族选举的其他事项，参照本法有关各条的规定办理。"},{"i":25,"n":"第二十五条","txt":"不设区的市、市辖区、县、自治县、乡、民族乡、镇的人民代表大会的代表名额分配到选区，按选区进行选举。选区可以按居住状况划分，也可以按生产单位、事业单位、工作单位划分。"},{"i":26,"n":"第二十六条","txt":"本行政区域内各选区每一代表所代表的人口数应当大体相等。"},{"i":27,"n":"第二十七条","txt":"选民登记按选区进行，经登记确认的选民资格长期有效。每次选举前对上次选民登记以后新满十八周岁的、被剥夺政治权利期满后恢复政治权利的选民，予以登记。对选民经登记后迁出原选区的，列入新迁入的选区的选民名单；对死亡的和依照法律被剥夺政治权利的人，从选民名单上除名。"},{"i":28,"n":"第二十八条","txt":"选民名单应在选举日的二十日以前公布，实行凭选民证参加投票选举的，并应当发给选民证。"},{"i":29,"n":"第二十九条","txt":"对于公布的选民名单有不同意见的，可以在选民名单公布之日起五日内向选举委员会提出申诉。选举委员会对申诉意见，应在三日内作出处理决定。申诉人如果对处理决定不服，可以在选举日的五日以前向人民法院起诉，人民法院应在选举日以前作出判决。人民法院的判决为最后决定。"},{"i":30,"n":"第三十条","txt":"全国和地方各级人民代表大会的代表候选人，按选区或者选举单位提名产生。"},{"i":31,"n":"第三十一条","txt":"全国和地方各级人民代表大会代表实行差额选举，代表候选人的人数应多于应选代表的名额。"},{"i":32,"n":"第三十二条","txt":"由选民直接选举人民代表大会代表的，代表候选人由各选区选民和各政党、各人民团体提名推荐。选举委员会汇总后，将代表候选人名单及代表候选人的基本情况在选举日的十五日以前公布，并交各该选区的选民小组讨论、协商，确定正式代表候选人名单。如果所提代表候选人的人数超过本法第三十一条规定的最高差额比例，由选举委员会交各该选区的选民小组讨论、协商，根据较多数选民的意见，确定正式代表候选人名单；对正式代表候选人不能形成较为一致意见的，进行预选，根据预选时得票多少的顺序，确定正式代表候选人名单。正式代表候选人名单及代表候选人的基本情况应当在选举日的七日以前公布。"},{"i":33,"n":"第三十三条","txt":"县级以上的地方各级人民代表大会在选举上一级人民代表大会代表时，代表候选人不限于各该级人民代表大会的代表。"},{"i":34,"n":"第三十四条","txt":"选举委员会或者人民代表大会主席团应当向选民或者代表介绍代表候选人的情况。推荐代表候选人的政党、人民团体和选民、代表可以在选民小组或者代表小组会议上介绍所推荐的代表候选人的情况。选举委员会根据选民的要求，应当组织代表候选人与选民见面，由代表候选人介绍本人的情况，回答选民的问题。但是，在选举日必须停止代表候选人的介绍。"},{"i":35,"n":"第三十五条","txt":"公民参加各级人民代表大会代表的选举，不得直接或者间接接受境外机构、组织、个人提供的与选举有关的任何形式的资助。"},{"i":36,"n":"第三十六条","txt":"全国人民代表大会和地方各级人民代表大会代表的选举，应当严格依照法定程序进行，并接受监督。任何组织或者个人都不得以任何方式干预选民或者代表自由行使选举权。"},{"i":37,"n":"第三十七条","txt":"在选民直接选举人民代表大会代表时，选民根据选举委员会的规定，凭身份证或者选民证领取选票。"},{"i":38,"n":"第三十八条","txt":"选举委员会应当根据各选区选民分布状况，按照方便选民投票的原则设立投票站，进行选举。选民居住比较集中的，可以召开选举大会，进行选举；因患有疾病等原因行动不便或者居住分散并且交通不便的选民，可以在流动票箱投票。"},{"i":39,"n":"第三十九条","txt":"县级以上的地方各级人民代表大会在选举上一级人民代表大会代表时，由各该级人民代表大会主席团主持。"},{"i":40,"n":"第四十条","txt":"全国和地方各级人民代表大会代表的选举，一律采用无记名投票的方法。选举时应当设有秘密写票处。"},{"i":41,"n":"第四十一条","txt":"选举人对于代表候选人可以投赞成票，可以投反对票，可以另选其他任何选民，也可以弃权。"},{"i":42,"n":"第四十二条","txt":"选民如果在选举期间外出，经选举委员会同意，可以书面委托其他选民代为投票。每一选民接受的委托不得超过三人，并应当按照委托人的意愿代为投票。"},{"i":43,"n":"第四十三条","txt":"投票结束后，由选民或者代表推选的监票、计票人员和选举委员会或者人民代表大会主席团的人员将投票人数和票数加以核对，作出记录，并由监票人签字。"},{"i":44,"n":"第四十四条","txt":"每次选举所投的票数，多于投票人数的无效，等于或者少于投票人数的有效。"},{"i":45,"n":"第四十五条","txt":"在选民直接选举人民代表大会代表时，选区全体选民的过半数参加投票，选举有效。代表候选人获得参加投票的选民过半数的选票时，始得当选。"},{"i":46,"n":"第四十六条","txt":"选举结果由选举委员会或者人民代表大会主席团根据本法确定是否有效，并予以宣布。"},{"i":47,"n":"第四十七条","txt":"代表资格审查委员会依法对当选代表是否符合宪法、法律规定的代表的基本条件，选举是否符合法律规定的程序，以及是否存在破坏选举和其他当选无效的违法行为进行审查，提出代表当选是否有效的意见，向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团报告。"},{"i":48,"n":"第四十八条","txt":"公民不得同时担任两个以上无隶属关系的行政区域的人民代表大会代表。"},{"i":49,"n":"第四十九条","txt":"全国和地方各级人民代表大会的代表，受选民和原选举单位的监督。选民或者选举单位都有权罢免自己选出的代表。"},{"i":50,"n":"第五十条","txt":"对于县级的人民代表大会代表，原选区选民五十人以上联名，对于乡级的人民代表大会代表，原选区选民三十人以上联名，可以向县级的人民代表大会常务委员会书面提出罢免要求。"},{"i":51,"n":"第五十一条","txt":"县级以上的地方各级人民代表大会举行会议的时候，主席团或者十分之一以上代表联名，可以提出对由该级人民代表大会选出的上一级人民代表大会代表的罢免案。在人民代表大会闭会期间，县级以上的地方各级人民代表大会常务委员会主任会议或者常务委员会五分之一以上组成人员联名，可以向常务委员会提出对由该级人民代表大会选出的上一级人民代表大会代表的罢免案。罢免案应当写明罢免理由。"},{"i":52,"n":"第五十二条","txt":"罢免代表采用无记名的表决方式。"},{"i":53,"n":"第五十三条","txt":"罢免县级和乡级的人民代表大会代表，须经原选区过半数的选民通过。"},{"i":54,"n":"第五十四条","txt":"县级以上的各级人民代表大会常务委员会组成人员，县级以上的各级人民代表大会专门委员会成员的代表职务被罢免的，其常务委员会组成人员或者专门委员会成员的职务相应撤销，由主席团或者常务委员会予以公告。"},{"i":55,"n":"第五十五条","txt":"全国人民代表大会代表，省、自治区、直辖市、设区的市、自治州的人民代表大会代表，可以向选举他的人民代表大会的常务委员会书面提出辞职。常务委员会接受辞职，须经常务委员会组成人员的过半数通过。接受辞职的决议，须报送上一级人民代表大会常务委员会备案、公告。"},{"i":56,"n":"第五十六条","txt":"县级以上的各级人民代表大会常务委员会组成人员，县级以上的各级人民代表大会的专门委员会成员，辞去代表职务的请求被接受的，其常务委员会组成人员、专门委员会成员的职务相应终止，由常务委员会予以公告。"},{"i":57,"n":"第五十七条","txt":"代表在任期内，因故出缺，由原选区或者原选举单位补选。"},{"i":58,"n":"第五十八条","txt":"为保障选民和代表自由行使选举权和被选举权，对有下列行为之一，破坏选举，违反治安管理规定的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":59,"n":"第五十九条","txt":"主持选举的机构发现有破坏选举的行为或者收到对破坏选举行为的举报，应当及时依法调查处理；需要追究法律责任的，及时移送有关机关予以处理。"},{"i":60,"n":"第六十条","txt":"省、自治区、直辖市的人民代表大会及其常务委员会根据本法可以制定选举实施细则，报全国人民代表大会常务委员会备案。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiyishiguif03a5d":[{"i":1,"n":"第一条","txt":"为了健全全国人民代表大会常务委员会的议事程序，保障和规范其行使职权，根据宪法、全国人民代表大会组织法，总结全国人民代表大会常务委员会工作的实践经验，制定本规则。"},{"i":2,"n":"第二条","txt":"全国人民代表大会常务委员会坚持中国共产党的领导，依照法定职权和法定程序举行会议、开展工作。"},{"i":3,"n":"第三条","txt":"全国人民代表大会常务委员会坚持和发展全过程人民民主，始终同人民保持密切联系，倾听人民的意见和建议，体现人民意志，保障人民权益。"},{"i":4,"n":"第四条","txt":"全国人民代表大会常务委员会审议议案、决定问题，实行民主集中制的原则，充分发扬民主，集体行使职权。"},{"i":5,"n":"第五条","txt":"全国人民代表大会常务委员会举行会议，应当合理安排会期、议程和日程，提高议事质量和效率。"},{"i":6,"n":"第六条","txt":"全国人民代表大会常务委员会会议一般每两个月举行一次，必要时可以加开会议；有特殊需要的时候，可以临时召集会议。"},{"i":7,"n":"第七条","txt":"常务委员会会议有常务委员会全体组成人员的过半数出席，始得举行。"},{"i":8,"n":"第八条","txt":"委员长会议拟订常务委员会会议议程草案，提请常务委员会全体会议决定。"},{"i":9,"n":"第九条","txt":"常务委员会举行会议，应当在会议举行七日以前，将开会日期、建议会议讨论的主要事项，通知常务委员会组成人员和列席会议的人员；临时召集的会议，可以临时通知。"},{"i":10,"n":"第十条","txt":"常务委员会举行会议的时候，国务院、中央军事委员会、国家监察委员会、最高人民法院、最高人民检察院的负责人列席会议。"},{"i":11,"n":"第十一条","txt":"常务委员会举行会议的时候，各省、自治区、直辖市和其他有关地方的人民代表大会常务委员会主任或者副主任一人列席会议，并可以邀请有关的全国人民代表大会代表列席会议。"},{"i":12,"n":"第十二条","txt":"常务委员会举行会议的时候，召开全体会议和分组会议，根据需要召开联组会议。"},{"i":13,"n":"第十三条","txt":"常务委员会分组会议由委员长会议确定若干名召集人，轮流主持会议。"},{"i":14,"n":"第十四条","txt":"常务委员会举行联组会议，由委员长主持。委员长可以委托副委员长主持会议。"},{"i":15,"n":"第十五条","txt":"常务委员会举行会议的时候，常务委员会组成人员应当出席会议；因病或者其他特殊原因不能出席的，应当通过常务委员会办事机构向委员长书面请假。"},{"i":16,"n":"第十六条","txt":"常务委员会会议公开举行。常务委员会会议会期、议程、日程和会议情况予以公开。必要时，经委员长会议决定，可以暂不公开有关议程。"},{"i":17,"n":"第十七条","txt":"常务委员会会议运用现代信息技术，推进会议文件资料电子化，采用网络视频等方式为常务委员会组成人员和列席人员履职提供便利和服务。"},{"i":18,"n":"第十八条","txt":"委员长会议可以向常务委员会提出属于常务委员会职权范围内的议案，由常务委员会会议审议。"},{"i":19,"n":"第十九条","txt":"提请常务委员会会议审议的议案，应当在会议召开十日前提交常务委员会。"},{"i":20,"n":"第二十条","txt":"委员长会议根据工作需要，可以委托常务委员会的工作委员会、办公厅起草议案草案，并向常务委员会会议作说明。"},{"i":21,"n":"第二十一条","txt":"对列入常务委员会会议议程的议案，提议案的机关、有关的专门委员会、常务委员会有关工作部门应当提供有关的资料。"},{"i":22,"n":"第二十二条","txt":"常务委员会全体会议听取关于议案的说明。内容相关联的议案可以合并说明。"},{"i":23,"n":"第二十三条","txt":"列入会议议程的法律案，常务委员会听取说明并初次审议后，由宪法和法律委员会进行统一审议，向下次或者以后的常务委员会会议提出审议结果的报告。"},{"i":24,"n":"第二十四条","txt":"提请批准国民经济和社会发展规划纲要、计划、预算的调整方案和决算的议案，交财政经济委员会审查，也可以同时交其他有关专门委员会审查，由财政经济委员会向常务委员会会议提出审查结果的报告。有关专门委员会的审查意见印发常务委员会会议。"},{"i":25,"n":"第二十五条","txt":"提请批准或者加入条约和重要协定的议案，交外事委员会审议，可以同时交其他有关专门委员会审议，由外事委员会向本次常务委员会会议提出审议结果的报告，也可以向下次或者以后的常务委员会会议提出审议结果的报告。有关专门委员会的审议意见印发常务委员会会议。"},{"i":26,"n":"第二十六条","txt":"依法需要报经常务委员会批准的法规和自治条例、单行条例等，由制定机关报送常务委员会，由委员长会议决定列入常务委员会会议议程，由有关的专门委员会进行审议并提出报告。"},{"i":27,"n":"第二十七条","txt":"列于《中华人民共和国香港特别行政区基本法》附件三、《中华人民共和国澳门特别行政区基本法》附件三的法律需要作出增减的，在征询香港特别行政区基本法委员会和香港特别行政区政府、澳门特别行政区基本法委员会和澳门特别行政区政府的意见后，由委员长会议提出议案，提请常务委员会会议审议。"},{"i":28,"n":"第二十八条","txt":"常务委员会联组会议可以听取和审议专门委员会对议案审议意见的汇报，对会议议题进行讨论。"},{"i":29,"n":"第二十九条","txt":"提议案的机关的负责人可以在常务委员会全体会议、联组会议上对议案作补充说明。"},{"i":30,"n":"第三十条","txt":"列入常务委员会会议议程的议案，在交付表决前，提案人要求撤回的，经委员长会议同意，对该议案的审议即行终止。"},{"i":31,"n":"第三十一条","txt":"拟提请常务委员会全体会议表决的议案，在审议中有重大问题需要进一步研究的，经委员长或者委员长会议提出，联组会议或者全体会议同意，可以暂不付表决，交有关专门委员会进一步审议，提出审议报告。"},{"i":32,"n":"第三十二条","txt":"常务委员会认为必要的时候，可以组织关于特定问题的调查委员会，并且根据调查委员会的报告，作出相应的决议。"},{"i":33,"n":"第三十三条","txt":"常务委员会根据年度工作计划和需要听取国务院、国家监察委员会、最高人民法院、最高人民检察院的专项工作报告。"},{"i":34,"n":"第三十四条","txt":"常务委员会全体会议听取报告后，可以由分组会议和联组会议进行审议。"},{"i":35,"n":"第三十五条","txt":"常务委员会组成人员对各项报告的审议意见交由有关机关研究处理。有关机关应当将研究处理情况向常务委员会提出书面报告。"},{"i":36,"n":"第三十六条","txt":"常务委员会分组会议对议案或者有关的报告进行审议的时候，应当通知有关部门派人到会，听取意见，回答询问。"},{"i":37,"n":"第三十七条","txt":"常务委员会围绕关系改革发展稳定大局和人民切身利益、社会普遍关注的重大问题，可以召开联组会议、分组会议，进行专题询问。"},{"i":38,"n":"第三十八条","txt":"根据常务委员会工作安排或者受委员长会议委托，专门委员会可以就有关问题开展调研询问，并提出开展调研询问情况的报告。"},{"i":39,"n":"第三十九条","txt":"在常务委员会会议期间，常务委员会组成人员十人以上联名，可以向常务委员会书面提出对国务院及国务院各部门和国家监察委员会、最高人民法院、最高人民检察院的质询案。"},{"i":40,"n":"第四十条","txt":"质询案必须写明质询对象、质询的问题和内容。"},{"i":41,"n":"第四十一条","txt":"质询案由委员长会议决定交由有关的专门委员会审议或者提请常务委员会会议审议。"},{"i":42,"n":"第四十二条","txt":"质询案由委员长会议决定，由受质询机关的负责人在常务委员会会议上或者有关的专门委员会会议上口头答复，或者由受质询机关书面答复。在专门委员会会议上答复的，专门委员会应当向常务委员会或者委员长会议提出报告。"},{"i":43,"n":"第四十三条","txt":"常务委员会组成人员在全体会议、联组会议和分组会议上发言，应当围绕会议确定的议题进行。"},{"i":44,"n":"第四十四条","txt":"在全体会议和联组会议上的发言，不超过十分钟；在分组会议上，第一次发言不超过十五分钟，第二次对同一问题的发言不超过十分钟。事先提出要求，经会议主持人同意的，可以延长发言时间。"},{"i":45,"n":"第四十五条","txt":"表决议案由常务委员会全体组成人员的过半数通过。"},{"i":46,"n":"第四十六条","txt":"交付表决的议案，有修正案的，先表决修正案。"},{"i":47,"n":"第四十七条","txt":"任免案、撤职案逐人表决，根据情况也可以合并表决。"},{"i":48,"n":"第四十八条","txt":"常务委员会表决议案，采用无记名按表决器方式。常务委员会组成人员应当按表决器。如表决器系统在使用中发生故障，采用举手方式或者其他方式。"},{"i":49,"n":"第四十九条","txt":"常务委员会通过的法律，由中华人民共和国主席签署主席令予以公布。"},{"i":50,"n":"第五十条","txt":"常务委员会决定任免的国务院副总理、国务委员以及各部部长、各委员会主任、中国人民银行行长、审计长、秘书长，由中华人民共和国主席根据常务委员会的决定，签署主席令任免并予以公布。"},{"i":51,"n":"第五十一条","txt":"常务委员会通过的法律、决议、决定及其说明、修改情况的汇报、审议结果的报告，发布的公告，决定批准或者加入的条约和重要协定，常务委员会、专门委员会的声明等，应当及时在常务委员会公报和中国人大网上刊载。"},{"i":52,"n":"第五十二条","txt":"本规则自公布之日起施行。"}],"quanguorenmindaibiaodahuizuzhifa":[{"i":1,"n":"第一条","txt":"为了健全全国人民代表大会及其常务委员会的组织和工作制度，保障和规范其行使职权，坚持和完善人民代表大会制度，保证人民当家作主，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"全国人民代表大会是最高国家权力机关，其常设机关是全国人民代表大会常务委员会。"},{"i":3,"n":"第三条","txt":"全国人民代表大会及其常务委员会坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，依照宪法和法律规定行使职权。"},{"i":4,"n":"第四条","txt":"全国人民代表大会由民主选举产生，对人民负责，受人民监督。"},{"i":5,"n":"第五条","txt":"全国人民代表大会及其常务委员会行使国家立法权，决定重大事项，监督宪法和法律的实施，维护社会主义法制的统一、尊严、权威，建设社会主义法治国家。"},{"i":6,"n":"第六条","txt":"全国人民代表大会及其常务委员会实行民主集中制原则，充分发扬民主，集体行使职权。"},{"i":7,"n":"第七条","txt":"全国人民代表大会及其常务委员会积极开展对外交往，加强同各国议会、国际和地区议会组织的交流与合作。"},{"i":8,"n":"第八条","txt":"全国人民代表大会每届任期五年。"},{"i":9,"n":"第九条","txt":"全国人民代表大会代表选出后，由全国人民代表大会常务委员会代表资格审查委员会进行审查。"},{"i":10,"n":"第十条","txt":"全国人民代表大会代表按照选举单位组成代表团。各代表团分别推选代表团团长、副团长。"},{"i":11,"n":"第十一条","txt":"全国人民代表大会每次会议举行预备会议，选举本次会议的主席团和秘书长，通过本次会议的议程和其他准备事项的决定。"},{"i":12,"n":"第十二条","txt":"主席团主持全国人民代表大会会议。"},{"i":13,"n":"第十三条","txt":"全国人民代表大会会议设立秘书处。秘书处由秘书长和副秘书长若干人组成。副秘书长的人选由主席团决定。"},{"i":14,"n":"第十四条","txt":"主席团处理下列事项："},{"i":15,"n":"第十五条","txt":"主席团常务主席就拟提请主席团审议事项，听取秘书处和有关专门委员会的报告，向主席团提出建议。"},{"i":16,"n":"第十六条","txt":"全国人民代表大会主席团，全国人民代表大会常务委员会，全国人民代表大会各专门委员会，国务院，中央军事委员会，国家监察委员会，最高人民法院，最高人民检察院，可以向全国人民代表大会提出属于全国人民代表大会职权范围内的议案。"},{"i":17,"n":"第十七条","txt":"一个代表团或者三十名以上的代表联名，可以向全国人民代表大会提出属于全国人民代表大会职权范围内的议案。"},{"i":18,"n":"第十八条","txt":"全国人民代表大会常务委员会委员长、副委员长、秘书长、委员的人选，中华人民共和国主席、副主席的人选，中央军事委员会主席的人选，国家监察委员会主任的人选，最高人民法院院长和最高人民检察院检察长的人选，由主席团提名，经各代表团酝酿协商后，再由主席团根据多数代表的意见确定正式候选人名单。"},{"i":19,"n":"第十九条","txt":"国务院总理和国务院其他组成人员的人选、中央军事委员会除主席以外的其他组成人员的人选，依照宪法的有关规定提名。"},{"i":20,"n":"第二十条","txt":"全国人民代表大会主席团、三个以上的代表团或者十分之一以上的代表，可以提出对全国人民代表大会常务委员会的组成人员，中华人民共和国主席、副主席，国务院和中央军事委员会的组成人员，国家监察委员会主任，最高人民法院院长和最高人民检察院检察长的罢免案，由主席团提请大会审议。"},{"i":21,"n":"第二十一条","txt":"全国人民代表大会会议期间，一个代表团或者三十名以上的代表联名，可以书面提出对国务院以及国务院各部门、国家监察委员会、最高人民法院、最高人民检察院的质询案。"},{"i":22,"n":"第二十二条","txt":"全国人民代表大会常务委员会对全国人民代表大会负责并报告工作。"},{"i":23,"n":"第二十三条","txt":"全国人民代表大会常务委员会由下列人员组成："},{"i":24,"n":"第二十四条","txt":"常务委员会委员长主持常务委员会会议和常务委员会的工作。副委员长、秘书长协助委员长工作。副委员长受委员长的委托，可以代行委员长的部分职权。"},{"i":25,"n":"第二十五条","txt":"常务委员会的委员长、副委员长、秘书长组成委员长会议，处理常务委员会的重要日常工作："},{"i":26,"n":"第二十六条","txt":"常务委员会设立代表资格审查委员会。"},{"i":27,"n":"第二十七条","txt":"常务委员会设立办公厅，在秘书长领导下工作。"},{"i":28,"n":"第二十八条","txt":"常务委员会设立法制工作委员会、预算工作委员会和其他需要设立的工作委员会。"},{"i":29,"n":"第二十九条","txt":"委员长会议，全国人民代表大会各专门委员会，国务院，中央军事委员会，国家监察委员会，最高人民法院，最高人民检察院，常务委员会组成人员十人以上联名，可以向常务委员会提出属于常务委员会职权范围内的议案。"},{"i":30,"n":"第三十条","txt":"常务委员会会议期间，常务委员会组成人员十人以上联名，可以向常务委员会书面提出对国务院以及国务院各部门、国家监察委员会、最高人民法院、最高人民检察院的质询案。"},{"i":31,"n":"第三十一条","txt":"常务委员会在全国人民代表大会闭会期间，根据国务院总理的提名，可以决定国务院其他组成人员的任免；根据中央军事委员会主席的提名，可以决定中央军事委员会其他组成人员的任免。"},{"i":32,"n":"第三十二条","txt":"常务委员会在全国人民代表大会闭会期间，根据委员长会议、国务院总理的提请，可以决定撤销国务院其他个别组成人员的职务；根据中央军事委员会主席的提请，可以决定撤销中央军事委员会其他个别组成人员的职务。"},{"i":33,"n":"第三十三条","txt":"常务委员会在全国人民代表大会每次会议举行的时候，必须向全国人民代表大会提出工作报告。"},{"i":34,"n":"第三十四条","txt":"全国人民代表大会设立民族委员会、宪法和法律委员会、监察和司法委员会、财政经济委员会、教育科学文化卫生委员会、外事委员会、华侨委员会、环境与资源保护委员会、农业与农村委员会、社会建设委员会和全国人民代表大会认为需要设立的其他专门委员会。各专门委员会受全国人民代表大会领导；在全国人民代表大会闭会期间，受全国人民代表大会常务委员会领导。"},{"i":35,"n":"第三十五条","txt":"各专门委员会每届任期同全国人民代表大会每届任期相同，履行职责到下届全国人民代表大会产生新的专门委员会为止。"},{"i":36,"n":"第三十六条","txt":"各专门委员会主任委员主持委员会会议和委员会的工作。副主任委员协助主任委员工作。"},{"i":37,"n":"第三十七条","txt":"各专门委员会的工作如下："},{"i":38,"n":"第三十八条","txt":"民族委员会可以对加强民族团结问题进行调查研究，提出建议；审议自治区报请全国人民代表大会常务委员会批准的自治区的自治条例和单行条例，向全国人民代表大会常务委员会提出报告。"},{"i":39,"n":"第三十九条","txt":"宪法和法律委员会承担推动宪法实施、开展宪法解释、推进合宪性审查、加强宪法监督、配合宪法宣传等工作职责。"},{"i":40,"n":"第四十条","txt":"财政经济委员会对国务院提出的国民经济和社会发展计划草案、规划纲要草案、中央和地方预算草案、中央决算草案以及相关报告和调整方案进行审查，提出初步审查意见、审查结果报告；其他专门委员会可以就有关草案和报告向财政经济委员会提出意见。"},{"i":41,"n":"第四十一条","txt":"全国人民代表大会或者全国人民代表大会常务委员会可以组织对于特定问题的调查委员会。调查委员会的组织和工作，由全国人民代表大会或者全国人民代表大会常务委员会决定。"},{"i":42,"n":"第四十二条","txt":"全国人民代表大会代表每届任期五年，从每届全国人民代表大会举行第一次会议开始，到下届全国人民代表大会举行第一次会议为止。"},{"i":43,"n":"第四十三条","txt":"全国人民代表大会代表必须模范地遵守宪法和法律，保守国家秘密，并且在自己参加的生产、工作和社会活动中，协助宪法和法律的实施。"},{"i":44,"n":"第四十四条","txt":"全国人民代表大会代表应当同原选举单位和人民保持密切联系，可以列席原选举单位的人民代表大会会议，通过多种方式听取和反映人民的意见和要求，努力为人民服务，充分发挥在全过程民主中的作用。"},{"i":45,"n":"第四十五条","txt":"全国人民代表大会常务委员会和各专门委员会、工作委员会应当同代表保持密切联系，听取代表的意见和建议，支持和保障代表依法履职，扩大代表对各项工作的参与，充分发挥代表作用。"},{"i":46,"n":"第四十六条","txt":"全国人民代表大会代表向全国人民代表大会或者全国人民代表大会常务委员会提出的对各方面工作的建议、批评和意见，由全国人民代表大会常务委员会办事机构交由有关机关、组织研究办理并负责答复。"},{"i":47,"n":"第四十七条","txt":"全国人民代表大会代表在出席全国人民代表大会会议和执行其他属于代表的职务的时候，国家根据实际需要给予适当的补贴和物质上的便利。"},{"i":48,"n":"第四十八条","txt":"全国人民代表大会代表、全国人民代表大会常务委员会的组成人员，在全国人民代表大会和全国人民代表大会常务委员会各种会议上的发言和表决，不受法律追究。"},{"i":49,"n":"第四十九条","txt":"全国人民代表大会代表非经全国人民代表大会主席团许可，在全国人民代表大会闭会期间非经全国人民代表大会常务委员会许可，不受逮捕或者刑事审判。"}],"quanguorenmindaibiaodahuiyishiguize":[{"i":1,"n":"第二条","txt":"全国人民代表大会会议于每年第一季度举行，会议召开的日期由全国人民代表大会常务委员会决定并予以公布。"},{"i":2,"n":"第三条","txt":"全国人民代表大会会议由全国人民代表大会常务委员会召集。每届全国人民代表大会第一次会议，在本届全国人民代表大会代表选举完成后的两个月内，由上届全国人民代表大会常务委员会召集。"},{"i":3,"n":"第四条","txt":"全国人民代表大会会议有三分之二以上的代表出席，始得举行。"},{"i":4,"n":"第五条","txt":"全国人民代表大会常务委员会在全国人民代表大会会议举行前，进行下列准备工作："},{"i":5,"n":"第六条","txt":"全国人民代表大会常务委员会在全国人民代表大会会议举行的一个月前，将开会日期和建议会议讨论的主要事项通知代表，并将准备提请会议审议的法律草案发给代表。"},{"i":6,"n":"第七条","txt":"全国人民代表大会会议举行前，代表按照选举单位组成代表团。代表团全体会议推选代表团团长、副团长。团长召集并主持代表团全体会议。副团长协助团长工作。"},{"i":7,"n":"第八条","txt":"全国人民代表大会会议举行前，召开预备会议，选举主席团和秘书长，通过会议议程和关于会议其他准备事项的决定。"},{"i":8,"n":"第九条","txt":"主席团主持全国人民代表大会会议。"},{"i":9,"n":"第十条","txt":"主席团第一次会议推选主席团常务主席若干人，推选主席团成员若干人分别担任每次大会全体会议的执行主席，并决定下列事项："},{"i":10,"n":"第十一条","txt":"主席团常务主席召集并主持主席团会议。主席团第一次会议由全国人民代表大会常务委员会委员长召集并主持，会议推选主席团常务主席后，由主席团常务主席主持。"},{"i":11,"n":"第十二条","txt":"代表团审议议案和有关报告，由代表团全体会议、代表小组会议审议。"},{"i":12,"n":"第十三条","txt":"主席团常务主席可以召开代表团团长会议，就议案和有关报告的重大问题听取各代表团的审议意见，进行讨论，并将讨论的情况和意见向主席团报告。"},{"i":13,"n":"第十四条","txt":"主席团可以召开大会全体会议进行大会发言，就议案和有关报告发表意见。"},{"i":14,"n":"第十五条","txt":"全国人民代表大会代表应当出席会议；因病或者其他特殊原因不能出席的，应当向会议秘书处书面请假。秘书处应当向主席团报告代表出席会议的情况和缺席的原因。"},{"i":15,"n":"第十六条","txt":"国务院的组成人员，中央军事委员会的组成人员，国家监察委员会主任，最高人民法院院长和最高人民检察院检察长，列席全国人民代表大会会议；其他有关机关、团体的负责人，经全国人民代表大会常务委员会决定，可以列席全国人民代表大会会议。"},{"i":16,"n":"第十七条","txt":"全国人民代表大会会议公开举行。"},{"i":17,"n":"第十八条","txt":"全国人民代表大会会议举行新闻发布会、记者会。"},{"i":18,"n":"第十九条","txt":"全国人民代表大会在必要的时候，可以举行秘密会议。举行秘密会议，经主席团征求各代表团的意见后，由有各代表团团长参加的主席团会议决定。"},{"i":19,"n":"第二十条","txt":"全国人民代表大会举行会议的时候，秘书处和有关的代表团应当为少数民族代表准备必要的翻译。"},{"i":20,"n":"第二十一条","txt":"全国人民代表大会举行会议，应当合理安排会议日程，提高议事质量和效率。"},{"i":21,"n":"第二十二条","txt":"全国人民代表大会会议运用现代信息技术，推进会议文件资料电子化，采用网络视频等方式为代表履职提供便利和服务。"},{"i":22,"n":"第二十三条","txt":"主席团，全国人民代表大会常务委员会，全国人民代表大会各专门委员会，国务院，中央军事委员会，国家监察委员会，最高人民法院，最高人民检察院，可以向全国人民代表大会提出属于全国人民代表大会职权范围内的议案，由主席团决定列入会议议程。"},{"i":23,"n":"第二十四条","txt":"列入会议议程的议案，提案人和有关的全国人民代表大会专门委员会、有关的全国人民代表大会常务委员会工作部门应当提供有关的资料。"},{"i":24,"n":"第二十五条","txt":"列入会议议程的议案，提案人应当向会议提出关于议案的说明。议案由各代表团进行审议，主席团可以并交有关的专门委员会进行审议、提出报告，由主席团审议决定提请大会全体会议表决。"},{"i":25,"n":"第二十六条","txt":"列入会议议程的法律案，大会全体会议听取关于该法律案的说明后，由各代表团审议，并由宪法和法律委员会、有关的专门委员会审议。"},{"i":26,"n":"第二十七条","txt":"向全国人民代表大会提出的法律案，在全国人民代表大会闭会期间，可以先向全国人民代表大会常务委员会提出，经全国人民代表大会常务委员会会议依照有关程序审议后，决定提请全国人民代表大会审议。"},{"i":27,"n":"第二十八条","txt":"专门委员会审议议案和有关报告，涉及专门性问题的时候，可以邀请有关方面的代表和专家列席会议，发表意见。"},{"i":28,"n":"第二十九条","txt":"列入会议议程的议案，在交付表决前，提案人要求撤回的，经主席团同意，会议对该议案的审议即行终止。"},{"i":29,"n":"第三十条","txt":"列入会议议程的议案，在审议中有重大问题需要进一步研究的，经主席团提出，由大会全体会议决定，可以授权全国人民代表大会常务委员会审议决定，并报全国人民代表大会下次会议备案或者提请全国人民代表大会下次会议审议。"},{"i":30,"n":"第三十一条","txt":"一个代表团或者三十名以上的代表联名提出的议案，经主席团决定不列入本次会议议程的，交有关的专门委员会在全国人民代表大会闭会后审议。有关的专门委员会进行审议后，向全国人民代表大会常务委员会提出审议结果报告，经全国人民代表大会常务委员会审议通过后，印发全国人民代表大会下次会议。"},{"i":31,"n":"第三十二条","txt":"全国人民代表大会代表向全国人民代表大会提出的对各方面工作的建议、批评和意见，由全国人民代表大会常务委员会办事机构交由有关机关、组织研究办理，并负责在交办之日起三个月内，至迟不超过六个月，予以答复。代表对答复不满意的，可以提出意见，由全国人民代表大会常务委员会办事机构交由有关机关、组织或者其上级机关、组织再作研究办理，并负责答复。"},{"i":32,"n":"第三十三条","txt":"全国人民代表大会每年举行会议的时候，全国人民代表大会常务委员会、国务院、最高人民法院、最高人民检察院向会议提出的工作报告，经各代表团审议后，会议可以作出相应的决议。"},{"i":33,"n":"第三十四条","txt":"全国人民代表大会会议举行的四十五日前，国务院有关主管部门应当就上一年度国民经济和社会发展计划执行情况的主要内容与本年度国民经济和社会发展计划草案的初步方案，上一年度中央和地方预算执行情况的主要内容与本年度中央和地方预算草案的初步方案，向全国人民代表大会财政经济委员会和有关的专门委员会汇报，由财政经济委员会进行初步审查。财政经济委员会进行初步审查时，应当邀请全国人民代表大会代表参加。"},{"i":34,"n":"第三十五条","txt":"全国人民代表大会每年举行会议的时候，国务院应当向会议提出关于上一年度国民经济和社会发展计划执行情况与本年度国民经济和社会发展计划草案的报告、国民经济和社会发展计划草案，关于上一年度中央和地方预算执行情况与本年度中央和地方预算草案的报告、中央和地方预算草案，由各代表团进行审查，并由财政经济委员会和有关的专门委员会审查。"},{"i":35,"n":"第三十六条","txt":"国民经济和社会发展计划、中央预算经全国人民代表大会批准后，在执行过程中必须作部分调整的，国务院应当将调整方案提请全国人民代表大会常务委员会审查和批准。"},{"i":36,"n":"第三十七条","txt":"国民经济和社会发展五年规划纲要和中长期规划纲要的审查、批准和调整，参照本章有关规定执行。"},{"i":37,"n":"第三十八条","txt":"全国人民代表大会常务委员会委员长、副委员长、秘书长、委员的人选，中华人民共和国主席、副主席的人选，中央军事委员会主席的人选，国家监察委员会主任的人选，最高人民法院院长和最高人民检察院检察长的人选，由主席团提名，经各代表团酝酿协商后，再由主席团根据多数代表的意见，确定正式候选人名单。"},{"i":38,"n":"第三十九条","txt":"候选人的提名人应当向会议介绍候选人的基本情况，并对代表提出的问题作必要的说明。"},{"i":39,"n":"第四十条","txt":"全国人民代表大会会议选举或者决定任命，采用无记名投票方式。得票数超过全体代表的半数的，始得当选或者通过。"},{"i":40,"n":"第四十一条","txt":"全国人民代表大会会议选举和决定任命的具体办法，由大会全体会议通过。"},{"i":41,"n":"第四十二条","txt":"全国人民代表大会选举或者决定任命的国家机构组成人员在依照法定程序产生后，公开进行宪法宣誓。宣誓仪式由主席团组织。"},{"i":42,"n":"第四十三条","txt":"全国人民代表大会会议期间，全国人民代表大会常务委员会的组成人员，中华人民共和国主席、副主席，国务院的组成人员，中央军事委员会的组成人员，国家监察委员会主任，最高人民法院院长，最高人民检察院检察长，全国人民代表大会专门委员会成员提出辞职的，由主席团将其辞职请求交各代表团审议后，提请大会全体会议决定；大会闭会期间提出辞职的，由委员长会议将其辞职请求提请全国人民代表大会常务委员会审议决定。"},{"i":43,"n":"第四十四条","txt":"主席团、三个以上的代表团或者十分之一以上的代表，可以提出对全国人民代表大会常务委员会的组成人员，中华人民共和国主席、副主席，国务院的组成人员，中央军事委员会的组成人员，国家监察委员会主任，最高人民法院院长和最高人民检察院检察长的罢免案，由主席团交各代表团审议后，提请大会全体会议表决；或者依照本规则第六章的规定，由主席团提议，经大会全体会议决定，组织调查委员会，由全国人民代表大会下次会议根据调查委员会的报告审议决定。"},{"i":44,"n":"第四十五条","txt":"全国人民代表大会常务委员会组成人员、专门委员会成员的全国人民代表大会代表职务被原选举单位罢免的，其全国人民代表大会常务委员会组成人员、专门委员会成员的职务相应撤销，由主席团或者全国人民代表大会常务委员会予以公告。"},{"i":45,"n":"第四十六条","txt":"全国人民代表大会常务委员会组成人员、专门委员会成员，辞去全国人民代表大会代表职务的请求被接受的，其全国人民代表大会常务委员会组成人员、专门委员会成员的职务相应终止，由全国人民代表大会常务委员会予以公告。"},{"i":46,"n":"第四十七条","txt":"各代表团审议议案和有关报告的时候，有关部门应当派负责人员到会，听取意见，回答代表提出的询问。"},{"i":47,"n":"第四十八条","txt":"全国人民代表大会会议期间，一个代表团或者三十名以上的代表联名，可以书面提出对国务院以及国务院各部门、国家监察委员会、最高人民法院、最高人民检察院的质询案。"},{"i":48,"n":"第四十九条","txt":"质询案必须写明质询对象、质询的问题和内容。"},{"i":49,"n":"第五十条","txt":"质询案按照主席团的决定由受质询机关的负责人在主席团会议、有关的专门委员会会议或者有关的代表团会议上口头答复，或者由受质询机关书面答复。在主席团会议或者专门委员会会议上答复的，提质询案的代表团团长或者代表有权列席会议，发表意见。"},{"i":50,"n":"第五十一条","txt":"全国人民代表大会认为必要的时候，可以组织关于特定问题的调查委员会。"},{"i":51,"n":"第五十二条","txt":"主席团、三个以上的代表团或者十分之一以上的代表联名，可以提议组织关于特定问题的调查委员会，由主席团提请大会全体会议决定。"},{"i":52,"n":"第五十三条","txt":"调查委员会进行调查的时候，一切有关的国家机关、社会团体和公民都有义务如实向它提供必要的材料。提供材料的公民要求调查委员会对材料来源保密的，调查委员会应当予以保密。"},{"i":53,"n":"第五十四条","txt":"调查委员会应当向全国人民代表大会提出调查报告。全国人民代表大会根据调查委员会的报告，可以作出相应的决议。"},{"i":54,"n":"第五十五条","txt":"全国人民代表大会代表在全国人民代表大会各种会议上的发言和表决，不受法律追究。"},{"i":55,"n":"第五十六条","txt":"代表在全国人民代表大会各种会议上发言，应当围绕会议确定的议题进行。"},{"i":56,"n":"第五十七条","txt":"代表在大会全体会议上发言的，每人可以发言两次，第一次不超过十分钟，第二次不超过五分钟。"},{"i":57,"n":"第五十八条","txt":"主席团成员和代表团团长或者代表团推选的代表在主席团每次会议上发言的，每人可以就同一议题发言两次，第一次不超过十五分钟，第二次不超过十分钟。经会议主持人许可，发言时间可以适当延长。"},{"i":58,"n":"第五十九条","txt":"大会全体会议表决议案，由全体代表的过半数通过。"},{"i":59,"n":"第六十条","txt":"会议表决议案采用无记名按表决器方式。如表决器系统在使用中发生故障，采用举手方式。"},{"i":60,"n":"第六十一条","txt":"全国人民代表大会选举产生的全国人民代表大会常务委员会委员长、副委员长、秘书长、委员，中华人民共和国主席、副主席，中央军事委员会主席，国家监察委员会主任，最高人民法院院长，最高人民检察院检察长，决定任命的中央军事委员会副主席、委员，通过的全国人民代表大会专门委员会成员，以全国人民代表大会公告予以公布。"},{"i":61,"n":"第六十二条","txt":"国家机构组成人员在全国人民代表大会会议期间辞职或者被罢免的，适用本规则第六十一条规定的公布程序。"},{"i":62,"n":"第六十三条","txt":"全国人民代表大会通过的宪法修正案，以全国人民代表大会公告予以公布。"},{"i":63,"n":"第六十四条","txt":"全国人民代表大会通过的法律，由中华人民共和国主席签署主席令予以公布。"},{"i":64,"n":"第六十五条","txt":"全国人民代表大会通过的法律、决议、决定，发布的公告，以及法律草案的说明、审议结果报告等，应当及时在全国人民代表大会常务委员会公报和中国人大网上刊载。"},{"i":65,"n":"第六十六条","txt":"本规则自公布之日起施行。"}],"gongzhirenyuanzhengwuchufenfa":[{"i":1,"n":"第一条","txt":"为了规范政务处分，加强对所有行使公权力的公职人员的监督，促进公职人员依法履职、秉公用权、廉洁从政从业、坚持道德操守，根据《中华人民共和国监察法》，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于监察机关对违法的公职人员给予政务处分的活动。"},{"i":3,"n":"第三条","txt":"监察机关应当按照管理权限，加强对公职人员的监督，依法给予违法的公职人员政务处分。"},{"i":4,"n":"第四条","txt":"给予公职人员政务处分，坚持党管干部原则，集体讨论决定；坚持法律面前一律平等，以事实为根据，以法律为准绳，给予的政务处分与违法行为的性质、情节、危害程度相当；坚持惩戒与教育相结合，宽严相济。"},{"i":5,"n":"第五条","txt":"给予公职人员政务处分，应当事实清楚、证据确凿、定性准确、处理恰当、程序合法、手续完备。"},{"i":6,"n":"第六条","txt":"公职人员依法履行职责受法律保护，非因法定事由、非经法定程序，不受政务处分。"},{"i":7,"n":"第七条","txt":"政务处分的种类为："},{"i":8,"n":"第八条","txt":"政务处分的期间为："},{"i":9,"n":"第九条","txt":"公职人员二人以上共同违法，根据各自在违法行为中所起的作用和应当承担的法律责任，分别给予政务处分。"},{"i":10,"n":"第十条","txt":"有关机关、单位、组织集体作出的决定违法或者实施违法行为的，对负有责任的领导人员和直接责任人员中的公职人员依法给予政务处分。"},{"i":11,"n":"第十一条","txt":"公职人员有下列情形之一的，可以从轻或者减轻给予政务处分："},{"i":12,"n":"第十二条","txt":"公职人员违法行为情节轻微，且具有本法第十一条规定的情形之一的，可以对其进行谈话提醒、批评教育、责令检查或者予以诫勉，免予或者不予政务处分。"},{"i":13,"n":"第十三条","txt":"公职人员有下列情形之一的，应当从重给予政务处分："},{"i":14,"n":"第十四条","txt":"公职人员犯罪，有下列情形之一的，予以开除："},{"i":15,"n":"第十五条","txt":"公职人员有两个以上违法行为的，应当分别确定政务处分。应当给予两种以上政务处分的，执行其中最重的政务处分；应当给予撤职以下多个相同政务处分的，可以在一个政务处分期以上、多个政务处分期之和以下确定政务处分期，但是最长不得超过四十八个月。"},{"i":16,"n":"第十六条","txt":"对公职人员的同一违法行为，监察机关和公职人员任免机关、单位不得重复给予政务处分和处分。"},{"i":17,"n":"第十七条","txt":"公职人员有违法行为，有关机关依照规定给予组织处理的，监察机关可以同时给予政务处分。"},{"i":18,"n":"第十八条","txt":"担任领导职务的公职人员有违法行为，被罢免、撤销、免去或者辞去领导职务的，监察机关可以同时给予政务处分。"},{"i":19,"n":"第十九条","txt":"公务员以及参照《中华人民共和国公务员法》管理的人员在政务处分期内，不得晋升职务、职级、衔级和级别；其中，被记过、记大过、降级、撤职的，不得晋升工资档次。被撤职的，按照规定降低职务、职级、衔级和级别，同时降低工资和待遇。"},{"i":20,"n":"第二十条","txt":"法律、法规授权或者受国家机关依法委托管理公共事务的组织中从事公务的人员，以及公办的教育、科研、文化、医疗卫生、体育等单位中从事管理的人员，在政务处分期内，不得晋升职务、岗位和职员等级、职称；其中，被记过、记大过、降级、撤职的，不得晋升薪酬待遇等级。被撤职的，降低职务、岗位或者职员等级，同时降低薪酬待遇。"},{"i":21,"n":"第二十一条","txt":"国有企业管理人员在政务处分期内，不得晋升职务、岗位等级和职称；其中，被记过、记大过、降级、撤职的，不得晋升薪酬待遇等级。被撤职的，降低职务或者岗位等级，同时降低薪酬待遇。"},{"i":22,"n":"第二十二条","txt":"基层群众性自治组织中从事管理的人员有违法行为的，监察机关可以予以警告、记过、记大过。"},{"i":23,"n":"第二十三条","txt":"《中华人民共和国监察法》第十五条第六项规定的人员有违法行为的，监察机关可以予以警告、记过、记大过。情节严重的，由所在单位直接给予或者监察机关建议有关机关、单位给予降低薪酬待遇、调离岗位、解除人事关系或者劳动关系等处理。"},{"i":24,"n":"第二十四条","txt":"公职人员被开除，或者依照本法第二十三条规定，受到解除人事关系或者劳动关系处理的，不得录用为公务员以及参照《中华人民共和国公务员法》管理的人员。"},{"i":25,"n":"第二十五条","txt":"公职人员违法取得的财物和用于违法行为的本人财物，除依法应当由其他机关没收、追缴或者责令退赔的，由监察机关没收、追缴或者责令退赔；应当退还原所有人或者原持有人的，依法予以退还；属于国家财产或者不应当退还以及无法退还的，上缴国库。"},{"i":26,"n":"第二十六条","txt":"公职人员被开除的，自政务处分决定生效之日起，应当解除其与所在机关、单位的人事关系或者劳动关系。"},{"i":27,"n":"第二十七条","txt":"已经退休的公职人员退休前或者退休后有违法行为的，不再给予政务处分，但是可以对其立案调查；依法应当予以降级、撤职、开除的，应当按照规定相应调整其享受的待遇，对其违法取得的财物和用于违法行为的本人财物依照本法第二十五条的规定处理。"},{"i":28,"n":"第二十八条","txt":"有下列行为之一的，予以记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除："},{"i":29,"n":"第二十九条","txt":"不按照规定请示、报告重大事项，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职："},{"i":31,"n":"第三十一条","txt":"违反规定出境或者办理因私出境证件的，予以记过或者记大过；情节严重的，予以降级或者撤职。"},{"i":32,"n":"第三十二条","txt":"有下列行为之一的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除："},{"i":33,"n":"第三十三条","txt":"有下列行为之一的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除："},{"i":34,"n":"第三十四条","txt":"收受可能影响公正行使公权力的礼品、礼金、有价证券等财物的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":35,"n":"第三十五条","txt":"有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职："},{"i":36,"n":"第三十六条","txt":"违反规定从事或者参与营利性活动，或者违反规定兼任职务、领取报酬的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":37,"n":"第三十七条","txt":"利用宗族或者黑恶势力等欺压群众，或者纵容、包庇黑恶势力活动的，予以撤职；情节严重的，予以开除。"},{"i":38,"n":"第三十八条","txt":"有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职："},{"i":39,"n":"第三十九条","txt":"有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除："},{"i":40,"n":"第四十条","txt":"有下列行为之一的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除："},{"i":41,"n":"第四十一条","txt":"公职人员有其他违法行为，影响公职人员形象，损害国家和人民利益的，可以根据情节轻重给予相应政务处分。"},{"i":42,"n":"第四十二条","txt":"监察机关对涉嫌违法的公职人员进行调查，应当由二名以上工作人员进行。监察机关进行调查时，有权依法向有关单位和个人了解情况，收集、调取证据。有关单位和个人应当如实提供情况。"},{"i":43,"n":"第四十三条","txt":"作出政务处分决定前，监察机关应当将调查认定的违法事实及拟给予政务处分的依据告知被调查人，听取被调查人的陈述和申辩，并对其陈述的事实、理由和证据进行核实，记录在案。被调查人提出的事实、理由和证据成立的，应予采纳。不得因被调查人的申辩而加重政务处分。"},{"i":44,"n":"第四十四条","txt":"调查终结后，监察机关应当根据下列不同情况，分别作出处理："},{"i":45,"n":"第四十五条","txt":"决定给予政务处分的，应当制作政务处分决定书。"},{"i":46,"n":"第四十六条","txt":"政务处分决定书应当及时送达被处分人和被处分人所在机关、单位，并在一定范围内宣布。"},{"i":47,"n":"第四十七条","txt":"参与公职人员违法案件调查、处理的人员有下列情形之一的，应当自行回避，被调查人、检举人及其他有关人员也有权要求其回避："},{"i":48,"n":"第四十八条","txt":"监察机关负责人的回避，由上级监察机关决定；其他参与违法案件调查、处理人员的回避，由监察机关负责人决定。"},{"i":49,"n":"第四十九条","txt":"公职人员依法受到刑事责任追究的，监察机关应当根据司法机关的生效判决、裁定、决定及其认定的事实和情节，依照本法规定给予政务处分。"},{"i":50,"n":"第五十条","txt":"监察机关对经各级人民代表大会、县级以上各级人民代表大会常务委员会选举或者决定任命的公职人员予以撤职、开除的，应当先依法罢免、撤销或者免去其职务，再依法作出政务处分决定。"},{"i":51,"n":"第五十一条","txt":"下级监察机关根据上级监察机关的指定管辖决定进行调查的案件，调查终结后，对不属于本监察机关管辖范围内的监察对象，应当交有管理权限的监察机关依法作出政务处分决定。"},{"i":52,"n":"第五十二条","txt":"公职人员涉嫌违法，已经被立案调查，不宜继续履行职责的，公职人员任免机关、单位可以决定暂停其履行职务。"},{"i":53,"n":"第五十三条","txt":"监察机关在调查中发现公职人员受到不实检举、控告或者诬告陷害，造成不良影响的，应当按照规定及时澄清事实，恢复名誉，消除不良影响。"},{"i":54,"n":"第五十四条","txt":"公职人员受到政务处分的，应当将政务处分决定书存入其本人档案。对于受到降级以上政务处分的，应当由人事部门按照管理权限在作出政务处分决定后一个月内办理职务、工资及其他有关待遇等的变更手续；特殊情况下，经批准可以适当延长办理期限，但是最长不得超过六个月。"},{"i":55,"n":"第五十五条","txt":"公职人员对监察机关作出的涉及本人的政务处分决定不服的，可以依法向作出决定的监察机关申请复审；公职人员对复审决定仍不服的，可以向上一级监察机关申请复核。"},{"i":56,"n":"第五十六条","txt":"复审、复核期间，不停止原政务处分决定的执行。"},{"i":57,"n":"第五十七条","txt":"有下列情形之一的，复审、复核机关应当撤销原政务处分决定，重新作出决定或者责令原作出决定的监察机关重新作出决定："},{"i":58,"n":"第五十八条","txt":"有下列情形之一的，复审、复核机关应当变更原政务处分决定，或者责令原作出决定的监察机关予以变更："},{"i":59,"n":"第五十九条","txt":"复审、复核机关认为政务处分决定认定事实清楚，适用法律正确的，应当予以维持。"},{"i":60,"n":"第六十条","txt":"公职人员的政务处分决定被变更，需要调整该公职人员的职务、职级、衔级、级别、岗位和职员等级或者薪酬待遇等的，应当按照规定予以调整。政务处分决定被撤销的，应当恢复该公职人员的级别、薪酬待遇，按照原职务、职级、衔级、岗位和职员等级安排相应的职务、职级、衔级、岗位和职员等级，并在原政务处分决定公布范围内为其恢复名誉。没收、追缴财物错误的，应当依法予以返还、赔偿。"},{"i":61,"n":"第六十一条","txt":"有关机关、单位无正当理由拒不采纳监察建议的，由其上级机关、主管部门责令改正，对该机关、单位给予通报批评，对负有责任的领导人员和直接责任人员依法给予处理。"},{"i":62,"n":"第六十二条","txt":"有关机关、单位、组织或者人员有下列情形之一的，由其上级机关，主管部门，任免机关、单位或者监察机关责令改正，依法给予处理："},{"i":63,"n":"第六十三条","txt":"监察机关及其工作人员有下列情形之一的，对负有责任的领导人员和直接责任人员依法给予处理："},{"i":64,"n":"第六十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"国务院及其相关主管部门根据本法的原则和精神，结合事业单位、国有企业等的实际情况，对事业单位、国有企业等的违法的公职人员处分事宜作出具体规定。"},{"i":66,"n":"第六十六条","txt":"中央军事委员会可以根据本法制定相关具体规定。"},{"i":67,"n":"第六十七条","txt":"本法施行前，已结案的案件如果需要复审、复核，适用当时的规定。尚未结案的案件，如果行为发生时的规定不认为是违法的，适用当时的规定；如果行为发生时的规定认为是违法的，依照当时的规定处理，但是如果本法不认为是违法或者根据本法处理较轻的，适用本法。"},{"i":68,"n":"第六十八条","txt":"本法自2020年7月1日起施行。"}],"fanwaiguozhicaifa":[{"i":1,"n":"第一条","txt":"为了维护国家主权、安全、发展利益，保护我国公民、组织的合法权益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国坚持独立自主的和平外交政策，坚持互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处的五项原则，维护以联合国为核心的国际体系和以国际法为基础的国际秩序，发展同世界各国的友好合作，推动构建人类命运共同体。"},{"i":3,"n":"第三条","txt":"中华人民共和国反对霸权主义和强权政治，反对任何国家以任何借口、任何方式干涉中国内政。"},{"i":4,"n":"第四条","txt":"国务院有关部门可以决定将直接或者间接参与制定、决定、实施本法第三条规定的歧视性限制措施的个人、组织列入反制清单。"},{"i":5,"n":"第五条","txt":"除根据本法第四条规定列入反制清单的个人、组织以外，国务院有关部门还可以决定对下列个人、组织采取反制措施："},{"i":6,"n":"第六条","txt":"国务院有关部门可以按照各自职责和任务分工，对本法第四条、第五条规定的个人、组织，根据实际情况决定采取下列一种或者几种措施："},{"i":7,"n":"第七条","txt":"国务院有关部门依据本法第四条至第六条规定作出的决定为最终决定。"},{"i":8,"n":"第八条","txt":"采取反制措施所依据的情形发生变化的，国务院有关部门可以暂停、变更或者取消有关反制措施。"},{"i":9,"n":"第九条","txt":"反制清单和反制措施的确定、暂停、变更或者取消，由外交部或者国务院其他有关部门发布命令予以公布。"},{"i":10,"n":"第十条","txt":"国家设立反外国制裁工作协调机制，负责统筹协调相关工作。"},{"i":11,"n":"第十一条","txt":"我国境内的组织和个人应当执行国务院有关部门采取的反制措施。"},{"i":12,"n":"第十二条","txt":"任何组织和个人均不得执行或者协助执行外国国家对我国公民、组织采取的歧视性限制措施。"},{"i":13,"n":"第十三条","txt":"对于危害我国主权、安全、发展利益的行为，除本法规定外，有关法律、行政法规、部门规章可以规定采取其他必要的反制措施。"},{"i":14,"n":"第十四条","txt":"任何组织和个人不执行、不配合实施反制措施的，依法追究法律责任。"},{"i":15,"n":"第十五条","txt":"对于外国国家、组织或者个人实施、协助、支持危害我国主权、安全、发展利益的行为，需要采取必要反制措施的，参照本法有关规定执行。"},{"i":16,"n":"第十六条","txt":"本法自公布之日起施行。"}],"gejirenmindaibiaodahuichangwuweiyuanhuijiandufa":[{"i":1,"n":"第一条","txt":"为了保障全国人民代表大会常务委员会和县级以上地方各级人民代表大会常务委员会依法行使监督职权，坚持好、完善好、运行好人民代表大会制度，发展社会主义民主政治，推进全面依法治国，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"各级人民代表大会常务委员会依据宪法和有关法律的规定，行使监督职权。"},{"i":3,"n":"第三条","txt":"各级人民代表大会常务委员会行使监督职权，应当坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持中国特色社会主义道路，确保宪法和法律、法规得到全面有效实施，确保行政权、监察权、审判权、检察权依法正确行使。"},{"i":4,"n":"第四条","txt":"各级人民代表大会常务委员会行使监督职权，应当围绕党和国家工作大局，以经济建设为中心，坚持改革开放，贯彻新发展理念，推动高质量发展，保障全面建设社会主义现代化国家、以中国式现代化全面推进中华民族伟大复兴。"},{"i":5,"n":"第五条","txt":"全国人民代表大会常务委员会监督宪法和法律的实施，地方各级人民代表大会及其常务委员会在本行政区域内保证宪法、法律、行政法规和上级人民代表大会及其常务委员会决议的遵守和执行，维护国家法治统一、尊严、权威。"},{"i":6,"n":"第六条","txt":"各级人民代表大会常务委员会对本级人民政府、监察委员会、人民法院和人民检察院的工作实施监督，实行正确监督、有效监督、依法监督，促进依法行政、依法监察、公正司法。"},{"i":7,"n":"第七条","txt":"各级人民代表大会常务委员会行使监督职权，应当坚持和发展全过程人民民主，尊重和保障人权，维护和促进社会公平正义。"},{"i":8,"n":"第八条","txt":"各级人民代表大会常务委员会按照民主集中制的原则，集体行使监督职权。"},{"i":9,"n":"第九条","txt":"各级人民代表大会常务委员会行使监督职权的情况，应当向本级人民代表大会报告，接受监督。"},{"i":10,"n":"第十条","txt":"各级人民代表大会常务委员会行使监督职权的情况，向社会公开。"},{"i":11,"n":"第十一条","txt":"各级人民代表大会常务委员会每年选择若干关系改革发展稳定大局和群众切身利益、社会普遍关注的重大问题，有计划地安排听取和审议本级人民政府、监察委员会、人民法院和人民检察院的专项工作报告。"},{"i":12,"n":"第十二条","txt":"常务委员会听取和审议本级人民政府、监察委员会、人民法院和人民检察院的专项工作报告的议题，根据有关法律的规定和下列途径反映的问题确定："},{"i":13,"n":"第十三条","txt":"常务委员会听取和审议专项工作报告前，委员长会议或者主任会议可以组织本级人民代表大会常务委员会组成人员和本级人民代表大会代表，对有关工作进行视察或者专题调查研究。"},{"i":14,"n":"第十四条","txt":"常务委员会听取和审议专项工作报告前，常务委员会办事机构应当将各方面对该项工作的意见汇总，交由本级人民政府、监察委员会、人民法院或者人民检察院研究并在专项工作报告中作出回应。"},{"i":15,"n":"第十五条","txt":"人民政府、监察委员会、人民法院或者人民检察院应当在常务委员会举行会议的二十日前，由其办事机构将专项工作报告送交本级人民代表大会有关专门委员会或者常务委员会有关工作机构征求意见；人民政府、监察委员会、人民法院或者人民检察院对报告修改后，在常务委员会举行会议的十日前送交常务委员会。"},{"i":16,"n":"第十六条","txt":"专项工作报告由人民政府、监察委员会、人民法院或者人民检察院的负责人向本级人民代表大会常务委员会报告，人民政府也可以委托有关部门负责人向本级人民代表大会常务委员会报告。"},{"i":17,"n":"第十七条","txt":"常务委员会组成人员对专项工作报告的审议意见交由本级人民政府、监察委员会、人民法院或者人民检察院研究处理。人民政府、监察委员会、人民法院或者人民检察院应当将研究处理情况由其办事机构送交本级人民代表大会有关专门委员会或者常务委员会有关工作机构征求意见后，向常务委员会提出书面报告。常务委员会认为必要时，可以对专项工作报告作出决议；本级人民政府、监察委员会、人民法院或者人民检察院应当在决议规定的期限内，将执行决议的情况向常务委员会报告。"},{"i":18,"n":"第十八条","txt":"本法所称财政经济工作监督，是指常务委员会依法对下列事项进行监督："},{"i":19,"n":"第十九条","txt":"国务院应当在每年六月，将上一年度的中央决算草案提请全国人民代表大会常务委员会审查和批准。"},{"i":20,"n":"第二十条","txt":"国务院和县级以上地方各级人民政府应当在每年六月至九月期间，向本级人民代表大会常务委员会报告本年度上一阶段国民经济和社会发展计划、预算的执行情况。"},{"i":21,"n":"第二十一条","txt":"常务委员会根据《中华人民共和国预算法》和全国人民代表大会常务委员会的有关决定，确定对决算草案和预算执行情况报告的重点审查内容。"},{"i":22,"n":"第二十二条","txt":"国民经济和社会发展计划、预算经人民代表大会批准后，在执行过程中需要作部分调整的，国务院和县级以上地方各级人民政府应当将调整方案提请本级人民代表大会常务委员会审查和批准。"},{"i":23,"n":"第二十三条","txt":"国民经济和社会发展五年规划纲要经人民代表大会批准后，在实施的中期阶段，人民政府应当将规划纲要实施情况的中期评估报告提请本级人民代表大会常务委员会审议。规划纲要经中期评估需要调整的，人民政府应当将调整方案提请本级人民代表大会常务委员会审查和批准。"},{"i":24,"n":"第二十四条","txt":"常务委员会应当对国有资产管理情况进行监督，建立健全国有资产管理情况报告制度。"},{"i":25,"n":"第二十五条","txt":"常务委员会应当对政府债务进行监督，建立健全政府债务管理情况报告制度。"},{"i":26,"n":"第二十六条","txt":"常务委员会应当对金融工作进行监督，建立健全金融工作情况报告制度。"},{"i":27,"n":"第二十七条","txt":"常务委员会每年审查和批准决算的同时，听取和审议本级人民政府提出的审计机关关于上一年度预算执行和其他财政收支的审计工作报告。"},{"i":28,"n":"第二十八条","txt":"常务委员会开展财政经济工作监督，可以组织开展专题调查研究，提出报告。"},{"i":29,"n":"第二十九条","txt":"常务委员会组成人员对本章规定的有关报告的审议意见交由本级人民政府研究处理。人民政府应当将研究处理情况由其办事机构送交本级人民代表大会有关专门委员会或者常务委员会有关工作机构征求意见后，向常务委员会提出书面报告。常务委员会认为必要时，可以对有关报告作出决议；本级人民政府应当在决议规定的期限内，将执行决议的情况向常务委员会报告。"},{"i":30,"n":"第三十条","txt":"常务委员会运用现代信息技术开展联网监督，建立健全信息共享和工作贯通协调机制，提高财政经济工作监督效能。"},{"i":31,"n":"第三十一条","txt":"各级人民代表大会常务委员会参照本法第十二条规定的途径，每年选择若干关系改革发展稳定大局和群众切身利益、社会普遍关注的重大问题，有计划地对有关法律、法规或者相关法律制度实施情况组织执法检查。"},{"i":32,"n":"第三十二条","txt":"常务委员会执法检查工作由本级人民代表大会有关专门委员会或者常务委员会有关工作机构具体组织实施。"},{"i":33,"n":"第三十三条","txt":"常务委员会按照精干、效能的原则，组织执法检查组。"},{"i":34,"n":"第三十四条","txt":"全国人民代表大会常务委员会和省、自治区、直辖市的人民代表大会常务委员会根据需要，可以委托下一级人民代表大会常务委员会对有关法律、法规或者相关法律制度在本行政区域内的实施情况进行检查。受委托的人民代表大会常务委员会应当将检查情况书面报送上一级人民代表大会常务委员会。"},{"i":35,"n":"第三十五条","txt":"执法检查可以采取座谈会、实地检查、第三方评估、问卷调查或者抽查等形式，深入了解情况，广泛听取意见。"},{"i":36,"n":"第三十六条","txt":"执法检查结束后，执法检查组应当及时提出执法检查报告，由委员长会议或者主任会议决定提请常务委员会审议。"},{"i":37,"n":"第三十七条","txt":"常务委员会组成人员对执法检查报告的审议意见及执法检查报告交由本级人民政府、监察委员会、人民法院或者人民检察院研究处理。人民政府、监察委员会、人民法院或者人民检察院应当将研究处理情况由其办事机构送交本级人民代表大会有关专门委员会或者常务委员会有关工作机构征求意见后，向常务委员会提出书面报告。常务委员会认为必要时，可以对执法检查报告作出决议；本级人民政府、监察委员会、人民法院或者人民检察院应当在决议规定的期限内，将执行决议的情况向常务委员会报告。"},{"i":38,"n":"第三十八条","txt":"行政法规、监察法规、地方性法规、自治条例和单行条例、规章等的备案、审查和撤销，依照《中华人民共和国立法法》和全国人民代表大会常务委员会的有关决定办理。"},{"i":39,"n":"第三十九条","txt":"县级以上地方各级人民代表大会常务委员会对下一级人民代表大会及其常务委员会作出的决议、决定和本级人民政府、监察委员会、人民法院、人民检察院制定的规范性文件，经审查，认为有下列不适当的情形之一的，有权予以撤销："},{"i":40,"n":"第四十条","txt":"县级以上地方各级人民代表大会常务委员会审查、撤销下一级人民代表大会及其常务委员会作出的不适当的决议、决定和本级人民政府、监察委员会、人民法院、人民检察院制定的不适当的规范性文件的程序，由省、自治区、直辖市的人民代表大会常务委员会参照《中华人民共和国立法法》和全国人民代表大会常务委员会的有关决定，作出具体规定。"},{"i":41,"n":"第四十一条","txt":"最高人民法院、最高人民检察院作出的属于审判、检察工作中具体应用法律的解释，应当自公布之日起三十日内报全国人民代表大会常务委员会备案。"},{"i":42,"n":"第四十二条","txt":"国务院、中央军事委员会、国家监察委员会和省、自治区、直辖市的人民代表大会常务委员会认为最高人民法院、最高人民检察院作出的具体应用法律的解释同宪法或者法律相抵触，或者存在合宪性、合法性问题的，最高人民法院、最高人民检察院之间认为对方作出的具体应用法律的解释同宪法或者法律相抵触，或者存在合宪性、合法性问题的，可以向全国人民代表大会常务委员会书面提出进行审查的要求，由全国人民代表大会有关专门委员会和常务委员会工作机构进行审查、提出意见。"},{"i":43,"n":"第四十三条","txt":"全国人民代表大会宪法和法律委员会、有关专门委员会、常务委员会工作机构经审查认为最高人民法院或者最高人民检察院作出的具体应用法律的解释同宪法或者法律相抵触，或者存在合宪性、合法性问题需要修改或者废止，而最高人民法院或者最高人民检察院不予修改或者废止的，应当提出撤销或者要求最高人民法院或者最高人民检察院予以修改、废止的议案、建议，或者提出由全国人民代表大会常务委员会作出法律解释的议案、建议，由委员长会议决定提请常务委员会审议。"},{"i":44,"n":"第四十四条","txt":"备案审查机关应当建立健全备案审查衔接联动机制，对应当由其他机关处理的审查要求或者审查建议，及时移送有关机关处理。"},{"i":45,"n":"第四十五条","txt":"常务委员会应当每年听取和审议备案审查工作情况报告。"},{"i":46,"n":"第四十六条","txt":"各级人民代表大会常务委员会会议审议议案和有关报告时，本级人民政府或者有关部门、监察委员会、人民法院或者人民检察院应当派有关负责人员到会，听取意见，回答询问。"},{"i":47,"n":"第四十七条","txt":"各级人民代表大会常务委员会围绕关系改革发展稳定大局和群众切身利益、社会普遍关注的重大问题，可以召开全体会议、联组会议或者分组会议，进行专题询问。本级人民政府及其有关部门、监察委员会、人民法院或者人民检察院的负责人应当到会，听取意见，回答询问。"},{"i":48,"n":"第四十八条","txt":"专题询问应当坚持问题导向，增强针对性、实效性，积极回应社会关切。"},{"i":49,"n":"第四十九条","txt":"常务委员会开展专题询问前，可以组织开展专题调查研究，深入了解情况，广泛听取意见。"},{"i":50,"n":"第五十条","txt":"专题询问中提出的意见交由有关国家机关研究处理，有关国家机关应当及时向常务委员会提交研究处理情况报告。必要时，委员长会议或者主任会议可以决定将研究处理情况报告提请常务委员会审议。"},{"i":51,"n":"第五十一条","txt":"全国人民代表大会常务委员会组成人员十人以上联名，省、自治区、直辖市、自治州、设区的市人民代表大会常务委员会组成人员五人以上联名，县级人民代表大会常务委员会组成人员三人以上联名，可以向常务委员会书面提出对本级人民政府及其部门和监察委员会、人民法院、人民检察院的质询案。"},{"i":52,"n":"第五十二条","txt":"质询案由委员长会议或者主任会议决定交由受质询的机关答复。"},{"i":53,"n":"第五十三条","txt":"提质询案的常务委员会组成人员的过半数对受质询机关的答复不满意的，可以提出要求，经委员长会议或者主任会议决定，由受质询机关再作答复。"},{"i":54,"n":"第五十四条","txt":"质询案以口头答复的，由受质询机关的负责人到会答复。质询案以书面答复的，由受质询机关的负责人签署。"},{"i":55,"n":"第五十五条","txt":"各级人民代表大会常务委员会对属于其职权范围内的事项，需要作出决议、决定，但有关重大事实不清的，可以组织关于特定问题的调查委员会。"},{"i":56,"n":"第五十六条","txt":"委员长会议或者主任会议可以向本级人民代表大会常务委员会提议组织关于特定问题的调查委员会，提请常务委员会审议。"},{"i":57,"n":"第五十七条","txt":"调查委员会由主任委员、副主任委员和委员组成，由委员长会议或者主任会议在本级人民代表大会常务委员会组成人员和本级人民代表大会代表中提名，提请常务委员会审议通过。调查委员会可以聘请有关专家参加调查工作。"},{"i":58,"n":"第五十八条","txt":"调查委员会进行调查时，有关的国家机关、社会团体、企业事业组织和公民都有义务向其提供必要的材料。"},{"i":59,"n":"第五十九条","txt":"调查委员会应当向产生它的常务委员会提出调查报告。常务委员会根据报告，可以作出相应的决议、决定。"},{"i":60,"n":"第六十条","txt":"县级以上地方各级人民代表大会常务委员会在本级人民代表大会闭会期间，可以决定撤销本级人民政府个别副省长、自治区副主席、副市长、副州长、副县长、副区长的职务；可以撤销由它任命的本级人民政府其他组成人员和监察委员会副主任、委员，人民法院副院长、庭长、副庭长、审判委员会委员、审判员，人民检察院副检察长、检察委员会委员、检察员，中级人民法院院长，人民检察院分院检察长的职务。"},{"i":61,"n":"第六十一条","txt":"县级以上地方各级人民政府、监察委员会、人民法院和人民检察院，可以向本级人民代表大会常务委员会提出对本法第六十条所列国家机关工作人员的撤职案。"},{"i":62,"n":"第六十二条","txt":"撤职案应当写明撤职的对象和理由，并提供有关的材料。"},{"i":63,"n":"第六十三条","txt":"各级人民代表大会常务委员会制定年度监督工作计划，加强工作统筹，综合运用听取和审议专项工作报告、执法检查、专题询问、专题调研等方式进行监督，增强监督工作的针对性、协调性、实效性。"},{"i":64,"n":"第六十四条","txt":"省、自治区、直辖市的人民代表大会常务委员会可以根据本法和有关法律，结合本地实际情况，制定实施办法。"},{"i":65,"n":"第六十五条","txt":"本法自2007年1月1日起施行。"}],"guowuyuanzuzhifa":[{"i":1,"n":"第一条","txt":"为了健全国务院的组织和工作制度，保障和规范国务院行使职权，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。"},{"i":3,"n":"第三条","txt":"国务院坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚决维护党中央权威和集中统一领导，坚决贯彻落实党中央决策部署，贯彻新发展理念，坚持依法行政，依照宪法和法律规定，全面正确履行政府职能。"},{"i":4,"n":"第四条","txt":"国务院对全国人民代表大会负责并报告工作；在全国人民代表大会闭会期间，对全国人民代表大会常务委员会负责并报告工作。"},{"i":5,"n":"第五条","txt":"国务院由总理、副总理、国务委员、各部部长、各委员会主任、中国人民银行行长、审计长、秘书长组成。"},{"i":6,"n":"第六条","txt":"国务院行使宪法和有关法律规定的职权。"},{"i":7,"n":"第七条","txt":"国务院实行国务院全体会议和国务院常务会议制度。国务院全体会议由国务院全体成员组成。国务院常务会议由总理、副总理、国务委员、秘书长组成。总理召集和主持国务院全体会议和国务院常务会议。国务院工作中的重大问题，必须经国务院常务会议或者国务院全体会议讨论决定。"},{"i":8,"n":"第八条","txt":"国务院全体会议的主要任务是讨论决定政府工作报告、国民经济和社会发展规划等国务院工作中的重大事项，部署国务院的重要工作。"},{"i":9,"n":"第九条","txt":"国务院发布的行政法规、决定、命令，向全国人民代表大会或者全国人民代表大会常务委员会提出的议案，任免人员，由总理签署。"},{"i":10,"n":"第十条","txt":"国务院秘书长在总理领导下，负责处理国务院的日常工作。"},{"i":11,"n":"第十一条","txt":"国务院组成部门的设立、撤销或者合并，经总理提出，由全国人民代表大会决定；在全国人民代表大会闭会期间，由全国人民代表大会常务委员会决定。国务院组成部门确定或者调整后，由全国人民代表大会或者全国人民代表大会常务委员会公布。"},{"i":12,"n":"第十二条","txt":"国务院组成部门设部长（主任、行长、审计长）一人，副部长（副主任、副行长、副审计长）二至四人；委员会可以设委员五至十人。"},{"i":13,"n":"第十三条","txt":"国务院可以根据工作需要和优化协同高效精简的原则，按照规定程序设立若干直属机构主管各项专门业务，设立若干办事机构协助总理办理专门事项。每个机构设负责人二至五人，由国务院任免。"},{"i":14,"n":"第十四条","txt":"国务院组成部门工作中的方针、政策、计划和重大行政措施，应当向国务院请示报告，由国务院决定。根据法律和国务院的行政法规、决定、命令，主管部门可以在本部门的权限范围内发布命令、指示。"},{"i":15,"n":"第十五条","txt":"国务院统一领导全国地方各级国家行政机关的工作。"},{"i":16,"n":"第十六条","txt":"国务院坚持科学决策、民主决策、依法决策，健全行政决策制度体系，规范重大行政决策程序，加强行政决策执行和评估，提高决策质量和效率。"},{"i":17,"n":"第十七条","txt":"国务院健全行政监督制度，加强行政复议、备案审查、行政执法监督、政府督查等工作，坚持政务公开，自觉接受各方面监督，强化对行政权力运行的制约和监督。"},{"i":18,"n":"第十八条","txt":"国务院组成人员应当坚决维护党中央权威和集中统一领导，模范遵守宪法和法律，认真履行职责，带头反对形式主义、官僚主义，为民务实，严守纪律，勤勉廉洁。"},{"i":19,"n":"第十九条","txt":"国务院组成部门、直属机构、办事机构应当各司其职、各负其责、加强协调、密切配合，确保党中央、国务院各项工作部署贯彻落实。"},{"i":20,"n":"第二十条","txt":"本法自公布之日起施行。"}],"guojiaxunzhangheguojiarongyuchenghaofa":[{"i":1,"n":"第一条","txt":"为了褒奖在中国特色社会主义建设中作出突出贡献的杰出人士，弘扬民族精神和时代精神，激发全国各族人民建设富强、民主、文明、和谐的社会主义现代化国家的积极性，实现中华民族伟大复兴，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家勋章和国家荣誉称号为国家最高荣誉。"},{"i":3,"n":"第三条","txt":"国家设立“共和国勋章”，授予在中国特色社会主义建设和保卫国家中作出巨大贡献、建立卓越功勋的杰出人士。"},{"i":4,"n":"第四条","txt":"国家设立国家荣誉称号，授予在经济、社会、国防、外交、教育、科技、文化、卫生、体育等各领域各行业作出重大贡献、享有崇高声誉的杰出人士。"},{"i":5,"n":"第五条","txt":"全国人民代表大会常务委员会委员长会议根据各方面的建议，向全国人民代表大会常务委员会提出授予国家勋章、国家荣誉称号的议案。"},{"i":6,"n":"第六条","txt":"全国人民代表大会常务委员会决定授予国家勋章和国家荣誉称号。"},{"i":7,"n":"第七条","txt":"中华人民共和国主席根据全国人民代表大会常务委员会的决定，向国家勋章和国家荣誉称号获得者授予国家勋章、国家荣誉称号奖章，签发证书。"},{"i":8,"n":"第八条","txt":"中华人民共和国主席进行国事活动，可以直接授予外国政要、国际友人等人士“友谊勋章”。"},{"i":9,"n":"第九条","txt":"国家在国庆日或者其他重大节日、纪念日，举行颁授国家勋章、国家荣誉称号的仪式；必要时，也可以在其他时间举行颁授国家勋章、国家荣誉称号的仪式。"},{"i":10,"n":"第十条","txt":"国家设立国家功勋簿，记载国家勋章和国家荣誉称号获得者及其功绩。"},{"i":11,"n":"第十一条","txt":"国家勋章和国家荣誉称号获得者应当受到国家和社会的尊重，享有受邀参加国家庆典和其他重大活动等崇高礼遇和国家规定的待遇。"},{"i":12,"n":"第十二条","txt":"国家和社会通过多种形式，宣传国家勋章和国家荣誉称号获得者的卓越功绩和杰出事迹。"},{"i":13,"n":"第十三条","txt":"国家勋章和国家荣誉称号为其获得者终身享有，但依照本法规定被撤销的除外。"},{"i":14,"n":"第十四条","txt":"国家勋章和国家荣誉称号获得者应当按照规定佩带国家勋章、国家荣誉称号奖章，妥善保管勋章、奖章及证书。"},{"i":15,"n":"第十五条","txt":"国家勋章和国家荣誉称号获得者去世的，其获得的勋章、奖章及证书由其继承人或者指定的人保存；没有继承人或者被指定人的，可以由国家收存。"},{"i":16,"n":"第十六条","txt":"生前作出突出贡献符合本法规定授予国家勋章、国家荣誉称号条件的人士，本法施行后去世的，可以向其追授国家勋章、国家荣誉称号。"},{"i":17,"n":"第十七条","txt":"国家勋章和国家荣誉称号获得者，应当珍视并保持国家给予的荣誉，模范地遵守宪法和法律，努力为人民服务，自觉维护国家勋章和国家荣誉称号的声誉。"},{"i":18,"n":"第十八条","txt":"国家勋章和国家荣誉称号获得者因犯罪被依法判处刑罚或者有其他严重违法、违纪等行为，继续享有国家勋章、国家荣誉称号将会严重损害国家最高荣誉的声誉的，由全国人民代表大会常务委员会决定撤销其国家勋章、国家荣誉称号并予以公告。"},{"i":19,"n":"第十九条","txt":"国家勋章和国家荣誉称号的有关具体事项，由国家功勋荣誉表彰有关工作机构办理。"},{"i":20,"n":"第二十条","txt":"国务院、中央军事委员会可以在各自的职权范围内开展功勋荣誉表彰奖励工作。"},{"i":21,"n":"第二十一条","txt":"本法自2016年1月1日起施行。"}],"guojiafazhanguihuafa":[{"i":1,"n":"第一条","txt":"为了规范国家发展规划的制定和保障国家发展规划的实施，强化国家发展规划战略导向作用，完善宏观经济治理体系，推动高质量发展，推进国家治理体系和治理能力现代化，全面建设社会主义现代化国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家发展规划的编制、审查和批准、实施及其监督等工作，适用本法。"},{"i":3,"n":"第三条","txt":"国家发展规划工作坚持中国共产党的领导，坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的路线方针政策和党中央决策部署，坚持以人民为中心的发展思想，践行全过程人民民主，坚持完整准确全面贯彻新发展理念，着力推动高质量发展，统筹发展和安全，全面深化改革，构建高水平社会主义市场经济体制，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，以中国式现代化全面推进中华民族伟大复兴。"},{"i":4,"n":"第四条","txt":"国家发展规划是社会主义现代化战略在规划期内的阶段性部署和安排，主要阐明国家战略意图、明确政府工作重点、引导规范社会主体行为，是规划期内经济社会发展的蓝图和行动纲领，是政府履行经济调节、市场监管、社会管理、公共服务、生态环境保护等职能的重要依据，是其他各级各类规划的总遵循。"},{"i":5,"n":"第五条","txt":"制定和实施国家发展规划应当坚持党中央集中统一领导，坚持从实际出发，坚持全国一盘棋，坚持发扬民主、集思广益，坚持规划法定原则。"},{"i":6,"n":"第六条","txt":"国家加强对国家发展规划实施的组织协调，建立健全规划衔接、政策协同、监测评估和监督等机制，保障国家发展规划有效实施。"},{"i":7,"n":"第七条","txt":"国家发展规划根据党中央关于制定国民经济和社会发展五年规划的建议和决策部署，由国务院组织编制。"},{"i":8,"n":"第八条","txt":"国家发展规划应当包括以下主要内容："},{"i":9,"n":"第九条","txt":"编制国家发展规划应当遵循自然规律、经济规律和社会发展规律，坚持国内和国际相统筹、目标导向和问题导向相结合、中长期目标和短期目标相贯通、全面规划和突出重点相协调、战略性和操作性相统一。"},{"i":10,"n":"第十条","txt":"编制国家发展规划应当开展前期研究。"},{"i":11,"n":"第十一条","txt":"编制国家发展规划应当统筹考虑要素支撑条件、资源环境承载能力、财政承受能力和重大风险防范等因素，加强政府中长期支出事项管理，对拟提出的经济社会发展主要目标和指标、重大战略任务、重大政策举措、重大工程项目等，加强多角度论证和多方案比选。"},{"i":12,"n":"第十二条","txt":"编制国家发展规划应当坚持顶层设计和问计于民相统一，健全公众参与机制，鼓励社会参与，通过互联网等途径向社会公开征集意见建议，采取多种方式广泛听取人民群众、企业事业单位和社会各方面的意见建议。"},{"i":13,"n":"第十三条","txt":"编制国家发展规划应当健全专家咨询论证制度，对国家发展规划编制中的有关重大问题组织相关领域专家进行论证，并形成论证报告。"},{"i":14,"n":"第十四条","txt":"编制国家发展规划应当创新编制手段，综合运用现代信息技术，充分发挥高等学校、科研机构、智库、行业协会等的辅助支持作用。"},{"i":15,"n":"第十五条","txt":"国家发展规划草案由国务院国家发展规划主管部门会同国家有关部门起草，按照规定程序报请党中央、国务院审议。"},{"i":16,"n":"第十六条","txt":"国家发展规划草案报党中央、国务院审议后，由国务院按照法律规定程序提请全国人民代表大会审查和批准。"},{"i":17,"n":"第十七条","txt":"国家发展规划草案提请全国人民代表大会审查和批准前，全国人民代表大会常务委员会组织全国人民代表大会有关专门委员会和常务委员会工作机构围绕国家发展规划编制工作适时开展专题调查研究。"},{"i":18,"n":"第十八条","txt":"全国人民代表大会会议举行前，国务院国家发展规划主管部门应当就国家发展规划编制的基本情况、初步方案等向全国人民代表大会财政经济委员会和有关专门委员会汇报，由财政经济委员会进行初步审查。初步审查意见送国务院国家发展规划主管部门。"},{"i":19,"n":"第十九条","txt":"全国人民代表大会举行会议时，国家发展规划草案由各代表团进行审查，并由财政经济委员会和有关专门委员会审查。"},{"i":20,"n":"第二十条","txt":"国家发展规划经全国人民代表大会审查和批准后公布实施。"},{"i":21,"n":"第二十一条","txt":"国家发展规划在实施过程中经评估需要进行调整的，由国务院提出调整方案，报党中央同意后，提请全国人民代表大会常务委员会审查和批准。"},{"i":22,"n":"第二十二条","txt":"国务院负责组织实施国家发展规划。"},{"i":23,"n":"第二十三条","txt":"国务院组织编制国民经济和社会发展年度计划，应当与国家发展规划保持衔接，贯彻国家发展规划提出的发展目标和重大战略任务，将国家发展规划确定的主要指标分解纳入年度指标体系，设置年度目标，做好年度间综合平衡，并根据国家发展规划确定的重大战略任务等合理确定年度工作重点。"},{"i":24,"n":"第二十四条","txt":"国家统筹各级各类规划编制，加强规划间衔接协调。"},{"i":25,"n":"第二十五条","txt":"国家健全国家发展规划与宏观政策协调和工作协同机制，结合经济社会发展形势，围绕实施国家发展规划，合理确定宏观政策取向，促进财政、货币、产业、科技、价格、就业、消费、投资、贸易、土地等政策协同发力，增强宏观政策取向一致性。"},{"i":26,"n":"第二十六条","txt":"各地区、各部门制定政策，应当符合国家发展规划确定的产业发展和结构调整方向、区域发展和空间格局优化方向。"},{"i":27,"n":"第二十七条","txt":"各地区、各部门应当合理配置公共资源、积极引导社会资源，支持实施国家发展规划确定的重大战略任务、重大政策举措、重大工程项目。"},{"i":28,"n":"第二十八条","txt":"国务院加强对国家发展规划实施情况的动态监测和评估，监测评估结果作为加强和改进国家发展规划实施的重要依据。"},{"i":29,"n":"第二十九条","txt":"全国人民代表大会及其常务委员会对国家发展规划实施情况依法进行监督。"},{"i":30,"n":"第三十条","txt":"国家发展规划实施的中期阶段，国务院应当组织对国家发展规划实施情况进行中期评估，形成中期评估报告，报党中央同意后，提请全国人民代表大会常务委员会审议。"},{"i":31,"n":"第三十一条","txt":"国家发展规划的规划期结束前，国务院应当组织对国家发展规划实施情况进行总结评估，形成总结评估报告，报党中央同意后，与提请审查和批准的下一个规划期国家发展规划草案一并提交全国人民代表大会。"},{"i":32,"n":"第三十二条","txt":"国务院国家发展规划主管部门会同国家有关部门承担国家发展规划实施情况中期评估和总结评估的具体工作。"},{"i":33,"n":"第三十三条","txt":"监察机关和审计机关在各自职责范围内对国家发展规划实施情况依法进行监督。"},{"i":34,"n":"第三十四条","txt":"国家发展规划实施情况应当作为衡量各地区、各部门依法履职情况的重要参考。"},{"i":35,"n":"第三十五条","txt":"国家工作人员在国家发展规划工作中滥用职权、玩忽职守、徇私舞弊或者有其他违法行为的，依法追究责任。"},{"i":36,"n":"第三十六条","txt":"省、自治区、直辖市国民经济和社会发展五年规划纲要草案应当报送国务院国家发展规划主管部门，与国家发展规划相衔接；经本级人民代表大会审查和批准后，报送国务院国家发展规划主管部门备案。"},{"i":37,"n":"第三十七条","txt":"国家坚持“一国两制”方针，支持香港特别行政区、澳门特别行政区主动对接国家发展规划，融入和服务国家发展大局。"},{"i":38,"n":"第三十八条","txt":"本法自公布之日起施行。"}],"guojiaanquanfa":[{"i":1,"n":"第一条","txt":"为了维护国家安全，保卫人民民主专政的政权和中国特色社会主义制度，保护人民的根本利益，保障改革开放和社会主义现代化建设的顺利进行，实现中华民族伟大复兴，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家安全是指国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展和国家其他重大利益相对处于没有危险和不受内外威胁的状态，以及保障持续安全状态的能力。"},{"i":3,"n":"第三条","txt":"国家安全工作应当坚持总体国家安全观，以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、文化、社会安全为保障，以促进国际安全为依托，维护各领域国家安全，构建国家安全体系，走中国特色国家安全道路。"},{"i":4,"n":"第四条","txt":"坚持中国共产党对国家安全工作的领导，建立集中统一、高效权威的国家安全领导体制。"},{"i":5,"n":"第五条","txt":"中央国家安全领导机构负责国家安全工作的决策和议事协调，研究制定、指导实施国家安全战略和有关重大方针政策，统筹协调国家安全重大事项和重要工作，推动国家安全法治建设。"},{"i":6,"n":"第六条","txt":"国家制定并不断完善国家安全战略，全面评估国际、国内安全形势，明确国家安全战略的指导方针、中长期目标、重点领域的国家安全政策、工作任务和措施。"},{"i":7,"n":"第七条","txt":"维护国家安全，应当遵守宪法和法律，坚持社会主义法治原则，尊重和保障人权，依法保护公民的权利和自由。"},{"i":8,"n":"第八条","txt":"维护国家安全，应当与经济社会发展相协调。"},{"i":9,"n":"第九条","txt":"维护国家安全，应当坚持预防为主、标本兼治，专门工作与群众路线相结合，充分发挥专门机关和其他有关机关维护国家安全的职能作用，广泛动员公民和组织，防范、制止和依法惩治危害国家安全的行为。"},{"i":10,"n":"第十条","txt":"维护国家安全，应当坚持互信、互利、平等、协作，积极同外国政府和国际组织开展安全交流合作，履行国际安全义务，促进共同安全，维护世界和平。"},{"i":11,"n":"第十一条","txt":"中华人民共和国公民、一切国家机关和武装力量、各政党和各人民团体、企业事业组织和其他社会组织，都有维护国家安全的责任和义务。"},{"i":12,"n":"第十二条","txt":"国家对在维护国家安全工作中作出突出贡献的个人和组织给予表彰和奖励。"},{"i":13,"n":"第十三条","txt":"国家机关工作人员在国家安全工作和涉及国家安全活动中，滥用职权、玩忽职守、徇私舞弊的，依法追究法律责任。"},{"i":14,"n":"第十四条","txt":"每年4月15日为全民国家安全教育日。"},{"i":15,"n":"第十五条","txt":"国家坚持中国共产党的领导，维护中国特色社会主义制度，发展社会主义民主政治，健全社会主义法治，强化权力运行制约和监督机制，保障人民当家作主的各项权利。"},{"i":16,"n":"第十六条","txt":"国家维护和发展最广大人民的根本利益，保卫人民安全，创造良好生存发展条件和安定工作生活环境，保障公民的生命财产安全和其他合法权益。"},{"i":17,"n":"第十七条","txt":"国家加强边防、海防和空防建设，采取一切必要的防卫和管控措施，保卫领陆、内水、领海和领空安全，维护国家领土主权和海洋权益。"},{"i":18,"n":"第十八条","txt":"国家加强武装力量革命化、现代化、正规化建设，建设与保卫国家安全和发展利益需要相适应的武装力量；实施积极防御军事战略方针，防备和抵御侵略，制止武装颠覆和分裂；开展国际军事安全合作，实施联合国维和、国际救援、海上护航和维护国家海外利益的军事行动，维护国家主权、安全、领土完整、发展利益和世界和平。"},{"i":19,"n":"第十九条","txt":"国家维护国家基本经济制度和社会主义市场经济秩序，健全预防和化解经济安全风险的制度机制，保障关系国民经济命脉的重要行业和关键领域、重点产业、重大基础设施和重大建设项目以及其他重大经济利益安全。"},{"i":20,"n":"第二十条","txt":"国家健全金融宏观审慎管理和金融风险防范、处置机制，加强金融基础设施和基础能力建设，防范和化解系统性、区域性金融风险，防范和抵御外部金融风险的冲击。"},{"i":21,"n":"第二十一条","txt":"国家合理利用和保护资源能源，有效管控战略资源能源的开发，加强战略资源能源储备，完善资源能源运输战略通道建设和安全保护措施，加强国际资源能源合作，全面提升应急保障能力，保障经济社会发展所需的资源能源持续、可靠和有效供给。"},{"i":22,"n":"第二十二条","txt":"国家健全粮食安全保障体系，保护和提高粮食综合生产能力，完善粮食储备制度、流通体系和市场调控机制，健全粮食安全预警制度，保障粮食供给和质量安全。"},{"i":23,"n":"第二十三条","txt":"国家坚持社会主义先进文化前进方向，继承和弘扬中华民族优秀传统文化，培育和践行社会主义核心价值观，防范和抵制不良文化的影响，掌握意识形态领域主导权，增强文化整体实力和竞争力。"},{"i":24,"n":"第二十四条","txt":"国家加强自主创新能力建设，加快发展自主可控的战略高新技术和重要领域核心关键技术，加强知识产权的运用、保护和科技保密能力建设，保障重大技术和工程的安全。"},{"i":25,"n":"第二十五条","txt":"国家建设网络与信息安全保障体系，提升网络与信息安全保护能力，加强网络和信息技术的创新研究和开发应用，实现网络和信息核心技术、关键基础设施和重要领域信息系统及数据的安全可控；加强网络管理，防范、制止和依法惩治网络攻击、网络入侵、网络窃密、散布违法有害信息等网络违法犯罪行为，维护国家网络空间主权、安全和发展利益。"},{"i":26,"n":"第二十六条","txt":"国家坚持和完善民族区域自治制度，巩固和发展平等团结互助和谐的社会主义民族关系。坚持各民族一律平等，加强民族交往、交流、交融，防范、制止和依法惩治民族分裂活动，维护国家统一、民族团结和社会和谐，实现各民族共同团结奋斗、共同繁荣发展。"},{"i":27,"n":"第二十七条","txt":"国家依法保护公民宗教信仰自由和正常宗教活动，坚持宗教独立自主自办的原则，防范、制止和依法惩治利用宗教名义进行危害国家安全的违法犯罪活动，反对境外势力干涉境内宗教事务，维护正常宗教活动秩序。"},{"i":28,"n":"第二十八条","txt":"国家反对一切形式的恐怖主义和极端主义，加强防范和处置恐怖主义的能力建设，依法开展情报、调查、防范、处置以及资金监管等工作，依法取缔恐怖活动组织和严厉惩治暴力恐怖活动。"},{"i":29,"n":"第二十九条","txt":"国家健全有效预防和化解社会矛盾的体制机制，健全公共安全体系，积极预防、减少和化解社会矛盾，妥善处置公共卫生、社会安全等影响国家安全和社会稳定的突发事件，促进社会和谐，维护公共安全和社会安定。"},{"i":30,"n":"第三十条","txt":"国家完善生态环境保护制度体系，加大生态建设和环境保护力度，划定生态保护红线，强化生态风险的预警和防控，妥善处置突发环境事件，保障人民赖以生存发展的大气、水、土壤等自然环境和条件不受威胁和破坏，促进人与自然和谐发展。"},{"i":31,"n":"第三十一条","txt":"国家坚持和平利用核能和核技术，加强国际合作，防止核扩散，完善防扩散机制，加强对核设施、核材料、核活动和核废料处置的安全管理、监管和保护，加强核事故应急体系和应急能力建设，防止、控制和消除核事故对公民生命健康和生态环境的危害，不断增强有效应对和防范核威胁、核攻击的能力。"},{"i":32,"n":"第三十二条","txt":"国家坚持和平探索和利用外层空间、国际海底区域和极地，增强安全进出、科学考察、开发利用的能力，加强国际合作，维护我国在外层空间、国际海底区域和极地的活动、资产和其他利益的安全。"},{"i":33,"n":"第三十三条","txt":"国家依法采取必要措施，保护海外中国公民、组织和机构的安全和正当权益，保护国家的海外利益不受威胁和侵害。"},{"i":34,"n":"第三十四条","txt":"国家根据经济社会发展和国家发展利益的需要，不断完善维护国家安全的任务。"},{"i":35,"n":"第三十五条","txt":"全国人民代表大会依照宪法规定，决定战争和和平的问题，行使宪法规定的涉及国家安全的其他职权。"},{"i":36,"n":"第三十六条","txt":"中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，宣布进入紧急状态，宣布战争状态，发布动员令，行使宪法规定的涉及国家安全的其他职权。"},{"i":37,"n":"第三十七条","txt":"国务院根据宪法和法律，制定涉及国家安全的行政法规，规定有关行政措施，发布有关决定和命令；实施国家安全法律法规和政策；依照法律规定决定省、自治区、直辖市的范围内部分地区进入紧急状态；行使宪法法律规定的和全国人民代表大会及其常务委员会授予的涉及国家安全的其他职权。"},{"i":38,"n":"第三十八条","txt":"中央军事委员会领导全国武装力量，决定军事战略和武装力量的作战方针，统一指挥维护国家安全的军事行动，制定涉及国家安全的军事法规，发布有关决定和命令。"},{"i":39,"n":"第三十九条","txt":"中央国家机关各部门按照职责分工，贯彻执行国家安全方针政策和法律法规，管理指导本系统、本领域国家安全工作。"},{"i":40,"n":"第四十条","txt":"地方各级人民代表大会和县级以上地方各级人民代表大会常务委员会在本行政区域内，保证国家安全法律法规的遵守和执行。"},{"i":41,"n":"第四十一条","txt":"人民法院依照法律规定行使审判权，人民检察院依照法律规定行使检察权，惩治危害国家安全的犯罪。"},{"i":42,"n":"第四十二条","txt":"国家安全机关、公安机关依法搜集涉及国家安全的情报信息，在国家安全工作中依法行使侦查、拘留、预审和执行逮捕以及法律规定的其他职权。"},{"i":43,"n":"第四十三条","txt":"国家机关及其工作人员在履行职责时，应当贯彻维护国家安全的原则。"},{"i":44,"n":"第四十四条","txt":"中央国家安全领导机构实行统分结合、协调高效的国家安全制度与工作机制。"},{"i":45,"n":"第四十五条","txt":"国家建立国家安全重点领域工作协调机制，统筹协调中央有关职能部门推进相关工作。"},{"i":46,"n":"第四十六条","txt":"国家建立国家安全工作督促检查和责任追究机制，确保国家安全战略和重大部署贯彻落实。"},{"i":47,"n":"第四十七条","txt":"各部门、各地区应当采取有效措施，贯彻实施国家安全战略。"},{"i":48,"n":"第四十八条","txt":"国家根据维护国家安全工作需要，建立跨部门会商工作机制，就维护国家安全工作的重大事项进行会商研判，提出意见和建议。"},{"i":49,"n":"第四十九条","txt":"国家建立中央与地方之间、部门之间、军地之间以及地区之间关于国家安全的协同联动机制。"},{"i":50,"n":"第五十条","txt":"国家建立国家安全决策咨询机制，组织专家和有关方面开展对国家安全形势的分析研判，推进国家安全的科学决策。"},{"i":51,"n":"第五十一条","txt":"国家健全统一归口、反应灵敏、准确高效、运转顺畅的情报信息收集、研判和使用制度，建立情报信息工作协调机制，实现情报信息的及时收集、准确研判、有效使用和共享。"},{"i":52,"n":"第五十二条","txt":"国家安全机关、公安机关、有关军事机关根据职责分工，依法搜集涉及国家安全的情报信息。"},{"i":53,"n":"第五十三条","txt":"开展情报信息工作，应当充分运用现代科学技术手段，加强对情报信息的鉴别、筛选、综合和研判分析。"},{"i":54,"n":"第五十四条","txt":"情报信息的报送应当及时、准确、客观，不得迟报、漏报、瞒报和谎报。"},{"i":55,"n":"第五十五条","txt":"国家制定完善应对各领域国家安全风险预案。"},{"i":56,"n":"第五十六条","txt":"国家建立国家安全风险评估机制，定期开展各领域国家安全风险调查评估。"},{"i":57,"n":"第五十七条","txt":"国家健全国家安全风险监测预警制度，根据国家安全风险程度，及时发布相应风险预警。"},{"i":58,"n":"第五十八条","txt":"对可能即将发生或者已经发生的危害国家安全的事件，县级以上地方人民政府及其有关主管部门应当立即按照规定向上一级人民政府及其有关主管部门报告，必要时可以越级上报。"},{"i":59,"n":"第五十九条","txt":"国家建立国家安全审查和监管的制度和机制，对影响或者可能影响国家安全的外商投资、特定物项和关键技术、网络信息技术产品和服务、涉及国家安全事项的建设项目，以及其他重大事项和活动，进行国家安全审查，有效预防和化解国家安全风险。"},{"i":60,"n":"第六十条","txt":"中央国家机关各部门依照法律、行政法规行使国家安全审查职责，依法作出国家安全审查决定或者提出安全审查意见并监督执行。"},{"i":61,"n":"第六十一条","txt":"省、自治区、直辖市依法负责本行政区域内有关国家安全审查和监管工作。"},{"i":62,"n":"第六十二条","txt":"国家建立统一领导、协同联动、有序高效的国家安全危机管控制度。"},{"i":63,"n":"第六十三条","txt":"发生危及国家安全的重大事件，中央有关部门和有关地方根据中央国家安全领导机构的统一部署，依法启动应急预案，采取管控处置措施。"},{"i":64,"n":"第六十四条","txt":"发生危及国家安全的特别重大事件，需要进入紧急状态、战争状态或者进行全国总动员、局部动员的，由全国人民代表大会、全国人民代表大会常务委员会或者国务院依照宪法和有关法律规定的权限和程序决定。"},{"i":65,"n":"第六十五条","txt":"国家决定进入紧急状态、战争状态或者实施国防动员后，履行国家安全危机管控职责的有关机关依照法律规定或者全国人民代表大会常务委员会规定，有权采取限制公民和组织权利、增加公民和组织义务的特别措施。"},{"i":66,"n":"第六十六条","txt":"履行国家安全危机管控职责的有关机关依法采取处置国家安全危机的管控措施，应当与国家安全危机可能造成的危害的性质、程度和范围相适应；有多种措施可供选择的，应当选择有利于最大程度保护公民、组织权益的措施。"},{"i":67,"n":"第六十七条","txt":"国家健全国家安全危机的信息报告和发布机制。"},{"i":68,"n":"第六十八条","txt":"国家安全威胁和危害得到控制或者消除后，应当及时解除管控处置措施，做好善后工作。"},{"i":69,"n":"第六十九条","txt":"国家健全国家安全保障体系，增强维护国家安全的能力。"},{"i":70,"n":"第七十条","txt":"国家健全国家安全法律制度体系，推动国家安全法治建设。"},{"i":71,"n":"第七十一条","txt":"国家加大对国家安全各项建设的投入，保障国家安全工作所需经费和装备。"},{"i":72,"n":"第七十二条","txt":"承担国家安全战略物资储备任务的单位，应当按照国家有关规定和标准对国家安全物资进行收储、保管和维护，定期调整更换，保证储备物资的使用效能和安全。"},{"i":73,"n":"第七十三条","txt":"鼓励国家安全领域科技创新，发挥科技在维护国家安全中的作用。"},{"i":74,"n":"第七十四条","txt":"国家采取必要措施，招录、培养和管理国家安全工作专门人才和特殊人才。"},{"i":75,"n":"第七十五条","txt":"国家安全机关、公安机关、有关军事机关开展国家安全专门工作，可以依法采取必要手段和方式，有关部门和地方应当在职责范围内提供支持和配合。"},{"i":76,"n":"第七十六条","txt":"国家加强国家安全新闻宣传和舆论引导，通过多种形式开展国家安全宣传教育活动，将国家安全教育纳入国民教育体系和公务员教育培训体系，增强全民国家安全意识。"},{"i":77,"n":"第七十七条","txt":"公民和组织应当履行下列维护国家安全的义务："},{"i":78,"n":"第七十八条","txt":"机关、人民团体、企业事业组织和其他社会组织应当对本单位的人员进行维护国家安全的教育，动员、组织本单位的人员防范、制止危害国家安全的行为。"},{"i":79,"n":"第七十九条","txt":"企业事业组织根据国家安全工作的要求，应当配合有关部门采取相关安全措施。"},{"i":80,"n":"第八十条","txt":"公民和组织支持、协助国家安全工作的行为受法律保护。"},{"i":81,"n":"第八十一条","txt":"公民和组织因支持、协助国家安全工作导致财产损失的，按照国家有关规定给予补偿；造成人身伤害或者死亡的，按照国家有关规定给予抚恤优待。"},{"i":82,"n":"第八十二条","txt":"公民和组织对国家安全工作有向国家机关提出批评建议的权利，对国家机关及其工作人员在国家安全工作中的违法失职行为有提出申诉、控告和检举的权利。"},{"i":83,"n":"第八十三条","txt":"在国家安全工作中，需要采取限制公民权利和自由的特别措施时，应当依法进行，并以维护国家安全的实际需要为限度。"},{"i":84,"n":"第八十四条","txt":"本法自公布之日起施行。"}],"guojiapeichangfa":[{"i":1,"n":"第一条","txt":"为保障公民、法人和其他组织享有依法取得国家赔偿的权利，促进国家机关依法行使职权，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家机关和国家机关工作人员行使职权，有本法规定的侵犯公民、法人和其他组织合法权益的情形，造成损害的，受害人有依照本法取得国家赔偿的权利。"},{"i":3,"n":"第三条","txt":"行政机关及其工作人员在行使行政职权时有下列侵犯人身权情形之一的，受害人有取得赔偿的权利："},{"i":4,"n":"第四条","txt":"行政机关及其工作人员在行使行政职权时有下列侵犯财产权情形之一的，受害人有取得赔偿的权利："},{"i":5,"n":"第五条","txt":"属于下列情形之一的，国家不承担赔偿责任："},{"i":6,"n":"第六条","txt":"受害的公民、法人和其他组织有权要求赔偿。"},{"i":7,"n":"第七条","txt":"行政机关及其工作人员行使行政职权侵犯公民、法人和其他组织的合法权益造成损害的，该行政机关为赔偿义务机关。"},{"i":8,"n":"第八条","txt":"经复议机关复议的，最初造成侵权行为的行政机关为赔偿义务机关，但复议机关的复议决定加重损害的，复议机关对加重的部分履行赔偿义务。"},{"i":9,"n":"第九条","txt":"赔偿义务机关有本法第三条、第四条规定情形之一的，应当给予赔偿。"},{"i":10,"n":"第十条","txt":"赔偿请求人可以向共同赔偿义务机关中的任何一个赔偿义务机关要求赔偿，该赔偿义务机关应当先予赔偿。"},{"i":11,"n":"第十一条","txt":"赔偿请求人根据受到的不同损害，可以同时提出数项赔偿要求。"},{"i":12,"n":"第十二条","txt":"要求赔偿应当递交申请书，申请书应当载明下列事项："},{"i":13,"n":"第十三条","txt":"赔偿义务机关应当自收到申请之日起两个月内，作出是否赔偿的决定，赔偿义务机关作出赔偿决定，应当充分听取赔偿请求人的意见，并可以与赔偿请求人就赔偿方式、赔偿项目和赔偿数额依照本法第四章的规定进行协商。"},{"i":14,"n":"第十四条","txt":"赔偿义务机关在规定期限内未作出是否赔偿的决定，赔偿请求人可以自期限届满之日起三个月内，向人民法院提起诉讼。"},{"i":15,"n":"第十五条","txt":"人民法院审理行政赔偿案件，赔偿请求人和赔偿义务机关对自己提出的主张，应当提供证据。"},{"i":16,"n":"第十六条","txt":"赔偿义务机关赔偿损失后，应当责令有故意或者重大过失的工作人员或者受委托的组织或者个人承担部分或者全部赔偿费用。"},{"i":17,"n":"第十七条","txt":"行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员在行使职权时有下列侵犯人身权情形之一的，受害人有取得赔偿的权利："},{"i":18,"n":"第十八条","txt":"行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员在行使职权时有下列侵犯财产权情形之一的，受害人有取得赔偿的权利："},{"i":19,"n":"第十九条","txt":"属于下列情形之一的，国家不承担赔偿责任："},{"i":20,"n":"第二十条","txt":"赔偿请求人的确定依照本法第六条的规定。"},{"i":21,"n":"第二十一条","txt":"行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员在行使职权时侵犯公民、法人和其他组织的合法权益造成损害的，该机关为赔偿义务机关。"},{"i":22,"n":"第二十二条","txt":"赔偿义务机关有本法第十七条、第十八条规定情形之一的，应当给予赔偿。"},{"i":23,"n":"第二十三条","txt":"赔偿义务机关应当自收到申请之日起两个月内，作出是否赔偿的决定。赔偿义务机关作出赔偿决定，应当充分听取赔偿请求人的意见，并可以与赔偿请求人就赔偿方式、赔偿项目和赔偿数额依照本法第四章的规定进行协商。"},{"i":24,"n":"第二十四条","txt":"赔偿义务机关在规定期限内未作出是否赔偿的决定，赔偿请求人可以自期限届满之日起三十日内向赔偿义务机关的上一级机关申请复议。"},{"i":25,"n":"第二十五条","txt":"复议机关应当自收到申请之日起两个月内作出决定。"},{"i":26,"n":"第二十六条","txt":"人民法院赔偿委员会处理赔偿请求，赔偿请求人和赔偿义务机关对自己提出的主张，应当提供证据。"},{"i":27,"n":"第二十七条","txt":"人民法院赔偿委员会处理赔偿请求，采取书面审查的办法。必要时，可以向有关单位和人员调查情况、收集证据。赔偿请求人与赔偿义务机关对损害事实及因果关系有争议的，赔偿委员会可以听取赔偿请求人和赔偿义务机关的陈述和申辩，并可以进行质证。"},{"i":28,"n":"第二十八条","txt":"人民法院赔偿委员会应当自收到赔偿申请之日起三个月内作出决定；属于疑难、复杂、重大案件的，经本院院长批准，可以延长三个月。"},{"i":29,"n":"第二十九条","txt":"中级以上的人民法院设立赔偿委员会，由人民法院三名以上审判员组成，组成人员的人数应当为单数。"},{"i":30,"n":"第三十条","txt":"赔偿请求人或者赔偿义务机关对赔偿委员会作出的决定，认为确有错误的，可以向上一级人民法院赔偿委员会提出申诉。"},{"i":31,"n":"第三十一条","txt":"赔偿义务机关赔偿后，应当向有下列情形之一的工作人员追偿部分或者全部赔偿费用："},{"i":32,"n":"第三十二条","txt":"国家赔偿以支付赔偿金为主要方式。"},{"i":33,"n":"第三十三条","txt":"侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。"},{"i":34,"n":"第三十四条","txt":"侵犯公民生命健康权的，赔偿金按照下列规定计算："},{"i":35,"n":"第三十五条","txt":"有本法第三条或者第十七条规定情形之一，致人精神损害的，应当在侵权行为影响的范围内，为受害人消除影响，恢复名誉，赔礼道歉；造成严重后果的，应当支付相应的精神损害抚慰金。"},{"i":36,"n":"第三十六条","txt":"侵犯公民、法人和其他组织的财产权造成损害的，按照下列规定处理："},{"i":37,"n":"第三十七条","txt":"赔偿费用列入各级财政预算。"},{"i":38,"n":"第三十八条","txt":"人民法院在民事诉讼、行政诉讼过程中，违法采取对妨害诉讼的强制措施、保全措施或者对判决、裁定及其他生效法律文书执行错误，造成损害的，赔偿请求人要求赔偿的程序，适用本法刑事赔偿程序的规定。"},{"i":39,"n":"第三十九条","txt":"赔偿请求人请求国家赔偿的时效为两年，自其知道或者应当知道国家机关及其工作人员行使职权时的行为侵犯其人身权、财产权之日起计算，但被羁押等限制人身自由期间不计算在内。在申请行政复议或者提起行政诉讼时一并提出赔偿请求的，适用行政复议法、行政诉讼法有关时效的规定。"},{"i":40,"n":"第四十条","txt":"外国人、外国企业和组织在中华人民共和国领域内要求中华人民共和国国家赔偿的，适用本法。"},{"i":41,"n":"第四十一条","txt":"赔偿请求人要求国家赔偿的，赔偿义务机关、复议机关和人民法院不得向赔偿请求人收取任何费用。"},{"i":42,"n":"第四十二条","txt":"本法自1995年1月1日起施行。"}],"guojiatongyongyuyanwenzifa":[{"i":1,"n":"第一条","txt":"为了推动国家通用语言文字的规范化、标准化及其健康发展，更好发挥国家通用语言文字在社会生活和促进各民族、各地区经济文化交流中的作用，铸牢中华民族共同体意识，坚定文化自信，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称的国家通用语言文字是普通话和规范汉字，是国家法定全国通用的语言文字。"},{"i":3,"n":"第三条","txt":"国家推广普及国家通用语言文字。"},{"i":4,"n":"第四条","txt":"公民有学习和使用国家通用语言文字的权利。任何组织或者个人都不得妨碍公民学习和使用国家通用语言文字。"},{"i":5,"n":"第五条","txt":"国家语言文字事业坚持中国共产党的领导。"},{"i":6,"n":"第六条","txt":"国家颁布国家通用语言文字的规范和标准，管理国家通用语言文字的社会应用，支持国家通用语言文字的教学和科学研究，推进国家通用语言文字的信息化、数字化、智能化建设，促进国家通用语言文字的规范、丰富和发展。"},{"i":7,"n":"第七条","txt":"县级以上人民政府应当将语言文字事业纳入国民经济和社会发展相关规划，将语言文字工作所需经费列入本级预算。"},{"i":8,"n":"第八条","txt":"对为国家通用语言文字事业做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":9,"n":"第九条","txt":"各民族都有使用和发展自己的语言文字的自由。"},{"i":10,"n":"第十条","txt":"国家机关以国家通用语言文字为公务用语用字。法律另有规定的除外。"},{"i":11,"n":"第十一条","txt":"学校及其他教育机构以国家通用语言文字为基本的教育教学用语用字。"},{"i":12,"n":"第十二条","txt":"中文出版物应当符合国家通用语言文字的规范和标准。"},{"i":13,"n":"第十三条","txt":"广播电台、电视台以普通话为基本的播音用语。"},{"i":14,"n":"第十四条","txt":"公共服务行业以规范汉字为基本的服务用字。因公共服务需要，招牌、广告、告示、标志牌等使用外国文字并同时使用中文的，应当使用规范汉字，并以规范汉字为主。"},{"i":15,"n":"第十五条","txt":"下列情形，应当以国家通用语言文字为基本的用语用字："},{"i":16,"n":"第十六条","txt":"在境内举办的国际展览、国际会议等，其标识、标牌、宣传品等需要使用外国语言文字的，应当同时使用国家通用语言文字。"},{"i":17,"n":"第十七条","txt":"信息处理和信息技术产品以及政府主办的或者提供社会公共服务的门户网站、移动应用程序等互联网信息平台中使用的国家通用语言文字，应当符合国家的规范和标准。"},{"i":18,"n":"第十八条","txt":"本章有关规定中，有下列情形的，可以使用方言："},{"i":19,"n":"第十九条","txt":"本章有关规定中，有下列情形的，可以保留或者使用繁体字、异体字："},{"i":20,"n":"第二十条","txt":"国家通用语言文字以《汉语拼音方案》作为拼写和注音工具。"},{"i":21,"n":"第二十一条","txt":"以普通话作为工作语言的岗位，其工作人员应当具备说普通话的能力。"},{"i":22,"n":"第二十二条","txt":"国际中文教育应当教授国家通用语言文字，通过国际交流合作促进人类文明交流互鉴。"},{"i":23,"n":"第二十三条","txt":"国家通用语言文字工作由国务院语言文字工作部门负责规划指导、管理监督。"},{"i":24,"n":"第二十四条","txt":"地方语言文字工作部门和其他有关部门，管理和监督本行政区域内的国家通用语言文字的使用。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府市场监督管理部门依法对企业名称和商品的名称、包装、说明以及广告的用语用字进行管理和监督。"},{"i":26,"n":"第二十六条","txt":"国务院语言文字工作部门颁布普通话水平测试等级标准。"},{"i":27,"n":"第二十七条","txt":"外国人名、地名等专有名词和科学技术术语译成国家通用语言文字，由国务院语言文字工作部门或者其他有关部门组织审定。"},{"i":28,"n":"第二十八条","txt":"对违反本法第二章有关规定，不按照国家通用语言文字的规范和标准使用语言文字的，公民、组织可以提出批评和建议，并可以向有关机关投诉、举报。接到投诉、举报的机关应当按照规定及时处理。"},{"i":29,"n":"第二十九条","txt":"本法第二十一条第二款规定的人员用语违反本法第二章有关规定的，有关单位应当对直接责任人员进行批评教育，责令改正；拒不改正的，由有关单位作出处理。"},{"i":30,"n":"第三十条","txt":"违反本法第二章有关规定的，由教育、新闻出版、广播电视、市场监督管理、住房城乡建设、文化和旅游、电影、交通运输、民政、公安、文物、网信、工业和信息化等有关部门依据各自职责责令改正；拒不改正的，给予警告或者通报批评，对直接负责的主管人员和其他直接责任人员依法给予处分。法律、行政法规另有规定的，从其规定。"},{"i":31,"n":"第三十一条","txt":"违反本法规定，干涉他人学习和使用国家通用语言文字的，由有关部门进行批评教育，责令改正，可以给予警告；构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":32,"n":"第三十二条","txt":"本法自2026年1月1日起施行。"}],"guohuifa":[{"i":1,"n":"第一条","txt":"为了维护国徽的尊严，正确使用国徽，增强公民的国家观念，弘扬爱国主义精神，培育和践行社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国国徽，中间是五星照耀下的天安门，周围是谷穗和齿轮。"},{"i":3,"n":"第三条","txt":"中华人民共和国国徽是中华人民共和国的象征和标志。"},{"i":4,"n":"第四条","txt":"下列机构应当悬挂国徽："},{"i":5,"n":"第五条","txt":"下列场所应当悬挂国徽："},{"i":6,"n":"第六条","txt":"下列机构的印章应当刻有国徽图案："},{"i":7,"n":"第七条","txt":"本法第六条规定的机构应当在其网站首页显著位置使用国徽图案。"},{"i":8,"n":"第八条","txt":"下列文书、出版物等应当印有国徽图案："},{"i":9,"n":"第九条","txt":"标示国界线的界桩、界碑和标示领海基点方位的标志碑以及其他用于显示国家主权的标志物可以使用国徽图案。"},{"i":10,"n":"第十条","txt":"下列证件、证照可以使用国徽图案："},{"i":11,"n":"第十一条","txt":"外事活动和国家驻外使馆、领馆以及其他外交代表机构对外使用国徽图案的办法，由外交部规定，报国务院批准后施行。"},{"i":12,"n":"第十二条","txt":"在本法规定的范围以外需要悬挂国徽或者使用国徽图案的，由全国人民代表大会常务委员会办公厅或者国务院办公厅会同有关主管部门规定。"},{"i":13,"n":"第十三条","txt":"国徽及其图案不得用于："},{"i":14,"n":"第十四条","txt":"不得悬挂破损、污损或者不合规格的国徽。"},{"i":15,"n":"第十五条","txt":"国徽应当作为爱国主义教育的重要内容。"},{"i":16,"n":"第十六条","txt":"悬挂的国徽由国家指定的企业统一制作，其直径的通用尺度为下列三种："},{"i":17,"n":"第十七条","txt":"国务院办公厅统筹协调全国范围内国徽管理有关工作。地方各级人民政府统筹协调本行政区域内国徽管理有关工作。"},{"i":18,"n":"第十八条","txt":"在公共场合故意以焚烧、毁损、涂划、玷污、践踏等方式侮辱中华人民共和国国徽的，依法追究刑事责任；情节较轻的，由公安机关处以十五日以下拘留。"},{"i":19,"n":"第十九条","txt":"本法自1991年10月1日起施行。"}],"guoqifa":[{"i":1,"n":"第一条","txt":"为了维护国旗的尊严，规范国旗的使用，增强公民的国家观念，弘扬爱国主义精神，培育和践行社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国国旗是五星红旗。"},{"i":3,"n":"第三条","txt":"国旗的通用尺度为国旗制法说明中所列明的五种尺度。特殊情况使用其他尺度的国旗，应当按照通用尺度成比例适当放大或者缩小。"},{"i":4,"n":"第四条","txt":"中华人民共和国国旗是中华人民共和国的象征和标志。"},{"i":5,"n":"第五条","txt":"下列场所或者机构所在地，应当每日升挂国旗："},{"i":6,"n":"第六条","txt":"下列机构所在地应当在工作日升挂国旗："},{"i":7,"n":"第七条","txt":"国庆节、国际劳动节、元旦、春节和国家宪法日等重要节日、纪念日，各级国家机关、各人民团体以及大型广场、公园等公共活动场所应当升挂国旗；企业事业组织，村民委员会、居民委员会，居民院（楼、小区）有条件的应当升挂国旗。"},{"i":8,"n":"第八条","txt":"举行重大庆祝、纪念活动，大型文化、体育活动，大型展览会，可以升挂国旗。"},{"i":9,"n":"第九条","txt":"国家倡导公民和组织在适宜的场合使用国旗及其图案，表达爱国情感。"},{"i":10,"n":"第十条","txt":"外交活动以及国家驻外使馆领馆和其他外交代表机构升挂、使用国旗的办法，由外交部规定。"},{"i":11,"n":"第十一条","txt":"中国人民解放军和中国人民武装警察部队升挂、使用国旗的办法，由中央军事委员会规定。"},{"i":12,"n":"第十二条","txt":"民用船舶和进入中国领水的外国船舶升挂国旗的办法，由国务院交通主管部门规定。"},{"i":13,"n":"第十三条","txt":"依照本法第五条、第六条、第七条的规定升挂国旗的，应当早晨升起，傍晚降下。"},{"i":14,"n":"第十四条","txt":"升挂国旗时，可以举行升旗仪式。"},{"i":15,"n":"第十五条","txt":"下列人士逝世，下半旗志哀："},{"i":16,"n":"第十六条","txt":"下列人士逝世，举行哀悼仪式时，其遗体、灵柩或者骨灰盒可以覆盖国旗："},{"i":17,"n":"第十七条","txt":"升挂国旗，应当将国旗置于显著的位置。"},{"i":18,"n":"第十八条","txt":"在直立的旗杆上升降国旗，应当徐徐升降。升起时，必须将国旗升至杆顶；降下时，不得使国旗落地。"},{"i":19,"n":"第十九条","txt":"不得升挂或者使用破损、污损、褪色或者不合规格的国旗，不得倒挂、倒插或者以其他有损国旗尊严的方式升挂、使用国旗。"},{"i":20,"n":"第二十条","txt":"国旗及其图案不得用作商标、授予专利权的外观设计和商业广告，不得用于私人丧事活动等不适宜的情形。"},{"i":21,"n":"第二十一条","txt":"国旗应当作为爱国主义教育的重要内容。"},{"i":22,"n":"第二十二条","txt":"国务院办公厅统筹协调全国范围内国旗管理有关工作。地方各级人民政府统筹协调本行政区域内国旗管理有关工作。"},{"i":23,"n":"第二十三条","txt":"在公共场合故意以焚烧、毁损、涂划、玷污、践踏等方式侮辱中华人民共和国国旗的，依法追究刑事责任；情节较轻的，由公安机关处以十五日以下拘留。"},{"i":24,"n":"第二十四条","txt":"本法自1990年10月1日起施行。"}],"guogefa":[{"i":1,"n":"第一条","txt":"为了维护国歌的尊严，规范国歌的奏唱、播放和使用，增强公民的国家观念，弘扬爱国主义精神，培育和践行社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国国歌是《义勇军进行曲》。"},{"i":3,"n":"第三条","txt":"中华人民共和国国歌是中华人民共和国的象征和标志。"},{"i":4,"n":"第四条","txt":"在下列场合，应当奏唱国歌："},{"i":5,"n":"第五条","txt":"国家倡导公民和组织在适宜的场合奏唱国歌，表达爱国情感。"},{"i":6,"n":"第六条","txt":"奏唱国歌，应当按照本法附件所载国歌的歌词和曲谱，不得采取有损国歌尊严的奏唱形式。"},{"i":7,"n":"第七条","txt":"奏唱国歌时，在场人员应当肃立，举止庄重，不得有不尊重国歌的行为。"},{"i":8,"n":"第八条","txt":"国歌不得用于或者变相用于商标、商业广告，不得在私人丧事活动等不适宜的场合使用，不得作为公共场所的背景音乐等。"},{"i":9,"n":"第九条","txt":"外交活动中奏唱国歌的场合和礼仪，由外交部规定。"},{"i":10,"n":"第十条","txt":"在本法第四条规定的场合奏唱国歌，应当使用国歌标准演奏曲谱或者国歌官方录音版本。"},{"i":11,"n":"第十一条","txt":"国歌纳入中小学教育。"},{"i":12,"n":"第十二条","txt":"新闻媒体应当积极开展对国歌的宣传，普及国歌奏唱礼仪知识。"},{"i":13,"n":"第十三条","txt":"国庆节、国际劳动节等重要的国家法定节日、纪念日，中央和省、自治区、直辖市的广播电台、电视台应当按照国务院广播电视主管部门规定的时点播放国歌。"},{"i":14,"n":"第十四条","txt":"县级以上各级人民政府及其有关部门在各自职责范围内，对国歌的奏唱、播放和使用进行监督管理。"},{"i":15,"n":"第十五条","txt":"在公共场合，故意篡改国歌歌词、曲谱，以歪曲、贬损方式奏唱国歌，或者以其他方式侮辱国歌的，由公安机关处以警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本法自2017年10月1日起施行。"}],"guojifa":[{"i":1,"n":"第一条","txt":"中华人民共和国国籍的取得、丧失和恢复，都适用本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国是统一的多民族的国家，各民族的人都具有中国国籍。"},{"i":3,"n":"第三条","txt":"中华人民共和国不承认中国公民具有双重国籍。"},{"i":4,"n":"第四条","txt":"父母双方或一方为中国公民，本人出生在中国，具有中国国籍。"},{"i":5,"n":"第五条","txt":"父母双方或一方为中国公民，本人出生在外国，具有中国国籍；但父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。"},{"i":6,"n":"第六条","txt":"父母无国籍或国籍不明，定居在中国，本人出生在中国，具有中国国籍。"},{"i":7,"n":"第七条","txt":"外国人或无国籍人，愿意遵守中国宪法和法律，并具有下列条件之一的，可以经申请批准加入中国国籍："},{"i":8,"n":"第八条","txt":"申请加入中国国籍获得批准的，即取得中国国籍；被批准加入中国国籍的，不得再保留外国国籍。"},{"i":9,"n":"第九条","txt":"定居外国的中国公民，自愿加入或取得外国国籍的，即自动丧失中国国籍。"},{"i":10,"n":"第十条","txt":"中国公民具有下列条件之一的，可以经申请批准退出中国国籍："},{"i":11,"n":"第十一条","txt":"申请退出中国国籍获得批准的，即丧失中国国籍。"},{"i":12,"n":"第十二条","txt":"国家工作人员和现役军人，不得退出中国国籍。"},{"i":13,"n":"第十三条","txt":"曾有过中国国籍的外国人，具有正当理由，可以申请恢复中国国籍；被批准恢复中国国籍的，不得再保留外国国籍。"},{"i":14,"n":"第十四条","txt":"中国国籍的取得、丧失和恢复，除第九条规定的以外，必须办理申请手续。未满十八周岁的人，可由其父母或其他法定代理人代为办理申请。"},{"i":15,"n":"第十五条","txt":"受理国籍申请的机关，在国内为当地市、县公安局，在国外为中国外交代表机关和领事机关。"},{"i":16,"n":"第十六条","txt":"加入、退出和恢复中国国籍的申请，由中华人民共和国公安部审批。经批准的，由公安部发给证书。"},{"i":17,"n":"第十七条","txt":"本法公布前，已经取得中国国籍的或已经丧失中国国籍的，继续有效。"},{"i":18,"n":"第十八条","txt":"本法自公布之日起施行。"}],"guofangfa":[{"i":1,"n":"第一条","txt":"为了建设和巩固国防，保障改革开放和社会主义现代化建设的顺利进行，实现中华民族伟大复兴，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家为防备和抵抗侵略，制止武装颠覆和分裂，保卫国家主权、统一、领土完整、安全和发展利益所进行的军事活动，以及与军事有关的政治、经济、外交、科技、教育等方面的活动，适用本法。"},{"i":3,"n":"第三条","txt":"国防是国家生存与发展的安全保障。"},{"i":4,"n":"第四条","txt":"国防活动坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，贯彻习近平强军思想，坚持总体国家安全观，贯彻新时代军事战略方针，建设与我国国际地位相称、与国家安全和发展利益相适应的巩固国防和强大武装力量。"},{"i":5,"n":"第五条","txt":"国家对国防活动实行统一的领导。"},{"i":6,"n":"第六条","txt":"中华人民共和国奉行防御性国防政策，独立自主、自力更生地建设和巩固国防，实行积极防御，坚持全民国防。"},{"i":7,"n":"第七条","txt":"保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。"},{"i":8,"n":"第八条","txt":"国家和社会尊重、优待军人，保障军人的地位和合法权益，开展各种形式的拥军优属活动，让军人成为全社会尊崇的职业。"},{"i":9,"n":"第九条","txt":"中华人民共和国积极推进国际军事交流与合作，维护世界和平，反对侵略扩张行为。"},{"i":10,"n":"第十条","txt":"对在国防活动中作出贡献的组织和个人，依照有关法律、法规的规定给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"任何组织和个人违反本法和有关法律，拒绝履行国防义务或者危害国防利益的，依法追究法律责任。"},{"i":12,"n":"第十二条","txt":"全国人民代表大会依照宪法规定，决定战争和和平的问题，并行使宪法规定的国防方面的其他职权。"},{"i":13,"n":"第十三条","txt":"中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，宣布战争状态，发布动员令，并行使宪法规定的国防方面的其他职权。"},{"i":14,"n":"第十四条","txt":"国务院领导和管理国防建设事业，行使下列职权："},{"i":15,"n":"第十五条","txt":"中央军事委员会领导全国武装力量，行使下列职权："},{"i":16,"n":"第十六条","txt":"中央军事委员会实行主席负责制。"},{"i":17,"n":"第十七条","txt":"国务院和中央军事委员会建立协调机制，解决国防事务的重大问题。"},{"i":18,"n":"第十八条","txt":"地方各级人民代表大会和县级以上地方各级人民代表大会常务委员会在本行政区域内，保证有关国防事务的法律、法规的遵守和执行。"},{"i":19,"n":"第十九条","txt":"地方各级人民政府和驻地军事机关根据需要召开军地联席会议，协调解决本行政区域内有关国防事务的问题。"},{"i":20,"n":"第二十条","txt":"中华人民共和国的武装力量属于人民。它的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，全心全意为人民服务。"},{"i":21,"n":"第二十一条","txt":"中华人民共和国的武装力量受中国共产党领导。武装力量中的中国共产党组织依照中国共产党章程进行活动。"},{"i":22,"n":"第二十二条","txt":"中华人民共和国的武装力量，由中国人民解放军、中国人民武装警察部队、民兵组成。"},{"i":23,"n":"第二十三条","txt":"中华人民共和国的武装力量必须遵守宪法和法律。"},{"i":24,"n":"第二十四条","txt":"中华人民共和国武装力量建设坚持走中国特色强军之路，坚持政治建军、改革强军、科技强军、人才强军、依法治军，加强军事训练，开展政治工作，提高保障水平，全面推进军事理论、军队组织形态、军事人员和武器装备现代化，构建中国特色现代作战体系，全面提高战斗力，努力实现党在新时代的强军目标。"},{"i":25,"n":"第二十五条","txt":"中华人民共和国武装力量的规模应当与保卫国家主权、安全、发展利益的需要相适应。"},{"i":26,"n":"第二十六条","txt":"中华人民共和国的兵役分为现役和预备役。军人和预备役人员的服役制度由法律规定。"},{"i":27,"n":"第二十七条","txt":"中国人民解放军、中国人民武装警察部队在规定岗位实行文职人员制度。"},{"i":28,"n":"第二十八条","txt":"中国人民解放军军旗、军徽是中国人民解放军的象征和标志。中国人民武装警察部队旗、徽是中国人民武装警察部队的象征和标志。"},{"i":29,"n":"第二十九条","txt":"国家禁止任何组织或者个人非法建立武装组织，禁止非法武装活动，禁止冒充军人或者武装力量组织。"},{"i":30,"n":"第三十条","txt":"中华人民共和国的领陆、领水、领空神圣不可侵犯。国家建设强大稳固的现代边防、海防和空防，采取有效的防卫和管理措施，保卫领陆、领水、领空的安全，维护国家海洋权益。"},{"i":31,"n":"第三十一条","txt":"中央军事委员会统一领导边防、海防、空防和其他重大安全领域的防卫工作。"},{"i":32,"n":"第三十二条","txt":"国家根据边防、海防、空防和其他重大安全领域防卫的需要，加强防卫力量建设，建设作战、指挥、通信、测控、导航、防护、交通、保障等国防设施。各级人民政府和军事机关应当依照法律、法规的规定，保障国防设施的建设，保护国防设施的安全。"},{"i":33,"n":"第三十三条","txt":"国家建立和完善国防科技工业体系，发展国防科研生产，为武装力量提供性能先进、质量可靠、配套完善、便于操作和维修的武器装备以及其他适用的军用物资，满足国防需要。"},{"i":34,"n":"第三十四条","txt":"国防科技工业实行军民结合、平战结合、军品优先、创新驱动、自主可控的方针。"},{"i":35,"n":"第三十五条","txt":"国家充分利用全社会优势资源，促进国防科学技术进步，加快技术自主研发，发挥高新技术在武器装备发展中的先导作用，增加技术储备，完善国防知识产权制度，促进国防科技成果转化，推进科技资源共享和协同创新，提高国防科研能力和武器装备技术水平。"},{"i":36,"n":"第三十六条","txt":"国家创造有利的环境和条件，加强国防科学技术人才培养，鼓励和吸引优秀人才进入国防科研生产领域，激发人才创新活力。"},{"i":37,"n":"第三十七条","txt":"国家依法实行军事采购制度，保障武装力量所需武器装备和物资、工程、服务的采购供应。"},{"i":38,"n":"第三十八条","txt":"国家对国防科研生产实行统一领导和计划调控；注重发挥市场机制作用，推进国防科研生产和军事采购活动公平竞争。"},{"i":39,"n":"第三十九条","txt":"国家保障国防事业的必要经费。国防经费的增长应当与国防需求和国民经济发展水平相适应。"},{"i":40,"n":"第四十条","txt":"国家为武装力量建设、国防科研生产和其他国防建设直接投入的资金、划拨使用的土地等资源，以及由此形成的用于国防目的的武器装备和设备设施、物资器材、技术成果等属于国防资产。"},{"i":41,"n":"第四十一条","txt":"国家根据国防建设和经济建设的需要，确定国防资产的规模、结构和布局，调整和处分国防资产。"},{"i":42,"n":"第四十二条","txt":"国家保护国防资产不受侵害，保障国防资产的安全、完整和有效。"},{"i":43,"n":"第四十三条","txt":"国家通过开展国防教育，使全体公民增强国防观念、强化忧患意识、掌握国防知识、提高国防技能、发扬爱国主义精神，依法履行国防义务。"},{"i":44,"n":"第四十四条","txt":"国防教育贯彻全民参与、长期坚持、讲求实效的方针，实行经常教育与集中教育相结合、普及教育与重点教育相结合、理论教育与行为教育相结合的原则。"},{"i":45,"n":"第四十五条","txt":"国防教育主管部门应当加强国防教育的组织管理，其他有关部门应当按照规定的职责做好国防教育工作。"},{"i":46,"n":"第四十六条","txt":"各级人民政府应当将国防教育纳入国民经济和社会发展计划，保障国防教育所需的经费。"},{"i":47,"n":"第四十七条","txt":"中华人民共和国的主权、统一、领土完整、安全和发展利益遭受威胁时，国家依照宪法和法律规定，进行全国总动员或者局部动员。"},{"i":48,"n":"第四十八条","txt":"国家将国防动员准备纳入国家总体发展规划和计划，完善国防动员体制，增强国防动员潜力，提高国防动员能力。"},{"i":49,"n":"第四十九条","txt":"国家建立战略物资储备制度。战略物资储备应当规模适度、储存安全、调用方便、定期更换，保障战时的需要。"},{"i":50,"n":"第五十条","txt":"国家国防动员领导机构、中央国家机关、中央军事委员会机关有关部门按照职责分工，组织国防动员准备和实施工作。"},{"i":51,"n":"第五十一条","txt":"国家根据国防动员需要，可以依法征收、征用组织和个人的设备设施、交通工具、场所和其他财产。"},{"i":52,"n":"第五十二条","txt":"国家依照宪法规定宣布战争状态，采取各种措施集中人力、物力和财力，领导全体公民保卫祖国、抵抗侵略。"},{"i":53,"n":"第五十三条","txt":"依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。"},{"i":54,"n":"第五十四条","txt":"企业事业组织和个人承担国防科研生产任务或者接受军事采购，应当按照要求提供符合质量标准的武器装备或者物资、工程、服务。"},{"i":55,"n":"第五十五条","txt":"公民应当接受国防教育。"},{"i":56,"n":"第五十六条","txt":"公民和组织应当支持国防建设，为武装力量的军事训练、战备勤务、防卫作战、非战争军事行动等活动提供便利条件或者其他协助。"},{"i":57,"n":"第五十七条","txt":"公民和组织有对国防建设提出建议的权利，有对危害国防利益的行为进行制止或者检举的权利。"},{"i":58,"n":"第五十八条","txt":"民兵、预备役人员和其他公民依法参加军事训练，担负战备勤务、防卫作战、非战争军事行动等任务时，应当履行自己的职责和义务；国家和社会保障其享有相应的待遇，按照有关规定对其实行抚恤优待。"},{"i":59,"n":"第五十九条","txt":"军人必须忠于祖国，忠于中国共产党，履行职责，英勇战斗，不怕牺牲，捍卫祖国的安全、荣誉和利益。"},{"i":60,"n":"第六十条","txt":"军人必须模范地遵守宪法和法律，遵守军事法规，执行命令，严守纪律。"},{"i":61,"n":"第六十一条","txt":"军人应当发扬人民军队的优良传统，热爱人民，保护人民，积极参加社会主义现代化建设，完成抢险救灾等任务。"},{"i":62,"n":"第六十二条","txt":"军人应当受到全社会的尊崇。"},{"i":63,"n":"第六十三条","txt":"国家和社会优待军人。"},{"i":64,"n":"第六十四条","txt":"国家建立退役军人保障制度，妥善安置退役军人，维护退役军人的合法权益。"},{"i":65,"n":"第六十五条","txt":"国家和社会抚恤优待残疾军人，对残疾军人的生活和医疗依法给予特别保障。"},{"i":66,"n":"第六十六条","txt":"国家和社会优待军人家属，抚恤优待烈士家属和因公牺牲、病故军人的家属。"},{"i":67,"n":"第六十七条","txt":"中华人民共和国坚持互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处五项原则，维护以联合国为核心的国际体系和以国际法为基础的国际秩序，坚持共同、综合、合作、可持续的安全观，推动构建人类命运共同体，独立自主地处理对外军事关系，开展军事交流与合作。"},{"i":68,"n":"第六十八条","txt":"中华人民共和国遵循以联合国宪章宗旨和原则为基础的国际关系基本准则，依照国家有关法律运用武装力量，保护海外中国公民、组织、机构和设施的安全，参加联合国维和、国际救援、海上护航、联演联训、打击恐怖主义等活动，履行国际安全义务，维护国家海外利益。"},{"i":69,"n":"第六十九条","txt":"中华人民共和国支持国际社会实施的有利于维护世界和地区和平、安全、稳定的与军事有关的活动，支持国际社会为公正合理地解决国际争端以及国际军备控制、裁军和防扩散所做的努力，参与安全领域多边对话谈判，推动制定普遍接受、公正合理的国际规则。"},{"i":70,"n":"第七十条","txt":"中华人民共和国在对外军事关系中遵守同外国、国际组织缔结或者参加的有关条约和协定。"},{"i":71,"n":"第七十一条","txt":"本法所称军人，是指在中国人民解放军服现役的军官、军士、义务兵等人员。"},{"i":72,"n":"第七十二条","txt":"中华人民共和国特别行政区的防务，由特别行政区基本法和有关法律规定。"},{"i":73,"n":"第七十三条","txt":"本法自2021年1月1日起施行。"}],"difanggejirenmindaibiaodahuihedifanggejirenminzhen0381c4":[{"i":1,"n":"第一条","txt":"为了健全地方各级人民代表大会和地方各级人民政府的组织和工作制度，保障和规范其行使职权，坚持和完善人民代表大会制度，保证人民当家作主，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"地方各级人民代表大会是地方国家权力机关。"},{"i":3,"n":"第三条","txt":"地方各级人民代表大会、县级以上的地方各级人民代表大会常务委员会和地方各级人民政府坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，依照宪法和法律规定行使职权。"},{"i":4,"n":"第四条","txt":"地方各级人民代表大会、县级以上的地方各级人民代表大会常务委员会和地方各级人民政府坚持以人民为中心，坚持和发展全过程人民民主，始终同人民保持密切联系，倾听人民的意见和建议，为人民服务，对人民负责，受人民监督。"},{"i":5,"n":"第五条","txt":"地方各级人民代表大会、县级以上的地方各级人民代表大会常务委员会和地方各级人民政府遵循在中央的统一领导下、充分发挥地方的主动性积极性的原则，保证宪法、法律和行政法规在本行政区域的实施。"},{"i":6,"n":"第六条","txt":"地方各级人民代表大会、县级以上的地方各级人民代表大会常务委员会和地方各级人民政府实行民主集中制原则。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市、自治州、县、自治县、市、市辖区、乡、民族乡、镇设立人民代表大会。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市、自治州、设区的市的人民代表大会代表由下一级的人民代表大会选举；县、自治县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表由选民直接选举。"},{"i":9,"n":"第九条","txt":"地方各级人民代表大会每届任期五年。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市的人民代表大会根据本行政区域的具体情况和实际需要，在不同宪法、法律、行政法规相抵触的前提下，可以制定和颁布地方性法规，报全国人民代表大会常务委员会和国务院备案。"},{"i":11,"n":"第十一条","txt":"县级以上的地方各级人民代表大会行使下列职权："},{"i":12,"n":"第十二条","txt":"乡、民族乡、镇的人民代表大会行使下列职权："},{"i":13,"n":"第十三条","txt":"地方各级人民代表大会有权罢免本级人民政府的组成人员。县级以上的地方各级人民代表大会有权罢免本级人民代表大会常务委员会的组成人员和由它选出的监察委员会主任、人民法院院长、人民检察院检察长。罢免人民检察院检察长，须报经上一级人民检察院检察长提请该级人民代表大会常务委员会批准。"},{"i":14,"n":"第十四条","txt":"地方各级人民代表大会会议每年至少举行一次。乡、民族乡、镇的人民代表大会会议一般每年举行两次。会议召开的日期由本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团决定，并予以公布。"},{"i":15,"n":"第十五条","txt":"县级以上的地方各级人民代表大会会议由本级人民代表大会常务委员会召集。"},{"i":16,"n":"第十六条","txt":"地方各级人民代表大会举行会议，应当合理安排会期和会议日程，提高议事质量和效率。"},{"i":17,"n":"第十七条","txt":"县级以上的地方各级人民代表大会每次会议举行预备会议，选举本次会议的主席团和秘书长，通过本次会议的议程和其他准备事项的决定。"},{"i":18,"n":"第十八条","txt":"乡、民族乡、镇的人民代表大会设主席，并可以设副主席一人至二人。主席、副主席由本级人民代表大会从代表中选出，任期同本级人民代表大会每届任期相同。"},{"i":19,"n":"第十九条","txt":"乡、民族乡、镇的人民代表大会举行会议的时候，选举主席团。由主席团主持会议，并负责召集下一次的本级人民代表大会会议。乡、民族乡、镇的人民代表大会主席、副主席为主席团的成员。"},{"i":20,"n":"第二十条","txt":"地方各级人民代表大会每届第一次会议，在本届人民代表大会代表选举完成后的两个月内，由上届本级人民代表大会常务委员会或者乡、民族乡、镇的上次人民代表大会主席团召集。"},{"i":21,"n":"第二十一条","txt":"县级以上的地方各级人民政府组成人员和监察委员会主任、人民法院院长、人民检察院检察长，乡级的人民政府领导人员，列席本级人民代表大会会议；县级以上的其他有关机关、团体负责人，经本级人民代表大会常务委员会决定，可以列席本级人民代表大会会议。"},{"i":22,"n":"第二十二条","txt":"地方各级人民代表大会举行会议的时候，主席团、常务委员会、各专门委员会、本级人民政府，可以向本级人民代表大会提出属于本级人民代表大会职权范围内的议案，由主席团决定提交人民代表大会会议审议，或者并交有关的专门委员会审议、提出报告，再由主席团审议决定提交大会表决。"},{"i":23,"n":"第二十三条","txt":"在地方各级人民代表大会审议议案的时候，代表可以向有关地方国家机关提出询问，由有关机关派人说明。"},{"i":24,"n":"第二十四条","txt":"地方各级人民代表大会举行会议的时候，代表十人以上联名可以书面提出对本级人民政府和它所属各工作部门以及监察委员会、人民法院、人民检察院的质询案。质询案必须写明质询对象、质询的问题和内容。"},{"i":25,"n":"第二十五条","txt":"地方各级人民代表大会进行选举和通过决议，以全体代表的过半数通过。"},{"i":26,"n":"第二十六条","txt":"县级以上的地方各级人民代表大会常务委员会的组成人员，乡、民族乡、镇的人民代表大会主席、副主席，省长、副省长，自治区主席、副主席，市长、副市长，州长、副州长，县长、副县长，区长、副区长，乡长、副乡长，镇长、副镇长，监察委员会主任，人民法院院长，人民检察院检察长的人选，由本级人民代表大会主席团或者代表依照本法规定联合提名。"},{"i":27,"n":"第二十七条","txt":"人民代表大会常务委员会主任、秘书长，乡、民族乡、镇的人民代表大会主席，人民政府正职领导人员，监察委员会主任，人民法院院长，人民检察院检察长的候选人数可以多一人，进行差额选举；如果提名的候选人只有一人，也可以等额选举。人民代表大会常务委员会副主任，乡、民族乡、镇的人民代表大会副主席，人民政府副职领导人员的候选人数应比应选人数多一人至三人，人民代表大会常务委员会委员的候选人数应比应选人数多十分之一至五分之一，由本级人民代表大会根据应选人数在选举办法中规定具体差额数，进行差额选举。如果提名的候选人数符合选举办法规定的差额数，由主席团提交代表酝酿、讨论后，进行选举。如果提名的候选人数超过选举办法规定的差额数，由主席团提交代表酝酿、讨论后，进行预选，根据在预选中得票多少的顺序，按照选举办法规定的差额数，确定正式候选人名单，进行选举。"},{"i":28,"n":"第二十八条","txt":"选举采用无记名投票方式。代表对于确定的候选人，可以投赞成票，可以投反对票，可以另选其他任何代表或者选民，也可以弃权。"},{"i":29,"n":"第二十九条","txt":"地方各级人民代表大会选举本级国家机关领导人员，获得过半数选票的候选人人数超过应选名额时，以得票多的当选。如遇票数相等不能确定当选人时，应当就票数相等的人再次投票，以得票多的当选。"},{"i":30,"n":"第三十条","txt":"地方各级人民代表大会补选常务委员会主任、副主任、秘书长、委员，乡、民族乡、镇的人民代表大会主席、副主席，省长、副省长，自治区主席、副主席，市长、副市长，州长、副州长，县长、副县长，区长、副区长，乡长、副乡长，镇长、副镇长，监察委员会主任，人民法院院长，人民检察院检察长时，候选人数可以多于应选人数，也可以同应选人数相等。选举办法由本级人民代表大会决定。"},{"i":31,"n":"第三十一条","txt":"县级以上的地方各级人民代表大会举行会议的时候，主席团、常务委员会或者十分之一以上代表联名，可以提出对本级人民代表大会常务委员会组成人员、人民政府组成人员、监察委员会主任、人民法院院长、人民检察院检察长的罢免案，由主席团提请大会审议。"},{"i":32,"n":"第三十二条","txt":"县级以上的地方各级人民代表大会常务委员会组成人员、专门委员会组成人员和人民政府领导人员，监察委员会主任，人民法院院长，人民检察院检察长，可以向本级人民代表大会提出辞职，由大会决定是否接受辞职；大会闭会期间，可以向本级人民代表大会常务委员会提出辞职，由常务委员会决定是否接受辞职。常务委员会决定接受辞职后，报本级人民代表大会备案。人民检察院检察长的辞职，须报经上一级人民检察院检察长提请该级人民代表大会常务委员会批准。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市、自治州、设区的市的人民代表大会根据需要，可以设法制委员会、财政经济委员会、教育科学文化卫生委员会、环境与资源保护委员会、社会建设委员会和其他需要设立的专门委员会；县、自治县、不设区的市、市辖区的人民代表大会根据需要，可以设法制委员会、财政经济委员会等专门委员会。"},{"i":34,"n":"第三十四条","txt":"各专门委员会的主任委员、副主任委员和委员的人选，由主席团在代表中提名，大会通过。在大会闭会期间，常务委员会可以任免专门委员会的个别副主任委员和部分委员，由主任会议提名，常务委员会会议通过。"},{"i":35,"n":"第三十五条","txt":"各专门委员会在本级人民代表大会及其常务委员会领导下，开展下列工作："},{"i":36,"n":"第三十六条","txt":"县级以上的地方各级人民代表大会可以组织关于特定问题的调查委员会。"},{"i":37,"n":"第三十七条","txt":"乡、民族乡、镇的每届人民代表大会第一次会议通过的代表资格审查委员会，行使职权至本届人民代表大会任期届满为止。"},{"i":38,"n":"第三十八条","txt":"地方各级人民代表大会代表任期，从每届本级人民代表大会举行第一次会议开始，到下届本级人民代表大会举行第一次会议为止。"},{"i":39,"n":"第三十九条","txt":"地方各级人民代表大会代表、常务委员会组成人员，在人民代表大会和常务委员会会议上的发言和表决，不受法律追究。"},{"i":40,"n":"第四十条","txt":"县级以上的地方各级人民代表大会代表，非经本级人民代表大会主席团许可，在大会闭会期间，非经本级人民代表大会常务委员会许可，不受逮捕或者刑事审判。如果因为是现行犯被拘留，执行拘留的公安机关应当立即向该级人民代表大会主席团或者常务委员会报告。"},{"i":41,"n":"第四十一条","txt":"地方各级人民代表大会代表在出席人民代表大会会议和执行代表职务的时候，国家根据需要给予往返的旅费和必要的物质上的便利或者补贴。"},{"i":42,"n":"第四十二条","txt":"县级以上的地方各级人民代表大会代表向本级人民代表大会及其常务委员会提出的对各方面工作的建议、批评和意见，由本级人民代表大会常务委员会的办事机构交有关机关和组织研究办理并负责答复。"},{"i":43,"n":"第四十三条","txt":"地方各级人民代表大会代表应当与原选区选民或者原选举单位和人民群众保持密切联系，听取和反映他们的意见和要求，充分发挥在发展全过程人民民主中的作用。"},{"i":44,"n":"第四十四条","txt":"省、自治区、直辖市、自治州、设区的市的人民代表大会代表受原选举单位的监督；县、自治县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表受选民的监督。"},{"i":45,"n":"第四十五条","txt":"地方各级人民代表大会代表因故不能担任代表职务的时候，由原选举单位或者由原选区选民补选。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市、自治州、县、自治县、市、市辖区的人民代表大会设立常务委员会，对本级人民代表大会负责并报告工作。"},{"i":47,"n":"第四十七条","txt":"省、自治区、直辖市、自治州、设区的市的人民代表大会常务委员会由本级人民代表大会在代表中选举主任、副主任若干人、秘书长、委员若干人组成。"},{"i":48,"n":"第四十八条","txt":"县级以上的地方各级人民代表大会常务委员会每届任期同本级人民代表大会每届任期相同，它行使职权到下届本级人民代表大会选出新的常务委员会为止。"},{"i":49,"n":"第四十九条","txt":"省、自治区、直辖市的人民代表大会常务委员会在本级人民代表大会闭会期间，根据本行政区域的具体情况和实际需要，在不同宪法、法律、行政法规相抵触的前提下，可以制定和颁布地方性法规，报全国人民代表大会常务委员会和国务院备案。"},{"i":50,"n":"第五十条","txt":"县级以上的地方各级人民代表大会常务委员会行使下列职权："},{"i":51,"n":"第五十一条","txt":"常务委员会会议由主任召集并主持，每两个月至少举行一次。遇有特殊需要时，可以临时召集常务委员会会议。主任可以委托副主任主持会议。"},{"i":52,"n":"第五十二条","txt":"县级以上的地方各级人民代表大会常务委员会主任会议可以向本级人民代表大会常务委员会提出属于常务委员会职权范围内的议案，由常务委员会会议审议。"},{"i":53,"n":"第五十三条","txt":"在常务委员会会议期间，省、自治区、直辖市、自治州、设区的市的人民代表大会常务委员会组成人员五人以上联名，县级的人民代表大会常务委员会组成人员三人以上联名，可以向常务委员会书面提出对本级人民政府及其工作部门、监察委员会、人民法院、人民检察院的质询案。质询案必须写明质询对象、质询的问题和内容。"},{"i":54,"n":"第五十四条","txt":"省、自治区、直辖市、自治州、设区的市的人民代表大会常务委员会主任、副主任和秘书长组成主任会议；县、自治县、不设区的市、市辖区的人民代表大会常务委员会主任、副主任组成主任会议。"},{"i":55,"n":"第五十五条","txt":"常务委员会主任因为健康情况不能工作或者缺位的时候，由常务委员会在副主任中推选一人代理主任的职务，直到主任恢复健康或者人民代表大会选出新的主任为止。"},{"i":56,"n":"第五十六条","txt":"县级以上的地方各级人民代表大会常务委员会设立代表资格审查委员会。"},{"i":57,"n":"第五十七条","txt":"代表资格审查委员会审查代表的选举是否符合法律规定。"},{"i":58,"n":"第五十八条","txt":"主任会议或者五分之一以上的常务委员会组成人员书面联名，可以向本级人民代表大会常务委员会提议组织关于特定问题的调查委员会，由全体会议决定。"},{"i":59,"n":"第五十九条","txt":"常务委员会根据工作需要，设立办事机构和法制工作委员会、预算工作委员会、代表工作委员会等工作机构。"},{"i":60,"n":"第六十条","txt":"县级以上的地方各级人民代表大会常务委员会和各专门委员会、工作机构应当建立健全常务委员会组成人员和各专门委员会、工作机构联系代表的工作机制，支持和保障代表依法履职，扩大代表对各项工作的参与，充分发挥代表作用。"},{"i":61,"n":"第六十一条","txt":"省、自治区、直辖市、自治州、县、自治县、市、市辖区、乡、民族乡、镇设立人民政府。"},{"i":62,"n":"第六十二条","txt":"地方各级人民政府应当维护宪法和法律权威，坚持依法行政，建设职能科学、权责法定、执法严明、公开公正、智能高效、廉洁诚信、人民满意的法治政府。"},{"i":63,"n":"第六十三条","txt":"地方各级人民政府应当坚持以人民为中心，全心全意为人民服务，提高行政效能，建设服务型政府。"},{"i":64,"n":"第六十四条","txt":"地方各级人民政府应当严格执行廉洁从政各项规定，加强廉政建设，建设廉洁政府。"},{"i":65,"n":"第六十五条","txt":"地方各级人民政府应当坚持诚信原则，加强政务诚信建设，建设诚信政府。"},{"i":66,"n":"第六十六条","txt":"地方各级人民政府应当坚持政务公开，全面推进决策、执行、管理、服务、结果公开，依法、及时、准确公开政府信息，推进政务数据有序共享，提高政府工作的透明度。"},{"i":67,"n":"第六十七条","txt":"地方各级人民政府应当坚持科学决策、民主决策、依法决策，提高决策的质量。"},{"i":68,"n":"第六十八条","txt":"地方各级人民政府应当依法接受监督，确保行政权力依法正确行使。"},{"i":69,"n":"第六十九条","txt":"地方各级人民政府对本级人民代表大会和上一级国家行政机关负责并报告工作。县级以上的地方各级人民政府在本级人民代表大会闭会期间，对本级人民代表大会常务委员会负责并报告工作。"},{"i":70,"n":"第七十条","txt":"省、自治区、直辖市、自治州、设区的市的人民政府分别由省长、副省长，自治区主席、副主席，市长、副市长，州长、副州长和秘书长、厅长、局长、委员会主任等组成。"},{"i":71,"n":"第七十一条","txt":"新的一届人民政府领导人员依法选举产生后，应当在两个月内提请本级人民代表大会常务委员会任命人民政府秘书长、厅长、局长、委员会主任、科长。"},{"i":72,"n":"第七十二条","txt":"地方各级人民政府每届任期五年。"},{"i":73,"n":"第七十三条","txt":"县级以上的地方各级人民政府行使下列职权："},{"i":74,"n":"第七十四条","txt":"省、自治区、直辖市的人民政府可以根据法律、行政法规和本省、自治区、直辖市的地方性法规，制定规章，报国务院和本级人民代表大会常务委员会备案。设区的市、自治州的人民政府可以根据法律、行政法规和本省、自治区的地方性法规，依照法律规定的权限制定规章，报国务院和省、自治区的人民代表大会常务委员会、人民政府以及本级人民代表大会常务委员会备案。"},{"i":75,"n":"第七十五条","txt":"县级以上的地方各级人民政府制定涉及个人、组织权利义务的规范性文件，应当依照法定权限和程序，进行评估论证、公开征求意见、合法性审查、集体讨论决定，并予以公布和备案。"},{"i":76,"n":"第七十六条","txt":"乡、民族乡、镇的人民政府行使下列职权："},{"i":77,"n":"第七十七条","txt":"地方各级人民政府分别实行省长、自治区主席、市长、州长、县长、区长、乡长、镇长负责制。"},{"i":78,"n":"第七十八条","txt":"县级以上的地方各级人民政府会议分为全体会议和常务会议。全体会议由本级人民政府全体成员组成。省、自治区、直辖市、自治州、设区的市的人民政府常务会议，分别由省长、副省长，自治区主席、副主席，市长、副市长，州长、副州长和秘书长组成。县、自治县、不设区的市、市辖区的人民政府常务会议，分别由县长、副县长，市长、副市长，区长、副区长组成。省长、自治区主席、市长、州长、县长、区长召集和主持本级人民政府全体会议和常务会议。政府工作中的重大问题，须经政府常务会议或者全体会议讨论决定。"},{"i":79,"n":"第七十九条","txt":"地方各级人民政府根据工作需要和优化协同高效以及精干的原则，设立必要的工作部门。"},{"i":80,"n":"第八十条","txt":"县级以上的地方各级人民政府根据国家区域发展战略，结合地方实际需要，可以共同建立跨行政区划的区域协同发展工作机制，加强区域合作。"},{"i":81,"n":"第八十一条","txt":"县级以上的地方各级人民政府根据应对重大突发事件的需要，可以建立跨部门指挥协调机制。"},{"i":82,"n":"第八十二条","txt":"各厅、局、委员会、科分别设厅长、局长、主任、科长，在必要的时候可以设副职。"},{"i":83,"n":"第八十三条","txt":"省、自治区、直辖市的人民政府的各工作部门受人民政府统一领导，并且依照法律或者行政法规的规定受国务院主管部门的业务指导或者领导。"},{"i":84,"n":"第八十四条","txt":"省、自治区、直辖市、自治州、县、自治县、市、市辖区的人民政府应当协助设立在本行政区域内不属于自己管理的国家机关、企业、事业单位进行工作，并且监督它们遵守和执行法律和政策。"},{"i":85,"n":"第八十五条","txt":"省、自治区的人民政府在必要的时候，经国务院批准，可以设立若干派出机关。"},{"i":86,"n":"第八十六条","txt":"街道办事处在本辖区内办理派出它的人民政府交办的公共服务、公共管理、公共安全等工作，依法履行综合管理、统筹协调、应急处置和行政执法等职责，反映居民的意见和要求。"},{"i":87,"n":"第八十七条","txt":"乡、民族乡、镇的人民政府和市辖区、不设区的市的人民政府或者街道办事处对基层群众性自治组织的工作给予指导、支持和帮助。基层群众性自治组织协助乡、民族乡、镇的人民政府和市辖区、不设区的市的人民政府或者街道办事处开展工作。"},{"i":88,"n":"第八十八条","txt":"乡、民族乡、镇的人民政府和街道办事处可以根据实际情况建立居民列席有关会议的制度。"},{"i":89,"n":"第八十九条","txt":"自治区、自治州、自治县的自治机关除行使本法规定的职权外，同时依照宪法、民族区域自治法和其他法律规定的权限行使自治权。"},{"i":90,"n":"第九十条","txt":"省、自治区、直辖市的人民代表大会及其常务委员会可以根据本法和实际情况，对执行中的问题作具体规定。"}],"chengshijuminweiyuanhuizuzhifa":[{"i":1,"n":"第一条","txt":"为了健全基层群众自治制度，由城市居民依法办理自己的事情，发展基层民主，维护居民的合法权益，推进基层治理体系和治理能力现代化，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"居民委员会是居民自我管理、自我服务、自我教育、自我监督的基层群众性自治组织，实行民主选举、民主协商、民主决策、民主管理、民主监督。"},{"i":3,"n":"第三条","txt":"居民委员会根据居民居住状况，按照便于居民自治，有利于基层治理的原则，一般在一千户至三千户的范围内设立，也可以根据实际需要，在适当范围内设立。设立居民委员会的区域称为社区。"},{"i":4,"n":"第四条","txt":"居民委员会工作坚持中国共产党的领导，坚持和发展全过程人民民主，坚持自治、法治、德治相结合。"},{"i":5,"n":"第五条","txt":"中央和地方基层群众自治指导监督部门负责指导和监督城市基层群众自治工作。"},{"i":6,"n":"第六条","txt":"不设区的市、市辖区的人民政府和街道办事处对居民委员会的工作给予指导、支持和帮助。居民委员会协助不设区的市、市辖区的人民政府或者街道办事处开展工作。"},{"i":7,"n":"第七条","txt":"对在居民自治工作中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":8,"n":"第八条","txt":"居民委员会由主任、副主任和委员共五至九人组成。"},{"i":9,"n":"第九条","txt":"居民委员会根据需要设人民调解、治安保卫、公共卫生、环境和物业管理、老年人和妇女儿童工作等委员会。"},{"i":10,"n":"第十条","txt":"居民委员会履行下列职责："},{"i":11,"n":"第十一条","txt":"居民委员会及其成员应当遵守宪法、法律、法规，遵守党和国家的政策，遵守并组织实施居民自治章程、居民公约，执行居民会议、居民代表会议的决定、决议，办事公道，廉洁奉公，热心为居民服务，接受居民监督。"},{"i":12,"n":"第十二条","txt":"居民委员会具有基层群众性自治组织法人资格，居民委员会主任为法定代表人。居民委员会可以从事为履行职能所需要的民事活动，但是不得提供担保。"},{"i":13,"n":"第十三条","txt":"居民委员会设立若干居民小组。居民小组在居民委员会的组织下开展活动。"},{"i":14,"n":"第十四条","txt":"居民委员会主任、副主任和委员，由本社区全体有选举权的居民或者由每户派代表选举产生；根据居民意见，也可以由居民代表选举产生。"},{"i":15,"n":"第十五条","txt":"居民委员会的选举，由居民选举委员会主持。"},{"i":16,"n":"第十六条","txt":"年满十八周岁的居民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是，依照法律被剥夺政治权利的人除外。"},{"i":17,"n":"第十七条","txt":"经登记的选民名单应当在选举日的二十日前公布；采取每户派代表或者居民代表选举方式的，应当同时公布户的代表或者新一届居民代表名单。"},{"i":18,"n":"第十八条","txt":"居民委员会成员候选人由社区党组织或者十名以上选民联合提名推荐。提名推荐候选人，应当从全体居民利益出发，推荐拥护中国共产党的领导、奉公守法、品行良好、公道正派、热心公益、具有一定文化水平和工作能力的人为候选人。被开除中国共产党党籍，因犯罪受过刑事处罚，利用黑恶势力从事非法活动，组织或者参加非法宗教活动或者邪教活动的，不得作为候选人。候选人的名额应当多于应选名额。居民选举委员会应当组织候选人与居民见面，由候选人介绍履行职责的设想，回答居民提出的问题。"},{"i":19,"n":"第十九条","txt":"选举居民委员会，采取全体有选举权的居民选举方式的，有选民的过半数参加投票，选举有效；采取每户派代表选举方式的，有户的代表的过半数参加投票，选举有效；采取居民代表选举方式的，有超过三分之二的居民代表参加投票，选举有效。"},{"i":20,"n":"第二十条","txt":"本社区十分之一以上有选举权的居民或者户的代表，或者三分之一以上的居民代表联名，可以提出罢免居民委员会成员的要求，并说明要求罢免的理由。被提出罢免的居民委员会成员有权提出申辩意见。"},{"i":21,"n":"第二十一条","txt":"居民委员会成员可以向居民委员会提出辞职申请，其职务自居民会议或者居民代表会议审议通过之日起终止。"},{"i":22,"n":"第二十二条","txt":"以暴力、威胁、欺骗、贿赂、伪造选票、虚报选举票数等不正当手段当选居民委员会成员的，当选无效。"},{"i":23,"n":"第二十三条","txt":"居民委员会成员丧失行为能力或者被判处刑罚的，其职务自行终止。"},{"i":24,"n":"第二十四条","txt":"居民委员会成员出缺，可以通过居民会议或者居民代表会议补选。"},{"i":25,"n":"第二十五条","txt":"居民委员会应当自新一届居民委员会产生之日起十日内完成工作移交。工作移交由居民选举委员会主持，由街道办事处监督。"},{"i":26,"n":"第二十六条","txt":"居民会议由本社区十八周岁以上的居民组成。"},{"i":27,"n":"第二十七条","txt":"居民会议应当有全体十八周岁以上的本社区居民或者户的代表的过半数参加。居民会议所作决定，应当经到会人员的过半数通过。"},{"i":28,"n":"第二十八条","txt":"居民代表会议由居民委员会成员和居民代表组成。居民代表应当占居民代表会议组成人员的五分之四以上。"},{"i":29,"n":"第二十九条","txt":"居民代表会议应当有三分之二以上的组成人员参加方可召开。居民代表会议所作决定，应当经到会组成人员的过半数通过。"},{"i":30,"n":"第三十条","txt":"居民会议制定或者修改居民自治章程、居民公约；审议居民委员会的年度工作报告，评议居民委员会成员的工作；讨论决定其他涉及全体居民利益的重要事项。"},{"i":31,"n":"第三十一条","txt":"居民自治章程、居民公约应当报不设区的市、市辖区的人民政府或者街道办事处备案。"},{"i":32,"n":"第三十二条","txt":"对涉及居民切身利益的公共事务、公益事业以及居民反映的实际困难和矛盾纠纷，居民委员会应当组织居民及其他利益相关方开展协商。"},{"i":33,"n":"第三十三条","txt":"居民委员会应当实行少数服从多数的民主决策机制和公开透明的工作原则，建立健全各种工作制度。"},{"i":34,"n":"第三十四条","txt":"居民委员会实行居务公开制度。"},{"i":35,"n":"第三十五条","txt":"居民委员会不及时公布应当公布的事项或者公布的事项不真实的，居民有权向不设区的市、市辖区的人民政府及其有关主管部门或者街道办事处反映，不设区的市、市辖区的人民政府及其有关主管部门或者街道办事处应当负责调查核实，责令依法公布；经查证确有违法行为的，有关人员应当依法承担责任。"},{"i":36,"n":"第三十六条","txt":"社区应当建立居务监督委员会，对居民委员会工作进行监督，其成员由居民会议或者居民代表会议在居民或者社区工作者中推选产生。居民委员会成员及其近亲属不得担任居务监督委员会成员。居务监督委员会的任期与居民委员会的任期相同。"},{"i":37,"n":"第三十七条","txt":"居民委员会成员接受居民会议或者居民代表会议对其履行职责情况的民主评议。民主评议每年至少进行一次，由居务监督委员会主持，民主评议结果应当及时向居民公布。"},{"i":38,"n":"第三十八条","txt":"居民委员会主任实行任期和离任经济责任审计，审计包括下列事项："},{"i":39,"n":"第三十九条","txt":"居民委员会和居务监督委员会应当建立居务档案。居务档案应当真实、准确、完整和规范。"},{"i":40,"n":"第四十条","txt":"居民委员会或者居民委员会成员作出的决定侵害居民合法权益的，受侵害的居民可以申请人民法院予以撤销，责任人依法承担法律责任。"},{"i":41,"n":"第四十一条","txt":"居民委员会日常运转经费、成员报酬及其标准，由不设区的市、市辖区的人民政府或者上级人民政府规定并拨付。"},{"i":42,"n":"第四十二条","txt":"居民委员会开展本社区公益活动或者社区服务项目，可以向街道办事处以及不设区的市、市辖区的人民政府申请经费支持，也可以根据自愿原则向居民或者受益的驻社区单位筹集资金，还可以依法与有公开募捐资格的慈善组织合作募集资金。收支账目应当及时公布，接受居民监督。"},{"i":43,"n":"第四十三条","txt":"不设区的市、市辖区的人民政府或者街道办事处需要居民委员会协助开展工作，应当提供必要的经费和条件。"},{"i":44,"n":"第四十四条","txt":"社区综合服务设施建设应当纳入相关规划，由县级以上地方人民政府统筹解决。"},{"i":45,"n":"第四十五条","txt":"不设区的市、市辖区的人民政府或者街道办事处应当为居民委员会成员以及其他社区工作者提供培训，帮助其提升政治素质、法治意识、政策水平和服务能力。"},{"i":46,"n":"第四十六条","txt":"机关、团体、部队、企业事业组织等驻社区单位，不参加本社区的居民委员会，但是应当支持居民委员会的工作。居民委员会组织讨论同驻社区单位有关的问题，需要驻社区单位参加会议时，驻社区单位应当派代表参加。驻社区单位在参与社区治理、提供社区服务中接受居民委员会指导，遵守居民公约，促进社区共建共治共享。"},{"i":47,"n":"第四十七条","txt":"县、自治县、乡、民族乡、镇以及开发区、独立工矿区、林区、垦区等设立居民委员会的，适用本法有关规定。"},{"i":48,"n":"第四十八条","txt":"地方各级人民代表大会和县级以上地方各级人民代表大会常务委员会在本行政区域内保证本法的实施，保障居民依法行使自治权利。"},{"i":49,"n":"第四十九条","txt":"省、自治区、直辖市的人民代表大会常务委员会可以根据本法，结合本行政区域的实际情况，制定实施办法。"},{"i":50,"n":"第五十条","txt":"本法自2026年1月1日起施行。"}],"waijiaotequanyuhuomiantiaoli":[{"i":1,"n":"第一条","txt":"为确定外国驻中国使馆和使馆人员的外交特权与豁免，便于外国驻中国使馆代表其国家有效地执行职务，特制定本条例。"},{"i":2,"n":"第二条","txt":"使馆外交人员原则上应当是具有派遣国国籍的人。如果委派中国或者第三国国籍的人为使馆外交人员，必须征得中国主管机关的同意。中国主管机关可以随时撤销此项同意。"},{"i":3,"n":"第三条","txt":"使馆及其馆长有权在使馆馆舍和使馆馆长交通工具上，使用派遣国的国旗或者国徽。"},{"i":4,"n":"第四条","txt":"使馆馆舍不受侵犯。中国国家工作人员进入使馆馆舍，须经使馆馆长或者其授权人员的同意。中国有关机关应当采取适当措施，保护使馆馆舍免受侵犯或者损害。"},{"i":5,"n":"第五条","txt":"使馆馆舍免纳捐税，但为其提供特定服务所收的费用不在此限。"},{"i":6,"n":"第六条","txt":"使馆的档案和文件不受侵犯。"},{"i":7,"n":"第七条","txt":"使馆人员在中国境内有行动和旅行的自由，中国政府规定禁止或者限制进入的区域除外。"},{"i":8,"n":"第八条","txt":"使馆为公务目的可以与派遣国政府以及派遣国其他使馆和领事馆自由通讯。通讯可以采用一切适当方法，包括外交信使、外交邮袋和明码、密码电信在内。"},{"i":9,"n":"第九条","txt":"使馆设置和使用供通讯用的无线电收发信机，必须经中国政府同意。使馆运进上述设备，按中国政府的有关规定办理。"},{"i":10,"n":"第十条","txt":"使馆来往的公文不受侵犯。"},{"i":11,"n":"第十一条","txt":"外交信使必须持有派遣国主管机关出具的信使证明书。外交信使人身不受侵犯，不受逮捕或者拘留。"},{"i":12,"n":"第十二条","txt":"外交代表人身不受侵犯，不受逮捕或者拘留。中国有关机关应当采取适当措施，防止外交代表的人身自由和尊严受到侵犯。"},{"i":13,"n":"第十三条","txt":"外交代表的寓所不受侵犯，并受保护。"},{"i":14,"n":"第十四条","txt":"外交代表享有刑事管辖豁免。"},{"i":15,"n":"第十五条","txt":"外交代表和第二十条规定享有豁免的人员的管辖豁免可以由派遣国政府明确表示放弃。"},{"i":16,"n":"第十六条","txt":"外交代表免纳捐税，但下列各项除外："},{"i":17,"n":"第十七条","txt":"外交代表免除一切个人和公共劳务以及军事义务。"},{"i":18,"n":"第十八条","txt":"使馆运进的公务用品、外交代表运进的自用物品，按照中国政府的有关规定免纳关税和其他捐税。"},{"i":19,"n":"第十九条","txt":"使馆和使馆人员携运自用的枪支、子弹入境，必须经中国政府批准，并且按中国政府的有关规定办理。"},{"i":20,"n":"第二十条","txt":"与外交代表共同生活的配偶及未成年子女，如果不是中国公民，享有第十二条至第十八条所规定的特权与豁免。"},{"i":21,"n":"第二十一条","txt":"外交代表如果是中国公民或者获得在中国永久居留资格的外国人，仅就其执行公务的行为，享有管辖豁免和不受侵犯。"},{"i":22,"n":"第二十二条","txt":"下列人员享有在中国过境或者逗留期间所必需的豁免和不受侵犯："},{"i":23,"n":"第二十三条","txt":"来中国访问的外国国家元首、政府首脑、外交部长及其他具有同等身份的官员，享有本条例所规定的特权与豁免。"},{"i":24,"n":"第二十四条","txt":"来中国参加联合国及其专门机构召开的国际会议的外国代表、临时来中国的联合国及其专门机构的官员和专家、联合国及其专门机构驻中国的代表机构和人员的待遇，按中国已加入的有关国际公约和中国与有关国际组织签订的协议办理。"},{"i":25,"n":"第二十五条","txt":"享有外交特权与豁免的人员："},{"i":26,"n":"第二十六条","txt":"如果外国给予中国驻该国使馆、使馆人员以及临时去该国的有关人员的外交特权与豁免，低于中国按本条例给予该国驻中国使馆、使馆人员以及临时来中国的有关人员的外交特权与豁免，中国政府根据对等原则，可以给予该国驻中国使馆、使馆人员以及临时来中国的有关人员以相应的外交特权与豁免。"},{"i":27,"n":"第二十七条","txt":"中国缔结或者参加的国际条约另有规定的，按照国际条约的规定办理，但中国声明保留的条款除外。"},{"i":28,"n":"第二十八条","txt":"本条例中下列用语的含义是："},{"i":29,"n":"第二十九条","txt":"本条例自公布之日起施行。"}],"waiguozhongyangyinhangcaichansifaqiangzhicuoshihuo4c6056":[{"i":1,"n":"第一条","txt":"中华人民共和国对外国中央银行财产给予财产保全和执行的司法强制措施的豁免；但是，外国中央银行或者其所属国政府书面放弃豁免的或者指定用于财产保全和执行的财产除外。"},{"i":2,"n":"第二条","txt":"本法所称外国中央银行，是指外国的和区域经济一体化组织的中央银行或者履行中央银行职能的金融管理机构。"},{"i":3,"n":"第三条","txt":"外国不给予中华人民共和国中央银行或者中华人民共和国特别行政区金融管理机构的财产以豁免，或者所给予的豁免低于本法的规定的，中华人民共和国根据对等原则办理。"},{"i":4,"n":"第四条","txt":"本法自公布之日起施行。"}],"waiguoguojiahuomianfa":[{"i":1,"n":"第一条","txt":"为了健全外国国家豁免制度，明确中华人民共和国的法院对涉及外国国家及其财产民事案件的管辖，保护当事人合法权益，维护国家主权平等，促进对外友好交往，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称的外国国家包括："},{"i":3,"n":"第三条","txt":"外国国家及其财产在中华人民共和国的法院享有管辖豁免，本法另有规定的除外。"},{"i":4,"n":"第四条","txt":"外国国家通过下列方式之一明示就特定事项或者案件接受中华人民共和国的法院管辖的，对于就该事项或者案件提起的诉讼，该外国国家在中华人民共和国的法院不享有管辖豁免："},{"i":5,"n":"第五条","txt":"外国国家有下列情形之一的，视为就特定事项或者案件接受中华人民共和国的法院管辖："},{"i":6,"n":"第六条","txt":"外国国家有下列情形之一的，不视为接受中华人民共和国的法院管辖："},{"i":7,"n":"第七条","txt":"外国国家与包括中华人民共和国在内的其他国家的组织或者个人进行的商业活动，在中华人民共和国领域内发生，或者虽然发生在中华人民共和国领域外但在中华人民共和国领域内产生直接影响的，对于该商业活动引起的诉讼，该外国国家在中华人民共和国的法院不享有管辖豁免。"},{"i":8,"n":"第八条","txt":"外国国家为获得个人提供的劳动或者劳务而签订的合同全部或者部分在中华人民共和国领域内履行的，对于因该合同引起的诉讼，该外国国家在中华人民共和国的法院不享有管辖豁免，但有下列情形之一的除外："},{"i":9,"n":"第九条","txt":"对于外国国家在中华人民共和国领域内的相关行为造成人身伤害、死亡或者造成动产、不动产损失引起的赔偿诉讼，该外国国家在中华人民共和国的法院不享有管辖豁免。"},{"i":10,"n":"第十条","txt":"对于下列财产事项的诉讼，外国国家在中华人民共和国的法院不享有管辖豁免："},{"i":11,"n":"第十一条","txt":"对于下列知识产权事项的诉讼，外国国家在中华人民共和国的法院不享有管辖豁免："},{"i":12,"n":"第十二条","txt":"外国国家与包括中华人民共和国在内的其他国家的组织或者个人之间的商业活动产生的争议，根据书面协议被提交仲裁的，或者外国国家通过国际投资条约等书面形式同意将其与包括中华人民共和国在内的其他国家的组织或者个人产生的投资争端提交仲裁的，对于需要法院审查的下列事项，该外国国家在中华人民共和国的法院不享有管辖豁免："},{"i":13,"n":"第十三条","txt":"外国国家的财产在中华人民共和国的法院享有司法强制措施豁免。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，外国国家的财产在中华人民共和国的法院不享有司法强制措施豁免："},{"i":15,"n":"第十五条","txt":"下列外国国家的财产不视为本法第十四条第三项规定的用于商业活动的财产："},{"i":16,"n":"第十六条","txt":"对于外国国家及其财产民事案件的审判和执行程序，本法没有规定的，适用中华人民共和国的民事诉讼法律以及其他相关法律的规定。"},{"i":17,"n":"第十七条","txt":"中华人民共和国的法院向外国国家送达传票或者其他诉讼文书，应当按照下列方式进行："},{"i":18,"n":"第十八条","txt":"经送达完成，外国国家未在中华人民共和国的法院指定期限内出庭的，法院应当主动查明该外国国家是否享有管辖豁免。对于外国国家在中华人民共和国的法院不享有管辖豁免的案件，法院可以缺席判决，但应当在诉讼文书送达之日的六个月以后。"},{"i":19,"n":"第十九条","txt":"中华人民共和国外交部就以下有关国家行为的事实问题出具的证明文件，中华人民共和国的法院应当采信："},{"i":20,"n":"第二十条","txt":"本法规定不影响外国的外交代表机构、领事机构、特别使团、驻国际组织代表团、派往国际会议的代表团及上述机构的相关人员根据中华人民共和国的法律、中华人民共和国缔结或者参加的国际条约享有的特权与豁免。"},{"i":21,"n":"第二十一条","txt":"外国给予中华人民共和国国家及其财产的豁免待遇低于本法规定的，中华人民共和国实行对等原则。"},{"i":22,"n":"第二十二条","txt":"中华人民共和国缔结或者参加的国际条约同本法有不同规定的，适用该国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":23,"n":"第二十三条","txt":"本法自2024年1月1日起施行。"}],"duiwaiguanxifa":[{"i":1,"n":"第一条","txt":"为了发展对外关系，维护国家主权、安全、发展利益，维护和发展人民利益，建设社会主义现代化强国，实现中华民族伟大复兴，促进世界和平与发展，推动构建人类命运共同体，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国发展同各国的外交关系和经济、文化等各领域的交流与合作，发展同联合国等国际组织的关系，适用本法。"},{"i":3,"n":"第三条","txt":"中华人民共和国坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，发展对外关系，促进友好交往。"},{"i":4,"n":"第四条","txt":"中华人民共和国坚持独立自主的和平外交政策，坚持互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处的五项原则。"},{"i":5,"n":"第五条","txt":"中华人民共和国对外工作坚持中国共产党的集中统一领导。"},{"i":6,"n":"第六条","txt":"国家机关和武装力量、各政党和各人民团体、企业事业组织和其他社会组织以及公民，在对外交流合作中有维护国家主权、安全、尊严、荣誉、利益的责任和义务。"},{"i":7,"n":"第七条","txt":"国家鼓励积极开展民间对外友好交流合作。"},{"i":8,"n":"第八条","txt":"任何组织和个人违反本法和有关法律，在对外交往中从事损害国家利益活动的，依法追究法律责任。"},{"i":9,"n":"第九条","txt":"中央外事工作领导机构负责对外工作的决策和议事协调，研究制定、指导实施国家对外战略和有关重大方针政策，负责对外工作的顶层设计、统筹协调、整体推进、督促落实。"},{"i":10,"n":"第十条","txt":"全国人民代表大会及其常务委员会批准和废除同外国缔结的条约和重要协定，行使宪法和法律规定的对外关系职权。"},{"i":11,"n":"第十一条","txt":"中华人民共和国主席代表中华人民共和国，进行国事活动，行使宪法和法律规定的对外关系职权。"},{"i":12,"n":"第十二条","txt":"国务院管理对外事务，同外国缔结条约和协定，行使宪法和法律规定的对外关系职权。"},{"i":13,"n":"第十三条","txt":"中央军事委员会组织开展国际军事交流与合作，行使宪法和法律规定的对外关系职权。"},{"i":14,"n":"第十四条","txt":"中华人民共和国外交部依法办理外交事务，承办党和国家领导人同外国领导人的外交往来事务。外交部加强对国家机关各部门、各地区对外交流合作的指导、协调、管理、服务。"},{"i":15,"n":"第十五条","txt":"中华人民共和国驻外国的使馆、领馆以及常驻联合国和其他政府间国际组织的代表团等驻外外交机构对外代表中华人民共和国。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市根据中央授权在特定范围内开展对外交流合作。"},{"i":17,"n":"第十七条","txt":"中华人民共和国发展对外关系，坚持维护中国特色社会主义制度，维护国家主权、统一和领土完整，服务国家经济社会发展。"},{"i":18,"n":"第十八条","txt":"中华人民共和国推动践行全球发展倡议、全球安全倡议、全球文明倡议，推进全方位、多层次、宽领域、立体化的对外工作布局。"},{"i":19,"n":"第十九条","txt":"中华人民共和国维护以联合国为核心的国际体系，维护以国际法为基础的国际秩序，维护以联合国宪章宗旨和原则为基础的国际关系基本准则。"},{"i":20,"n":"第二十条","txt":"中华人民共和国坚持共同、综合、合作、可持续的全球安全观，加强国际安全合作，完善参与全球安全治理机制。"},{"i":21,"n":"第二十一条","txt":"中华人民共和国坚持公平普惠、开放合作、全面协调、创新联动的全球发展观，促进经济、社会、环境协调可持续发展和人的全面发展。"},{"i":22,"n":"第二十二条","txt":"中华人民共和国尊重和保障人权，坚持人权的普遍性原则同本国实际相结合，促进人权全面协调发展，在平等和相互尊重的基础上开展人权领域国际交流与合作，推动国际人权事业健康发展。"},{"i":23,"n":"第二十三条","txt":"中华人民共和国主张世界各国超越国家、民族、文化差异，弘扬和平、发展、公平、正义、民主、自由的全人类共同价值。"},{"i":24,"n":"第二十四条","txt":"中华人民共和国坚持平等、互鉴、对话、包容的文明观，尊重文明多样性，推动不同文明交流对话。"},{"i":25,"n":"第二十五条","txt":"中华人民共和国积极参与全球环境气候治理，加强绿色低碳国际合作，共谋全球生态文明建设，推动构建公平合理、合作共赢的全球环境气候治理体系。"},{"i":26,"n":"第二十六条","txt":"中华人民共和国坚持推进高水平对外开放，发展对外贸易，积极促进和依法保护外商投资，鼓励开展对外投资等对外经济合作，推动共建“一带一路”高质量发展，维护多边贸易体制，反对单边主义和保护主义，推动建设开放型世界经济。"},{"i":27,"n":"第二十七条","txt":"中华人民共和国通过经济、技术、物资、人才、管理等方式开展对外援助，促进发展中国家经济发展和社会进步，增强其自主可持续发展能力，推动国际发展合作。"},{"i":28,"n":"第二十八条","txt":"中华人民共和国根据发展对外关系的需要，开展教育、科技、文化、卫生、体育、社会、生态、军事、安全、法治等领域交流合作。"},{"i":29,"n":"第二十九条","txt":"国家统筹推进国内法治和涉外法治，加强涉外领域立法，加强涉外法治体系建设。"},{"i":30,"n":"第三十条","txt":"国家依照宪法和法律缔结或者参加条约和协定，善意履行有关条约和协定规定的义务。"},{"i":31,"n":"第三十一条","txt":"国家采取适当措施实施和适用条约和协定。"},{"i":32,"n":"第三十二条","txt":"国家在遵守国际法基本原则和国际关系基本准则的基础上，加强涉外领域法律法规的实施和适用，并依法采取执法、司法等措施，维护国家主权、安全、发展利益，保护中国公民、组织合法权益。"},{"i":33,"n":"第三十三条","txt":"对于违反国际法和国际关系基本准则，危害中华人民共和国主权、安全、发展利益的行为，中华人民共和国有权采取相应反制和限制措施。"},{"i":34,"n":"第三十四条","txt":"中华人民共和国在一个中国原则基础上，按照和平共处五项原则同世界各国建立和发展外交关系。"},{"i":35,"n":"第三十五条","txt":"国家采取措施执行联合国安全理事会根据联合国宪章第七章作出的具有约束力的制裁决议和相关措施。"},{"i":36,"n":"第三十六条","txt":"中华人民共和国依据有关法律和缔结或者参加的条约和协定，给予外国外交机构、外国国家官员、国际组织及其官员相应的特权与豁免。"},{"i":37,"n":"第三十七条","txt":"国家依法采取必要措施，保护中国公民和组织在海外的安全和正当权益，保护国家的海外利益不受威胁和侵害。"},{"i":38,"n":"第三十八条","txt":"中华人民共和国依法保护在中国境内的外国人和外国组织的合法权利和利益。"},{"i":39,"n":"第三十九条","txt":"中华人民共和国加强多边双边法治对话，推进对外法治交流合作。"},{"i":40,"n":"第四十条","txt":"国家健全对外工作综合保障体系，增强发展对外关系、维护国家利益的能力。"},{"i":41,"n":"第四十一条","txt":"国家保障对外工作所需经费，建立与发展对外关系需求和国民经济发展水平相适应的经费保障机制。"},{"i":42,"n":"第四十二条","txt":"国家加强对外工作人才队伍建设，采取措施推动做好人才培养、使用、管理、服务、保障等工作。"},{"i":43,"n":"第四十三条","txt":"国家通过多种形式促进社会公众理解和支持对外工作。"},{"i":44,"n":"第四十四条","txt":"国家推进国际传播能力建设，推动世界更好了解和认识中国，促进人类文明交流互鉴。"},{"i":45,"n":"第四十五条","txt":"本法自2023年7月1日起施行。"}],"jieyanfa":[{"i":1,"n":"第一条","txt":"根据中华人民共和国宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在发生严重危及国家的统一、安全或者社会公共安全的动乱、暴乱或者严重骚乱，不采取非常措施不足以维护社会秩序、保护人民的生命和财产安全的紧急状态时，国家可以决定实行戒严。"},{"i":3,"n":"第三条","txt":"全国或者个别省、自治区、直辖市的戒严，由国务院提请全国人民代表大会常务委员会决定；中华人民共和国主席根据全国人民代表大会常务委员会的决定，发布戒严令。"},{"i":4,"n":"第四条","txt":"戒严期间，为保证戒严的实施和维护社会治安秩序，国家可以依照本法在戒严地区内，对宪法、法律规定的公民权利和自由的行使作出特别规定。"},{"i":5,"n":"第五条","txt":"戒严地区内的人民政府应当依照本法采取必要的措施，尽快恢复正常社会秩序，保障人民的生命和财产安全以及基本生活必需品的供应。"},{"i":6,"n":"第六条","txt":"戒严地区内的一切组织和个人，必须严格遵守戒严令和实施戒严令的规定，积极协助人民政府恢复正常社会秩序。"},{"i":7,"n":"第七条","txt":"国家对遵守戒严令和实施戒严令的规定的组织和个人，采取有效措施保护其合法权益不受侵犯。"},{"i":8,"n":"第八条","txt":"戒严任务由人民警察、人民武装警察执行；必要时，国务院可以向中央军事委员会提出，由中央军事委员会决定派出人民解放军协助执行戒严任务。"},{"i":9,"n":"第九条","txt":"全国或者个别省、自治区、直辖市的戒严，由国务院组织实施。"},{"i":10,"n":"第十条","txt":"戒严实施机关建立戒严指挥机构，由戒严指挥机构协调执行戒严任务的有关方面的行动，统一部署和实施戒严措施。"},{"i":11,"n":"第十一条","txt":"戒严令应当规定戒严的地域范围、起始时间、实施机关等事项。"},{"i":12,"n":"第十二条","txt":"根据本法第二条规定实行戒严的紧急状态消除后，应当及时解除戒严。"},{"i":13,"n":"第十三条","txt":"戒严期间，戒严实施机关可以决定在戒严地区采取下列措施，并可以制定具体实施办法："},{"i":14,"n":"第十四条","txt":"戒严期间，戒严实施机关可以决定在戒严地区采取交通管制措施，限制人员进出交通管制区域，并对进出交通管制区域人员的证件、车辆、物品进行检查。"},{"i":15,"n":"第十五条","txt":"戒严期间，戒严实施机关可以决定在戒严地区采取宵禁措施。宵禁期间，在实行宵禁地区的街道或者其他公共场所通行，必须持有本人身份证件和戒严实施机关制发的特别通行证。"},{"i":16,"n":"第十六条","txt":"戒严期间，戒严实施机关或者戒严指挥机构可以在戒严地区对下列物品采取特别管理措施："},{"i":17,"n":"第十七条","txt":"根据执行戒严任务的需要，戒严地区的县级以上人民政府可以临时征用国家机关、企业事业组织、社会团体以及公民个人的房屋、场所、设施、运输工具、工程机械等。在非常紧急的情况下，执行戒严任务的人民警察、人民武装警察、人民解放军的现场指挥员可以直接决定临时征用，地方人民政府应当给予协助。实施征用应当开具征用单据。"},{"i":18,"n":"第十八条","txt":"戒严期间，对戒严地区的下列单位、场所，采取措施，加强警卫："},{"i":19,"n":"第十九条","txt":"为保障戒严地区内的人民基本生活必需品的供应，戒严实施机关可以对基本生活必需品的生产、运输、供应、价格，采取特别管理措施。"},{"i":20,"n":"第二十条","txt":"戒严实施机关依照本法采取的实施戒严令的措施和办法，需要公众遵守的，应当公布；在实施过程中，根据情况，对于不需要继续实施的措施和办法，应当及时公布停止实施。"},{"i":21,"n":"第二十一条","txt":"执行戒严任务的人民警察、人民武装警察和人民解放军是戒严执勤人员。"},{"i":22,"n":"第二十二条","txt":"戒严执勤人员依照戒严实施机关的规定，有权对戒严地区公共道路上或者其他公共场所内的人员的证件、车辆、物品进行检查。"},{"i":23,"n":"第二十三条","txt":"戒严执勤人员依照戒严实施机关的规定，有权对违反宵禁规定的人予以扣留，直至清晨宵禁结束；并有权对被扣留者的人身进行搜查，对其携带的物品进行检查。"},{"i":24,"n":"第二十四条","txt":"戒严执勤人员依照戒严实施机关的规定，有权对下列人员立即予以拘留："},{"i":25,"n":"第二十五条","txt":"戒严执勤人员依照戒严实施机关的规定，有权对被拘留的人员的人身进行搜查，有权对犯罪嫌疑分子的住所和涉嫌藏匿犯罪分子、犯罪嫌疑分子或者武器、弹药等危险物品的场所进行搜查。"},{"i":26,"n":"第二十六条","txt":"在戒严地区有下列聚众情形之一、阻止无效的，戒严执勤人员根据有关规定，可以使用警械强行制止或者驱散，并将其组织者和拒不服从的人员强行带离现场或者立即予以拘留："},{"i":27,"n":"第二十七条","txt":"戒严执勤人员对于依照本法规定予以拘留的人员，应当及时登记和讯问，发现不需要继续拘留的，应当立即释放。"},{"i":28,"n":"第二十八条","txt":"在戒严地区遇有下列特别紧急情形之一，使用警械无法制止时，戒严执勤人员可以使用枪支等武器："},{"i":29,"n":"第二十九条","txt":"戒严执勤人员应当遵守法律、法规和执勤规则，服从命令，履行职责，尊重当地民族风俗习惯，不得侵犯和损害公民的合法权益。"},{"i":30,"n":"第三十条","txt":"戒严执勤人员依法执行任务的行为受法律保护。"},{"i":31,"n":"第三十一条","txt":"在个别县、市的局部范围内突然发生严重骚乱，严重危及国家安全、社会公共安全和人民的生命财产安全，国家没有作出戒严决定时，当地省级人民政府报经国务院批准，可以决定并组织人民警察、人民武装警察实施交通管制和现场管制，限制人员进出管制区域，对进出管制区域人员的证件、车辆、物品进行检查，对参与骚乱的人可以强行予以驱散、强行带离现场、搜查，对组织者和拒不服从的人员可以立即予以拘留；在人民警察、人民武装警察力量还不足以维持社会秩序时，可以报请国务院向中央军事委员会提出，由中央军事委员会决定派出人民解放军协助当地人民政府恢复和维持正常社会秩序。"},{"i":32,"n":"第三十二条","txt":"本法自公布之日起施行。"}],"cunminweiyuanhuizuzhifa":[{"i":1,"n":"第一条","txt":"为了健全基层群众自治制度，由村民依法办理自己的事情，发展基层民主，维护村民的合法权益，促进乡村全面振兴，推进基层治理体系和治理能力现代化，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"村民委员会是村民自我管理、自我服务、自我教育、自我监督的基层群众性自治组织，实行民主选举、民主协商、民主决策、民主管理、民主监督。"},{"i":3,"n":"第三条","txt":"村民委员会根据村民居住状况、人口多少，按照便于村民自治，有利于经济发展和基层治理的原则设立。"},{"i":4,"n":"第四条","txt":"村民委员会工作坚持中国共产党的领导，坚持和发展全过程人民民主，坚持自治、法治、德治相结合。"},{"i":5,"n":"第五条","txt":"中央和地方基层群众自治指导监督部门负责指导和监督农村基层群众自治工作。"},{"i":6,"n":"第六条","txt":"乡、民族乡、镇的人民政府对村民委员会的工作给予指导、支持和帮助，但是不得干预依法属于村民自治范围内的事项。"},{"i":7,"n":"第七条","txt":"对在村民自治工作中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":8,"n":"第八条","txt":"村民委员会由主任、副主任和委员共三至七人组成。"},{"i":9,"n":"第九条","txt":"村民委员会根据需要设人民调解、治安保卫、公共卫生、人居环境、老年人和妇女儿童工作等委员会。村民委员会成员可以兼任下属委员会的成员。人口少的村的村民委员会可以不设下属委员会，由村民委员会成员分工负责有关工作。"},{"i":10,"n":"第十条","txt":"村民委员会应当支持和组织村民依法发展各种形式的合作经济和其他经济，承担本村生产的服务和协调工作，促进农村生产建设和经济发展。"},{"i":11,"n":"第十一条","txt":"村民委员会应当宣传宪法、法律、法规，宣传党和国家的政策，支持和推动村民履行法律规定的义务，维护村民的合法权益，支持和引导村民践行社会主义核心价值观，铸牢中华民族共同体意识，发展文化教育，普及科技知识，促进男女平等和家庭和睦，关心关爱老年人、留守儿童、残疾人和困难村民，增强团结互助，推进移风易俗，培育文明乡风。"},{"i":12,"n":"第十二条","txt":"村民委员会及其成员应当遵守宪法、法律、法规，遵守党和国家的政策，遵守并组织实施村民自治章程、村规民约，执行村民会议、村民代表会议的决定、决议，办事公道，廉洁奉公，热心为村民服务，接受村民监督。"},{"i":13,"n":"第十三条","txt":"村民委员会具有基层群众性自治组织法人资格，村民委员会主任为法定代表人。村民委员会可以从事为履行职能所需要的民事活动，但是不得提供担保。"},{"i":14,"n":"第十四条","txt":"村民委员会主任、副主任和委员，由村民直接选举产生。任何组织或者个人不得指定、委派或者撤换村民委员会成员。"},{"i":15,"n":"第十五条","txt":"村民委员会的选举，由村民选举委员会主持。"},{"i":16,"n":"第十六条","txt":"年满十八周岁的村民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是，依照法律被剥夺政治权利的人除外。"},{"i":17,"n":"第十七条","txt":"登记参加选举的村民名单应当在选举日的二十日前由村民选举委员会公布。"},{"i":18,"n":"第十八条","txt":"村民委员会成员候选人由村党组织或者登记参加选举的村民提名推荐。提名推荐候选人，应当从全体村民利益出发，推荐拥护中国共产党的领导、奉公守法、品行良好、公道正派、热心公益、具有一定文化水平和工作能力的村民为候选人。被开除中国共产党党籍，因犯罪受过刑事处罚，利用宗族或者黑恶势力从事非法活动，组织或者参加非法宗教活动或者邪教活动的，不得作为候选人。候选人的名额应当多于应选名额。村民选举委员会应当组织候选人与村民见面，由候选人介绍履行职责的设想，回答村民提出的问题。"},{"i":19,"n":"第十九条","txt":"本村五分之一以上有选举权的村民或者三分之一以上的村民代表联名，可以提出罢免村民委员会成员的要求，并说明要求罢免的理由。被提出罢免的村民委员会成员有权提出申辩意见。"},{"i":20,"n":"第二十条","txt":"村民委员会成员可以向村民委员会提出辞职申请，其职务自村民会议或者村民代表会议审议通过之日起终止。"},{"i":21,"n":"第二十一条","txt":"以暴力、威胁、欺骗、贿赂、伪造选票、虚报选举票数等不正当手段当选村民委员会成员的，当选无效。"},{"i":22,"n":"第二十二条","txt":"村民委员会成员丧失行为能力或者被判处刑罚的，其职务自行终止。"},{"i":23,"n":"第二十三条","txt":"村民委员会成员出缺，可以由村民会议或者村民代表会议进行补选。补选程序参照本法第十八条的规定办理。补选的村民委员会成员的任期到本届村民委员会任期届满时止。"},{"i":24,"n":"第二十四条","txt":"村民委员会应当自新一届村民委员会产生之日起十日内完成工作移交。工作移交由村民选举委员会主持，由乡、民族乡、镇的人民政府监督。"},{"i":25,"n":"第二十五条","txt":"村民会议由本村十八周岁以上的村民组成。"},{"i":26,"n":"第二十六条","txt":"召开村民会议，应当有本村十八周岁以上村民的过半数，或者本村三分之二以上的户的代表参加，村民会议所作决定应当经到会人员的过半数通过。法律对召开村民会议及作出决定另有规定的，依照其规定。"},{"i":27,"n":"第二十七条","txt":"村民会议审议村民委员会的年度工作报告，评议村民委员会成员的工作；有权撤销或者变更村民委员会不适当的决定；有权撤销或者变更村民代表会议不适当的决定。"},{"i":28,"n":"第二十八条","txt":"涉及村民利益的下列事项，经村民会议讨论决定方可办理："},{"i":29,"n":"第二十九条","txt":"人数较多或者居住分散的村，可以设立村民代表会议，讨论决定村民会议授权的事项。村民代表会议由村民委员会成员和村民代表组成，村民代表应当占村民代表会议组成人员的五分之四以上，妇女村民代表应当占村民代表会议组成人员的三分之一以上。"},{"i":30,"n":"第三十条","txt":"村民代表会议由村民委员会召集。村民代表会议每季度召开一次。有五分之一以上的村民代表提议，应当召集村民代表会议。"},{"i":31,"n":"第三十一条","txt":"村民会议可以制定和修改村民自治章程、村规民约，并报乡、民族乡、镇的人民政府备案。"},{"i":32,"n":"第三十二条","txt":"村民小组在村民委员会的组织下开展活动。村民小组会议讨论决定本村民小组的重要事项。"},{"i":33,"n":"第三十三条","txt":"对涉及村民切身利益的公共事务、公益事业以及村民反映的实际困难和矛盾纠纷，村民委员会应当组织村民及其他利益相关方开展协商。"},{"i":34,"n":"第三十四条","txt":"村民委员会应当实行少数服从多数的民主决策机制和公开透明的工作原则，建立健全各种工作制度。"},{"i":35,"n":"第三十五条","txt":"村民委员会实行村务公开制度。"},{"i":36,"n":"第三十六条","txt":"村民委员会不及时公布应当公布的事项或者公布的事项不真实的，村民有权向乡、民族乡、镇的人民政府或者县级人民政府及其有关主管部门反映，有关人民政府或者主管部门应当负责调查核实，责令依法公布；经查证确有违法行为的，有关人员应当依法承担责任。"},{"i":37,"n":"第三十七条","txt":"村应当建立村务监督委员会或者其他形式的村务监督机构，负责村民民主理财，监督村务公开等制度的落实，其成员由村民会议或者村民代表会议在村民中推选产生，其中应有具备财会、管理知识的人员。村民委员会成员及其近亲属不得担任村务监督机构成员。村务监督机构的任期与村民委员会的任期相同。"},{"i":38,"n":"第三十八条","txt":"村民委员会成员以及由村民或者村集体承担误工补贴的聘用人员，应当接受村民会议或者村民代表会议对其履行职责情况的民主评议。民主评议每年至少进行一次，由村务监督机构主持。"},{"i":39,"n":"第三十九条","txt":"村民委员会和村务监督机构应当建立村务档案。村务档案包括：选举文件和选票，会议记录，公益设施基本资料，基本建设资料等。村务档案应当真实、准确、完整和规范。"},{"i":40,"n":"第四十条","txt":"村民委员会成员实行任期和离任经济责任审计，审计包括下列事项："},{"i":41,"n":"第四十一条","txt":"村民委员会或者村民委员会成员作出的决定侵害村民合法权益的，受侵害的村民可以申请人民法院予以撤销，责任人依法承担法律责任。"},{"i":42,"n":"第四十二条","txt":"村民委员会日常运转经费、成员基本报酬标准由县级以上人民政府规定，并由县级人民政府给予适当补助。"},{"i":43,"n":"第四十三条","txt":"乡、民族乡、镇的人民政府对村民委员会协助政府开展工作应当提供必要的经费和条件。"},{"i":44,"n":"第四十四条","txt":"村级综合服务设施建设应当纳入相关规划。县级以上地方人民政府应当对村级综合服务设施建设给予支持。"},{"i":45,"n":"第四十五条","txt":"乡、民族乡、镇的人民政府或者县级人民政府应当为村民委员会成员以及其他村务工作者提供培训，帮助其提升政治素质、法治意识、政策水平和服务能力。"},{"i":46,"n":"第四十六条","txt":"不设区的市、市辖区、街道以及开发区、林区、垦区等设立村民委员会的，适用本法有关规定。"},{"i":47,"n":"第四十七条","txt":"驻在农村的机关、团体、部队、国有及国有控股企业、事业单位及其人员不参加村民委员会组织，但应当通过多种形式参与乡村建设，并遵守有关村规民约。"},{"i":48,"n":"第四十八条","txt":"地方各级人民代表大会和县级以上地方各级人民代表大会常务委员会在本行政区域内保证本法的实施，保障村民依法行使自治权利。"},{"i":49,"n":"第四十九条","txt":"省、自治区、直辖市的人民代表大会常务委员会根据本法，结合本行政区域的实际情况，制定实施办法。"},{"i":50,"n":"第五十条","txt":"本法自公布之日起施行。"}],"jianchaguanfa":[{"i":1,"n":"第一条","txt":"为了全面推进高素质检察官队伍建设，加强对检察官的管理和监督，维护检察官合法权益，保障人民检察院依法独立行使检察权，保障检察官依法履行职责，保障司法公正，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"检察官是依法行使国家检察权的检察人员，包括最高人民检察院、地方各级人民检察院和军事检察院等专门人民检察院的检察长、副检察长、检察委员会委员和检察员。"},{"i":3,"n":"第三条","txt":"检察官必须忠实执行宪法和法律，维护社会公平正义，全心全意为人民服务。"},{"i":4,"n":"第四条","txt":"检察官应当勤勉尽责，清正廉明，恪守职业道德。"},{"i":5,"n":"第五条","txt":"检察官履行职责，应当以事实为根据，以法律为准绳，秉持客观公正的立场。"},{"i":6,"n":"第六条","txt":"检察官依法履行职责，受法律保护，不受行政机关、社会团体和个人的干涉。"},{"i":7,"n":"第七条","txt":"检察官的职责："},{"i":8,"n":"第八条","txt":"人民检察院检察长、副检察长、检察委员会委员除履行检察职责外，还应当履行与其职务相适应的职责。"},{"i":9,"n":"第九条","txt":"检察官在检察长领导下开展工作，重大办案事项由检察长决定。检察长可以将部分职权委托检察官行使，可以授权检察官签发法律文书。"},{"i":10,"n":"第十条","txt":"检察官应当履行下列义务："},{"i":11,"n":"第十一条","txt":"检察官享有下列权利："},{"i":12,"n":"第十二条","txt":"担任检察官必须具备下列条件："},{"i":13,"n":"第十三条","txt":"下列人员不得担任检察官："},{"i":14,"n":"第十四条","txt":"初任检察官采用考试、考核的办法，按照德才兼备的标准，从具备检察官条件的人员中择优提出人选。"},{"i":15,"n":"第十五条","txt":"人民检察院可以根据检察工作需要，从律师或者法学教学、研究人员等从事法律职业的人员中公开选拔检察官。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市设立检察官遴选委员会，负责初任检察官人选专业能力的审核。"},{"i":17,"n":"第十七条","txt":"初任检察官一般到基层人民检察院任职。上级人民检察院检察官一般逐级遴选；最高人民检察院和省级人民检察院检察官可以从下两级人民检察院遴选。参加上级人民检察院遴选的检察官应当在下级人民检察院担任检察官一定年限，并具有遴选职位相关工作经历。"},{"i":18,"n":"第十八条","txt":"检察官的任免，依照宪法和法律规定的任免权限和程序办理。"},{"i":19,"n":"第十九条","txt":"检察官在依照法定程序产生后，在就职时应当公开进行宪法宣誓。"},{"i":20,"n":"第二十条","txt":"检察官有下列情形之一的，应当依法提请免除其检察官职务："},{"i":21,"n":"第二十一条","txt":"对于不具备本法规定条件或者违反法定程序被选举为人民检察院检察长的，上一级人民检察院检察长有权提请本级人民代表大会常务委员会不批准。"},{"i":22,"n":"第二十二条","txt":"发现违反本法规定的条件任命检察官的，任命机关应当撤销该项任命；上级人民检察院发现下级人民检察院检察官的任命违反本法规定的条件的，应当要求下级人民检察院依法提请任命机关撤销该项任命。"},{"i":23,"n":"第二十三条","txt":"检察官不得兼任人民代表大会常务委员会的组成人员，不得兼任行政机关、监察机关、审判机关的职务，不得兼任企业或者其他营利性组织、事业单位的职务，不得兼任律师、仲裁员和公证员。"},{"i":24,"n":"第二十四条","txt":"检察官之间有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的，不得同时担任下列职务："},{"i":25,"n":"第二十五条","txt":"检察官的配偶、父母、子女有下列情形之一的，检察官应当实行任职回避："},{"i":26,"n":"第二十六条","txt":"检察官实行员额制管理。检察官员额根据案件数量、经济社会发展情况、人口数量和人民检察院层级等因素确定，在省、自治区、直辖市内实行总量控制、动态管理，优先考虑基层人民检察院和案件数量多的人民检察院办案需要。"},{"i":27,"n":"第二十七条","txt":"检察官实行单独职务序列管理。"},{"i":28,"n":"第二十八条","txt":"最高人民检察院检察长为首席大检察官。"},{"i":29,"n":"第二十九条","txt":"检察官等级的确定，以检察官德才表现、业务水平、检察工作实绩和工作年限等为依据。"},{"i":30,"n":"第三十条","txt":"检察官的等级设置、确定和晋升的具体办法，由国家另行规定。"},{"i":31,"n":"第三十一条","txt":"初任检察官实行统一职前培训制度。"},{"i":32,"n":"第三十二条","txt":"对检察官应当有计划地进行政治、理论和业务培训。"},{"i":33,"n":"第三十三条","txt":"检察官培训情况，作为检察官任职、等级晋升的依据之一。"},{"i":34,"n":"第三十四条","txt":"检察官培训机构按照有关规定承担培训检察官的任务。"},{"i":35,"n":"第三十五条","txt":"检察官申请辞职，应当由本人书面提出，经批准后，依照法律规定的程序免除其职务。"},{"i":36,"n":"第三十六条","txt":"辞退检察官应当依照法律规定的程序免除其职务。"},{"i":37,"n":"第三十七条","txt":"检察官从人民检察院离任后两年内，不得以律师身份担任诉讼代理人或者辩护人。"},{"i":38,"n":"第三十八条","txt":"检察官因工作需要，经单位选派或者批准，可以在高等学校、科研院所协助开展实践性教学、研究工作，并遵守国家有关规定。"},{"i":39,"n":"第三十九条","txt":"人民检察院设立检察官考评委员会，负责对本院检察官的考核工作。"},{"i":40,"n":"第四十条","txt":"检察官考评委员会的组成人员为五至九人。"},{"i":41,"n":"第四十一条","txt":"对检察官的考核，应当全面、客观、公正，实行平时考核和年度考核相结合。"},{"i":42,"n":"第四十二条","txt":"对检察官的考核内容包括：检察工作实绩、职业道德、专业水平、工作能力、工作作风。重点考核检察工作实绩。"},{"i":43,"n":"第四十三条","txt":"年度考核结果分为优秀、称职、基本称职和不称职四个等次。"},{"i":44,"n":"第四十四条","txt":"考核结果以书面形式通知检察官本人。检察官对考核结果如果有异议，可以申请复核。"},{"i":45,"n":"第四十五条","txt":"检察官在检察工作中有显著成绩和贡献的，或者有其他突出事迹的，应当给予奖励。"},{"i":46,"n":"第四十六条","txt":"检察官有下列表现之一的，应当给予奖励："},{"i":47,"n":"第四十七条","txt":"检察官有下列行为之一的，应当给予处分；构成犯罪的，依法追究刑事责任："},{"i":48,"n":"第四十八条","txt":"检察官涉嫌违纪违法，已经被立案调查、侦查，不宜继续履行职责的，按照管理权限和规定的程序暂时停止其履行职务。"},{"i":49,"n":"第四十九条","txt":"最高人民检察院和省、自治区、直辖市设立检察官惩戒委员会，负责从专业角度审查认定检察官是否存在本法第四十七条第四项、第五项规定的违反检察职责的行为，提出构成故意违反职责、存在重大过失、存在一般过失或者没有违反职责等审查意见。检察官惩戒委员会提出审查意见后，人民检察院依照有关规定作出是否予以惩戒的决定，并给予相应处理。"},{"i":50,"n":"第五十条","txt":"检察官惩戒委员会审议惩戒事项时，当事检察官有权申请有关人员回避，有权进行陈述、举证、辩解。"},{"i":51,"n":"第五十一条","txt":"检察官惩戒委员会作出的审查意见应当送达当事检察官。当事检察官对审查意见有异议的，可以向惩戒委员会提出，惩戒委员会应当对异议及其理由进行审查，作出决定。"},{"i":52,"n":"第五十二条","txt":"检察官惩戒委员会审议惩戒事项的具体程序，由最高人民检察院商有关部门确定。"},{"i":53,"n":"第五十三条","txt":"人民检察院设立检察官权益保障委员会，维护检察官合法权益，保障检察官依法履行职责。"},{"i":54,"n":"第五十四条","txt":"除下列情形外，不得将检察官调离检察业务岗位："},{"i":55,"n":"第五十五条","txt":"任何单位或者个人不得要求检察官从事超出法定职责范围的事务。"},{"i":56,"n":"第五十六条","txt":"检察官的职业尊严和人身安全受法律保护。"},{"i":57,"n":"第五十七条","txt":"检察官因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，人民检察院应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任。"},{"i":58,"n":"第五十八条","txt":"检察官因依法履行职责，本人及其近亲属人身安全面临危险的，人民检察院、公安机关应当对检察官及其近亲属采取人身保护、禁止特定人员接触等必要保护措施。"},{"i":59,"n":"第五十九条","txt":"检察官实行与其职责相适应的工资制度，按照检察官等级享有国家规定的工资待遇，并建立与公务员工资同步调整机制。"},{"i":60,"n":"第六十条","txt":"检察官实行定期增资制度。"},{"i":61,"n":"第六十一条","txt":"检察官享受国家规定的津贴、补贴、奖金、保险和福利待遇。"},{"i":62,"n":"第六十二条","txt":"检察官因公致残的，享受国家规定的伤残待遇。检察官因公牺牲、因公死亡或者病故的，其亲属享受国家规定的抚恤和优待。"},{"i":63,"n":"第六十三条","txt":"检察官的退休制度，根据检察工作特点，由国家另行规定。"},{"i":64,"n":"第六十四条","txt":"检察官退休后，享受国家规定的养老金和其他待遇。"},{"i":65,"n":"第六十五条","txt":"对于国家机关及其工作人员侵犯本法第十一条规定的检察官权利的行为，检察官有权提出控告。"},{"i":66,"n":"第六十六条","txt":"对检察官处分或者人事处理错误的，应当及时予以纠正；造成名誉损害的，应当恢复名誉、消除影响、赔礼道歉；造成经济损失的，应当赔偿。对打击报复的直接责任人员，应当依法追究其责任。"},{"i":67,"n":"第六十七条","txt":"国家对初任检察官实行统一法律职业资格考试制度，由国务院司法行政部门商最高人民检察院等有关部门组织实施。"},{"i":68,"n":"第六十八条","txt":"人民检察院的检察官助理在检察官指导下负责审查案件材料、草拟法律文书等检察辅助事务。"},{"i":69,"n":"第六十九条","txt":"有关检察官的权利、义务和管理制度，本法已有规定的，适用本法的规定；本法未作规定的，适用公务员管理的相关法律法规。"},{"i":70,"n":"第七十条","txt":"本法自2019年10月1日起施行。"}],"minzuquyuzizhifa":[{"i":1,"n":"第一条","txt":"中华人民共和国民族区域自治法，根据中华人民共和国宪法制定。"},{"i":2,"n":"第二条","txt":"各少数民族聚居的地方实行区域自治。"},{"i":3,"n":"第三条","txt":"民族自治地方设立自治机关，自治机关是国家的一级地方政权机关。"},{"i":4,"n":"第四条","txt":"民族自治地方的自治机关行使宪法第三章第五节规定的地方国家机关的职权，同时依照宪法和本法以及其他法律规定的权限行使自治权，根据本地方的实际情况贯彻执行国家的法律、政策。"},{"i":5,"n":"第五条","txt":"民族自治地方的自治机关必须维护国家的统一，保证宪法和法律在本地方的遵守和执行。"},{"i":6,"n":"第六条","txt":"民族自治地方的自治机关领导各族人民集中力量进行社会主义现代化建设。"},{"i":7,"n":"第七条","txt":"民族自治地方的自治机关要把国家的整体利益放在首位，积极完成上级国家机关交给的各项任务。"},{"i":8,"n":"第八条","txt":"上级国家机关保障民族自治地方的自治机关行使自治权，并且依据民族自治地方的特点和需要，努力帮助民族自治地方加速发展社会主义建设事业。"},{"i":9,"n":"第九条","txt":"上级国家机关和民族自治地方的自治机关维护和发展各民族的平等、团结、互助的社会主义民族关系。禁止对任何民族的歧视和压迫，禁止破坏民族团结和制造民族分裂的行为。"},{"i":10,"n":"第十条","txt":"民族自治地方的自治机关保障本地方各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。"},{"i":11,"n":"第十一条","txt":"民族自治地方的自治机关保障各民族公民有宗教信仰自由。"},{"i":12,"n":"第十二条","txt":"少数民族聚居的地方，根据当地民族关系、经济发展等条件，并参酌历史情况，可以建立以一个或者几个少数民族聚居区为基础的自治地方。"},{"i":13,"n":"第十三条","txt":"民族自治地方的名称，除特殊情况外，按照地方名称、民族名称、行政地位的顺序组成。"},{"i":14,"n":"第十四条","txt":"民族自治地方的建立、区域界线的划分、名称的组成，由上级国家机关会同有关地方的国家机关，和有关民族的代表充分协商拟定，按照法律规定的程序报请批准。"},{"i":15,"n":"第十五条","txt":"民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。"},{"i":16,"n":"第十六条","txt":"民族自治地方的人民代表大会中，除实行区域自治的民族的代表外，其他居住在本行政区域内的民族也应当有适当名额的代表。"},{"i":17,"n":"第十七条","txt":"自治区主席、自治州州长、自治县县长由实行区域自治的民族的公民担任。自治区、自治州、自治县的人民政府的其他组成人员，应当合理配备实行区域自治的民族和其他少数民族的人员。"},{"i":18,"n":"第十八条","txt":"民族自治地方的自治机关所属工作部门的干部中，应当合理配备实行区域自治的民族和其他少数民族的人员。"},{"i":19,"n":"第十九条","txt":"民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例报省、自治区、直辖市的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会和国务院备案。"},{"i":20,"n":"第二十条","txt":"上级国家机关的决议、决定、命令和指示，如有不适合民族自治地方实际情况的，自治机关可以报经该上级国家机关批准，变通执行或者停止执行；该上级国家机关应当在收到报告之日起六十日内给予答复。"},{"i":21,"n":"第二十一条","txt":"民族自治地方的自治机关在执行职务的时候，依照本民族自治地方自治条例的规定，使用当地通用的一种或者几种语言文字；同时使用几种通用的语言文字执行职务的，可以以实行区域自治的民族的语言文字为主。"},{"i":22,"n":"第二十二条","txt":"民族自治地方的自治机关根据社会主义建设的需要，采取各种措施从当地民族中大量培养各级干部、各种科学技术、经营管理等专业人才和技术工人，充分发挥他们的作用，并且注意在少数民族妇女中培养各级干部和各种专业技术人才。"},{"i":23,"n":"第二十三条","txt":"民族自治地方的企业、事业单位依照国家规定招收人员时，优先招收少数民族人员，并且可以从农村和牧区少数民族人口中招收。"},{"i":24,"n":"第二十四条","txt":"民族自治地方的自治机关依照国家的军事制度和当地的实际需要，经国务院批准，可以组织本地方维护社会治安的公安部队。"},{"i":25,"n":"第二十五条","txt":"民族自治地方的自治机关在国家计划的指导下，根据本地方的特点和需要，制定经济建设的方针、政策和计划，自主地安排和管理地方性的经济建设事业。"},{"i":26,"n":"第二十六条","txt":"民族自治地方的自治机关在坚持社会主义原则的前提下，根据法律规定和本地方经济发展的特点，合理调整生产关系和经济结构，努力发展社会主义市场经济。"},{"i":27,"n":"第二十七条","txt":"民族自治地方的自治机关根据法律规定，确定本地方内草场和森林的所有权和使用权。"},{"i":28,"n":"第二十八条","txt":"民族自治地方的自治机关依照法律规定，管理和保护本地方的自然资源。"},{"i":29,"n":"第二十九条","txt":"民族自治地方的自治机关在国家计划的指导下，根据本地方的财力、物力和其他具体条件，自主地安排地方基本建设项目。"},{"i":30,"n":"第三十条","txt":"民族自治地方的自治机关自主地管理隶属于本地方的企业、事业。"},{"i":31,"n":"第三十一条","txt":"民族自治地方依照国家规定，可以开展对外经济贸易活动，经国务院批准，可以开辟对外贸易口岸。"},{"i":32,"n":"第三十二条","txt":"民族自治地方的财政是一级财政，是国家财政的组成部分。"},{"i":33,"n":"第三十三条","txt":"民族自治地方的自治机关对本地方的各项开支标准、定员、定额，根据国家规定的原则，结合本地方的实际情况，可以制定补充规定和具体办法。自治区制定的补充规定和具体办法，报国务院备案；自治州、自治县制定的补充规定和具体办法，须报省、自治区、直辖市人民政府批准。"},{"i":34,"n":"第三十四条","txt":"民族自治地方的自治机关在执行国家税法的时候，除应由国家统一审批的减免税收项目以外，对属于地方财政收入的某些需要从税收上加以照顾和鼓励的，可以实行减税或者免税。自治州、自治县决定减税或者免税，须报省、自治区、直辖市人民政府批准。"},{"i":35,"n":"第三十五条","txt":"民族自治地方根据本地方经济和社会发展的需要，可以依照法律规定设立地方商业银行和城乡信用合作组织。"},{"i":36,"n":"第三十六条","txt":"民族自治地方的自治机关根据国家的教育方针，依照法律规定，决定本地方的教育规划，各级各类学校的设置、学制、办学形式、教学内容、教学用语和招生办法。"},{"i":37,"n":"第三十七条","txt":"民族自治地方的自治机关自主地发展民族教育，扫除文盲，举办各类学校，普及九年义务教育，采取多种形式发展普通高级中等教育和中等职业技术教育，根据条件和需要发展高等教育，培养各少数民族专业人才。"},{"i":38,"n":"第三十八条","txt":"民族自治地方的自治机关自主地发展具有民族形式和民族特点的文学、艺术、新闻、出版、广播、电影、电视等民族文化事业，加大对文化事业的投入，加强文化设施建设，加快各项文化事业的发展。"},{"i":39,"n":"第三十九条","txt":"民族自治地方的自治机关自主地决定本地方的科学技术发展规划，普及科学技术知识。"},{"i":40,"n":"第四十条","txt":"民族自治地方的自治机关，自主地决定本地方的医疗卫生事业的发展规划，发展现代医药和民族传统医药。"},{"i":41,"n":"第四十一条","txt":"民族自治地方的自治机关自主地发展体育事业，开展民族传统体育活动，增强各族人民的体质。"},{"i":42,"n":"第四十二条","txt":"民族自治地方的自治机关积极开展和其他地方的教育、科学技术、文化艺术、卫生、体育等方面的交流和协作。"},{"i":43,"n":"第四十三条","txt":"民族自治地方的自治机关根据法律规定，制定管理流动人口的办法。"},{"i":44,"n":"第四十四条","txt":"民族自治地方实行计划生育和优生优育，提高各民族人口素质。"},{"i":45,"n":"第四十五条","txt":"民族自治地方的自治机关保护和改善生活环境和生态环境，防治污染和其他公害，实现人口、资源和环境的协调发展。"},{"i":46,"n":"第四十六条","txt":"民族自治地方的人民法院和人民检察院对本级人民代表大会及其常务委员会负责。民族自治地方的人民检察院并对上级人民检察院负责。"},{"i":47,"n":"第四十七条","txt":"民族自治地方的人民法院和人民检察院应当用当地通用的语言审理和检察案件，并合理配备通晓当地通用的少数民族语言文字的人员。对于不通晓当地通用的语言文字的诉讼参与人，应当为他们提供翻译。法律文书应当根据实际需要，使用当地通用的一种或者几种文字。保障各民族公民都有使用本民族语言文字进行诉讼的权利。"},{"i":48,"n":"第四十八条","txt":"民族自治地方的自治机关保障本地方内各民族都享有平等权利。"},{"i":49,"n":"第四十九条","txt":"民族自治地方的自治机关教育和鼓励各民族的干部互相学习语言文字。汉族干部要学习当地少数民族的语言文字，少数民族干部在学习、使用本民族语言文字的同时，也要学习全国通用的普通话和规范汉字。"},{"i":50,"n":"第五十条","txt":"民族自治地方的自治机关帮助聚居在本地方的其他少数民族，建立相应的自治地方或者民族乡。"},{"i":51,"n":"第五十一条","txt":"民族自治地方的自治机关在处理涉及本地方各民族的特殊问题的时候，必须与他们的代表充分协商，尊重他们的意见。"},{"i":52,"n":"第五十二条","txt":"民族自治地方的自治机关保障本地方内各民族公民都享有宪法规定的公民权利，并且教育他们履行公民应尽的义务。"},{"i":53,"n":"第五十三条","txt":"民族自治地方的自治机关提倡爱祖国、爱人民、爱劳动、爱科学、爱社会主义的公德，对本地方内各民族公民进行爱国主义、共产主义和民族政策的教育。教育各民族的干部和群众互相信任，互相学习，互相帮助，互相尊重语言文字、风俗习惯和宗教信仰，共同维护国家的统一和各民族的团结。"},{"i":54,"n":"第五十四条","txt":"上级国家机关有关民族自治地方的决议、决定、命令和指示，应当适合民族自治地方的实际情况。"},{"i":55,"n":"第五十五条","txt":"上级国家机关应当帮助、指导民族自治地方经济发展战略的研究、制定和实施，从财政、金融、物资、技术和人才等方面，帮助各民族自治地方加速发展经济、教育、科学技术、文化、卫生、体育等事业。"},{"i":56,"n":"第五十六条","txt":"国家根据统一规划和市场需求，优先在民族自治地方合理安排资源开发项目和基础设施建设项目。国家在重大基础设施投资项目中适当增加投资比重和政策性银行贷款比重。"},{"i":57,"n":"第五十七条","txt":"国家根据民族自治地方的经济发展特点和需要，综合运用货币市场和资本市场，加大对民族自治地方的金融扶持力度。金融机构对民族自治地方的固定资产投资项目和符合国家产业政策的企业，在开发资源、发展多种经济方面的合理资金需求，应当给予重点扶持。"},{"i":58,"n":"第五十八条","txt":"上级国家机关从财政、金融、人才等方面帮助民族自治地方的企业进行技术创新，促进产业结构升级。"},{"i":59,"n":"第五十九条","txt":"国家设立各项专用资金，扶助民族自治地方发展经济文化建设事业。"},{"i":60,"n":"第六十条","txt":"上级国家机关根据国家的民族贸易政策和民族自治地方的需要，对民族自治地方的商业、供销和医药企业，从投资、金融、税收等方面给予扶持。"},{"i":61,"n":"第六十一条","txt":"国家制定优惠政策，扶持民族自治地方发展对外经济贸易，扩大民族自治地方生产企业对外贸易经营自主权，鼓励发展地方优势产品出口，实行优惠的边境贸易政策。"},{"i":62,"n":"第六十二条","txt":"随着国民经济的发展和财政收入的增长，上级财政逐步加大对民族自治地方财政转移支付力度。通过一般性财政转移支付、专项财政转移支付、民族优惠政策财政转移支付以及国家确定的其他方式，增加对民族自治地方的资金投入，用于加快民族自治地方经济发展和社会进步，逐步缩小与发达地区的差距。"},{"i":63,"n":"第六十三条","txt":"上级国家机关在投资、金融、税收等方面扶持民族自治地方改善农业、牧业、林业等生产条件和水利、交通、能源、通信等基础设施；扶持民族自治地方合理利用本地资源发展地方工业、乡镇企业、中小企业以及少数民族特需商品和传统手工业品的生产。"},{"i":64,"n":"第六十四条","txt":"上级国家机关应当组织、支持和鼓励经济发达地区与民族自治地方开展经济、技术协作和多层次、多方面的对口支援，帮助和促进民族自治地方经济、教育、科学技术、文化、卫生、体育事业的发展。"},{"i":65,"n":"第六十五条","txt":"国家在民族自治地方开发资源、进行建设的时候，应当照顾民族自治地方的利益，作出有利于民族自治地方经济建设的安排，照顾当地少数民族的生产和生活。国家采取措施，对输出自然资源的民族自治地方给予一定的利益补偿。"},{"i":66,"n":"第六十六条","txt":"上级国家机关应当把民族自治地方的重大生态平衡、环境保护的综合治理工程项目纳入国民经济和社会发展计划，统一部署。"},{"i":67,"n":"第六十七条","txt":"上级国家机关隶属的在民族自治地方的企业、事业单位依照国家规定招收人员时，优先招收当地少数民族人员。"},{"i":68,"n":"第六十八条","txt":"上级国家机关非经民族自治地方自治机关同意，不得改变民族自治地方所属企业的隶属关系。"},{"i":69,"n":"第六十九条","txt":"国家和上级人民政府应当从财政、金融、物资、技术、人才等方面加大对民族自治地方的贫困地区的扶持力度，帮助贫困人口尽快摆脱贫困状况，实现小康。"},{"i":70,"n":"第七十条","txt":"上级国家机关帮助民族自治地方从当地民族中大量培养各级干部、各种专业人才和技术工人；根据民族自治地方的需要，采取多种形式调派适当数量的教师、医生、科学技术和经营管理人员，参加民族自治地方的工作，对他们的生活待遇给予适当照顾。"},{"i":71,"n":"第七十一条","txt":"国家加大对民族自治地方的教育投入，并采取特殊措施，帮助民族自治地方加速普及九年义务教育和发展其他教育事业，提高各民族人民的科学文化水平。"},{"i":72,"n":"第七十二条","txt":"上级国家机关应当对各民族的干部和群众加强民族政策的教育，经常检查民族政策和有关法律的遵守和执行。"},{"i":73,"n":"第七十三条","txt":"国务院及其有关部门应当在职权范围内，为实施本法分别制定行政法规、规章、具体措施和办法。"},{"i":74,"n":"第七十四条","txt":"本法由全国人民代表大会通过，自1984年10月1日起施行。"}],"minzutuanjiejinbucujinfa":[{"i":1,"n":"第一条","txt":"为了促进民族团结进步，铸牢中华民族共同体意识，推进中华民族共同体建设，推动实现中华民族伟大复兴，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"民族团结进步事业坚持中国共产党的全面领导，高举中国特色社会主义伟大旗帜，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，巩固各民族团结奋斗的共同思想政治基础，坚定不移走中国特色解决民族问题的正确道路，为强国建设、民族复兴凝聚力量。"},{"i":3,"n":"第三条","txt":"铸牢中华民族共同体意识，应当引导各族人民牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念，增强中华民族凝聚力。"},{"i":4,"n":"第四条","txt":"推进中华民族共同体建设，应当统筹经济、政治、文化、社会和生态文明建设，全面实现各民族共同繁荣发展，确保各族人民共同当家做主人，构筑中华民族共有精神家园，促进各民族全方位互嵌和广泛交往交流交融，共同守护人与自然和谐共生的生态家园，推动中华民族成为认同度更高、凝聚力更强的命运共同体。"},{"i":5,"n":"第五条","txt":"中华人民共和国公民在法律面前一律平等。"},{"i":6,"n":"第六条","txt":"中华民族共同体意识是民族团结之本。国家坚持增进共同性、尊重和包容差异性，促进各民族守望相助、和谐共处，维护中华民族大团结。禁止破坏民族团结和制造民族分裂的行为。"},{"i":7,"n":"第七条","txt":"国家推动各民族共同团结奋斗、共同繁荣发展，促进物质文明、政治文明、精神文明、社会文明、生态文明协调发展，全面推进中华民族发展进步。"},{"i":8,"n":"第八条","txt":"国家坚持和完善民族区域自治制度，维护国家统一和民族团结。"},{"i":9,"n":"第九条","txt":"国家坚持依法治理民族事务，依法保障各族群众合法权益，加强宪法法律宣传教育，增强各族群众的国家意识、公民意识、法治意识，维护社会主义法治的统一、尊严和权威，在法治轨道上推进民族事务治理体系和治理能力现代化。"},{"i":10,"n":"第十条","txt":"中华人民共和国公民有维护国家统一和全国各民族团结的义务，应当维护国家主权、安全、发展利益。"},{"i":11,"n":"第十一条","txt":"国家坚持以社会主义核心价值观为引领，深化爱国主义、集体主义、社会主义教育，引导各族群众弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神，坚定对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同。"},{"i":12,"n":"第十二条","txt":"国家组织开展中国共产党史、新中国史、改革开放史、社会主义发展史、中华民族发展史宣传教育，引导各族群众牢固树立正确的国家观、历史观、民族观、文化观、宗教观。"},{"i":13,"n":"第十三条","txt":"国家发展社会主义先进文化，弘扬革命文化，传承中华优秀传统文化，引导各族群众增进中华文化认同，增强中华文化自信。"},{"i":14,"n":"第十四条","txt":"国家树立和突出各民族共有共享的中华文化符号和中华民族形象，依托中华民族的文化和自然遗产等资源，推动中华文明标识体系的构建。"},{"i":15,"n":"第十五条","txt":"国家全面推广普及国家通用语言文字。任何组织和个人不得妨碍公民学习和使用国家通用语言文字。"},{"i":16,"n":"第十六条","txt":"各级各类学校及其他教育机构应当将铸牢中华民族共同体意识的要求贯穿教育全过程，融入课堂教学、社会实践、主题教育和网络教育相结合的教育体系。"},{"i":17,"n":"第十七条","txt":"国家推动中国自主的中华民族共同体史料体系、话语体系、理论体系建设，支持高等学校、科研机构等单位加强对中华民族共同体重大基础性问题的研究，阐释中华民族和中华文明多元一体格局的历史与内涵，揭示中华民族形成和发展的道理、学理、哲理。"},{"i":18,"n":"第十八条","txt":"国家将铸牢中华民族共同体意识教育纳入国民教育、干部教育、社会教育体系。"},{"i":19,"n":"第十九条","txt":"报刊、广播、电视等新闻媒体和出版单位、网络服务提供者应当开展有关铸牢中华民族共同体意识、推进中华民族共同体建设的宣传报道、成就展示等工作。"},{"i":20,"n":"第二十条","txt":"各级人民政府应当推动将铸牢中华民族共同体意识的要求融入家庭、家教和家风建设。"},{"i":21,"n":"第二十一条","txt":"国家支持香港特别行政区、澳门特别行政区开展中华民族历史、中华文化和国情教育，引导香港特别行政区同胞、澳门特别行政区同胞自觉维护国家主权、安全、发展利益。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府应当统筹经济社会发展规划和公共资源配置，推进互嵌式社区环境建设，完善各族群众共居共学、共建共享、共事共乐的社会条件。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府应当将铸牢中华民族共同体意识的要求纳入城市规划、建设、治理和服务全过程，因地制宜完善友好型、包容性、融合式的城市民族工作政策措施。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府应当加强民族地区之间、民族地区与其他地区之间人口流动服务平台的共建和信息的共享，增强协作能力，提高跨区域政务服务的便利化水平。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府应当依法保障民族地区之间、民族地区与其他地区之间跨区域就业创业公民的合法权益，支持开展法律法规和政策、国家通用语言文字、职业技能等方面的培训，开展职业指导、职业介绍等服务。"},{"i":26,"n":"第二十六条","txt":"国务院教育行政部门和省级人民政府应当支持民族地区和其他地区高等学校双向跨区域招生，加强人才培养的协作。"},{"i":27,"n":"第二十七条","txt":"各级人民政府应当支持学校、群团组织和其他社会组织，利用中华民族共同体形成和发展的历史文化资源，开展青少年跨区域社会实践、研学游学和参观考察等交流活动，增强民族自豪感和自信心。"},{"i":28,"n":"第二十八条","txt":"各级人民政府应当鼓励和支持志愿者和志愿服务组织，在各类志愿服务活动中促进各族群众的交流合作和友爱互助。"},{"i":29,"n":"第二十九条","txt":"国家增进各民族文化互鉴融通，鼓励各民族互相欣赏优秀传统文化、互相学习语言文字。各级人民政府应当支持文化工作者和有关单位，创作和展示具有中华文化底蕴、体现各民族交往交流交融的文艺作品。"},{"i":30,"n":"第三十条","txt":"国家发挥旅游业在促进各民族交往交流交融方面的积极作用，推进文化和旅游深度融合发展，开发有利于弘扬中华文化的旅游线路和文化创意产品。"},{"i":31,"n":"第三十一条","txt":"国家支持利用互联网、大数据、人工智能等现代技术手段开展交流活动，鼓励和引导网络产品、服务的提供者制作、传播体现中华民族大团结的作品和信息，营造有利于铸牢中华民族共同体意识的和谐网络环境。任何组织和个人不得以文字、图片和音视频等方式，制作和传播含有民族仇恨、民族歧视等破坏民族团结进步内容的信息。"},{"i":32,"n":"第三十二条","txt":"国家贯彻新发展理念，支持民族地区全面深化改革开放、全面融入国家发展战略、提升自我发展能力，加快民族地区高质量发展，推进各民族共同富裕，推动各民族共同迈向社会主义现代化。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府及其有关部门制定和实施经济社会发展领域的规划计划、政策措施，应当有利于铸牢中华民族共同体意识、推进中华民族共同体建设，有利于维护国家统一、反对分裂，有利于改善民生、凝聚人心。"},{"i":34,"n":"第三十四条","txt":"国家促进区域协调发展，完善区域一体化发展机制和差别化区域支持政策，健全对口支援、东西部协作等帮扶协作机制。"},{"i":35,"n":"第三十五条","txt":"国务院有关部门和县级以上地方人民政府应当加强交通、能源、水利、信息、物流等基础设施建设，推进民族地区与其他地区之间的互联互通。"},{"i":36,"n":"第三十六条","txt":"国家建设现代化产业体系，因地制宜发展新质生产力，有序推进区域间的产业合作和利益共享机制建设，支持民族地区在优化区域产业链和供应链布局、推进全国统一大市场建设中充分发挥作用。"},{"i":37,"n":"第三十七条","txt":"国务院有关部门和县级以上地方人民政府应当推动就业、教育、医疗等方面公共服务资源的合理配置，增强基本公共服务均衡性和可及性，促进民族地区各级各类教育协调发展，提高民族地区公共服务保障能力。"},{"i":38,"n":"第三十八条","txt":"国务院有关部门和县级以上地方人民政府应当统筹优化农业、生态、城镇等各类空间布局，加强民族地区的生态环境保护和自然资源的可持续利用，引导各族群众共同维护中华民族永续发展的生态空间。"},{"i":39,"n":"第三十九条","txt":"国务院有关部门和边境地区县级以上地方人民政府应当统筹推进兴边富民、稳边固边，鼓励支援边境地区建设，推进基础设施和公共服务设施建设，改善边境村落人居环境和生产生活条件。"},{"i":40,"n":"第四十条","txt":"国家加强时代新风新貌的培育，推进公民道德建设，开展群众性法治宣传教育和科学技术普及，推动移风易俗，倡导文明进步的新风尚，引导各族群众在生活交往、婚丧嫁娶等活动中自觉遵守法律法规、遵循公序良俗。"},{"i":41,"n":"第四十一条","txt":"坚持和完善党委统一领导、政府依法管理、统一战线工作部门牵头协调、民族工作部门履职尽责、各部门通力合作、全社会共同参与的民族工作格局，健全民族工作协调机制。"},{"i":42,"n":"第四十二条","txt":"中央和国家机关各部门、地方各机关各部门在各自职责范围内开展铸牢中华民族共同体意识、促进民族团结进步工作。各机关对在本单位内发生的破坏民族团结进步的行为应当及时予以制止。"},{"i":43,"n":"第四十三条","txt":"各级人民代表大会和县级以上人民代表大会常务委员会依照法定职权，在各项工作中落实铸牢中华民族共同体意识、推进中华民族共同体建设的要求。"},{"i":44,"n":"第四十四条","txt":"工会、共产主义青年团、妇女联合会、工商业联合会、文学艺术界联合会、作家协会、科学技术协会、归国华侨联合会、台湾同胞联谊会、残疾人联合会和其他群团组织，应当发挥各自优势，面向所联系的领域开展铸牢中华民族共同体意识工作，团结所联系的群体为中华民族共同体建设贡献力量。"},{"i":45,"n":"第四十五条","txt":"企业事业组织应当遵守社会公德，履行社会责任，将铸牢中华民族共同体意识的要求融入业务培训、文化建设等活动中，促进民族团结进步。"},{"i":46,"n":"第四十六条","txt":"宗教团体、宗教院校和宗教活动场所，应当开展铸牢中华民族共同体意识宣传教育，坚持我国宗教中国化方向，引导宗教与社会主义社会相适应，引导宗教教职人员、信教群众弘扬爱国主义传统，促进民族和睦、宗教和顺、社会和谐。"},{"i":47,"n":"第四十七条","txt":"基层人民政府应当对居民委员会、村民委员会开展铸牢中华民族共同体意识工作给予指导、支持和帮助。"},{"i":48,"n":"第四十八条","txt":"军队依照本法和有关法律规定，结合国防活动开展铸牢中华民族共同体意识宣传教育，充分利用自身资源保障中华民族共同体建设，巩固和发展军政军民团结，维护国家统一和安全。"},{"i":49,"n":"第四十九条","txt":"国家将铸牢中华民族共同体意识的要求贯穿干部的培养、选拔、使用和管理全过程，加强民族地区干部队伍建设，重视培养和使用少数民族干部。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府应当将铸牢中华民族共同体意识、促进民族团结进步工作纳入国民经济和社会发展规划及年度计划，将相关工作经费列入预算。"},{"i":51,"n":"第五十一条","txt":"国家将民族事务纳入共建共治共享的社会治理机制，加强组织协调和基层治理力量，强化科技支撑，提升社会治理效能。"},{"i":52,"n":"第五十二条","txt":"国务院有关部门和地方各级人民政府应当贯彻总体国家安全观，健全民族领域重大事项请示报告制度，加强对民族领域重大风险隐患的排查、识别、评估、预警和处置，提升防范化解风险的能力，维护国家安全和社会稳定。"},{"i":53,"n":"第五十三条","txt":"地方各级人民政府和有关机关应当加强矛盾纠纷预防和化解能力建设，发挥多元化纠纷解决机制的作用，准确认定纠纷的性质，依法处理和化解纠纷，维护民族团结。任何组织和个人不得以民族身份、风俗习惯、宗教信仰等为由，故意引发或者激化矛盾，扰乱公共秩序。"},{"i":54,"n":"第五十四条","txt":"公民对破坏民族团结进步的行为有权进行投诉和举报，对国家机关及其工作人员不履行或者不正确履行铸牢中华民族共同体意识、促进民族团结进步法定职责的行为有权进行检举。"},{"i":55,"n":"第五十五条","txt":"开展民族团结进步示范创建工作，应当突出铸牢中华民族共同体意识的要求。"},{"i":56,"n":"第五十六条","txt":"每年9月的第四周为民族团结进步宣传周，国家通过多种形式集中开展铸牢中华民族共同体意识宣传教育活动。"},{"i":57,"n":"第五十七条","txt":"国家机关及其工作人员不履行或者不正确履行本法规定职责的，或者对本法第五十八条、第五十九条、第六十条、第六十一条规定的违法行为未及时予以制止并依法予以处理的，由其主管部门或者有关机关责令改正；造成不良后果或者影响的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"任何组织和个人违反本法有关规定，破坏民族团结进步的，由县级以上人民政府有关部门按照职责及时予以制止、责令改正，并依法给予处罚。构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"任何组织和个人以民族身份为由实施就业歧视、拒绝提供商品或者服务，或者实施法律法规禁止的其他歧视行为的，由县级以上民族工作、人力资源和社会保障、市场监管等有关部门按照职责责令改正；造成不良后果或者影响的，予以警告或者通报批评。法律法规另有处罚规定的，从其规定。"},{"i":60,"n":"第六十条","txt":"社会团体、企业事业组织和其他社会组织对在本单位内发生的破坏民族团结进步的行为，应当及时予以制止；未及时制止，造成不良后果或者影响的，由上级机关或者有关主管部门予以警告或者通报批评，并对直接负责的主管人员和其他直接责任人员依法追究法律责任。"},{"i":61,"n":"第六十一条","txt":"网络运营者违反本法规定，未履行管理责任的，由网信、电信、公安、国家安全、新闻出版、广播电视等有关主管部门按照职责责令改正；拒不改正或者情节严重的，依法给予处罚。"},{"i":62,"n":"第六十二条","txt":"组织、策划、实施暴力恐怖活动、民族分裂活动或者宗教极端活动，构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"中华人民共和国境外的组织和个人，针对中华人民共和国实施破坏民族团结进步、制造民族分裂行为的，依法追究法律责任。"},{"i":64,"n":"第六十四条","txt":"省、自治区、直辖市和设区的市、自治州人民代表大会及其常务委员会，可以结合当地实际情况，制定促进民族团结进步的地方性法规。"},{"i":65,"n":"第六十五条","txt":"本法自2026年7月1日起施行。"}],"faguanfa":[{"i":1,"n":"第一条","txt":"为了全面推进高素质法官队伍建设，加强对法官的管理和监督，维护法官合法权益，保障人民法院依法独立行使审判权，保障法官依法履行职责，保障司法公正，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"法官是依法行使国家审判权的审判人员，包括最高人民法院、地方各级人民法院和军事法院等专门人民法院的院长、副院长、审判委员会委员、庭长、副庭长和审判员。"},{"i":3,"n":"第三条","txt":"法官必须忠实执行宪法和法律，维护社会公平正义，全心全意为人民服务。"},{"i":4,"n":"第四条","txt":"法官应当公正对待当事人和其他诉讼参与人，对一切个人和组织在适用法律上一律平等。"},{"i":5,"n":"第五条","txt":"法官应当勤勉尽责，清正廉明，恪守职业道德。"},{"i":6,"n":"第六条","txt":"法官审判案件，应当以事实为根据，以法律为准绳，秉持客观公正的立场。"},{"i":7,"n":"第七条","txt":"法官依法履行职责，受法律保护，不受行政机关、社会团体和个人的干涉。"},{"i":8,"n":"第八条","txt":"法官的职责："},{"i":9,"n":"第九条","txt":"人民法院院长、副院长、审判委员会委员、庭长、副庭长除履行审判职责外，还应当履行与其职务相适应的职责。"},{"i":10,"n":"第十条","txt":"法官应当履行下列义务："},{"i":11,"n":"第十一条","txt":"法官享有下列权利："},{"i":12,"n":"第十二条","txt":"担任法官必须具备下列条件："},{"i":13,"n":"第十三条","txt":"下列人员不得担任法官："},{"i":14,"n":"第十四条","txt":"初任法官采用考试、考核的办法，按照德才兼备的标准，从具备法官条件的人员中择优提出人选。"},{"i":15,"n":"第十五条","txt":"人民法院可以根据审判工作需要，从律师或者法学教学、研究人员等从事法律职业的人员中公开选拔法官。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市设立法官遴选委员会，负责初任法官人选专业能力的审核。"},{"i":17,"n":"第十七条","txt":"初任法官一般到基层人民法院任职。上级人民法院法官一般逐级遴选；最高人民法院和高级人民法院法官可以从下两级人民法院遴选。参加上级人民法院遴选的法官应当在下级人民法院担任法官一定年限，并具有遴选职位相关工作经历。"},{"i":18,"n":"第十八条","txt":"法官的任免，依照宪法和法律规定的任免权限和程序办理。"},{"i":19,"n":"第十九条","txt":"法官在依照法定程序产生后，在就职时应当公开进行宪法宣誓。"},{"i":20,"n":"第二十条","txt":"法官有下列情形之一的，应当依法提请免除其法官职务："},{"i":21,"n":"第二十一条","txt":"发现违反本法规定的条件任命法官的，任命机关应当撤销该项任命；上级人民法院发现下级人民法院法官的任命违反本法规定的条件的，应当建议下级人民法院依法提请任命机关撤销该项任命。"},{"i":22,"n":"第二十二条","txt":"法官不得兼任人民代表大会常务委员会的组成人员，不得兼任行政机关、监察机关、检察机关的职务，不得兼任企业或者其他营利性组织、事业单位的职务，不得兼任律师、仲裁员和公证员。"},{"i":23,"n":"第二十三条","txt":"法官之间有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的，不得同时担任下列职务："},{"i":24,"n":"第二十四条","txt":"法官的配偶、父母、子女有下列情形之一的，法官应当实行任职回避："},{"i":25,"n":"第二十五条","txt":"法官实行员额制管理。法官员额根据案件数量、经济社会发展情况、人口数量和人民法院审级等因素确定，在省、自治区、直辖市内实行总量控制、动态管理，优先考虑基层人民法院和案件数量多的人民法院办案需要。"},{"i":26,"n":"第二十六条","txt":"法官实行单独职务序列管理。"},{"i":27,"n":"第二十七条","txt":"最高人民法院院长为首席大法官。"},{"i":28,"n":"第二十八条","txt":"法官等级的确定，以法官德才表现、业务水平、审判工作实绩和工作年限等为依据。"},{"i":29,"n":"第二十九条","txt":"法官的等级设置、确定和晋升的具体办法，由国家另行规定。"},{"i":30,"n":"第三十条","txt":"初任法官实行统一职前培训制度。"},{"i":31,"n":"第三十一条","txt":"对法官应当有计划地进行政治、理论和业务培训。"},{"i":32,"n":"第三十二条","txt":"法官培训情况，作为法官任职、等级晋升的依据之一。"},{"i":33,"n":"第三十三条","txt":"法官培训机构按照有关规定承担培训法官的任务。"},{"i":34,"n":"第三十四条","txt":"法官申请辞职，应当由本人书面提出，经批准后，依照法律规定的程序免除其职务。"},{"i":35,"n":"第三十五条","txt":"辞退法官应当依照法律规定的程序免除其职务。"},{"i":36,"n":"第三十六条","txt":"法官从人民法院离任后两年内，不得以律师身份担任诉讼代理人或者辩护人。"},{"i":37,"n":"第三十七条","txt":"法官因工作需要，经单位选派或者批准，可以在高等学校、科研院所协助开展实践性教学、研究工作，并遵守国家有关规定。"},{"i":38,"n":"第三十八条","txt":"人民法院设立法官考评委员会，负责对本院法官的考核工作。"},{"i":39,"n":"第三十九条","txt":"法官考评委员会的组成人员为五至九人。"},{"i":40,"n":"第四十条","txt":"对法官的考核，应当全面、客观、公正，实行平时考核和年度考核相结合。"},{"i":41,"n":"第四十一条","txt":"对法官的考核内容包括：审判工作实绩、职业道德、专业水平、工作能力、审判作风。重点考核审判工作实绩。"},{"i":42,"n":"第四十二条","txt":"年度考核结果分为优秀、称职、基本称职和不称职四个等次。"},{"i":43,"n":"第四十三条","txt":"考核结果以书面形式通知法官本人。法官对考核结果如果有异议，可以申请复核。"},{"i":44,"n":"第四十四条","txt":"法官在审判工作中有显著成绩和贡献的，或者有其他突出事迹的，应当给予奖励。"},{"i":45,"n":"第四十五条","txt":"法官有下列表现之一的，应当给予奖励："},{"i":46,"n":"第四十六条","txt":"法官有下列行为之一的，应当给予处分；构成犯罪的，依法追究刑事责任："},{"i":47,"n":"第四十七条","txt":"法官涉嫌违纪违法，已经被立案调查、侦查，不宜继续履行职责的，按照管理权限和规定的程序暂时停止其履行职务。"},{"i":48,"n":"第四十八条","txt":"最高人民法院和省、自治区、直辖市设立法官惩戒委员会，负责从专业角度审查认定法官是否存在本法第四十六条第四项、第五项规定的违反审判职责的行为，提出构成故意违反职责、存在重大过失、存在一般过失或者没有违反职责等审查意见。法官惩戒委员会提出审查意见后，人民法院依照有关规定作出是否予以惩戒的决定，并给予相应处理。"},{"i":49,"n":"第四十九条","txt":"法官惩戒委员会审议惩戒事项时，当事法官有权申请有关人员回避，有权进行陈述、举证、辩解。"},{"i":50,"n":"第五十条","txt":"法官惩戒委员会作出的审查意见应当送达当事法官。当事法官对审查意见有异议的，可以向惩戒委员会提出，惩戒委员会应当对异议及其理由进行审查，作出决定。"},{"i":51,"n":"第五十一条","txt":"法官惩戒委员会审议惩戒事项的具体程序，由最高人民法院商有关部门确定。"},{"i":52,"n":"第五十二条","txt":"人民法院设立法官权益保障委员会，维护法官合法权益，保障法官依法履行职责。"},{"i":53,"n":"第五十三条","txt":"除下列情形外，不得将法官调离审判岗位："},{"i":54,"n":"第五十四条","txt":"任何单位或者个人不得要求法官从事超出法定职责范围的事务。"},{"i":55,"n":"第五十五条","txt":"法官的职业尊严和人身安全受法律保护。"},{"i":56,"n":"第五十六条","txt":"法官因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，人民法院应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任。"},{"i":57,"n":"第五十七条","txt":"法官因依法履行职责，本人及其近亲属人身安全面临危险的，人民法院、公安机关应当对法官及其近亲属采取人身保护、禁止特定人员接触等必要保护措施。"},{"i":58,"n":"第五十八条","txt":"法官实行与其职责相适应的工资制度，按照法官等级享有国家规定的工资待遇，并建立与公务员工资同步调整机制。"},{"i":59,"n":"第五十九条","txt":"法官实行定期增资制度。"},{"i":60,"n":"第六十条","txt":"法官享受国家规定的津贴、补贴、奖金、保险和福利待遇。"},{"i":61,"n":"第六十一条","txt":"法官因公致残的，享受国家规定的伤残待遇。法官因公牺牲、因公死亡或者病故的，其亲属享受国家规定的抚恤和优待。"},{"i":62,"n":"第六十二条","txt":"法官的退休制度，根据审判工作特点，由国家另行规定。"},{"i":63,"n":"第六十三条","txt":"法官退休后，享受国家规定的养老金和其他待遇。"},{"i":64,"n":"第六十四条","txt":"对于国家机关及其工作人员侵犯本法第十一条规定的法官权利的行为，法官有权提出控告。"},{"i":65,"n":"第六十五条","txt":"对法官处分或者人事处理错误的，应当及时予以纠正；造成名誉损害的，应当恢复名誉、消除影响、赔礼道歉；造成经济损失的，应当赔偿。对打击报复的直接责任人员，应当依法追究其责任。"},{"i":66,"n":"第六十六条","txt":"国家对初任法官实行统一法律职业资格考试制度，由国务院司法行政部门商最高人民法院等有关部门组织实施。"},{"i":67,"n":"第六十七条","txt":"人民法院的法官助理在法官指导下负责审查案件材料、草拟法律文书等审判辅助事务。"},{"i":68,"n":"第六十八条","txt":"有关法官的权利、义务和管理制度，本法已有规定的，适用本法的规定；本法未作规定的，适用公务员管理的相关法律法规。"},{"i":69,"n":"第六十九条","txt":"本法自2019年10月1日起施行。"}],"fazhixuanchuanjiaoyufa":[{"i":1,"n":"第一条","txt":"为了加强法治宣传教育，提升全民法治素养和社会治理法治化水平，形成全社会尊法学法守法用法的良好氛围，夯实全面依法治国的社会基础，推动建设更高水平的社会主义法治国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"法治宣传教育坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，贯彻习近平法治思想，弘扬社会主义法治精神，推动法治成为社会共识和基本准则，为全面建设社会主义现代化国家营造良好法治环境。"},{"i":3,"n":"第三条","txt":"法治宣传教育坚持以人民为中心、服务大局、守正创新，坚持与依法治理、法治实践相融合，坚持依法治国和以德治国相结合，坚持依法治国和依规治党有机统一，践行社会主义核心价值观，健全党委领导、人大监督、政府主导、各方协同、社会参与的工作机制。"},{"i":4,"n":"第四条","txt":"国家实行公民终身法治教育制度，将法治教育纳入国民教育、干部教育、社会教育体系。"},{"i":5,"n":"第五条","txt":"法治宣传教育的主要内容包括："},{"i":6,"n":"第六条","txt":"国家编制全国法治宣传教育规划。"},{"i":7,"n":"第七条","txt":"国务院司法行政部门主管全国法治宣传教育工作。县级以上地方人民政府司法行政部门主管本行政区域的法治宣传教育工作。"},{"i":8,"n":"第八条","txt":"国家机关和武装力量、各政党和各群团组织、事业单位，应当结合各自的职责组织开展法治宣传教育。"},{"i":9,"n":"第九条","txt":"国家机关按照“谁执法谁普法”的精神，实行普法责任制。"},{"i":10,"n":"第十条","txt":"国家加强涉外法治宣传教育，提升法治文化国际传播能力，积极阐释中国特色涉外法治理念、主张和成功实践。"},{"i":11,"n":"第十一条","txt":"开展法治宣传教育，应当遵守宪法和法律，遵守公共秩序，尊重社会公德。"},{"i":12,"n":"第十二条","txt":"对在法治宣传教育工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"国家加强宪法宣传教育，推动宪法宣传教育常态化、长效化，增强全社会的宪法意识，弘扬宪法精神，加强宪法实施。"},{"i":14,"n":"第十四条","txt":"国家加强宪法和特别行政区基本法宣传教育，增强香港特别行政区同胞、澳门特别行政区同胞维护宪法和基本法确定的特别行政区宪制秩序的意识。"},{"i":15,"n":"第十五条","txt":"国家通过多种形式开展国家安全法治宣传教育，增强全民国家安全意识。"},{"i":16,"n":"第十六条","txt":"国家利用重大节日、纪念日等，结合法律法规的公布施行，组织开展群众性法治宣传教育活动，持续深入开展全民普法，推动法治宣传教育融入法治实践、基层治理和日常生活，在全社会树立宪法法律至上、法律面前人人平等等基本法治观念。"},{"i":17,"n":"第十七条","txt":"法律法规制定机关应当加强立法全过程宣传解读，积极采取多种形式发布信息、介绍情况、回应关切；通过公开征求意见，召开座谈会、论证会、听证会，设立基层立法联系点等形式，扩大社会参与，将立法与法治宣传教育有机结合。"},{"i":18,"n":"第十八条","txt":"行政机关应当将法治宣传教育融入日常管理、服务、执法和争议解决过程，综合运用释法说理、疏导回应、指导示范、组织听证、发布解读典型案例等方式，开展法治宣传教育。"},{"i":19,"n":"第十九条","txt":"监察机关、审判机关、检察机关等应当将法治宣传教育融入案件办理过程，结合各自的职责，运用依法公开审理案件、法律文书释法说理、发布解读典型案例等方式，开展法治宣传教育。"},{"i":20,"n":"第二十条","txt":"民族事务部门应当以铸牢中华民族共同体意识为主线，开展法治宣传教育，促进民族团结进步，增强中华民族凝聚力，推进中华民族共同体建设。"},{"i":21,"n":"第二十一条","txt":"宗教事务部门应当加强法治宣传教育，引导宗教界人士和信教群众自觉维护宪法法律权威，在法律法规规定范围内开展活动。"},{"i":22,"n":"第二十二条","txt":"网信、电信、公安等部门应当加强对网络服务提供者和网络用户的法治宣传教育，引导其自觉遵守法律法规、尊重社会公德，营造文明安全的网络环境。"},{"i":23,"n":"第二十三条","txt":"应急管理、卫生健康、公安等部门应当组织开展自然灾害、事故灾难、公共卫生事件和社会安全事件应对的法治宣传教育，推动全社会提高突发事件预防和应对能力。"},{"i":24,"n":"第二十四条","txt":"民政、人力资源社会保障等部门应当根据老年人、残疾人、进城务工人员等群体的需求和特点，开展有针对性的法治宣传教育，提高其依法维护自身合法权益的意识和能力。"},{"i":25,"n":"第二十五条","txt":"各级人民政府应当加强基层法治宣传教育，支持、指导和帮助村民委员会、居民委员会开展法治宣传教育，引导村民、居民依法维护自身合法权益、表达诉求、解决纠纷。"},{"i":26,"n":"第二十六条","txt":"各级人民政府应当根据新经济新领域发展需要，加强对相关组织和人员的法治宣传教育，引导其依法维护自身合法权益、履行法定义务。"},{"i":27,"n":"第二十七条","txt":"工会、共产主义青年团、妇女联合会、工商业联合会、法学会、残疾人联合会等群团组织，应当在各自的职责范围内开展法治宣传教育。"},{"i":28,"n":"第二十八条","txt":"行业协会、商会等加强对会员的法治宣传教育，提高会员维护自身合法权益、防范法律风险的能力，提升行业治理法治化水平。"},{"i":29,"n":"第二十九条","txt":"企业加强对职工的法治教育培训，建立并实施管理人员学法用法制度，提升管理法治化水平。"},{"i":30,"n":"第三十条","txt":"法律服务机构和法律服务工作者在提供法律服务、调解处理矛盾纠纷时，结合工作开展法治宣传教育。"},{"i":31,"n":"第三十一条","txt":"公共场所的经营者、管理者应当依法在其经营管理的场所内，围绕消费者权益保护、反电信网络诈骗、食品药品安全、消防安全、个人信息保护、产品责任等群众关心的问题，开展法治宣传教育。"},{"i":32,"n":"第三十二条","txt":"国家加强对开展境外投资合作、对外援助的企业以及出境人员等的法治宣传教育，提供涉外法律服务，引导其遵守我国和当地法律，防范和应对法律风险。"},{"i":33,"n":"第三十三条","txt":"国家加强国家工作人员宪法宣传教育。国家工作人员应当加强宪法学习，树立宪法意识，恪守宪法原则，弘扬宪法精神，履行宪法使命。"},{"i":34,"n":"第三十四条","txt":"国家工作人员应当带头尊法学法守法用法，树立依法履职的法治观念，提高运用法治思维和法治方式深化改革、推动发展、化解矛盾、维护稳定、应对风险的能力。"},{"i":35,"n":"第三十五条","txt":"录用国家工作人员，应当将有关法律知识纳入录用考试内容。"},{"i":36,"n":"第三十六条","txt":"健全国家工作人员日常学法制度。国家工作人员所在单位应当根据工作性质和特点，采取多种形式开展法治教育。"},{"i":37,"n":"第三十七条","txt":"实行领导干部应知应会党内法规和法律法规清单制度。"},{"i":38,"n":"第三十八条","txt":"加强对领导干部学法用法情况的监督。领导干部学法用法情况应当按照规定列入年度述职内容。"},{"i":39,"n":"第三十九条","txt":"国家、社会、学校、家庭加强协同配合，根据青少年的身心特点和成长需求，对青少年开展法治宣传教育，普及青少年在家庭生活、校园学习、社会活动中所必需的法律知识，教育引导青少年树立守法意识、规则意识、诚信意识和防范违法犯罪的意识，自觉遵守法律规定，规范自身行为，维护自身合法权益，尊重他人合法权益。"},{"i":40,"n":"第四十条","txt":"教育行政部门应当将法治教育融入学校教育的各个阶段，明确各级各类学校法治教育目标、内容以及评价要求，推广法治实践教学和案例教学，将法治教育内容融入相关教材，将法治素养纳入学生综合素质评价范围。"},{"i":41,"n":"第四十一条","txt":"各级各类学校应当开设法治教育课程，利用青少年法治教育实践基地等场所开展法治实践教育。中小学校应当按照要求聘任法治副校长，配备受过专业培养或者经过专门培训、能够胜任法治教育任务的教师，可以聘任校外法治辅导员。"},{"i":42,"n":"第四十二条","txt":"审判机关、检察机关以及公安、司法行政等部门，律师协会等社会组织，应当支持学校按照教育教学计划开展法治教育，提供法治实践教育资源，支持教育行政部门、学校开发法治教育课程。"},{"i":43,"n":"第四十三条","txt":"未成年人的父母或者其他监护人应当提高对未成年人进行法治教育的意识和能力，针对不同年龄段未成年人的身心发展特点，教育未成年人增强自我保护意识，养成守法行为习惯。"},{"i":44,"n":"第四十四条","txt":"网络服务提供者应当依法开展未成年人网络法治宣传教育，履行未成年人网络保护义务，引导未成年人养成文明网络行为习惯，营造有利于未成年人身心健康的网络环境。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府应当将法治宣传教育工作纳入本地区法治建设总体部署，纳入精神文明建设和平安建设。"},{"i":46,"n":"第四十六条","txt":"司法行政部门应当会同有关部门、单位加强法治宣传教育人才队伍建设，分层分类开展培训。"},{"i":47,"n":"第四十七条","txt":"司法行政部门应当推进法治宣传教育专家库建设，选聘优秀法治人才组成普法讲师团，组织开展法治宣讲活动。其他部门可以根据需要，建设具有部门工作特点的法治宣传教育专家库或者讲师团。"},{"i":48,"n":"第四十八条","txt":"国家鼓励和支持法治宣传教育理论研究，加强法治传播、法治文化等相关人才培养。"},{"i":49,"n":"第四十九条","txt":"国家健全媒体公益普法制度，引导报刊、广播、电视等新闻媒体和网络服务提供者履行公益普法责任，开展公益法治宣传教育。"},{"i":50,"n":"第五十条","txt":"文化和旅游、新闻出版、广播电视、电影、网信等部门应当加强法治文化建设，鼓励和支持优秀法治文艺作品、出版物、广播电视、电影和网络视听作品的创作生产和宣传推广。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府应当加强对法治文化相关文物等文化遗产的保护和利用，宣传代表性人物的事迹和精神，弘扬社会主义法治文化，推动中华优秀传统法律文化的创造性转化、创新性发展。"},{"i":52,"n":"第五十二条","txt":"县级以上人民政府应当依据国土空间规划，因地制宜统筹规划、建设法治文化场所，在公共设施建设和公共空间利用时体现法治元素。"},{"i":53,"n":"第五十三条","txt":"负有法治宣传教育职责的部门、单位应当根据不同地区、行业、群体的法治需求精准开展法治宣传教育，采取生动活泼、通俗易懂、群众喜闻乐见的形式和方法，发挥法治人物、见义勇为人员等典型示范作用，讲好中国宪法故事、中国法治故事，增强法治宣传教育的针对性和实效性，力戒形式主义。"},{"i":54,"n":"第五十四条","txt":"鼓励创新法治宣传教育形式和方法，支持运用新平台新技术新产品和无障碍方式开展法治宣传教育。"},{"i":55,"n":"第五十五条","txt":"县级以上人民政府应当将法治宣传教育经费列入本级预算，加强资金管理，提高资金使用效益，保障法治宣传教育工作需要。"},{"i":56,"n":"第五十六条","txt":"司法行政部门组织对法治宣传教育规划实施情况进行评估，并将评估结果向社会公布，接受社会监督。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府司法行政部门发现同级负有法治宣传教育职责的部门、单位，未依法履行法治宣传教育职责的，应当及时发出普法提示。有关部门、单位收到普法提示后，应当及时采取改进措施并反馈相关情况。"},{"i":58,"n":"第五十八条","txt":"各级人民代表大会常务委员会应当通过听取和审议专项工作报告、执法检查、专题询问、专题调研等方式，加强对法治宣传教育工作的监督。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府司法行政部门未依法履行法治宣传教育工作职责的，由本级人民政府或者上级司法行政部门责令限期改正；逾期未改正的，予以通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":60,"n":"第六十条","txt":"违反法治宣传教育经费管理规定的，由有关主管部门责令限期改正；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":61,"n":"第六十一条","txt":"侵占、破坏法治宣传教育设施，损毁展品、器材的，由有关主管部门责令限期改正，并给予批评教育。"},{"i":62,"n":"第六十二条","txt":"违反本法规定开展法治宣传教育，造成不良社会影响的，由有关主管部门予以制止，并给予批评教育。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，造成他人损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"中国人民解放军、中国人民武装警察部队依照本法和中央军事委员会的有关规定开展法治宣传教育工作。"},{"i":65,"n":"第六十五条","txt":"本法自2025年11月1日起施行。"}],"aomentebiexingzhengqujibenfa":[{"i":1,"n":"第一条","txt":"澳门特别行政区是中华人民共和国不可分离的部分。"},{"i":2,"n":"第二条","txt":"中华人民共和国全国人民代表大会授权澳门特别行政区依照本法的规定实行高度自治，享有行政管理权、立法权、独立的司法权和终审权。"},{"i":3,"n":"第三条","txt":"澳门特别行政区的行政机关和立法机关由澳门特别行政区永久性居民依照本法有关规定组成。"},{"i":4,"n":"第四条","txt":"澳门特别行政区依法保障澳门特别行政区居民和其他人的权利和自由。"},{"i":5,"n":"第五条","txt":"澳门特别行政区不实行社会主义的制度和政策，保持原有的资本主义制度和生活方式，五十年不变。"},{"i":6,"n":"第六条","txt":"澳门特别行政区以法律保护私有财产权。"},{"i":7,"n":"第七条","txt":"澳门特别行政区境内的土地和自然资源，除在澳门特别行政区成立前已依法确认的私有土地外，属于国家所有，由澳门特别行政区政府负责管理、使用、开发、出租或批给个人、法人使用或开发，其收入全部归澳门特别行政区政府支配。"},{"i":8,"n":"第八条","txt":"澳门原有的法律、法令、行政法规和其他规范性文件，除同本法相抵触或经澳门特别行政区的立法机关或其他有关机关依照法定程序作出修改者外，予以保留。"},{"i":9,"n":"第九条","txt":"澳门特别行政区的行政机关、立法机关和司法机关，除使用中文外，还可使用葡文，葡文也是正式语文。"},{"i":10,"n":"第十条","txt":"澳门特别行政区除悬挂和使用中华人民共和国国旗和国徽外，还可悬挂和使用澳门特别行政区区旗和区徽。"},{"i":11,"n":"第十一条","txt":"根据中华人民共和国宪法第三十一条，澳门特别行政区的制度和政策，包括社会、经济制度，有关保障居民的基本权利和自由的制度，行政管理、立法和司法方面的制度，以及有关政策，均以本法的规定为依据。"},{"i":12,"n":"第十二条","txt":"澳门特别行政区是中华人民共和国的一个享有高度自治权的地方行政区域，直辖于中央人民政府。"},{"i":13,"n":"第十三条","txt":"中央人民政府负责管理与澳门特别行政区有关的外交事务。"},{"i":14,"n":"第十四条","txt":"中央人民政府负责管理澳门特别行政区的防务。"},{"i":15,"n":"第十五条","txt":"中央人民政府依照本法有关规定任免澳门特别行政区行政长官、政府主要官员和检察长。"},{"i":16,"n":"第十六条","txt":"澳门特别行政区享有行政管理权，依照本法有关规定自行处理澳门特别行政区的行政事务。"},{"i":17,"n":"第十七条","txt":"澳门特别行政区享有立法权。"},{"i":18,"n":"第十八条","txt":"在澳门特别行政区实行的法律为本法以及本法第八条规定的澳门原有法律和澳门特别行政区立法机关制定的法律。"},{"i":19,"n":"第十九条","txt":"澳门特别行政区享有独立的司法权和终审权。"},{"i":20,"n":"第二十条","txt":"澳门特别行政区可享有全国人民代表大会、全国人民代表大会常务委员会或中央人民政府授予的其他权力。"},{"i":21,"n":"第二十一条","txt":"澳门特别行政区居民中的中国公民依法参与国家事务的管理。"},{"i":22,"n":"第二十二条","txt":"中央人民政府所属各部门、各省、自治区、直辖市均不得干预澳门特别行政区依照本法自行管理的事务。"},{"i":23,"n":"第二十三条","txt":"澳门特别行政区应自行立法禁止任何叛国、分裂国家、煽动叛乱、颠覆中央人民政府及窃取国家机密的行为，禁止外国的政治性组织或团体在澳门特别行政区进行政治活动，禁止澳门特别行政区的政治性组织或团体与外国的政治性组织或团体建立联系。"},{"i":24,"n":"第二十四条","txt":"澳门特别行政区居民，简称澳门居民，包括永久性居民和非永久性居民。"},{"i":25,"n":"第二十五条","txt":"澳门居民在法律面前一律平等，不因国籍、血统、种族、性别、语言、宗教、政治或思想信仰、文化程度、经济状况或社会条件而受到歧视。"},{"i":26,"n":"第二十六条","txt":"澳门特别行政区永久性居民依法享有选举权和被选举权。"},{"i":27,"n":"第二十七条","txt":"澳门居民享有言论、新闻、出版的自由，结社、集会、游行、示威的自由，组织和参加工会、罢工的权利和自由。"},{"i":28,"n":"第二十八条","txt":"澳门居民的人身自由不受侵犯。"},{"i":29,"n":"第二十九条","txt":"澳门居民除其行为依照当时法律明文规定为犯罪和应受惩处外，不受刑罚处罚。"},{"i":30,"n":"第三十条","txt":"澳门居民的人格尊严不受侵犯。禁止用任何方法对居民进行侮辱、诽谤和诬告陷害。"},{"i":31,"n":"第三十一条","txt":"澳门居民的住宅和其他房屋不受侵犯。禁止任意或非法搜查、侵入居民的住宅和其他房屋。"},{"i":32,"n":"第三十二条","txt":"澳门居民的通讯自由和通讯秘密受法律保护。除因公共安全和追查刑事犯罪的需要，由有关机关依照法律规定对通讯进行检查外，任何部门或个人不得以任何理由侵犯居民的通讯自由和通讯秘密。"},{"i":33,"n":"第三十三条","txt":"澳门居民有在澳门特别行政区境内迁徙的自由，有移居其他国家和地区的自由。澳门居民有旅行和出入境的自由，有依照法律取得各种旅行证件的权利。有效旅行证件持有人，除非受到法律制止，可自由离开澳门特别行政区，无需特别批准。"},{"i":34,"n":"第三十四条","txt":"澳门居民有信仰的自由。"},{"i":35,"n":"第三十五条","txt":"澳门居民有选择职业和工作的自由。"},{"i":36,"n":"第三十六条","txt":"澳门居民有权诉诸法律，向法院提起诉讼，得到律师的帮助以保护自己的合法权益，以及获得司法补救。"},{"i":37,"n":"第三十七条","txt":"澳门居民有从事教育、学术研究、文学艺术创作和其他文化活动的自由。"},{"i":38,"n":"第三十八条","txt":"澳门居民的婚姻自由、成立家庭和自愿生育的权利受法律保护。"},{"i":39,"n":"第三十九条","txt":"澳门居民有依法享受社会福利的权利。劳工的福利待遇和退休保障受法律保护。"},{"i":40,"n":"第四十条","txt":"《公民权利和政治权利国际公约》、《经济、社会与文化权利的国际公约》和国际劳工公约适用于澳门的有关规定继续有效，通过澳门特别行政区的法律予以实施。"},{"i":41,"n":"第四十一条","txt":"澳门居民享有澳门特别行政区法律保障的其他权利和自由。"},{"i":42,"n":"第四十二条","txt":"在澳门的葡萄牙后裔居民的利益依法受澳门特别行政区的保护，他们的习俗和文化传统应受尊重。"},{"i":43,"n":"第四十三条","txt":"在澳门特别行政区境内的澳门居民以外的其他人，依法享有本章规定的澳门居民的权利和自由。"},{"i":44,"n":"第四十四条","txt":"澳门居民和在澳门的其他人有遵守澳门特别行政区实行的法律的义务。"},{"i":45,"n":"第四十五条","txt":"澳门特别行政区行政长官是澳门特别行政区的首长，代表澳门特别行政区。"},{"i":46,"n":"第四十六条","txt":"澳门特别行政区行政长官由年满四十周岁，在澳门通常居住连续满二十年的澳门特别行政区永久性居民中的中国公民担任。"},{"i":47,"n":"第四十七条","txt":"澳门特别行政区行政长官在当地通过选举或协商产生，由中央人民政府任命。"},{"i":48,"n":"第四十八条","txt":"澳门特别行政区行政长官任期五年，可连任一次。"},{"i":49,"n":"第四十九条","txt":"澳门特别行政区行政长官在任职期内不得具有外国居留权，不得从事私人赢利活动。行政长官就任时应向澳门特别行政区终审法院院长申报财产，记录在案。"},{"i":50,"n":"第五十条","txt":"澳门特别行政区行政长官行使下列职权："},{"i":51,"n":"第五十一条","txt":"澳门特别行政区行政长官如认为立法会通过的法案不符合澳门特别行政区的整体利益，可在九十日内提出书面理由并将法案发回立法会重议。立法会如以不少于全体议员三分之二多数再次通过原案，行政长官必须在三十日内签署公布或依照本法第五十二条的规定处理。"},{"i":52,"n":"第五十二条","txt":"澳门特别行政区行政长官遇有下列情况之一时，可解散立法会："},{"i":53,"n":"第五十三条","txt":"澳门特别行政区行政长官在立法会未通过政府提出的财政预算案时，可按上一财政年度的开支标准批准临时短期拨款。"},{"i":54,"n":"第五十四条","txt":"澳门特别行政区行政长官如有下列情况之一者必须辞职："},{"i":55,"n":"第五十五条","txt":"澳门特别行政区行政长官短期不能履行职务时，由各司司长按各司的排列顺序临时代理其职务。各司的排列顺序由法律规定。"},{"i":56,"n":"第五十六条","txt":"澳门特别行政区行政会是协助行政长官决策的机构。"},{"i":57,"n":"第五十七条","txt":"澳门特别行政区行政会的委员由行政长官从政府主要官员、立法会议员和社会人士中委任，其任免由行政长官决定。行政会委员的任期不超过委任他的行政长官的任期，但在新的行政长官就任前，原行政会委员暂时留任。"},{"i":58,"n":"第五十八条","txt":"澳门特别行政区行政会由行政长官主持。行政会的会议每月至少举行一次。行政长官在作出重要决策、向立法会提交法案、制定行政法规和解散立法会前，须征询行政会的意见，但人事任免、纪律制裁和紧急情况下采取的措施除外。"},{"i":59,"n":"第五十九条","txt":"澳门特别行政区设立廉政公署，独立工作。廉政专员对行政长官负责。"},{"i":60,"n":"第六十条","txt":"澳门特别行政区设立审计署，独立工作。审计长对行政长官负责。"},{"i":61,"n":"第六十一条","txt":"澳门特别行政区政府是澳门特别行政区的行政机关。"},{"i":62,"n":"第六十二条","txt":"澳门特别行政区政府的首长是澳门特别行政区行政长官。澳门特别行政区政府设司、局、厅、处。"},{"i":63,"n":"第六十三条","txt":"澳门特别行政区政府的主要官员由在澳门通常居住连续满十五年的澳门特别行政区永久性居民中的中国公民担任。"},{"i":64,"n":"第六十四条","txt":"澳门特别行政区政府行使下列职权："},{"i":65,"n":"第六十五条","txt":"澳门特别行政区政府必须遵守法律，对澳门特别行政区立法会负责：执行立法会通过并已生效的法律；定期向立法会作施政报告；答复立法会议员的质询。"},{"i":66,"n":"第六十六条","txt":"澳门特别行政区行政机关可根据需要设立咨询组织。"},{"i":67,"n":"第六十七条","txt":"澳门特别行政区立法会是澳门特别行政区的立法机关。"},{"i":68,"n":"第六十八条","txt":"澳门特别行政区立法会议员由澳门特别行政区永久性居民担任。"},{"i":69,"n":"第六十九条","txt":"澳门特别行政区立法会除第一届另有规定外，每届任期四年。"},{"i":70,"n":"第七十条","txt":"澳门特别行政区立法会如经行政长官依照本法规定解散，须于九十日内依照本法第六十八条的规定重新产生。"},{"i":71,"n":"第七十一条","txt":"澳门特别行政区立法会行使下列职权："},{"i":72,"n":"第七十二条","txt":"澳门特别行政区立法会设主席、副主席各一人。主席、副主席由立法会议员互选产生。"},{"i":73,"n":"第七十三条","txt":"澳门特别行政区立法会主席缺席时由副主席代理。"},{"i":74,"n":"第七十四条","txt":"澳门特别行政区立法会主席行使下列职权："},{"i":75,"n":"第七十五条","txt":"澳门特别行政区立法会议员依照本法规定和法定程序提出议案。凡不涉及公共收支、政治体制或政府运作的议案，可由立法会议员个别或联名提出。凡涉及政府政策的议案，在提出前必须得到行政长官的书面同意。"},{"i":76,"n":"第七十六条","txt":"澳门特别行政区立法会议员有权依照法定程序对政府的工作提出质询。"},{"i":77,"n":"第七十七条","txt":"澳门特别行政区立法会举行会议的法定人数为不少于全体议员的二分之一。除本法另有规定外，立法会的法案、议案由全体议员过半数通过。"},{"i":78,"n":"第七十八条","txt":"澳门特别行政区立法会通过的法案，须经行政长官签署、公布，方能生效。"},{"i":79,"n":"第七十九条","txt":"澳门特别行政区立法会议员在立法会会议上的发言和表决，不受法律追究。"},{"i":80,"n":"第八十条","txt":"澳门特别行政区立法会议员非经立法会许可不受逮捕，但现行犯不在此限。"},{"i":81,"n":"第八十一条","txt":"澳门特别行政区立法会议员如有下列情况之一，经立法会决定，即丧失其立法会议员的资格："},{"i":82,"n":"第八十二条","txt":"澳门特别行政区法院行使审判权。"},{"i":83,"n":"第八十三条","txt":"澳门特别行政区法院独立进行审判，只服从法律，不受任何干涉。"},{"i":84,"n":"第八十四条","txt":"澳门特别行政区设立初级法院、中级法院和终审法院。"},{"i":85,"n":"第八十五条","txt":"澳门特别行政区初级法院可根据需要设立若干专门法庭。"},{"i":86,"n":"第八十六条","txt":"澳门特别行政区设立行政法院。行政法院是管辖行政诉讼和税务诉讼的法院。不服行政法院裁决者，可向中级法院上诉。"},{"i":87,"n":"第八十七条","txt":"澳门特别行政区各级法院的法官，根据当地法官、律师和知名人士组成的独立委员会的推荐，由行政长官任命。法官的选用以其专业资格为标准，符合标准的外籍法官也可聘用。"},{"i":88,"n":"第八十八条","txt":"澳门特别行政区各级法院的院长由行政长官从法官中选任。"},{"i":89,"n":"第八十九条","txt":"澳门特别行政区法官依法进行审判，不听从任何命令或指示，但本法第十九条第三款规定的情况除外。"},{"i":90,"n":"第九十条","txt":"澳门特别行政区检察院独立行使法律赋予的检察职能，不受任何干涉。"},{"i":91,"n":"第九十一条","txt":"原在澳门实行的司法辅助人员的任免制度予以保留。"},{"i":92,"n":"第九十二条","txt":"澳门特别行政区政府可参照原在澳门实行的办法，作出有关当地和外来的律师在澳门特别行政区执业的规定。"},{"i":93,"n":"第九十三条","txt":"澳门特别行政区可与全国其他地区的司法机关通过协商依法进行司法方面的联系和相互提供协助。"},{"i":94,"n":"第九十四条","txt":"在中央人民政府协助和授权下，澳门特别行政区可与外国就司法互助关系作出适当安排。"},{"i":95,"n":"第九十五条","txt":"澳门特别行政区可设立非政权性的市政机构。市政机构受政府委托为居民提供文化、康乐、环境卫生等方面的服务，并就有关上述事务向澳门特别行政区政府提供咨询意见。"},{"i":96,"n":"第九十六条","txt":"市政机构的职权和组成由法律规定。"},{"i":97,"n":"第九十七条","txt":"澳门特别行政区的公务人员必须是澳门特别行政区永久性居民。本法第九十八条和九十九条规定的公务人员，以及澳门特别行政区聘用的某些专业技术人员和初级公务人员除外。"},{"i":98,"n":"第九十八条","txt":"澳门特别行政区成立时，原在澳门任职的公务人员，包括警务人员和司法辅助人员，均可留用，继续工作，其薪金、津贴、福利待遇不低于原来的标准，原来享有的年资予以保留。"},{"i":99,"n":"第九十九条","txt":"澳门特别行政区可任用原澳门公务人员中的或持有澳门特别行政区永久性居民身份证的葡籍和其他外籍人士担任各级公务人员，但本法另有规定者除外。"},{"i":100,"n":"第一百条","txt":"公务人员应根据其本人的资格、经验和才能予以任用和提升。澳门原有关于公务人员的录用、纪律、提升和正常晋级制度基本不变，但得根据澳门社会的发展加以改进。"},{"i":101,"n":"第一百零一条","txt":"澳门特别行政区行政长官、主要官员、行政会委员、立法会议员、法官和检察官，必须拥护中华人民共和国澳门特别行政区基本法，尽忠职守，廉洁奉公，效忠中华人民共和国澳门特别行政区，并依法宣誓。"},{"i":102,"n":"第一百零二条","txt":"澳门特别行政区行政长官、主要官员、立法会主席、终审法院院长、检察长在就职时，除按本法第一百零一条的规定宣誓外，还必须宣誓效忠中华人民共和国。"},{"i":103,"n":"第一百零三条","txt":"澳门特别行政区依法保护私人和法人财产的取得、使用、处置和继承的权利，以及依法征用私人和法人财产时被征用财产的所有人得到补偿的权利。"},{"i":104,"n":"第一百零四条","txt":"澳门特别行政区保持财政独立。"},{"i":105,"n":"第一百零五条","txt":"澳门特别行政区的财政预算以量入为出为原则，力求收支平衡，避免赤字，并与本地生产总值的增长率相适应。"},{"i":106,"n":"第一百零六条","txt":"澳门特别行政区实行独立的税收制度。"},{"i":107,"n":"第一百零七条","txt":"澳门特别行政区的货币金融制度由法律规定。"},{"i":108,"n":"第一百零八条","txt":"澳门元为澳门特别行政区的法定货币，继续流通。"},{"i":109,"n":"第一百零九条","txt":"澳门特别行政区不实行外汇管制政策。澳门元自由兑换。"},{"i":110,"n":"第一百一十条","txt":"澳门特别行政区保持自由港地位，除法律另有规定外，不征收关税。"},{"i":111,"n":"第一百一十一条","txt":"澳门特别行政区实行自由贸易政策，保障货物、无形财产和资本的流动自由。"},{"i":112,"n":"第一百一十二条","txt":"澳门特别行政区为单独的关税地区。"},{"i":113,"n":"第一百一十三条","txt":"澳门特别行政区根据当时的产地规则，可对产品签发产地来源证。"},{"i":114,"n":"第一百一十四条","txt":"澳门特别行政区依法保护工商企业的自由经营，自行制定工商业的发展政策。"},{"i":115,"n":"第一百一十五条","txt":"澳门特别行政区根据经济发展的情况，自行制定劳工政策，完善劳工法律。"},{"i":116,"n":"第一百一十六条","txt":"澳门特别行政区保持和完善原在澳门实行的航运经营和管理体制，自行制定航运政策。"},{"i":117,"n":"第一百一十七条","txt":"澳门特别行政区政府经中央人民政府具体授权可自行制定民用航空的各项管理制度。"},{"i":118,"n":"第一百一十八条","txt":"澳门特别行政区根据本地整体利益自行制定旅游娱乐业的政策。"},{"i":119,"n":"第一百一十九条","txt":"澳门特别行政区政府依法实行环境保护。"},{"i":120,"n":"第一百二十条","txt":"澳门特别行政区依法承认和保护澳门特别行政区成立前已批出或决定的年期超过一九九九年十二月十九日的合法土地契约和与土地契约有关的一切权利。"},{"i":121,"n":"第一百二十一条","txt":"澳门特别行政区政府自行制定教育政策，包括教育体制和管理、教学语言、经费分配、考试制度、承认学历和学位等政策，推动教育的发展。"},{"i":122,"n":"第一百二十二条","txt":"澳门原有各类学校均可继续开办。澳门特别行政区各类学校均有办学的自主性，依法享有教学自由和学术自由。"},{"i":123,"n":"第一百二十三条","txt":"澳门特别行政区政府自行制定促进医疗卫生服务和发展中西医药的政策。社会团体和私人可依法提供各种医疗卫生服务。"},{"i":124,"n":"第一百二十四条","txt":"澳门特别行政区政府自行制定科学技术政策，依法保护科学技术的研究成果、专利和发明创造。"},{"i":125,"n":"第一百二十五条","txt":"澳门特别行政区政府自行制定文化政策，包括文学艺术、广播、电影、电视等政策。"},{"i":126,"n":"第一百二十六条","txt":"澳门特别行政区政府自行制定新闻、出版政策。"},{"i":127,"n":"第一百二十七条","txt":"澳门特别行政区政府自行制定体育政策。民间体育团体可依法继续存在和发展。"},{"i":128,"n":"第一百二十八条","txt":"澳门特别行政区政府根据宗教信仰自由的原则，不干预宗教组织的内部事务，不干预宗教组织和教徒同澳门以外地区的宗教组织和教徒保持及发展关系，不限制与澳门特别行政区法律没有抵触的宗教活动。"},{"i":129,"n":"第一百二十九条","txt":"澳门特别行政区政府自行确定专业制度，根据公平合理的原则，制定有关评审和颁授各种专业和执业资格的办法。"},{"i":130,"n":"第一百三十条","txt":"澳门特别行政区政府在原有社会福利制度的基础上，根据经济条件和社会需要自行制定有关社会福利的发展和改进的政策。"},{"i":131,"n":"第一百三十一条","txt":"澳门特别行政区的社会服务团体，在不抵触法律的情况下，可以自行决定其服务方式。"},{"i":132,"n":"第一百三十二条","txt":"澳门特别行政区政府根据需要和可能逐步改善原在澳门实行的对教育、科学、技术、文化、体育、康乐、医疗卫生、社会福利、社会工作等方面的民间组织的资助政策。"},{"i":133,"n":"第一百三十三条","txt":"澳门特别行政区的教育、科学、技术、文化、新闻、出版、体育、康乐、专业、医疗卫生、劳工、妇女、青年、归侨、社会福利、社会工作等方面的民间团体和宗教组织同全国其他地区相应的团体和组织的关系，以互不隶属、互不干涉、互相尊重的原则为基础。"},{"i":134,"n":"第一百三十四条","txt":"澳门特别行政区的教育、科学、技术、文化、新闻、出版、体育、康乐、专业、医疗卫生、劳工、妇女、青年、归侨、社会福利、社会工作等方面的民间团体和宗教组织可同世界各国、各地区及国际的有关团体和组织保持和发展关系，各该团体和组织可根据需要冠用“中国澳门”的名义，参与有关活动。"},{"i":135,"n":"第一百三十五条","txt":"澳门特别行政区政府的代表，可作为中华人民共和国政府代表团的成员，参加由中央人民政府进行的同澳门特别行政区直接有关的外交谈判。"},{"i":136,"n":"第一百三十六条","txt":"澳门特别行政区可在经济、贸易、金融、航运、通讯、旅游、文化、科技、体育等适当领域以“中国澳门”的名义，单独地同世界各国、各地区及有关国际组织保持和发展关系，签订和履行有关协议。"},{"i":137,"n":"第一百三十七条","txt":"对以国家为单位参加的、同澳门特别行政区有关的、适当领域的国际组织和国际会议，澳门特别行政区政府可派遣代表作为中华人民共和国代表团的成员或以中央人民政府和上述有关国际组织或国际会议允许的身份参加，并以“中国澳门”的名义发表意见。"},{"i":138,"n":"第一百三十八条","txt":"中华人民共和国缔结的国际协议，中央人民政府可根据情况和澳门特别行政区的需要，在征询澳门特别行政区政府的意见后，决定是否适用于澳门特别行政区。"},{"i":139,"n":"第一百三十九条","txt":"中央人民政府授权澳门特别行政区政府依照法律给持有澳门特别行政区永久性居民身份证的中国公民签发中华人民共和国澳门特别行政区护照，给在澳门特别行政区的其他合法居留者签发中华人民共和国澳门特别行政区的其他旅行证件。上述护照和旅行证件，前往各国和各地区有效，并载明持有人有返回澳门特别行政区的权利。"},{"i":140,"n":"第一百四十条","txt":"中央人民政府协助或授权澳门特别行政区政府同有关国家和地区谈判和签订互免签证协议。"},{"i":141,"n":"第一百四十一条","txt":"澳门特别行政区可根据需要在外国设立官方或半官方的经济和贸易机构，报中央人民政府备案。"},{"i":142,"n":"第一百四十二条","txt":"外国在澳门特别行政区设立领事机构或其他官方、半官方机构，须经中央人民政府批准。"},{"i":143,"n":"第一百四十三条","txt":"本法的解释权属于全国人民代表大会常务委员会。"},{"i":144,"n":"第一百四十四条","txt":"本法的修改权属于全国人民代表大会。"},{"i":145,"n":"第一百四十五条","txt":"澳门特别行政区成立时，澳门原有法律除由全国人民代表大会常务委员会宣布为同本法抵触者外，采用为澳门特别行政区法律，如以后发现有的法律与本法抵触，可依照本法规定和法定程序修改或停止生效。"}],"aomentebiexingzhengquzhujunfa":[{"i":1,"n":"第一条","txt":"为了保障中央人民政府派驻澳门特别行政区负责防务的军队依法履行职责，维护国家的主权、统一、领土完整和澳门的安全，根据宪法和澳门特别行政区基本法，制定本法。"},{"i":2,"n":"第二条","txt":"中央人民政府派驻澳门特别行政区负责防务的军队，称中国人民解放军驻澳门部队（以下称澳门驻军）。"},{"i":3,"n":"第三条","txt":"澳门驻军不干预澳门特别行政区的地方事务。澳门特别行政区政府在必要时，可以向中央人民政府请求澳门驻军协助维持社会治安和救助灾害。"},{"i":4,"n":"第四条","txt":"澳门驻军人员除须遵守全国性的法律外，还须遵守澳门特别行政区的法律。"},{"i":5,"n":"第五条","txt":"澳门驻军费用由中央人民政府负担。"},{"i":6,"n":"第六条","txt":"澳门驻军履行下列防务职责："},{"i":7,"n":"第七条","txt":"在全国人民代表大会常务委员会决定宣布战争状态或者因澳门特别行政区内发生澳门特别行政区政府不能控制的危及国家统一或者安全的动乱而决定澳门特别行政区进入紧急状态时，澳门驻军根据中央人民政府决定在澳门特别行政区实施的全国性法律的规定履行职责。"},{"i":8,"n":"第八条","txt":"澳门驻军的飞行器、舰船等武器装备和物资以及持有澳门驻军制发的证件或者证明文件的执行职务的人员和车辆，不受澳门特别行政区执法人员检查、搜查和扣押。"},{"i":9,"n":"第九条","txt":"澳门驻军人员对妨碍其执行职务的行为，可以依照在澳门特别行政区实施的法律的规定采取措施予以制止。"},{"i":10,"n":"第十条","txt":"澳门特别行政区政府应当支持澳门驻军履行防务职责，保障澳门驻军和澳门驻军人员的合法权益。"},{"i":11,"n":"第十一条","txt":"澳门驻军进行训练、演习等军事活动，涉及澳门特别行政区公共利益的，应当事先通报澳门特别行政区政府。"},{"i":12,"n":"第十二条","txt":"澳门驻军和澳门特别行政区政府共同保护澳门特别行政区内的军事设施。"},{"i":13,"n":"第十三条","txt":"澳门驻军的军事用地由澳门特别行政区政府无偿提供。"},{"i":14,"n":"第十四条","txt":"澳门特别行政区政府向中央人民政府请求澳门驻军协助维持社会治安和救助灾害并经中央人民政府批准后，澳门驻军根据中央军事委员会的命令派出部队执行协助维持社会治安和救助灾害的任务，任务完成后即返回驻地。"},{"i":15,"n":"第十五条","txt":"澳门驻军和澳门特别行政区政府应当建立必要的联系，协商处理与驻军有关的事宜。"},{"i":16,"n":"第十六条","txt":"澳门驻军人员应当履行下列义务："},{"i":17,"n":"第十七条","txt":"澳门驻军人员不得参加澳门的政治组织、宗教组织和社会团体。"},{"i":18,"n":"第十八条","txt":"澳门驻军和澳门驻军人员不得以任何形式从事营利性经营活动。澳门驻军人员并不得从事与军人职责不相称的其他任何活动。"},{"i":19,"n":"第十九条","txt":"澳门驻军人员违反全国性的法律和澳门特别行政区的法律的，依法追究法律责任。"},{"i":20,"n":"第二十条","txt":"澳门驻军人员犯罪的案件由军事司法机关管辖；但是，澳门驻军人员非执行职务的行为，侵犯澳门居民、澳门驻军以外的其他人的人身权、财产权以及其他违反澳门特别行政区法律构成犯罪的案件，由澳门特别行政区司法机关管辖。"},{"i":21,"n":"第二十一条","txt":"澳门特别行政区执法人员依法拘捕的涉嫌犯罪的人员，查明是澳门驻军人员的，应当移交澳门驻军羁押。被羁押的人员所涉及的案件，依照本法第二十条的规定确定管辖。"},{"i":22,"n":"第二十二条","txt":"澳门驻军人员被澳门特别行政区法院判处剥夺或者限制人身自由的刑罚或者保安处分的，依照澳门特别行政区的法律规定送交执行；但是，澳门特别行政区有关执法机关与军事司法机关对执行的地点另行协商确定的除外。"},{"i":23,"n":"第二十三条","txt":"澳门驻军人员违反澳门特别行政区的法律，侵害澳门居民、澳门驻军以外的其他人的民事权利的，当事人可以通过协商、调解解决；不愿通过协商、调解解决或者协商、调解不成的，被侵权人可以向法院提起诉讼。澳门驻军人员非执行职务的行为引起的民事侵权案件，由澳门特别行政区法院管辖；执行职务的行为引起的民事侵权案件，由中华人民共和国最高人民法院管辖，侵权行为的损害赔偿适用澳门特别行政区法律。"},{"i":24,"n":"第二十四条","txt":"澳门驻军的机关或者单位在澳门特别行政区与澳门居民、澳门驻军以外的其他人发生合同纠纷时，当事人可以通过协商、调解解决。当事人不愿通过协商、调解解决或者协商、调解不成的，可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，向仲裁机构申请仲裁。当事人没有在合同中订立仲裁条款，事后又没有达成书面仲裁协议的，可以向澳门特别行政区法院提起诉讼；但是，当事人对提起诉讼的法院另有约定的除外。"},{"i":25,"n":"第二十五条","txt":"在澳门特别行政区法院的诉讼活动中，澳门驻军对澳门驻军人员身份、执行职务的行为等事实发出的证明文件为有效证据。但是，相反证据成立的除外。"},{"i":26,"n":"第二十六条","txt":"澳门驻军的国防等国家行为不受澳门特别行政区法院管辖。"},{"i":27,"n":"第二十七条","txt":"澳门特别行政区法院作出的判决、裁定涉及澳门驻军的机关或者单位的财产执行的，澳门驻军的机关或者单位必须履行；但是，澳门特别行政区法院不得对澳门驻军的武器装备、物资和其他财产实施强制执行。"},{"i":28,"n":"第二十八条","txt":"军事司法机关可以与澳门特别行政区司法机关和有关执法机关通过协商进行司法方面的联系和相互提供协助。"},{"i":29,"n":"第二十九条","txt":"本法的解释权属于全国人民代表大会常务委员会。"},{"i":30,"n":"第三十条","txt":"本法自1999年12月20日起施行。"}],"aiguozhuyijiaoyufa":[{"i":1,"n":"第一条","txt":"为了加强新时代爱国主义教育，传承和弘扬爱国主义精神，凝聚全面建设社会主义现代化国家、全面推进中华民族伟大复兴的磅礴力量，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中国是世界上历史最悠久的国家之一，中国各族人民共同创造了光辉灿烂的文化、共同缔造了统一的多民族国家。国家在全体人民中开展爱国主义教育，培育和增进对中华民族和伟大祖国的情感，传承民族精神、增强国家观念，壮大和团结一切爱国力量，使爱国主义成为全体人民的坚定信念、精神力量和自觉行动。"},{"i":3,"n":"第三条","txt":"爱国主义教育应当高举中国特色社会主义伟大旗帜，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持爱国和爱党、爱社会主义相统一，以维护国家统一和民族团结为着力点，把全面建成社会主义现代化强国、实现中华民族伟大复兴作为鲜明主题。"},{"i":4,"n":"第四条","txt":"爱国主义教育坚持中国共产党的领导，健全统一领导、齐抓共管、各方参与、共同推进的工作格局。"},{"i":5,"n":"第五条","txt":"爱国主义教育应当坚持思想引领、文化涵育，教育引导、实践养成，主题鲜明、融入日常，因地制宜、注重实效。"},{"i":6,"n":"第六条","txt":"爱国主义教育的主要内容是："},{"i":7,"n":"第七条","txt":"国家开展铸牢中华民族共同体意识教育，促进各民族交往交流交融，增进对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同，构筑中华民族共有精神家园。"},{"i":8,"n":"第八条","txt":"爱国主义教育应当坚持传承和发展中华优秀传统文化，弘扬社会主义核心价值观，推进中国特色社会主义文化建设，坚定文化自信，建设中华民族现代文明。"},{"i":9,"n":"第九条","txt":"爱国主义教育应当把弘扬爱国主义精神与扩大对外开放结合起来，坚持理性、包容、开放，尊重各国历史特点和文化传统，借鉴吸收人类一切优秀文明成果。"},{"i":10,"n":"第十条","txt":"在每年10月1日中华人民共和国国庆日，国家和社会各方面举行多种形式的庆祝活动，集中开展爱国主义教育。"},{"i":11,"n":"第十一条","txt":"中央爱国主义教育主管部门负责全国爱国主义教育工作的指导、监督和统筹协调。"},{"i":12,"n":"第十二条","txt":"地方爱国主义教育主管部门负责本地区爱国主义教育工作的指导、监督和统筹协调。"},{"i":13,"n":"第十三条","txt":"工会、共产主义青年团、妇女联合会、工商业联合会、文学艺术界联合会、作家协会、科学技术协会、归国华侨联合会、台湾同胞联谊会、残疾人联合会、青年联合会和其他群团组织，应当发挥各自优势，面向所联系的领域和群体开展爱国主义教育。"},{"i":14,"n":"第十四条","txt":"国家采取多种形式开展法治宣传教育、国家安全和国防教育，增强公民的法治意识、国家安全和国防观念，引导公民自觉履行维护国家统一和民族团结，维护国家安全、荣誉和利益的义务。"},{"i":15,"n":"第十五条","txt":"国家将爱国主义教育纳入国民教育体系。各级各类学校应当将爱国主义教育贯穿学校教育全过程，办好、讲好思想政治理论课，并将爱国主义教育内容融入各类学科和教材中。"},{"i":16,"n":"第十六条","txt":"各级各类学校应当将课堂教学与课外实践和体验相结合，把爱国主义教育内容融入校园文化建设和学校各类主题活动，组织学生参观爱国主义教育基地等场馆设施，参加爱国主义教育校外实践活动。"},{"i":17,"n":"第十七条","txt":"未成年人的父母或者其他监护人应当把热爱祖国融入家庭教育，支持、配合学校开展爱国主义教育教学活动，引导、鼓励未成年人参加爱国主义教育社会活动。"},{"i":18,"n":"第十八条","txt":"国家机关应当加强对公职人员的爱国主义教育，发挥公职人员在忠于国家、为国奉献，维护国家统一、促进民族团结，维护国家安全、荣誉和利益方面的模范带头作用。"},{"i":19,"n":"第十九条","txt":"企业事业单位应当将爱国主义教育列入本单位教育计划，大力弘扬劳模精神、劳动精神、工匠精神，结合经营管理、业务培训、文化体育等活动，开展爱国主义教育。"},{"i":20,"n":"第二十条","txt":"基层人民政府和基层群众性自治组织应当把爱国主义教育融入社会主义精神文明建设活动，在市民公约、村规民约中体现爱国主义精神，鼓励和支持开展以爱国主义为主题的群众性文化、体育等活动。"},{"i":21,"n":"第二十一条","txt":"行业协会商会等社会团体应当把爱国主义精神体现在团体章程、行业规范中，根据本团体本行业特点开展爱国主义教育，培育会员的爱国热情和社会担当，发挥会员中公众人物和有社会影响力人士的示范作用。"},{"i":22,"n":"第二十二条","txt":"国家鼓励和支持宗教团体、宗教院校、宗教活动场所开展爱国主义教育，增强宗教教职人员和信教群众的国家意识、公民意识、法治意识和爱国情感，引导宗教与社会主义社会相适应。"},{"i":23,"n":"第二十三条","txt":"国家采取措施开展历史文化教育和“一国两制”实践教育，增强香港特别行政区同胞、澳门特别行政区同胞的爱国精神，自觉维护国家主权、统一和领土完整。"},{"i":24,"n":"第二十四条","txt":"中央和省级爱国主义教育主管部门应当加强对爱国主义教育工作的统筹，指导推动有关部门和单位创新爱国主义教育方式，充分利用各类爱国主义教育资源和平台载体，推进爱国主义教育有效实施。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府应当加强对红色资源的保护、管理和利用，发掘具有历史价值、纪念意义的红色资源，推动红色旅游融合发展示范区建设，发挥红色资源教育功能，传承爱国主义精神。"},{"i":26,"n":"第二十六条","txt":"爱国主义教育基地应当加强内容建设，丰富展览展示方式，打造精品陈列，为国家机关、企业事业单位、社会组织、公民开展爱国主义教育活动和参观学习提供便利服务，发挥爱国主义教育功能。"},{"i":27,"n":"第二十七条","txt":"国家通过功勋荣誉表彰制度，褒奖在强国建设、民族复兴中做出突出贡献的人士，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。"},{"i":28,"n":"第二十八条","txt":"在中国人民抗日战争胜利纪念日、烈士纪念日、南京大屠杀死难者国家公祭日和其他重要纪念日，县级以上人民政府应当组织开展纪念活动，举行敬献花篮、瞻仰纪念设施、祭扫烈士墓、公祭等纪念仪式。"},{"i":29,"n":"第二十九条","txt":"在春节、元宵节、清明节、端午节、中秋节和元旦、国际妇女节、国际劳动节、青年节、国际儿童节、中国农民丰收节及其他重要节日，组织开展各具特色的民俗文化活动、纪念庆祝活动，增进家国情怀。"},{"i":30,"n":"第三十条","txt":"组织举办重大庆祝、纪念活动和大型文化体育活动、展览会，应当依法举行庄严、隆重的升挂国旗、奏唱国歌仪式。"},{"i":31,"n":"第三十一条","txt":"广播电台、电视台、报刊出版单位等应当创新宣传报道方式，通过制作、播放、刊登爱国主义题材的优秀作品，开设专题专栏，加强新闻报道，发布公益广告等方式，生动讲好爱国故事，弘扬爱国主义精神。"},{"i":32,"n":"第三十二条","txt":"网络信息服务提供者应当加强网络爱国主义教育内容建设，制作、传播体现爱国主义精神的网络信息和作品，开发、运用新平台新技术新产品，生动开展网上爱国主义教育活动。"},{"i":33,"n":"第三十三条","txt":"国家鼓励和支持企业事业单位、社会组织和公民依法开展爱国主义教育活动。"},{"i":34,"n":"第三十四条","txt":"中央爱国主义教育主管部门建立健全爱国主义教育基地的认定、保护、管理制度，制定爱国主义教育基地保护利用规划，加强对爱国主义教育基地保护、管理、利用的指导和监督。"},{"i":35,"n":"第三十五条","txt":"国家鼓励和支持创作爱国主义题材的文学、影视、音乐、舞蹈、戏剧、美术、书法等文艺作品，在优秀文艺作品评选、表彰、展览、展演时突出爱国主义导向。"},{"i":36,"n":"第三十六条","txt":"国家鼓励和支持出版体现爱国主义精神的优秀课外读物，鼓励和支持开发体现爱国主义精神的面向青少年和儿童的动漫、音视频产品等。"},{"i":37,"n":"第三十七条","txt":"任何公民和组织都应当弘扬爱国主义精神，自觉维护国家安全、荣誉和利益，不得有下列行为："},{"i":38,"n":"第三十八条","txt":"教育、文化和旅游、退役军人事务、新闻出版、广播电视、电影、网信、文物等部门应当按照法定职责，对违反本法第三十七条规定的行为及时予以制止，造成不良社会影响的，应当责令及时消除影响，并依照有关法律、行政法规的规定予以处罚。构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"负有爱国主义教育职责的部门、单位不依法履行爱国主义教育职责的，对负有责任的领导人员和直接责任人员，依法给予处分。"},{"i":40,"n":"第四十条","txt":"本法自2024年1月1日起施行。"}],"jianchaguanfa-2":[{"i":1,"n":"第一条","txt":"为了加强对监察官的管理和监督，保障监察官依法履行职责，维护监察官合法权益，推进高素质专业化监察官队伍建设，推进监察工作规范化、法治化，根据宪法和《中华人民共和国监察法》，制定本法。"},{"i":2,"n":"第二条","txt":"监察官的管理和监督坚持中国共产党领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持党管干部原则，增强监察官的使命感、责任感、荣誉感，建设忠诚干净担当的监察官队伍。"},{"i":3,"n":"第三条","txt":"监察官包括下列人员："},{"i":4,"n":"第四条","txt":"监察官应当忠诚坚定、担当尽责、清正廉洁，做严格自律、作风优良、拒腐防变的表率。"},{"i":5,"n":"第五条","txt":"监察官应当维护宪法和法律的尊严和权威，以事实为根据，以法律为准绳，客观公正地履行职责，保障当事人的合法权益。"},{"i":6,"n":"第六条","txt":"监察官应当严格按照规定的权限和程序履行职责，坚持民主集中制，重大事项集体研究。"},{"i":7,"n":"第七条","txt":"监察机关应当建立健全对监察官的监督制度和机制，确保权力受到严格约束。"},{"i":8,"n":"第八条","txt":"监察官依法履行职责受法律保护，不受行政机关、社会团体和个人的干涉。"},{"i":9,"n":"第九条","txt":"监察官依法履行下列职责："},{"i":10,"n":"第十条","txt":"监察官应当履行下列义务："},{"i":11,"n":"第十一条","txt":"监察官享有下列权利："},{"i":12,"n":"第十二条","txt":"担任监察官应当具备下列条件："},{"i":13,"n":"第十三条","txt":"有下列情形之一的，不得担任监察官："},{"i":14,"n":"第十四条","txt":"监察官的选用，坚持德才兼备、以德为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派，突出政治标准，注重工作实绩。"},{"i":15,"n":"第十五条","txt":"监察官采用考试、考核的办法，从符合监察官条件的人员中择优选用。"},{"i":16,"n":"第十六条","txt":"录用监察官，应当依照法律和国家有关规定采取公开考试、严格考察、平等竞争、择优录取的办法。"},{"i":17,"n":"第十七条","txt":"监察委员会可以根据监察工作需要，依照法律和国家有关规定从中国共产党机关、国家机关、事业单位、国有企业等机关、单位从事公务的人员中选择符合任职条件的人员担任监察官。"},{"i":18,"n":"第十八条","txt":"监察委员会可以根据监察工作需要，依照法律和国家有关规定在从事与监察机关职能职责相关的职业或者教学、研究的人员中选拔或者聘任符合任职条件的人员担任监察官。"},{"i":19,"n":"第十九条","txt":"国家监察委员会主任由全国人民代表大会选举和罢免，副主任、委员由国家监察委员会主任提请全国人民代表大会常务委员会任免。"},{"i":20,"n":"第二十条","txt":"监察官就职时应当依照法律规定进行宪法宣誓。"},{"i":21,"n":"第二十一条","txt":"监察官有下列情形之一的，应当免去其监察官职务："},{"i":22,"n":"第二十二条","txt":"监察官不得兼任人民代表大会常务委员会的组成人员，不得兼任行政机关、审判机关、检察机关的职务，不得兼任企业或者其他营利性组织、事业单位的职务，不得兼任人民陪审员、人民监督员、执业律师、仲裁员和公证员。"},{"i":23,"n":"第二十三条","txt":"监察官担任县级、设区的市级监察委员会主任的，应当按照有关规定实行地域回避。"},{"i":24,"n":"第二十四条","txt":"监察官之间有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的，不得同时担任下列职务："},{"i":25,"n":"第二十五条","txt":"监察官等级分为十三级，依次为总监察官、一级副总监察官、二级副总监察官，一级高级监察官、二级高级监察官、三级高级监察官、四级高级监察官，一级监察官、二级监察官、三级监察官、四级监察官、五级监察官、六级监察官。"},{"i":26,"n":"第二十六条","txt":"国家监察委员会主任为总监察官。"},{"i":27,"n":"第二十七条","txt":"监察官等级的确定，以监察官担任的职务职级、德才表现、业务水平、工作实绩和工作年限等为依据。"},{"i":28,"n":"第二十八条","txt":"监察官的等级设置、确定和晋升的具体办法，由国家另行规定。"},{"i":29,"n":"第二十九条","txt":"初任监察官实行职前培训制度。"},{"i":30,"n":"第三十条","txt":"对监察官应当有计划地进行政治、理论和业务培训。"},{"i":31,"n":"第三十一条","txt":"监察官培训机构按照有关规定承担培训监察官的任务。"},{"i":32,"n":"第三十二条","txt":"国家加强监察学科建设，鼓励具备条件的普通高等学校设置监察专业或者开设监察课程，培养德才兼备的高素质监察官后备人才，提高监察官的专业能力。"},{"i":33,"n":"第三十三条","txt":"监察官依照法律和国家有关规定实行任职交流。"},{"i":34,"n":"第三十四条","txt":"监察官申请辞职，应当由本人书面提出，按照管理权限批准后，依照规定的程序免去其职务。"},{"i":35,"n":"第三十五条","txt":"监察官有依法应当予以辞退情形的，依照规定的程序免去其职务。"},{"i":36,"n":"第三十六条","txt":"对监察官的考核，应当全面、客观、公正，实行平时考核、专项考核和年度考核相结合。"},{"i":37,"n":"第三十七条","txt":"监察官的考核应当按照管理权限，全面考核监察官的德、能、勤、绩、廉，重点考核政治素质、工作实绩和廉洁自律情况。"},{"i":38,"n":"第三十八条","txt":"年度考核结果分为优秀、称职、基本称职和不称职四个等次。"},{"i":39,"n":"第三十九条","txt":"年度考核结果以书面形式通知监察官本人。监察官对考核结果如果有异议，可以申请复核。"},{"i":40,"n":"第四十条","txt":"对在监察工作中有显著成绩和贡献，或者有其他突出事迹的监察官、监察官集体，给予奖励。"},{"i":41,"n":"第四十一条","txt":"监察官有下列表现之一的，给予奖励："},{"i":42,"n":"第四十二条","txt":"监察机关应当规范工作流程，加强内部监督制约机制建设，强化对监察官执行职务和遵守法律情况的监督。"},{"i":43,"n":"第四十三条","txt":"任何单位和个人对监察官的违纪违法行为，有权检举、控告。受理检举、控告的机关应当及时调查处理，并将结果告知检举人、控告人。"},{"i":44,"n":"第四十四条","txt":"对于审判机关、检察机关、执法部门等移送的监察官违纪违法履行职责的问题线索，监察机关应当及时调查处理。"},{"i":45,"n":"第四十五条","txt":"监察委员会根据工作需要，按照规定从各方面代表中聘请特约监察员等监督人员，对监察官履行职责情况进行监督，提出加强和改进监察工作的意见、建议。"},{"i":46,"n":"第四十六条","txt":"监察官不得打听案情、过问案件、说情干预。对于上述行为，办理监察事项的监察官应当及时向上级报告。有关情况应当登记备案。"},{"i":47,"n":"第四十七条","txt":"办理监察事项的监察官有下列情形之一的，应当自行回避，监察对象、检举人、控告人及其他有关人员也有权要求其回避；没有主动申请回避的，监察机关应当依法决定其回避："},{"i":48,"n":"第四十八条","txt":"监察官应当严格执行保密制度，控制监察事项知悉范围和时间，不得私自留存、隐匿、查阅、摘抄、复制、携带问题线索和涉案资料，严禁泄露监察工作秘密。"},{"i":49,"n":"第四十九条","txt":"监察官离任三年内，不得从事与监察和司法工作相关联且可能发生利益冲突的职业。"},{"i":50,"n":"第五十条","txt":"监察官应当遵守有关规范领导干部配偶、子女及其配偶经商办企业行为的规定。违反规定的，予以处理。"},{"i":51,"n":"第五十一条","txt":"监察官的配偶、父母、子女及其配偶不得以律师身份担任该监察官所任职监察机关办理案件的诉讼代理人、辩护人，或者提供其他有偿法律服务。"},{"i":52,"n":"第五十二条","txt":"监察官有下列行为之一的，依法给予处理；构成犯罪的，依法追究刑事责任："},{"i":53,"n":"第五十三条","txt":"监察官涉嫌违纪违法，已经被立案审查、调查、侦查，不宜继续履行职责的，按照管理权限和规定的程序暂时停止其履行职务。"},{"i":54,"n":"第五十四条","txt":"实行监察官责任追究制度，对滥用职权、失职失责造成严重后果的，终身追究责任或者进行问责。"},{"i":55,"n":"第五十五条","txt":"除下列情形外，不得将监察官调离："},{"i":56,"n":"第五十六条","txt":"任何单位或者个人不得要求监察官从事超出法定职责范围的事务。"},{"i":57,"n":"第五十七条","txt":"监察官的职业尊严和人身安全受法律保护。"},{"i":58,"n":"第五十八条","txt":"监察官因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，监察机关应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任。"},{"i":59,"n":"第五十九条","txt":"监察官因依法履行职责，本人及其近亲属人身安全面临危险的，监察机关、公安机关应当对监察官及其近亲属采取人身保护、禁止特定人员接触等必要保护措施。"},{"i":60,"n":"第六十条","txt":"监察官实行国家规定的工资制度，享受监察官等级津贴和其他津贴、补贴、奖金、保险、福利待遇。监察官的工资及等级津贴制度，由国家另行规定。"},{"i":61,"n":"第六十一条","txt":"监察官因公致残的，享受国家规定的伤残待遇。监察官因公牺牲或者病故的，其亲属享受国家规定的抚恤和优待。"},{"i":62,"n":"第六十二条","txt":"监察官退休后，享受国家规定的养老金和其他待遇。"},{"i":63,"n":"第六十三条","txt":"对于国家机关及其工作人员侵犯监察官权利的行为，监察官有权提出控告。"},{"i":64,"n":"第六十四条","txt":"监察官对涉及本人的政务处分、处分和人事处理不服的，可以依照规定的程序申请复审、复核，提出申诉。"},{"i":65,"n":"第六十五条","txt":"对监察官的政务处分、处分或者人事处理错误的，应当及时予以纠正；造成名誉损害的，应当恢复名誉、消除影响、赔礼道歉；造成经济损失的，应当赔偿。对打击报复的直接责任人员，应当依法追究其责任。"},{"i":66,"n":"第六十六条","txt":"有关监察官的权利、义务和管理制度，本法已有规定的，适用本法的规定；本法未作规定的，适用《中华人民共和国公务员法》等法律法规的规定。"},{"i":67,"n":"第六十七条","txt":"中国人民解放军和中国人民武装警察部队的监察官制度，按照国家和军队有关规定执行。"},{"i":68,"n":"第六十八条","txt":"本法自2022年1月1日起施行。"}],"jianchafa":[{"i":1,"n":"第一条","txt":"为了深入开展廉政建设和反腐败工作，加强对所有行使公权力的公职人员的监督，实现国家监察全面覆盖，持续深化国家监察体制改革，推进国家治理体系和治理能力现代化，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"坚持中国共产党对国家监察工作的领导，以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，构建集中统一、权威高效的中国特色国家监察体制。"},{"i":3,"n":"第三条","txt":"各级监察委员会是行使国家监察职能的专责机关，依照本法对所有行使公权力的公职人员（以下称公职人员）进行监察，调查职务违法和职务犯罪，开展廉政建设和反腐败工作，维护宪法和法律的尊严。"},{"i":4,"n":"第四条","txt":"监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。"},{"i":5,"n":"第五条","txt":"国家监察工作严格遵照宪法和法律，以事实为根据，以法律为准绳；权责对等，严格监督；遵守法定程序，公正履行职责；尊重和保障人权，在适用法律上一律平等，保障监察对象及相关人员的合法权益；惩戒与教育相结合，宽严相济。"},{"i":6,"n":"第六条","txt":"国家监察工作坚持标本兼治、综合治理，强化监督问责，严厉惩治腐败；深化改革、健全法治，有效制约和监督权力；加强法治教育和道德教育，弘扬中华优秀传统文化，构建不敢腐、不能腐、不想腐的长效机制。"},{"i":7,"n":"第七条","txt":"中华人民共和国国家监察委员会是最高监察机关。"},{"i":8,"n":"第八条","txt":"国家监察委员会由全国人民代表大会产生，负责全国监察工作。"},{"i":9,"n":"第九条","txt":"地方各级监察委员会由本级人民代表大会产生，负责本行政区域内的监察工作。"},{"i":10,"n":"第十条","txt":"国家监察委员会领导地方各级监察委员会的工作，上级监察委员会领导下级监察委员会的工作。"},{"i":11,"n":"第十一条","txt":"监察委员会依照本法和有关法律规定履行监督、调查、处置职责："},{"i":12,"n":"第十二条","txt":"各级监察委员会可以向本级中国共产党机关、国家机关、中国人民政治协商会议委员会机关、法律法规授权或者委托管理公共事务的组织和单位以及辖区内特定区域、国有企业、事业单位等派驻或者派出监察机构、监察专员。"},{"i":13,"n":"第十三条","txt":"派驻或者派出的监察机构、监察专员根据授权，按照管理权限依法对公职人员进行监督，提出监察建议，依法对公职人员进行调查、处置。"},{"i":14,"n":"第十四条","txt":"国家实行监察官制度，依法确定监察官的等级设置、任免、考评和晋升等制度。"},{"i":15,"n":"第十五条","txt":"监察机关对下列公职人员和有关人员进行监察："},{"i":16,"n":"第十六条","txt":"各级监察机关按照管理权限管辖本辖区内本法第十五条规定的人员所涉监察事项。"},{"i":17,"n":"第十七条","txt":"上级监察机关可以将其所管辖的监察事项指定下级监察机关管辖，也可以将下级监察机关有管辖权的监察事项指定给其他监察机关管辖。"},{"i":18,"n":"第十八条","txt":"监察机关行使监督、调查职权，有权依法向有关单位和个人了解情况，收集、调取证据。有关单位和个人应当如实提供。"},{"i":19,"n":"第十九条","txt":"对可能发生职务违法的监察对象，监察机关按照管理权限，可以直接或者委托有关机关、人员进行谈话，或者进行函询，要求说明情况。"},{"i":20,"n":"第二十条","txt":"在调查过程中，对涉嫌职务违法的被调查人，监察机关可以进行谈话，要求其就涉嫌违法行为作出陈述，必要时向被调查人出具书面通知。"},{"i":21,"n":"第二十一条","txt":"监察机关根据案件情况，经依法审批，可以强制涉嫌严重职务违法或者职务犯罪的被调查人到案接受调查。"},{"i":22,"n":"第二十二条","txt":"在调查过程中，监察机关可以询问证人等人员。"},{"i":23,"n":"第二十三条","txt":"被调查人涉嫌严重职务违法或者职务犯罪，并有下列情形之一的，经监察机关依法审批，可以对其采取责令候查措施："},{"i":24,"n":"第二十四条","txt":"被调查人涉嫌贪污贿赂、失职渎职等严重职务违法或者职务犯罪，监察机关已经掌握其部分违法犯罪事实及证据，仍有重要问题需要进一步调查，并有下列情形之一的，经监察机关依法审批，可以将其留置在特定场所："},{"i":25,"n":"第二十五条","txt":"对于未被留置的下列人员，监察机关发现存在逃跑、自杀等重大安全风险的，经依法审批，可以进行管护："},{"i":26,"n":"第二十六条","txt":"监察机关调查涉嫌贪污贿赂、失职渎职等严重职务违法或者职务犯罪，根据工作需要，可以依照规定查询、冻结涉案单位和个人的存款、汇款、债券、股票、基金份额等财产。有关单位和个人应当配合。"},{"i":27,"n":"第二十七条","txt":"监察机关可以对涉嫌职务犯罪的被调查人以及可能隐藏被调查人或者犯罪证据的人的身体、物品、住处和其他有关地方进行搜查。在搜查时，应当出示搜查证，并有被搜查人或者其家属等见证人在场。"},{"i":28,"n":"第二十八条","txt":"监察机关在调查过程中，可以调取、查封、扣押用以证明被调查人涉嫌违法犯罪的财物、文件和电子数据等信息。采取调取、查封、扣押措施，应当收集原物原件，会同持有人或者保管人、见证人，当面逐一拍照、登记、编号，开列清单，由在场人员当场核对、签名，并将清单副本交财物、文件的持有人或者保管人。"},{"i":29,"n":"第二十九条","txt":"监察机关在调查过程中，可以直接或者指派、聘请具有专门知识的人在调查人员主持下进行勘验检查。勘验检查情况应当制作笔录，由参加勘验检查的人员和见证人签名或者盖章。"},{"i":30,"n":"第三十条","txt":"监察机关在调查过程中，对于案件中的专门性问题，可以指派、聘请有专门知识的人进行鉴定。鉴定人进行鉴定后，应当出具鉴定意见，并且签名。"},{"i":31,"n":"第三十一条","txt":"监察机关调查涉嫌重大贪污贿赂等职务犯罪，根据需要，经过严格的批准手续，可以采取技术调查措施，按照规定交有关机关执行。"},{"i":32,"n":"第三十二条","txt":"依法应当留置的被调查人如果在逃，监察机关可以决定在本行政区域内通缉，由公安机关发布通缉令，追捕归案。通缉范围超出本行政区域的，应当报请有权决定的上级监察机关决定。"},{"i":33,"n":"第三十三条","txt":"监察机关为防止被调查人及相关人员逃匿境外，经省级以上监察机关批准，可以对被调查人及相关人员采取限制出境措施，由公安机关依法执行。对于不需要继续采取限制出境措施的，应当及时解除。"},{"i":34,"n":"第三十四条","txt":"涉嫌职务犯罪的被调查人主动认罪认罚，有下列情形之一的，监察机关经领导人员集体研究，并报上一级监察机关批准，可以在移送人民检察院时提出从宽处罚的建议："},{"i":35,"n":"第三十五条","txt":"职务违法犯罪的涉案人员揭发有关被调查人职务违法犯罪行为，查证属实的，或者提供重要线索，有助于调查其他案件的，监察机关经领导人员集体研究，并报上一级监察机关批准，可以在移送人民检察院时提出从宽处罚的建议。"},{"i":36,"n":"第三十六条","txt":"监察机关依照本法规定收集的物证、书证、证人证言、被调查人供述和辩解、视听资料、电子数据等证据材料，在刑事诉讼中可以作为证据使用。"},{"i":37,"n":"第三十七条","txt":"人民法院、人民检察院、公安机关、审计机关等国家机关在工作中发现公职人员涉嫌贪污贿赂、失职渎职等职务违法或者职务犯罪的问题线索，应当移送监察机关，由监察机关依法调查处置。"},{"i":38,"n":"第三十八条","txt":"监察机关对于报案或者举报，应当接受并按照有关规定处理。对于不属于本机关管辖的，应当移送主管机关处理。"},{"i":39,"n":"第三十九条","txt":"监察机关应当严格按照程序开展工作，建立问题线索处置、调查、审理各部门相互协调、相互制约的工作机制。"},{"i":40,"n":"第四十条","txt":"监察机关对监察对象的问题线索，应当按照有关规定提出处置意见，履行审批手续，进行分类办理。线索处置情况应当定期汇总、通报，定期检查、抽查。"},{"i":41,"n":"第四十一条","txt":"需要采取初步核实方式处置问题线索的，监察机关应当依法履行审批程序，成立核查组。初步核实工作结束后，核查组应当撰写初步核实情况报告，提出处理建议。承办部门应当提出分类处理意见。初步核实情况报告和分类处理意见报监察机关主要负责人审批。"},{"i":42,"n":"第四十二条","txt":"经过初步核实，对监察对象涉嫌职务违法犯罪，需要追究法律责任的，监察机关应当按照规定的权限和程序办理立案手续。"},{"i":43,"n":"第四十三条","txt":"监察机关对职务违法和职务犯罪案件，应当进行调查，收集被调查人有无违法犯罪以及情节轻重的证据，查明违法犯罪事实，形成相互印证、完整稳定的证据链。"},{"i":44,"n":"第四十四条","txt":"调查人员采取讯问、询问、强制到案、责令候查、管护、留置、搜查、调取、查封、扣押、勘验检查等调查措施，均应当依照规定出示证件，出具书面通知，由二人以上进行，形成笔录、报告等书面材料，并由相关人员签名、盖章。"},{"i":45,"n":"第四十五条","txt":"调查人员应当严格执行调查方案，不得随意扩大调查范围、变更调查对象和事项。"},{"i":46,"n":"第四十六条","txt":"采取强制到案、责令候查或者管护措施，应当按照规定的权限和程序，经监察机关主要负责人批准。"},{"i":47,"n":"第四十七条","txt":"监察机关采取留置措施，应当由监察机关领导人员集体研究决定。设区的市级以下监察机关采取留置措施，应当报上一级监察机关批准。省级监察机关采取留置措施，应当报国家监察委员会备案。"},{"i":48,"n":"第四十八条","txt":"留置时间不得超过三个月。在特殊情况下，可以延长一次，延长时间不得超过三个月。省级以下监察机关采取留置措施的，延长留置时间应当报上一级监察机关批准。监察机关发现采取留置措施不当或者不需要继续采取留置措施的，应当及时解除或者变更为责令候查措施。"},{"i":49,"n":"第四十九条","txt":"监察机关采取强制到案、责令候查、管护、留置措施，可以根据工作需要提请公安机关配合。公安机关应当依法予以协助。"},{"i":50,"n":"第五十条","txt":"采取管护或者留置措施后，应当在二十四小时以内，通知被管护人员、被留置人员所在单位和家属，但有可能伪造、隐匿、毁灭证据，干扰证人作证或者串供等有碍调查情形的除外。有碍调查的情形消失后，应当立即通知被管护人员、被留置人员所在单位和家属。解除管护或者留置的，应当及时通知被管护人员、被留置人员所在单位和家属。"},{"i":51,"n":"第五十一条","txt":"监察机关在调查工作结束后，应当依法对案件事实和证据、性质认定、程序手续、涉案财物等进行全面审理，形成审理报告，提请集体审议。"},{"i":52,"n":"第五十二条","txt":"监察机关根据监督、调查结果，依法作出如下处置："},{"i":53,"n":"第五十三条","txt":"监察机关经调查，对违法取得的财物，依法予以没收、追缴或者责令退赔；对涉嫌犯罪取得的财物，应当随案移送人民检察院。"},{"i":54,"n":"第五十四条","txt":"对监察机关移送的案件，人民检察院依照《中华人民共和国刑事诉讼法》对被调查人采取强制措施。"},{"i":55,"n":"第五十五条","txt":"监察机关在调查贪污贿赂、失职渎职等职务犯罪案件过程中，被调查人逃匿或者死亡，有必要继续调查的，应当继续调查并作出结论。被调查人逃匿，在通缉一年后不能到案，或者死亡的，由监察机关提请人民检察院依照法定程序，向人民法院提出没收违法所得的申请。"},{"i":56,"n":"第五十六条","txt":"监察对象对监察机关作出的涉及本人的处理决定不服的，可以在收到处理决定之日起一个月内，向作出决定的监察机关申请复审，复审机关应当在一个月内作出复审决定；监察对象对复审决定仍不服的，可以在收到复审决定之日起一个月内，向上一级监察机关申请复核，复核机关应当在二个月内作出复核决定。复审、复核期间，不停止原处理决定的执行。复核机关经审查，认定处理决定有错误的，原处理机关应当及时予以纠正。"},{"i":57,"n":"第五十七条","txt":"国家监察委员会统筹协调与其他国家、地区、国际组织开展的反腐败国际交流、合作，组织反腐败国际条约实施工作。"},{"i":58,"n":"第五十八条","txt":"国家监察委员会会同有关单位加强与有关国家、地区、国际组织在反腐败方面开展引渡、移管被判刑人、遣返、联合调查、调查取证、资产追缴和信息交流等执法司法合作和司法协助。"},{"i":59,"n":"第五十九条","txt":"国家监察委员会加强对反腐败国际追逃追赃和防逃工作的组织协调，督促有关单位做好相关工作："},{"i":60,"n":"第六十条","txt":"各级监察委员会应当接受本级人民代表大会及其常务委员会的监督。"},{"i":61,"n":"第六十一条","txt":"监察机关应当依法公开监察工作信息，接受民主监督、社会监督、舆论监督。"},{"i":62,"n":"第六十二条","txt":"监察机关根据工作需要，可以从各方面代表中聘请特约监察员。特约监察员按照规定对监察机关及其工作人员履行职责情况实行监督。"},{"i":63,"n":"第六十三条","txt":"监察机关通过设立内部专门的监督机构等方式，加强对监察人员执行职务和遵守法律情况的监督，建设忠诚、干净、担当的监察队伍。"},{"i":64,"n":"第六十四条","txt":"监察人员涉嫌严重职务违法或者职务犯罪，为防止造成更为严重的后果或者恶劣影响，监察机关经依法审批，可以对其采取禁闭措施。禁闭的期限不得超过七日。"},{"i":65,"n":"第六十五条","txt":"监察人员必须模范遵守宪法和法律，忠于职守、秉公执法，清正廉洁、保守秘密；必须具有良好的政治素质，熟悉监察业务，具备运用法律、法规、政策和调查取证等能力，自觉接受监督。"},{"i":66,"n":"第六十六条","txt":"对于监察人员打听案情、过问案件、说情干预的，办理监察事项的监察人员应当及时报告。有关情况应当登记备案。"},{"i":67,"n":"第六十七条","txt":"办理监察事项的监察人员有下列情形之一的，应当自行回避，监察对象、检举人及其他有关人员也有权要求其回避："},{"i":68,"n":"第六十八条","txt":"监察机关涉密人员离岗离职后，应当遵守脱密期管理规定，严格履行保密义务，不得泄露相关秘密。"},{"i":69,"n":"第六十九条","txt":"监察机关及其工作人员有下列行为之一的，被调查人及其近亲属、利害关系人有权向该机关申诉："},{"i":70,"n":"第七十条","txt":"对调查工作结束后发现立案依据不充分或者失实，案件处置出现重大失误，监察人员严重违法的，应当追究负有责任的领导人员和直接责任人员的责任。"},{"i":71,"n":"第七十一条","txt":"有关单位拒不执行监察机关作出的处理决定，或者无正当理由拒不采纳监察建议的，由其主管部门、上级机关责令改正，对单位给予通报批评；对负有责任的领导人员和直接责任人员依法给予处理。"},{"i":72,"n":"第七十二条","txt":"有关人员违反本法规定，有下列行为之一的，由其所在单位、主管部门、上级机关或者监察机关责令改正，依法给予处理："},{"i":73,"n":"第七十三条","txt":"监察对象对控告人、检举人、证人或者监察人员进行报复陷害的；控告人、检举人、证人捏造事实诬告陷害监察对象的，依法给予处理。"},{"i":74,"n":"第七十四条","txt":"监察机关及其工作人员有下列行为之一的，对负有责任的领导人员和直接责任人员依法给予处理："},{"i":75,"n":"第七十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"监察机关及其工作人员行使职权，侵犯公民、法人和其他组织的合法权益造成损害的，依法给予国家赔偿。"},{"i":77,"n":"第七十七条","txt":"中国人民解放军和中国人民武装警察部队开展监察工作，由中央军事委员会根据本法制定具体规定。"},{"i":78,"n":"第七十八条","txt":"本法自公布之日起施行。《中华人民共和国行政监察法》同时废止。"}],"lifafa":[{"i":1,"n":"第一条","txt":"为了规范立法活动，健全国家立法制度，提高立法质量，完善中国特色社会主义法律体系，发挥立法的引领和推动作用，保障和发展社会主义民主，全面推进依法治国，建设社会主义法治国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"法律、行政法规、地方性法规、自治条例和单行条例的制定、修改和废止，适用本法。"},{"i":3,"n":"第三条","txt":"立法应当坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，推进中国特色社会主义法治体系建设，保障在法治轨道上全面建设社会主义现代化国家。"},{"i":4,"n":"第四条","txt":"立法应当坚持以经济建设为中心，坚持改革开放，贯彻新发展理念，保障以中国式现代化全面推进中华民族伟大复兴。"},{"i":5,"n":"第五条","txt":"立法应当符合宪法的规定、原则和精神，依照法定的权限和程序，从国家整体利益出发，维护社会主义法制的统一、尊严、权威。"},{"i":6,"n":"第六条","txt":"立法应当坚持和发展全过程人民民主，尊重和保障人权，保障和促进社会公平正义。"},{"i":7,"n":"第七条","txt":"立法应当从实际出发，适应经济社会发展和全面深化改革的要求，科学合理地规定公民、法人和其他组织的权利与义务、国家机关的权力与责任。"},{"i":8,"n":"第八条","txt":"立法应当倡导和弘扬社会主义核心价值观，坚持依法治国和以德治国相结合，铸牢中华民族共同体意识，推动社会主义精神文明建设。"},{"i":9,"n":"第九条","txt":"立法应当适应改革需要，坚持在法治下推进改革和在改革中完善法治相统一，引导、推动、规范、保障相关改革，发挥法治在国家治理体系和治理能力现代化中的重要作用。"},{"i":10,"n":"第十条","txt":"全国人民代表大会和全国人民代表大会常务委员会根据宪法规定行使国家立法权。"},{"i":11,"n":"第十一条","txt":"下列事项只能制定法律："},{"i":12,"n":"第十二条","txt":"本法第十一条规定的事项尚未制定法律的，全国人民代表大会及其常务委员会有权作出决定，授权国务院可以根据实际需要，对其中的部分事项先制定行政法规，但是有关犯罪和刑罚、对公民政治权利的剥夺和限制人身自由的强制措施和处罚、司法制度等事项除外。"},{"i":13,"n":"第十三条","txt":"授权决定应当明确授权的目的、事项、范围、期限以及被授权机关实施授权决定应当遵循的原则等。"},{"i":14,"n":"第十四条","txt":"授权立法事项，经过实践检验，制定法律的条件成熟时，由全国人民代表大会及其常务委员会及时制定法律。法律制定后，相应立法事项的授权终止。"},{"i":15,"n":"第十五条","txt":"被授权机关应当严格按照授权决定行使被授予的权力。"},{"i":16,"n":"第十六条","txt":"全国人民代表大会及其常务委员会可以根据改革发展的需要，决定就特定事项授权在规定期限和范围内暂时调整或者暂时停止适用法律的部分规定。"},{"i":17,"n":"第十七条","txt":"全国人民代表大会主席团可以向全国人民代表大会提出法律案，由全国人民代表大会会议审议。"},{"i":18,"n":"第十八条","txt":"一个代表团或者三十名以上的代表联名，可以向全国人民代表大会提出法律案，由主席团决定是否列入会议议程，或者先交有关的专门委员会审议、提出是否列入会议议程的意见，再决定是否列入会议议程。"},{"i":19,"n":"第十九条","txt":"向全国人民代表大会提出的法律案，在全国人民代表大会闭会期间，可以先向常务委员会提出，经常务委员会会议依照本法第二章第三节规定的有关程序审议后，决定提请全国人民代表大会审议，由常务委员会向大会全体会议作说明，或者由提案人向大会全体会议作说明。"},{"i":20,"n":"第二十条","txt":"常务委员会决定提请全国人民代表大会会议审议的法律案，应当在会议举行的一个月前将法律草案发给代表，并可以适时组织代表研读讨论，征求代表的意见。"},{"i":21,"n":"第二十一条","txt":"列入全国人民代表大会会议议程的法律案，大会全体会议听取提案人的说明后，由各代表团进行审议。"},{"i":22,"n":"第二十二条","txt":"列入全国人民代表大会会议议程的法律案，由有关的专门委员会进行审议，向主席团提出审议意见，并印发会议。"},{"i":23,"n":"第二十三条","txt":"列入全国人民代表大会会议议程的法律案，由宪法和法律委员会根据各代表团和有关的专门委员会的审议意见，对法律案进行统一审议，向主席团提出审议结果报告和法律草案修改稿，对涉及的合宪性问题以及重要的不同意见应当在审议结果报告中予以说明，经主席团会议审议通过后，印发会议。"},{"i":24,"n":"第二十四条","txt":"列入全国人民代表大会会议议程的法律案，必要时，主席团常务主席可以召开各代表团团长会议，就法律案中的重大问题听取各代表团的审议意见，进行讨论，并将讨论的情况和意见向主席团报告。"},{"i":25,"n":"第二十五条","txt":"列入全国人民代表大会会议议程的法律案，在交付表决前，提案人要求撤回的，应当说明理由，经主席团同意，并向大会报告，对该法律案的审议即行终止。"},{"i":26,"n":"第二十六条","txt":"法律案在审议中有重大问题需要进一步研究的，经主席团提出，由大会全体会议决定，可以授权常务委员会根据代表的意见进一步审议，作出决定，并将决定情况向全国人民代表大会下次会议报告；也可以授权常务委员会根据代表的意见进一步审议，提出修改方案，提请全国人民代表大会下次会议审议决定。"},{"i":27,"n":"第二十七条","txt":"法律草案修改稿经各代表团审议，由宪法和法律委员会根据各代表团的审议意见进行修改，提出法律草案表决稿，由主席团提请大会全体会议表决，由全体代表的过半数通过。"},{"i":28,"n":"第二十八条","txt":"全国人民代表大会通过的法律由国家主席签署主席令予以公布。"},{"i":29,"n":"第二十九条","txt":"委员长会议可以向常务委员会提出法律案，由常务委员会会议审议。"},{"i":30,"n":"第三十条","txt":"常务委员会组成人员十人以上联名，可以向常务委员会提出法律案，由委员长会议决定是否列入常务委员会会议议程，或者先交有关的专门委员会审议、提出是否列入会议议程的意见，再决定是否列入常务委员会会议议程。不列入常务委员会会议议程的，应当向常务委员会会议报告或者向提案人说明。"},{"i":31,"n":"第三十一条","txt":"列入常务委员会会议议程的法律案，除特殊情况外，应当在会议举行的七日前将法律草案发给常务委员会组成人员。"},{"i":32,"n":"第三十二条","txt":"列入常务委员会会议议程的法律案，一般应当经三次常务委员会会议审议后再交付表决。"},{"i":33,"n":"第三十三条","txt":"列入常务委员会会议议程的法律案，各方面的意见比较一致的，可以经两次常务委员会会议审议后交付表决；调整事项较为单一或者部分修改的法律案，各方面的意见比较一致，或者遇有紧急情形的，也可以经一次常务委员会会议审议即交付表决。"},{"i":34,"n":"第三十四条","txt":"常务委员会分组会议审议法律案时，提案人应当派人听取意见，回答询问。"},{"i":35,"n":"第三十五条","txt":"列入常务委员会会议议程的法律案，由有关的专门委员会进行审议，提出审议意见，印发常务委员会会议。"},{"i":36,"n":"第三十六条","txt":"列入常务委员会会议议程的法律案，由宪法和法律委员会根据常务委员会组成人员、有关的专门委员会的审议意见和各方面提出的意见，对法律案进行统一审议，提出修改情况的汇报或者审议结果报告和法律草案修改稿，对涉及的合宪性问题以及重要的不同意见应当在修改情况的汇报或者审议结果报告中予以说明。对有关的专门委员会的审议意见没有采纳的，应当向有关的专门委员会反馈。"},{"i":37,"n":"第三十七条","txt":"专门委员会审议法律案时，应当召开全体会议审议，根据需要，可以要求有关机关、组织派有关负责人说明情况。"},{"i":38,"n":"第三十八条","txt":"专门委员会之间对法律草案的重要问题意见不一致时，应当向委员长会议报告。"},{"i":39,"n":"第三十九条","txt":"列入常务委员会会议议程的法律案，宪法和法律委员会、有关的专门委员会和常务委员会工作机构应当听取各方面的意见。听取意见可以采取座谈会、论证会、听证会等多种形式。"},{"i":40,"n":"第四十条","txt":"列入常务委员会会议议程的法律案，应当在常务委员会会议后将法律草案及其起草、修改的说明等向社会公布，征求意见，但是经委员长会议决定不公布的除外。向社会公布征求意见的时间一般不少于三十日。征求意见的情况应当向社会通报。"},{"i":41,"n":"第四十一条","txt":"列入常务委员会会议议程的法律案，常务委员会工作机构应当收集整理分组审议的意见和各方面提出的意见以及其他有关资料，分送宪法和法律委员会、有关的专门委员会，并根据需要，印发常务委员会会议。"},{"i":42,"n":"第四十二条","txt":"拟提请常务委员会会议审议通过的法律案，在宪法和法律委员会提出审议结果报告前，常务委员会工作机构可以对法律草案中主要制度规范的可行性、法律出台时机、法律实施的社会效果和可能出现的问题等进行评估。评估情况由宪法和法律委员会在审议结果报告中予以说明。"},{"i":43,"n":"第四十三条","txt":"列入常务委员会会议议程的法律案，在交付表决前，提案人要求撤回的，应当说明理由，经委员长会议同意，并向常务委员会报告，对该法律案的审议即行终止。"},{"i":44,"n":"第四十四条","txt":"法律草案修改稿经常务委员会会议审议，由宪法和法律委员会根据常务委员会组成人员的审议意见进行修改，提出法律草案表决稿，由委员长会议提请常务委员会全体会议表决，由常务委员会全体组成人员的过半数通过。"},{"i":45,"n":"第四十五条","txt":"列入常务委员会会议审议的法律案，因各方面对制定该法律的必要性、可行性等重大问题存在较大意见分歧搁置审议满两年的，或者因暂不付表决经过两年没有再次列入常务委员会会议议程审议的，委员长会议可以决定终止审议，并向常务委员会报告；必要时，委员长会议也可以决定延期审议。"},{"i":46,"n":"第四十六条","txt":"对多部法律中涉及同类事项的个别条款进行修改，一并提出法律案的，经委员长会议决定，可以合并表决，也可以分别表决。"},{"i":47,"n":"第四十七条","txt":"常务委员会通过的法律由国家主席签署主席令予以公布。"},{"i":48,"n":"第四十八条","txt":"法律解释权属于全国人民代表大会常务委员会。"},{"i":49,"n":"第四十九条","txt":"国务院、中央军事委员会、国家监察委员会、最高人民法院、最高人民检察院、全国人民代表大会各专门委员会，可以向全国人民代表大会常务委员会提出法律解释要求或者提出相关法律案。"},{"i":50,"n":"第五十条","txt":"常务委员会工作机构研究拟订法律解释草案，由委员长会议决定列入常务委员会会议议程。"},{"i":51,"n":"第五十一条","txt":"法律解释草案经常务委员会会议审议，由宪法和法律委员会根据常务委员会组成人员的审议意见进行审议、修改，提出法律解释草案表决稿。"},{"i":52,"n":"第五十二条","txt":"法律解释草案表决稿由常务委员会全体组成人员的过半数通过，由常务委员会发布公告予以公布。"},{"i":53,"n":"第五十三条","txt":"全国人民代表大会常务委员会的法律解释同法律具有同等效力。"},{"i":54,"n":"第五十四条","txt":"全国人民代表大会及其常务委员会加强对立法工作的组织协调，发挥在立法工作中的主导作用。"},{"i":55,"n":"第五十五条","txt":"全国人民代表大会及其常务委员会坚持科学立法、民主立法、依法立法，通过制定、修改、废止、解释法律和编纂法典等多种形式，增强立法的系统性、整体性、协同性、时效性。"},{"i":56,"n":"第五十六条","txt":"全国人民代表大会常务委员会通过立法规划和年度立法计划、专项立法计划等形式，加强对立法工作的统筹安排。编制立法规划和立法计划，应当认真研究代表议案和建议，广泛征集意见，科学论证评估，根据经济社会发展和民主法治建设的需要，按照加强重点领域、新兴领域、涉外领域立法的要求，确定立法项目。立法规划和立法计划由委员长会议通过并向社会公布。"},{"i":57,"n":"第五十七条","txt":"全国人民代表大会有关的专门委员会、常务委员会工作机构应当提前参与有关方面的法律草案起草工作；综合性、全局性、基础性的重要法律草案，可以由有关的专门委员会或者常务委员会工作机构组织起草。"},{"i":58,"n":"第五十八条","txt":"提出法律案，应当同时提出法律草案文本及其说明，并提供必要的参阅资料。修改法律的，还应当提交修改前后的对照文本。法律草案的说明应当包括制定或者修改法律的必要性、可行性和主要内容，涉及合宪性问题的相关意见以及起草过程中对重大分歧意见的协调处理情况。"},{"i":59,"n":"第五十九条","txt":"向全国人民代表大会及其常务委员会提出的法律案，在列入会议议程前，提案人有权撤回。"},{"i":60,"n":"第六十条","txt":"交付全国人民代表大会及其常务委员会全体会议表决未获得通过的法律案，如果提案人认为必须制定该法律，可以按照法律规定的程序重新提出，由主席团、委员长会议决定是否列入会议议程；其中，未获得全国人民代表大会通过的法律案，应当提请全国人民代表大会审议决定。"},{"i":61,"n":"第六十一条","txt":"法律应当明确规定施行日期。"},{"i":62,"n":"第六十二条","txt":"签署公布法律的主席令载明该法律的制定机关、通过和施行日期。"},{"i":63,"n":"第六十三条","txt":"法律的修改和废止程序，适用本章的有关规定。"},{"i":64,"n":"第六十四条","txt":"法律草案与其他法律相关规定不一致的，提案人应当予以说明并提出处理意见，必要时应当同时提出修改或者废止其他法律相关规定的议案。"},{"i":65,"n":"第六十五条","txt":"法律根据内容需要，可以分编、章、节、条、款、项、目。"},{"i":66,"n":"第六十六条","txt":"法律规定明确要求有关国家机关对专门事项作出配套的具体规定的，有关国家机关应当自法律施行之日起一年内作出规定，法律对配套的具体规定制定期限另有规定的，从其规定。有关国家机关未能在期限内作出配套的具体规定的，应当向全国人民代表大会常务委员会说明情况。"},{"i":67,"n":"第六十七条","txt":"全国人民代表大会有关的专门委员会、常务委员会工作机构可以组织对有关法律或者法律中有关规定进行立法后评估。评估情况应当向常务委员会报告。"},{"i":68,"n":"第六十八条","txt":"全国人民代表大会及其常务委员会作出有关法律问题的决定，适用本法的有关规定。"},{"i":69,"n":"第六十九条","txt":"全国人民代表大会常务委员会工作机构可以对有关具体问题的法律询问进行研究予以答复，并报常务委员会备案。"},{"i":70,"n":"第七十条","txt":"全国人民代表大会常务委员会工作机构根据实际需要设立基层立法联系点，深入听取基层群众和有关方面对法律草案和立法工作的意见。"},{"i":71,"n":"第七十一条","txt":"全国人民代表大会常务委员会工作机构加强立法宣传工作，通过多种形式发布立法信息、介绍情况、回应关切。"},{"i":72,"n":"第七十二条","txt":"国务院根据宪法和法律，制定行政法规。"},{"i":73,"n":"第七十三条","txt":"国务院法制机构应当根据国家总体工作部署拟订国务院年度立法计划，报国务院审批。国务院年度立法计划中的法律项目应当与全国人民代表大会常务委员会的立法规划和立法计划相衔接。国务院法制机构应当及时跟踪了解国务院各部门落实立法计划的情况，加强组织协调和督促指导。"},{"i":74,"n":"第七十四条","txt":"行政法规由国务院有关部门或者国务院法制机构具体负责起草，重要行政管理的法律、行政法规草案由国务院法制机构组织起草。行政法规在起草过程中，应当广泛听取有关机关、组织、人民代表大会代表和社会公众的意见。听取意见可以采取座谈会、论证会、听证会等多种形式。"},{"i":75,"n":"第七十五条","txt":"行政法规起草工作完成后，起草单位应当将草案及其说明、各方面对草案主要问题的不同意见和其他有关资料送国务院法制机构进行审查。"},{"i":76,"n":"第七十六条","txt":"行政法规的决定程序依照中华人民共和国国务院组织法的有关规定办理。"},{"i":77,"n":"第七十七条","txt":"行政法规由总理签署国务院令公布。"},{"i":78,"n":"第七十八条","txt":"行政法规签署公布后，及时在国务院公报和中国政府法制信息网以及在全国范围内发行的报纸上刊载。"},{"i":79,"n":"第七十九条","txt":"国务院可以根据改革发展的需要，决定就行政管理等领域的特定事项，在规定期限和范围内暂时调整或者暂时停止适用行政法规的部分规定。"},{"i":80,"n":"第八十条","txt":"省、自治区、直辖市的人民代表大会及其常务委员会根据本行政区域的具体情况和实际需要，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规。"},{"i":81,"n":"第八十一条","txt":"设区的市的人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以对城乡建设与管理、生态文明建设、历史文化保护、基层治理等方面的事项制定地方性法规，法律对设区的市制定地方性法规的事项另有规定的，从其规定。设区的市的地方性法规须报省、自治区的人民代表大会常务委员会批准后施行。省、自治区的人民代表大会常务委员会对报请批准的地方性法规，应当对其合法性进行审查，认为同宪法、法律、行政法规和本省、自治区的地方性法规不抵触的，应当在四个月内予以批准。"},{"i":82,"n":"第八十二条","txt":"地方性法规可以就下列事项作出规定："},{"i":83,"n":"第八十三条","txt":"省、自治区、直辖市和设区的市、自治州的人民代表大会及其常务委员会根据区域协调发展的需要，可以协同制定地方性法规，在本行政区域或者有关区域内实施。"},{"i":84,"n":"第八十四条","txt":"经济特区所在地的省、市的人民代表大会及其常务委员会根据全国人民代表大会的授权决定，制定法规，在经济特区范围内实施。"},{"i":85,"n":"第八十五条","txt":"民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例，报省、自治区、直辖市的人民代表大会常务委员会批准后生效。"},{"i":86,"n":"第八十六条","txt":"规定本行政区域特别重大事项的地方性法规，应当由人民代表大会通过。"},{"i":87,"n":"第八十七条","txt":"地方性法规案、自治条例和单行条例案的提出、审议和表决程序，根据中华人民共和国地方各级人民代表大会和地方各级人民政府组织法，参照本法第二章第二节、第三节、第五节的规定，由本级人民代表大会规定。"},{"i":88,"n":"第八十八条","txt":"省、自治区、直辖市的人民代表大会制定的地方性法规由大会主席团发布公告予以公布。"},{"i":89,"n":"第八十九条","txt":"地方性法规、自治条例和单行条例公布后，其文本以及草案的说明、审议结果报告等，应当及时在本级人民代表大会常务委员会公报和中国人大网、本地方人民代表大会网站以及在本行政区域范围内发行的报纸上刊载。"},{"i":90,"n":"第九十条","txt":"省、自治区、直辖市和设区的市、自治州的人民代表大会常务委员会根据实际需要设立基层立法联系点，深入听取基层群众和有关方面对地方性法规、自治条例和单行条例草案的意见。"},{"i":91,"n":"第九十一条","txt":"国务院各部、委员会、中国人民银行、审计署和具有行政管理职能的直属机构以及法律规定的机构，可以根据法律和国务院的行政法规、决定、命令，在本部门的权限范围内，制定规章。"},{"i":92,"n":"第九十二条","txt":"涉及两个以上国务院部门职权范围的事项，应当提请国务院制定行政法规或者由国务院有关部门联合制定规章。"},{"i":93,"n":"第九十三条","txt":"省、自治区、直辖市和设区的市、自治州的人民政府，可以根据法律、行政法规和本省、自治区、直辖市的地方性法规，制定规章。"},{"i":94,"n":"第九十四条","txt":"国务院部门规章和地方政府规章的制定程序，参照本法第三章的规定，由国务院规定。"},{"i":95,"n":"第九十五条","txt":"部门规章应当经部务会议或者委员会会议决定。"},{"i":96,"n":"第九十六条","txt":"部门规章由部门首长签署命令予以公布。"},{"i":97,"n":"第九十七条","txt":"部门规章签署公布后，及时在国务院公报或者部门公报和中国政府法制信息网以及在全国范围内发行的报纸上刊载。"},{"i":98,"n":"第九十八条","txt":"宪法具有最高的法律效力，一切法律、行政法规、地方性法规、自治条例和单行条例、规章都不得同宪法相抵触。"},{"i":99,"n":"第九十九条","txt":"法律的效力高于行政法规、地方性法规、规章。"},{"i":100,"n":"第一百条","txt":"地方性法规的效力高于本级和下级地方政府规章。"},{"i":101,"n":"第一百零一条","txt":"自治条例和单行条例依法对法律、行政法规、地方性法规作变通规定的，在本自治地方适用自治条例和单行条例的规定。"},{"i":102,"n":"第一百零二条","txt":"部门规章之间、部门规章与地方政府规章之间具有同等效力，在各自的权限范围内施行。"},{"i":103,"n":"第一百零三条","txt":"同一机关制定的法律、行政法规、地方性法规、自治条例和单行条例、规章，特别规定与一般规定不一致的，适用特别规定；新的规定与旧的规定不一致的，适用新的规定。"},{"i":104,"n":"第一百零四条","txt":"法律、行政法规、地方性法规、自治条例和单行条例、规章不溯及既往，但为了更好地保护公民、法人和其他组织的权利和利益而作的特别规定除外。"},{"i":105,"n":"第一百零五条","txt":"法律之间对同一事项的新的一般规定与旧的特别规定不一致，不能确定如何适用时，由全国人民代表大会常务委员会裁决。"},{"i":106,"n":"第一百零六条","txt":"地方性法规、规章之间不一致时，由有关机关依照下列规定的权限作出裁决："},{"i":107,"n":"第一百零七条","txt":"法律、行政法规、地方性法规、自治条例和单行条例、规章有下列情形之一的，由有关机关依照本法第一百零八条规定的权限予以改变或者撤销："},{"i":108,"n":"第一百零八条","txt":"改变或者撤销法律、行政法规、地方性法规、自治条例和单行条例、规章的权限是："},{"i":109,"n":"第一百零九条","txt":"行政法规、地方性法规、自治条例和单行条例、规章应当在公布后的三十日内依照下列规定报有关机关备案："},{"i":110,"n":"第一百一十条","txt":"国务院、中央军事委员会、国家监察委员会、最高人民法院、最高人民检察院和各省、自治区、直辖市的人民代表大会常务委员会认为行政法规、地方性法规、自治条例和单行条例同宪法或者法律相抵触，或者存在合宪性、合法性问题的，可以向全国人民代表大会常务委员会书面提出进行审查的要求，由全国人民代表大会有关的专门委员会和常务委员会工作机构进行审查、提出意见。"},{"i":111,"n":"第一百一十一条","txt":"全国人民代表大会专门委员会、常务委员会工作机构可以对报送备案的行政法规、地方性法规、自治条例和单行条例等进行主动审查，并可以根据需要进行专项审查。"},{"i":112,"n":"第一百一十二条","txt":"全国人民代表大会专门委员会、常务委员会工作机构在审查中认为行政法规、地方性法规、自治条例和单行条例同宪法或者法律相抵触，或者存在合宪性、合法性问题的，可以向制定机关提出书面审查意见；也可以由宪法和法律委员会与有关的专门委员会、常务委员会工作机构召开联合审查会议，要求制定机关到会说明情况，再向制定机关提出书面审查意见。制定机关应当在两个月内研究提出是否修改或者废止的意见，并向全国人民代表大会宪法和法律委员会、有关的专门委员会或者常务委员会工作机构反馈。"},{"i":113,"n":"第一百一十三条","txt":"全国人民代表大会有关的专门委员会、常务委员会工作机构应当按照规定要求，将审查情况向提出审查建议的国家机关、社会团体、企业事业组织以及公民反馈，并可以向社会公开。"},{"i":114,"n":"第一百一十四条","txt":"其他接受备案的机关对报送备案的地方性法规、自治条例和单行条例、规章的审查程序，按照维护法制统一的原则，由接受备案的机关规定。"},{"i":115,"n":"第一百一十五条","txt":"备案审查机关应当建立健全备案审查衔接联动机制，对应当由其他机关处理的审查要求或者审查建议，及时移送有关机关处理。"},{"i":116,"n":"第一百一十六条","txt":"对法律、行政法规、地方性法规、自治条例和单行条例、规章和其他规范性文件，制定机关根据维护法制统一的原则和改革发展的需要进行清理。"},{"i":117,"n":"第一百一十七条","txt":"中央军事委员会根据宪法和法律，制定军事法规。"},{"i":118,"n":"第一百一十八条","txt":"国家监察委员会根据宪法和法律、全国人民代表大会常务委员会的有关决定，制定监察法规，报全国人民代表大会常务委员会备案。"},{"i":119,"n":"第一百一十九条","txt":"最高人民法院、最高人民检察院作出的属于审判、检察工作中具体应用法律的解释，应当主要针对具体的法律条文，并符合立法的目的、原则和原意。遇有本法第四十八条第二款规定情况的，应当向全国人民代表大会常务委员会提出法律解释的要求或者提出制定、修改有关法律的议案。"},{"i":120,"n":"第一百二十条","txt":"本法自2000年7月1日起施行。"}],"dijietiaoyuechengxufa":[{"i":1,"n":"第一条","txt":"根据中华人民共和国宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国同外国缔结的双边和多边条约、协定和其他具有条约、协定性质的文件。"},{"i":3,"n":"第三条","txt":"中华人民共和国国务院，即中央人民政府，同外国缔结条约和协定。"},{"i":4,"n":"第四条","txt":"中华人民共和国以下列名义同外国缔结条约和协定："},{"i":5,"n":"第五条","txt":"谈判和签署条约、协定的决定程序如下："},{"i":6,"n":"第六条","txt":"谈判和签署条约、协定的代表按照下列程序委派："},{"i":7,"n":"第七条","txt":"条约和重要协定的批准由全国人民代表大会常务委员会决定。"},{"i":8,"n":"第八条","txt":"本法第七条第二款所列范围以外的国务院规定须经核准或者缔约各方议定须经核准的协定和其他具有条约性质的文件签署后，由外交部或者国务院有关部门会同外交部，报请国务院核准。"},{"i":9,"n":"第九条","txt":"无须全国人民代表大会常务委员会决定批准或者国务院核准的协定签署后，除以中华人民共和国政府部门名义缔结的协定由本部门送外交部登记外，其他协定由国务院有关部门报国务院备案。"},{"i":10,"n":"第十条","txt":"缔约双方为使同一条约、协定生效需要履行的国内法律程序不同的，该条约、协定于缔约双方完成各自法律程序并以外交照会方式相互通知后生效。"},{"i":11,"n":"第十一条","txt":"加入多边条约和协定，分别由全国人民代表大会常务委员会或者国务院决定。"},{"i":12,"n":"第十二条","txt":"接受多边条约和协定，由国务院决定。"},{"i":13,"n":"第十三条","txt":"中华人民共和国同外国缔结的双边条约、协定，以中文和缔约另一方的官方文字写成，两种文本同等作准；必要时，可以附加使用缔约双方同意的一种第三国文字，作为同等作准的第三种正式文本或者作为起参考作用的非正式文本；经缔约双方同意，也可以规定对条约、协定的解释发生分歧时，以该第三种文本为准。"},{"i":14,"n":"第十四条","txt":"以中华人民共和国或者中华人民共和国政府名义缔结的双边条约、协定的签字正本，以及经条约、协定的保存国或者国际组织核证无误的多边条约、协定的副本，由外交部保存；以中华人民共和国政府部门名义缔结的双边协定的签字正本，由本部门保存。"},{"i":15,"n":"第十五条","txt":"经全国人民代表大会常务委员会决定批准或者加入的条约和重要协定，由全国人民代表大会常务委员会公报公布。其他条约、协定的公布办法由国务院规定。"},{"i":16,"n":"第十六条","txt":"中华人民共和国缔结的条约和协定由外交部编入《中华人民共和国条约集》。"},{"i":17,"n":"第十七条","txt":"中华人民共和国缔结的条约和协定由外交部按照联合国宪章的有关规定向联合国秘书处登记。"},{"i":18,"n":"第十八条","txt":"中华人民共和国同国际组织缔结条约和协定的程序，依照本法及有关国际组织章程的规定办理。"},{"i":19,"n":"第十九条","txt":"中华人民共和国缔结的条约和协定的修改、废除或者退出的程序，比照各该条约、协定的缔结的程序办理。"},{"i":20,"n":"第二十条","txt":"国务院可以根据本法制定实施条例。"},{"i":21,"n":"第二十一条","txt":"本法自公布之日起施行。"}],"yingxionglieshibaohufa":[{"i":1,"n":"第一条","txt":"为了加强对英雄烈士的保护，维护社会公共利益，传承和弘扬英雄烈士精神、爱国主义精神，培育和践行社会主义核心价值观，激发实现中华民族伟大复兴中国梦的强大精神力量，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家和人民永远尊崇、铭记英雄烈士为国家、人民和民族作出的牺牲和贡献。"},{"i":3,"n":"第三条","txt":"英雄烈士事迹和精神是中华民族的共同历史记忆和社会主义核心价值观的重要体现。"},{"i":4,"n":"第四条","txt":"各级人民政府应当加强对英雄烈士的保护，将宣传、弘扬英雄烈士事迹和精神作为社会主义精神文明建设的重要内容。"},{"i":5,"n":"第五条","txt":"每年9月30日为烈士纪念日，国家在首都北京天安门广场人民英雄纪念碑前举行纪念仪式，缅怀英雄烈士。"},{"i":6,"n":"第六条","txt":"在清明节和重要纪念日，机关、团体、乡村、社区、学校、企业事业单位和军队有关单位根据实际情况，组织开展英雄烈士纪念活动。"},{"i":7,"n":"第七条","txt":"国家建立并保护英雄烈士纪念设施，纪念、缅怀英雄烈士。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将英雄烈士纪念设施建设和保护纳入国民经济和社会发展规划、城乡规划，加强对英雄烈士纪念设施的保护和管理；对具有重要纪念意义、教育意义的英雄烈士纪念设施依照《中华人民共和国文物保护法》的规定，核定公布为文物保护单位。"},{"i":9,"n":"第九条","txt":"英雄烈士纪念设施应当免费向社会开放，供公众瞻仰、悼念英雄烈士，开展纪念教育活动，告慰先烈英灵。"},{"i":10,"n":"第十条","txt":"英雄烈士纪念设施保护单位应当健全服务和管理工作规范，方便瞻仰、悼念英雄烈士，保持英雄烈士纪念设施庄严、肃穆、清净的环境和氛围。"},{"i":11,"n":"第十一条","txt":"安葬英雄烈士时，县级以上人民政府、军队有关部门应当举行庄严、肃穆、文明、节俭的送迎、安葬仪式。"},{"i":12,"n":"第十二条","txt":"国家建立健全英雄烈士祭扫制度和礼仪规范，引导公民庄严有序地开展祭扫活动。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府有关部门应当引导公民通过瞻仰英雄烈士纪念设施、集体宣誓、网上祭奠等形式，铭记英雄烈士的事迹，传承和弘扬英雄烈士的精神。"},{"i":14,"n":"第十四条","txt":"英雄烈士在国外安葬的，中华人民共和国驻该国外交、领事代表机构应当结合驻在国实际情况组织开展祭扫活动。"},{"i":15,"n":"第十五条","txt":"国家鼓励和支持开展对英雄烈士事迹和精神的研究，以辩证唯物主义和历史唯物主义为指导认识和记述历史。"},{"i":16,"n":"第十六条","txt":"各级人民政府、军队有关部门应当加强对英雄烈士遗物、史料的收集、保护和陈列展示工作，组织开展英雄烈士史料的研究、编纂和宣传工作。"},{"i":17,"n":"第十七条","txt":"教育行政部门应当以青少年学生为重点，将英雄烈士事迹和精神的宣传教育纳入国民教育体系。"},{"i":18,"n":"第十八条","txt":"文化、新闻出版、广播电视、电影、网信等部门应当鼓励和支持以英雄烈士事迹为题材、弘扬英雄烈士精神的优秀文学艺术作品、广播电视节目以及出版物的创作生产和宣传推广。"},{"i":19,"n":"第十九条","txt":"广播电台、电视台、报刊出版单位、互联网信息服务提供者，应当通过播放或者刊登英雄烈士题材作品、发布公益广告、开设专栏等方式，广泛宣传英雄烈士事迹和精神。"},{"i":20,"n":"第二十条","txt":"国家鼓励和支持自然人、法人和非法人组织以捐赠财产、义务宣讲英雄烈士事迹和精神、帮扶英雄烈士遗属等公益活动的方式，参与英雄烈士保护工作。"},{"i":21,"n":"第二十一条","txt":"国家实行英雄烈士抚恤优待制度。英雄烈士遗属按照国家规定享受教育、就业、养老、住房、医疗等方面的优待。抚恤优待水平应当与国民经济和社会发展相适应并逐步提高。"},{"i":22,"n":"第二十二条","txt":"禁止歪曲、丑化、亵渎、否定英雄烈士事迹和精神。"},{"i":23,"n":"第二十三条","txt":"网信和电信、公安等有关部门在对网络信息进行依法监督管理工作中，发现发布或者传输以侮辱、诽谤或者其他方式侵害英雄烈士的姓名、肖像、名誉、荣誉的信息的，应当要求网络运营者停止传输，采取消除等处置措施和其他必要措施；对来源于中华人民共和国境外的上述信息，应当通知有关机构采取技术措施和其他必要措施阻断传播。"},{"i":24,"n":"第二十四条","txt":"任何组织和个人有权对侵害英雄烈士合法权益和其他违反本法规定的行为，向负责英雄烈士保护工作的部门、网信、公安等有关部门举报，接到举报的部门应当依法及时处理。"},{"i":25,"n":"第二十五条","txt":"对侵害英雄烈士的姓名、肖像、名誉、荣誉的行为，英雄烈士的近亲属可以依法向人民法院提起诉讼。"},{"i":26,"n":"第二十六条","txt":"以侮辱、诽谤或者其他方式侵害英雄烈士的姓名、肖像、名誉、荣誉，损害社会公共利益的，依法承担民事责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"在英雄烈士纪念设施保护范围内从事有损纪念英雄烈士环境和氛围的活动的，纪念设施保护单位应当及时劝阻；不听劝阻的，由县级以上地方人民政府负责英雄烈士保护工作的部门、文物主管部门按照职责规定给予批评教育，责令改正；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":28,"n":"第二十八条","txt":"侵占、破坏、污损英雄烈士纪念设施的，由县级以上人民政府负责英雄烈士保护工作的部门责令改正；造成损失的，依法承担民事责任；被侵占、破坏、污损的纪念设施属于文物保护单位的，依照《中华人民共和国文物保护法》的规定处罚；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府有关部门及其工作人员在英雄烈士保护工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本法自2018年5月1日起施行。"}],"ludiguojiefa":[{"i":1,"n":"第一条","txt":"为了规范和加强陆地国界工作，保障陆地国界及边境的安全稳定，促进我国与陆地邻国睦邻友好和交流合作，维护国家主权、安全和领土完整，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国陆地国界的划定和勘定，陆地国界及边境的防卫、管理和建设，陆地国界事务的国际合作等，适用本法。"},{"i":3,"n":"第三条","txt":"陆地国界是指划分中华人民共和国与陆地邻国接壤的领陆和内水的界限。陆地国界垂直划分中华人民共和国与陆地邻国的领空和底土。"},{"i":4,"n":"第四条","txt":"中华人民共和国的主权和领土完整神圣不可侵犯。"},{"i":5,"n":"第五条","txt":"国家对陆地国界工作实行统一的领导。"},{"i":6,"n":"第六条","txt":"外交部负责陆地国界涉外事务，参与陆地国界管理相关工作，牵头开展对外谈判、缔约、履约及国际合作，处理需要通过外交途径解决的问题，组织开展国界线和界标维护管理。"},{"i":7,"n":"第七条","txt":"在中央军事委员会领导下，有关军事机关组织、指导、协调陆地国界及边境的防卫管控、维护社会稳定、处置突发事件、边防合作及相关工作。"},{"i":8,"n":"第八条","txt":"边境省、自治区的各级人民代表大会及其常务委员会在本行政区域内，保证有关陆地国界及边境的法律法规的遵守和执行。"},{"i":9,"n":"第九条","txt":"军地有关部门、单位依托有关统筹协调机构，合力推进强边固防，组织开展边防防卫管控、边防基础设施建设与维护管理等工作，共同维护陆地国界及边境的安全稳定与正常秩序。"},{"i":10,"n":"第十条","txt":"国家采取有效措施，加强边防建设，支持边境经济社会发展和对外开放，推进固边兴边富民行动，提高边境公共服务和基础设施建设水平，改善边境生产生活条件，鼓励和支持边民在边境生产生活，促进边防建设与边境经济社会协调发展。"},{"i":11,"n":"第十一条","txt":"国家加强陆地国界宣传教育，铸牢中华民族共同体意识，弘扬中华民族捍卫祖国统一和领土完整的精神，增强公民的国家观念和国土安全意识，构筑中华民族共有精神家园。"},{"i":12,"n":"第十二条","txt":"国家保障陆地国界工作经费。"},{"i":13,"n":"第十三条","txt":"公民和组织应当维护陆地国界及边境安全稳定，保护界标和边防基础设施，配合、协助开展陆地国界相关工作。"},{"i":14,"n":"第十四条","txt":"中华人民共和国遵守同外国缔结或者共同参加的有关陆地国界事务的条约。"},{"i":15,"n":"第十五条","txt":"国家坚持平等互信、友好协商的原则，通过谈判与陆地邻国处理陆地国界及相关事务，妥善解决争端和历史遗留的边界问题。"},{"i":16,"n":"第十六条","txt":"国家与陆地邻国通过谈判缔结划定陆地国界的条约，规定陆地国界的走向和位置。"},{"i":17,"n":"第十七条","txt":"国家与陆地邻国根据划界条约，实地勘定陆地国界并缔结勘界条约。"},{"i":18,"n":"第十八条","txt":"为保持国界线清晰稳定，国家与有关陆地邻国开展陆地国界联合检查，缔结联合检查条约。"},{"i":19,"n":"第十九条","txt":"勘定陆地国界依据的自然地理环境发生无法恢复原状的重大变化时，国家可与陆地邻国协商，重新勘定陆地国界。"},{"i":20,"n":"第二十条","txt":"国家设置界标在实地标示陆地国界。"},{"i":21,"n":"第二十一条","txt":"陆地国界的划定、勘定、联合检查和设置界标等具体工作，由外交部会同国务院有关部门、有关军事机关和有关边境省、自治区依法组织实施。"},{"i":22,"n":"第二十二条","txt":"中国人民解放军、中国人民武装警察部队应当在边境开展边防执勤、管控，组织演训和勘察等活动，坚决防范、制止和打击入侵、蚕食、渗透、挑衅等行为，守卫陆地国界，维护边境安全稳定。"},{"i":23,"n":"第二十三条","txt":"边境省、自治区的各级人民政府统筹资源配置，加强维护国界安全的群防队伍建设，支持和配合边防执勤、管控工作。"},{"i":24,"n":"第二十四条","txt":"国家根据边防管控需要，可以在靠近陆地国界的特定区域划定边境禁区并设置警示标志，禁止无关人员进入。"},{"i":25,"n":"第二十五条","txt":"国家根据陆地国界及边境防卫需要，可以在陆地国界内侧建设拦阻、交通、通信、监控、警戒、防卫及辅助设施等边防基础设施，也可以与陆地邻国协商后在陆地国界线上建设拦阻设施。"},{"i":26,"n":"第二十六条","txt":"国家对陆地国界及边境的管理和相关建设实行统筹协调、分工负责、依法管理。"},{"i":27,"n":"第二十七条","txt":"陆地国界及边境管理应当保障陆地国界清晰和安全稳定。"},{"i":28,"n":"第二十八条","txt":"依照本法规定在边境地区设立经济、贸易、旅游等跨境合作区域或者开展跨境合作活动，应当符合边防管控要求，不得危害边防安全。"},{"i":29,"n":"第二十九条","txt":"在陆地国界及边境管理中遇有重要情况和重大问题，有关地方人民政府、军事机关应当立即按照规定向上级机关报告。"},{"i":30,"n":"第三十条","txt":"边境省、自治区可以根据本行政区域的具体情况和实际需要制定地方性法规、地方政府规章，对陆地国界及边境管理执行中的问题作出规定。"},{"i":31,"n":"第三十一条","txt":"国家可以与有关陆地邻国缔结条约，就陆地国界及边境管理制度作出规定。条约对陆地国界及边境管理制度另有规定的，按照条约的规定执行。"},{"i":32,"n":"第三十二条","txt":"界标和边防基础设施受法律保护。"},{"i":33,"n":"第三十三条","txt":"为保持陆地国界清晰可视，国家可以在陆地国界内侧开辟和清理通视道。"},{"i":34,"n":"第三十四条","txt":"国务院有关部门和边境省、自治区的各级人民政府应当采取措施维护界河（江、湖）走向稳定，并依照有关条约保护和合理利用边界水。"},{"i":35,"n":"第三十五条","txt":"国家经与陆地邻国协商，可以在靠近陆地国界的适当地点设立边境口岸。"},{"i":36,"n":"第三十六条","txt":"国务院有关部门经与陆地邻国相关部门协商或者根据照顾边民往来、维护边境安全稳定的需要，可以设立边民通道并予以规范管理。"},{"i":37,"n":"第三十七条","txt":"人员、交通运输工具、货物、物品等应当依照相关法律法规通过陆地国界出境入境，并接受有关主管部门的检查、检疫和监管。"},{"i":38,"n":"第三十八条","txt":"禁止任何个人非法越界。"},{"i":39,"n":"第三十九条","txt":"航空器飞越陆地国界，应当经有关主管机关批准并且遵守我国法律法规规定。未经批准飞越陆地国界的，有关主管机关应当采取必要措施进行处置。"},{"i":40,"n":"第四十条","txt":"任何组织或者个人未经有关主管部门批准不得在陆地国界附近修建永久性建筑物。"},{"i":41,"n":"第四十一条","txt":"任何组织或者个人不得在陆地国界附近通过声音、光照、展示标示物、投掷或者传递物品、放置漂流物或者空飘物等方式从事危害国家安全或者影响我国与邻国友好关系的活动。"},{"i":42,"n":"第四十二条","txt":"国家根据边防管理需要可以划定边境管理区。边境管理区人员通行、居住依照国家有关规定实行专门管理措施。"},{"i":43,"n":"第四十三条","txt":"国家支持沿边城镇建设，健全沿边城镇体系，完善边境城镇功能，强化支撑能力建设。"},{"i":44,"n":"第四十四条","txt":"国务院有关部门和边境省、自治区人民政府依照有关规定，可以建设或者批准设立边民互市贸易区（点）、边境经济合作区等区域。"},{"i":45,"n":"第四十五条","txt":"国务院有关部门和边境省、自治区的各级人民政府应当采取措施保护边境生态环境，防止生态破坏，防治大气、水、土壤和其他污染。"},{"i":46,"n":"第四十六条","txt":"国务院有关部门和边境省、自治区的各级人民政府应当采取措施预防传染病、动植物疫情、外来物种入侵以及洪涝、火灾等从陆地国界传入或者在边境传播、蔓延。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，国家可以封控边境、关闭口岸，并依照有关法律法规采取其他紧急措施："},{"i":48,"n":"第四十八条","txt":"国家按照平等互利原则与陆地邻国开展国际合作，处理陆地国界事务，推进安全合作，深化互利共赢。"},{"i":49,"n":"第四十九条","txt":"国家可以与有关陆地邻国协商建立边界联合委员会机制，指导和协调有关国际合作，执行有关条约，协商并处理与陆地国界管理有关的重要事项。"},{"i":50,"n":"第五十条","txt":"有关军事机关可以与陆地邻国相关部门建立边防合作机制，沟通协商边防交往合作中的重大事项与问题，通过与陆地邻国相关边防机构建立边防会谈会晤机制，交涉处理边防有关事务，巩固和发展睦邻友好关系，共同维护陆地国界的安全稳定。"},{"i":51,"n":"第五十一条","txt":"国家可以与有关陆地邻国在相应国界地段协商建立边界（边防）代表机制，由代表、副代表和相关工作人员组成，通过会谈、会晤和联合调查等方式处理边界事件、日常纠纷等问题。"},{"i":52,"n":"第五十二条","txt":"公安、海关、移民等部门可以与陆地邻国相关部门建立合作机制，交流信息，开展执法合作，共同防范和打击跨界违法犯罪活动。"},{"i":53,"n":"第五十三条","txt":"国家有关主管机关和有关军事机关可以与陆地邻国相关部门开展合作，共同打击恐怖主义、分裂主义和极端主义活动。"},{"i":54,"n":"第五十四条","txt":"国家提升沿边对外开放便利化水平，优化边境地区营商环境；经与陆地邻国协商，可以在双方接壤区域设立跨境经济合作区、跨境旅游合作区、生态保护区等区域。"},{"i":55,"n":"第五十五条","txt":"边境省、自治区的县级以上各级人民政府依照国家有关规定，可以与陆地邻国相应行政区域地方政府开展经济、旅游、文化、体育、抢险救灾和生态环境等领域合作。"},{"i":56,"n":"第五十六条","txt":"国务院有关部门可以与陆地邻国相关部门在口岸建设和管理、自然资源利用、生态环境保护、疫情防控、应急管理等领域开展合作，建立相互通报、信息共享、技术与人才交流等合作机制。"},{"i":57,"n":"第五十七条","txt":"有违反本法第三十二条第二款行为的，由公安机关依照《中华人民共和国治安管理处罚法》、《中华人民共和国军事设施保护法》有关规定处罚。损毁界标、边防基础设施的，应当责令行为人赔偿损失。"},{"i":58,"n":"第五十八条","txt":"有违反本法第三十七条、第三十八条第一款或者第三十九条规定行为的，由有关部门依照相关法律法规，按照职责分工处罚。"},{"i":59,"n":"第五十九条","txt":"国家机关及其工作人员在陆地国界工作中不履行法定职责，泄露国家秘密或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":60,"n":"第六十条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"界标是指竖立在陆地国界上或者陆地国界两侧，在实地标示陆地国界走向，且其地理坐标已测定并记载于勘界条约或者联合检查条约中的标志，包括基本界标、辅助界标、导标和浮标等。"},{"i":62,"n":"第六十二条","txt":"本法自2022年1月1日起施行。"}],"jihuiyouxingshiweifa":[{"i":1,"n":"第一条","txt":"为了保障公民依法行使集会、游行、示威的权利，维护社会安定和公共秩序，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内举行集会、游行、示威，均适用本法。"},{"i":3,"n":"第三条","txt":"公民行使集会、游行、示威的权利，各级人民政府应当依照本法规定，予以保障。"},{"i":4,"n":"第四条","txt":"公民在行使集会、游行、示威的权利的时候，必须遵守宪法和法律，不得反对宪法所确定的基本原则，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。"},{"i":5,"n":"第五条","txt":"集会、游行、示威应当和平地进行，不得携带武器、管制刀具和爆炸物，不得使用暴力或者煽动使用暴力。"},{"i":6,"n":"第六条","txt":"集会、游行、示威的主管机关，是集会、游行、示威举行地的市、县公安局、城市公安分局；游行、示威路线经过两个以上区、县的，主管机关为所经过区、县的公安机关的共同上一级公安机关。"},{"i":7,"n":"第七条","txt":"举行集会、游行、示威，必须依照本法规定向主管机关提出申请并获得许可。"},{"i":8,"n":"第八条","txt":"举行集会、游行、示威，必须有负责人。"},{"i":9,"n":"第九条","txt":"主管机关接到集会、游行、示威申请书后，应当在申请举行日期的二日前，将许可或者不许可的决定书面通知其负责人。不许可的，应当说明理由。逾期不通知的，视为许可。"},{"i":10,"n":"第十条","txt":"申请举行集会、游行、示威要求解决具体问题的，主管机关接到申请书后，可以通知有关机关或者单位同集会、游行、示威的负责人协商解决问题，并可以将申请举行的时间推迟五日。"},{"i":11,"n":"第十一条","txt":"主管机关认为按照申请的时间、地点、路线举行集会、游行、示威，将对交通秩序和社会秩序造成严重影响的，在决定许可时或者决定许可后，可以变更举行集会、游行、示威的时间、地点、路线，并及时通知其负责人。"},{"i":12,"n":"第十二条","txt":"申请举行的集会、游行、示威，有下列情形之一的，不予许可："},{"i":13,"n":"第十三条","txt":"集会、游行、示威的负责人对主管机关不许可的决定不服的，可以自接到决定通知之日起三日内，向同级人民政府申请复议，人民政府应当自接到申请复议书之日起三日内作出决定。"},{"i":14,"n":"第十四条","txt":"集会、游行、示威的负责人在提出申请后接到主管机关通知前，可以撤回申请；接到主管机关许可的通知后，决定不举行集会、游行、示威的，应当及时告知主管机关，参加人已经集合的，应当负责解散。"},{"i":15,"n":"第十五条","txt":"公民不得在其居住地以外的城市发动、组织、参加当地公民的集会、游行、示威。"},{"i":16,"n":"第十六条","txt":"国家机关工作人员不得组织或者参加违背有关法律、法规规定的国家机关工作人员职责、义务的集会、游行、示威。"},{"i":17,"n":"第十七条","txt":"以国家机关、社会团体、企业事业组织的名义组织或者参加集会、游行、示威，必须经本单位负责人批准。"},{"i":18,"n":"第十八条","txt":"对于依法举行的集会、游行、示威，主管机关应当派出人民警察维持交通秩序和社会秩序，保障集会、游行、示威的顺利进行。"},{"i":19,"n":"第十九条","txt":"依法举行的集会、游行、示威，任何人不得以暴力、胁迫或者其他非法手段进行扰乱、冲击和破坏。"},{"i":20,"n":"第二十条","txt":"为了保障依法举行的游行的行进，负责维持交通秩序的人民警察可以临时变通执行交通规则的有关规定。"},{"i":21,"n":"第二十一条","txt":"游行在行进中遇有不可预料的情况，不能按照许可的路线行进时，人民警察现场负责人有权改变游行队伍的行进路线。"},{"i":22,"n":"第二十二条","txt":"集会、游行、示威在国家机关、军事机关、广播电台、电视台、外国驻华使馆领馆等单位所在地举行或者经过的，主管机关为了维持秩序，可以在附近设置临时警戒线，未经人民警察许可，不得逾越。"},{"i":23,"n":"第二十三条","txt":"在下列场所周边距离十米至三百米内，不得举行集会、游行、示威，经国务院或者省、自治区、直辖市的人民政府批准的除外："},{"i":24,"n":"第二十四条","txt":"举行集会、游行、示威的时间限于早六时至晚十时，经当地人民政府决定或者批准的除外。"},{"i":25,"n":"第二十五条","txt":"集会、游行、示威应当按照许可的目的、方式、标语、口号、起止时间、地点、路线及其他事项进行。"},{"i":26,"n":"第二十六条","txt":"举行集会、游行、示威，不得违反治安管理法规，不得进行犯罪活动或者煽动犯罪。"},{"i":27,"n":"第二十七条","txt":"举行集会、游行、示威，有下列情形之一的，人民警察应当予以制止："},{"i":28,"n":"第二十八条","txt":"举行集会、游行、示威，有违反治安管理行为的，依照治安管理处罚法有关规定予以处罚。"},{"i":29,"n":"第二十九条","txt":"举行集会、游行、示威，有犯罪行为的，依照刑法有关规定追究刑事责任。"},{"i":30,"n":"第三十条","txt":"扰乱、冲击或者以其他方法破坏依法举行的集会、游行、示威的，公安机关可以处以警告或者十五日以下拘留；情节严重，构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"当事人对公安机关依照本法第二十八条第二款或者第三十条的规定给予的拘留处罚决定不服的，可以自接到处罚决定通知之日起五日内，向上一级公安机关提出申诉，上一级公安机关应当自接到申诉之日起五日内作出裁决；对上一级公安机关裁决不服的，可以自接到裁决通知之日起五日内，向人民法院提起诉讼。"},{"i":32,"n":"第三十二条","txt":"在举行集会、游行、示威过程中，破坏公私财物或者侵害他人身体造成伤亡的，除依照刑法或者治安管理处罚法的有关规定可以予以处罚外，还应当依法承担赔偿责任。"},{"i":33,"n":"第三十三条","txt":"公民在本人居住地以外的城市发动、组织当地公民的集会、游行、示威的，公安机关有权予以拘留或者强行遣回原地。"},{"i":34,"n":"第三十四条","txt":"外国人在中国境内举行集会、游行、示威，适用本法规定。"},{"i":35,"n":"第三十五条","txt":"国务院公安部门可以根据本法制定实施条例，报国务院批准施行。"},{"i":36,"n":"第三十六条","txt":"本法自公布之日起施行。"}],"lingshitequanyuhuomiantiaoli":[{"i":1,"n":"第一条","txt":"为确定外国驻中国领馆和领馆成员的领事特权与豁免，便于外国驻中国领馆在领区内代表其国家有效地执行职务，制定本条例。"},{"i":2,"n":"第二条","txt":"领事官员应当是具有派遣国国籍的人。如果委派具有中国或者第三国国籍的人或者派遣国在中国永久居留的人为领事官员，必须征得中国主管机关的同意。中国主管机关可以随时撤销此项同意。"},{"i":3,"n":"第三条","txt":"领馆及其馆长有权在领馆馆舍、馆长寓所和馆长执行职务所乘用的交通工具上，使用派遣国国旗或者国徽。"},{"i":4,"n":"第四条","txt":"领馆馆舍不受侵犯。中国国家工作人员进入领馆馆舍，须经领馆馆长或者派遣国使馆馆长或者他们两人中一人授权的人员同意。遇有火灾或者其他灾害须迅速采取保护行动时，可以推定领馆馆长已经同意。中国有关机关应当采取适当措施保护领馆馆舍免受侵犯或者损害。"},{"i":5,"n":"第五条","txt":"领馆馆舍和馆长寓所免纳捐税，但为其提供特定服务所收的费用不在此限。"},{"i":6,"n":"第六条","txt":"领馆的档案和文件不受侵犯。"},{"i":7,"n":"第七条","txt":"领馆成员在中国境内有行动和旅行的自由，但中国政府规定禁止或者限制进入的区域除外。"},{"i":8,"n":"第八条","txt":"领馆为公务目的可以同派遣国政府以及派遣国使馆和其他领馆自由通讯。通讯可以采用一切适当方法，包括外交信使或者领事信使、外交邮袋或者领事邮袋和明码、密码电信在内。"},{"i":9,"n":"第九条","txt":"领馆设置和使用无线电收发信机，必须经中国政府同意。领馆运进上述设备，按照中国政府的有关规定办理。"},{"i":10,"n":"第十条","txt":"领事邮袋不得开拆或者扣留。"},{"i":11,"n":"第十一条","txt":"领事信使必须是具有派遣国国籍的人，并且不得是在中国永久居留的。领事信使必须持有派遣国主管机关出具的信使证明书。领事信使人身不受侵犯，不受逮捕或者拘留。"},{"i":12,"n":"第十二条","txt":"领事官员人身不受侵犯。中国有关机关应当采取适当措施，防止领事官员的人身自由和尊严受到侵犯。"},{"i":13,"n":"第十三条","txt":"领事官员的寓所不受侵犯。"},{"i":14,"n":"第十四条","txt":"领事官员和领馆行政技术人员执行职务的行为享有司法和行政管辖豁免。领事官员执行职务以外的行为的管辖豁免，按照中国与外国签订的双边条约、协定或者根据对等原则办理。"},{"i":15,"n":"第十五条","txt":"领馆成员可以被要求在司法或者行政程序中到场作证，但没有义务就其执行职务所涉及事项作证。领馆成员有权拒绝以鉴定人身份就派遣国的法律提出证词。"},{"i":16,"n":"第十六条","txt":"本条例规定的有关人员所享有的管辖豁免可以由派遣国政府明确表示放弃。"},{"i":17,"n":"第十七条","txt":"领事官员和领馆行政技术人员免纳捐税，但下列各项除外："},{"i":18,"n":"第十八条","txt":"领馆成员免除一切个人和公共劳务以及军事义务。"},{"i":19,"n":"第十九条","txt":"领馆运进的公务用品，领事官员运进的自用物品和领馆行政技术人员到任后半年内运进的自用物品包括安家物品，按照中国政府的有关规定免纳关税和其他捐税，但保管、运输及类似服务费用除外。"},{"i":20,"n":"第二十条","txt":"领馆和领馆成员携带自用的枪支、子弹入出境，必须经中国政府批准，并且按照中国政府的有关规定办理。"},{"i":21,"n":"第二十一条","txt":"与领事官员、领馆行政技术人员、领馆服务人员共同生活的配偶及未成年子女，分别享有领事官员、领馆行政技术人员、领馆服务人员根据本条例第七条、第十七条、第十八条、第十九条的规定所享有的特权与豁免，但身为中国公民或者在中国永久居留的外国人除外。"},{"i":22,"n":"第二十二条","txt":"领事官员如果是中国公民或者在中国永久居留的外国人，仅就其执行职务的行为，享有本条例规定的特权与豁免。"},{"i":23,"n":"第二十三条","txt":"下列人员在中国过境或者逗留期间享有所必需的豁免和不受侵犯："},{"i":24,"n":"第二十四条","txt":"享有领事特权与豁免的人员："},{"i":25,"n":"第二十五条","txt":"领事官员不得在中国境内为私人利益从事任何职务范围以外的职业或者商业活动。"},{"i":26,"n":"第二十六条","txt":"如果外国给予中国驻该国领馆、领馆成员以及途经或者临时去该国的中国驻第三国领事官员的领事特权与豁免，不同于中国给予该国驻中国领馆、领馆成员以及途经或者临时来中国的该国驻第三国领事官员的领事特权与豁免，中国政府根据对等原则，可以给予该国驻中国领馆、领馆成员以及途经或者临时来中国的该国驻第三国领事官员以相应的领事特权与豁免。"},{"i":27,"n":"第二十七条","txt":"中国缔结或者参加的国际条约对领事特权与豁免另有规定的，按照国际条约的规定办理，但中国声明保留的条款除外。"},{"i":28,"n":"第二十八条","txt":"本条例中下列用语的含义是："},{"i":29,"n":"第二十九条","txt":"本条例自公布之日起施行。"}],"linghaijipilianqufa":[{"i":1,"n":"第一条","txt":"为行使中华人民共和国对领海的主权和对毗连区的管制权，维护国家安全和海洋权益，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国领海为邻接中华人民共和国陆地领土和内水的一带海域。"},{"i":3,"n":"第三条","txt":"中华人民共和国领海的宽度从领海基线量起为十二海里。"},{"i":4,"n":"第四条","txt":"中华人民共和国毗连区为领海以外邻接领海的一带海域。毗连区的宽度为十二海里。"},{"i":5,"n":"第五条","txt":"中华人民共和国对领海的主权及于领海上空、领海的海床及底土。"},{"i":6,"n":"第六条","txt":"外国非军用船舶，享有依法无害通过中华人民共和国领海的权利。"},{"i":7,"n":"第七条","txt":"外国潜水艇和其他潜水器通过中华人民共和国领海，必须在海面航行，并展示其旗帜。"},{"i":8,"n":"第八条","txt":"外国船舶通过中华人民共和国领海，必须遵守中华人民共和国法律、法规，不得损害中华人民共和国的和平、安全和良好秩序。"},{"i":9,"n":"第九条","txt":"为维护航行安全和其他特殊需要，中华人民共和国政府可以要求通过中华人民共和国领海的外国船舶使用指定的航道或者依照规定的分道通航制航行，具体办法由中华人民共和国政府或者其有关主管部门公布。"},{"i":10,"n":"第十条","txt":"外国军用船舶或者用于非商业目的的外国政府船舶在通过中华人民共和国领海时，违反中华人民共和国法律、法规的，中华人民共和国有关主管机关有权令其立即离开领海，对所造成的损失或者损害，船旗国应当负国际责任。"},{"i":11,"n":"第十一条","txt":"任何国际组织、外国的组织或者个人，在中华人民共和国领海内进行科学研究、海洋作业等活动，须经中华人民共和国政府或者其有关主管部门批准，遵守中华人民共和国法律、法规。"},{"i":12,"n":"第十二条","txt":"外国航空器只有根据该国政府与中华人民共和国政府签订的协定、协议，或者经中华人民共和国政府或者其授权的机关批准或者接受，方可进入中华人民共和国领海上空。"},{"i":13,"n":"第十三条","txt":"中华人民共和国有权在毗连区内，为防止和惩处在其陆地领土、内水或者领海内违反有关安全、海关、财政、卫生或者入境出境管理的法律、法规的行为行使管制权。"},{"i":14,"n":"第十四条","txt":"中华人民共和国有关主管机关有充分理由认为外国船舶违反中华人民共和国法律、法规时，可以对该外国船舶行使紧追权。"},{"i":15,"n":"第十五条","txt":"中华人民共和国领海基线由中华人民共和国政府公布。"},{"i":16,"n":"第十六条","txt":"中华人民共和国政府依据本法制定有关规定。"},{"i":17,"n":"第十七条","txt":"本法自公布之日起施行。"}],"xianggangtebiexingzhengqujibenfa":[{"i":1,"n":"第一条","txt":"香港特别行政区是中华人民共和国不可分离的部分。"},{"i":2,"n":"第二条","txt":"全国人民代表大会授权香港特别行政区依照本法的规定实行高度自治，享有行政管理权、立法权、独立的司法权和终审权。"},{"i":3,"n":"第三条","txt":"香港特别行政区的行政机关和立法机关由香港永久性居民依照本法有关规定组成。"},{"i":4,"n":"第四条","txt":"香港特别行政区依法保障香港特别行政区居民和其他人的权利和自由。"},{"i":5,"n":"第五条","txt":"香港特别行政区不实行社会主义制度和政策，保持原有的资本主义制度和生活方式，五十年不变。"},{"i":6,"n":"第六条","txt":"香港特别行政区依法保护私有财产权。"},{"i":7,"n":"第七条","txt":"香港特别行政区境内的土地和自然资源属于国家所有，由香港特别行政区政府负责管理、使用、开发、出租或批给个人、法人或团体使用或开发，其收入全归香港特别行政区政府支配。"},{"i":8,"n":"第八条","txt":"香港原有法律，即普通法、衡平法、条例、附属立法和习惯法，除同本法相抵触或经香港特别行政区的立法机关作出修改者外，予以保留。"},{"i":9,"n":"第九条","txt":"香港特别行政区的行政机关、立法机关和司法机关，除使用中文外，还可使用英文，英文也是正式语文。"},{"i":10,"n":"第十条","txt":"香港特别行政区除悬挂中华人民共和国国旗和国徽外，还可使用香港特别行政区区旗和区徽。"},{"i":11,"n":"第十一条","txt":"根据中华人民共和国宪法第三十一条，香港特别行政区的制度和政策，包括社会、经济制度，有关保障居民的基本权利和自由的制度，行政管理、立法和司法方面的制度，以及有关政策，均以本法的规定为依据。"},{"i":12,"n":"第十二条","txt":"香港特别行政区是中华人民共和国的一个享有高度自治权的地方行政区域，直辖于中央人民政府。"},{"i":13,"n":"第十三条","txt":"中央人民政府负责管理与香港特别行政区有关的外交事务。"},{"i":14,"n":"第十四条","txt":"中央人民政府负责管理香港特别行政区的防务。"},{"i":15,"n":"第十五条","txt":"中央人民政府依照本法第四章的规定任命香港特别行政区行政长官和行政机关的主要官员。"},{"i":16,"n":"第十六条","txt":"香港特别行政区享有行政管理权，依照本法的有关规定自行处理香港特别行政区的行政事务。"},{"i":17,"n":"第十七条","txt":"香港特别行政区享有立法权。"},{"i":18,"n":"第十八条","txt":"在香港特别行政区实行的法律为本法以及本法第八条规定的香港原有法律和香港特别行政区立法机关制定的法律。"},{"i":19,"n":"第十九条","txt":"香港特别行政区享有独立的司法权和终审权。"},{"i":20,"n":"第二十条","txt":"香港特别行政区可享有全国人民代表大会和全国人民代表大会常务委员会及中央人民政府授予的其他权力。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区居民中的中国公民依法参与国家事务的管理。"},{"i":22,"n":"第二十二条","txt":"中央人民政府所属各部门、各省、自治区、直辖市均不得干预香港特别行政区根据本法自行管理的事务。"},{"i":23,"n":"第二十三条","txt":"香港特别行政区应自行立法禁止任何叛国、分裂国家、煽动叛乱、颠覆中央人民政府及窃取国家机密的行为，禁止外国的政治性组织或团体在香港特别行政区进行政治活动，禁止香港特别行政区的政治性组织或团体与外国的政治性组织或团体建立联系。"},{"i":24,"n":"第二十四条","txt":"香港特别行政区居民，简称香港居民，包括永久性居民和非永久性居民。"},{"i":25,"n":"第二十五条","txt":"香港居民在法律面前一律平等。"},{"i":26,"n":"第二十六条","txt":"香港特别行政区永久性居民依法享有选举权和被选举权。"},{"i":27,"n":"第二十七条","txt":"香港居民享有言论、新闻、出版的自由，结社、集会、游行、示威的自由，组织和参加工会、罢工的权利和自由。"},{"i":28,"n":"第二十八条","txt":"香港居民的人身自由不受侵犯。"},{"i":29,"n":"第二十九条","txt":"香港居民的住宅和其他房屋不受侵犯。禁止任意或非法搜查、侵入居民的住宅和其他房屋。"},{"i":30,"n":"第三十条","txt":"香港居民的通讯自由和通讯秘密受法律的保护。除因公共安全和追查刑事犯罪的需要，由有关机关依照法律程序对通讯进行检查外，任何部门或个人不得以任何理由侵犯居民的通讯自由和通讯秘密。"},{"i":31,"n":"第三十一条","txt":"香港居民有在香港特别行政区境内迁徙的自由，有移居其他国家和地区的自由。香港居民有旅行和出入境的自由。有效旅行证件的持有人，除非受到法律制止，可自由离开香港特别行政区，无需特别批准。"},{"i":32,"n":"第三十二条","txt":"香港居民有信仰的自由。"},{"i":33,"n":"第三十三条","txt":"香港居民有选择职业的自由。"},{"i":34,"n":"第三十四条","txt":"香港居民有进行学术研究、文学艺术创作和其他文化活动的自由。"},{"i":35,"n":"第三十五条","txt":"香港居民有权得到秘密法律咨询、向法院提起诉讼、选择律师及时保护自己的合法权益或在法庭上为其代理和获得司法补救。"},{"i":36,"n":"第三十六条","txt":"香港居民有依法享受社会福利的权利。劳工的福利待遇和退休保障受法律保护。"},{"i":37,"n":"第三十七条","txt":"香港居民的婚姻自由和自愿生育的权利受法律保护。"},{"i":38,"n":"第三十八条","txt":"香港居民享有香港特别行政区法律保障的其他权利和自由。"},{"i":39,"n":"第三十九条","txt":"《公民权利和政治权利国际公约》、《经济、社会与文化权利的国际公约》和国际劳工公约适用于香港的有关规定继续有效，通过香港特别行政区的法律予以实施。"},{"i":40,"n":"第四十条","txt":"“新界”原居民的合法传统权益受香港特别行政区的保护。"},{"i":41,"n":"第四十一条","txt":"在香港特别行政区境内的香港居民以外的其他人，依法享有本章规定的香港居民的权利和自由。"},{"i":42,"n":"第四十二条","txt":"香港居民和在香港的其他人有遵守香港特别行政区实行的法律的义务。"},{"i":43,"n":"第四十三条","txt":"香港特别行政区行政长官是香港特别行政区的首长，代表香港特别行政区。"},{"i":44,"n":"第四十四条","txt":"香港特别行政区行政长官由年满四十周岁，在香港通常居住连续满二十年并在外国无居留权的香港特别行政区永久性居民中的中国公民担任。"},{"i":45,"n":"第四十五条","txt":"香港特别行政区行政长官在当地通过选举或协商产生，由中央人民政府任命。"},{"i":46,"n":"第四十六条","txt":"香港特别行政区行政长官任期五年，可连任一次。"},{"i":47,"n":"第四十七条","txt":"香港特别行政区行政长官必须廉洁奉公、尽忠职守。"},{"i":48,"n":"第四十八条","txt":"香港特别行政区行政长官行使下列职权："},{"i":49,"n":"第四十九条","txt":"香港特别行政区行政长官如认为立法会通过的法案不符合香港特别行政区的整体利益，可在三个月内将法案发回立法会重议，立法会如以不少于全体议员三分之二多数再次通过原案，行政长官必须在一个月内签署公布或按本法第五十条的规定处理。"},{"i":50,"n":"第五十条","txt":"香港特别行政区行政长官如拒绝签署立法会再次通过的法案或立法会拒绝通过政府提出的财政预算案或其他重要法案，经协商仍不能取得一致意见，行政长官可解散立法会。"},{"i":51,"n":"第五十一条","txt":"香港特别行政区立法会如拒绝批准政府提出的财政预算案，行政长官可向立法会申请临时拨款。如果由于立法会已被解散而不能批准拨款，行政长官可在选出新的立法会前的一段时期内，按上一财政年度的开支标准，批准临时短期拨款。"},{"i":52,"n":"第五十二条","txt":"香港特别行政区行政长官如有下列情况之一者必须辞职："},{"i":53,"n":"第五十三条","txt":"香港特别行政区行政长官短期不能履行职务时，由政务司长、财政司长、律政司长依次临时代理其职务。"},{"i":54,"n":"第五十四条","txt":"香港特别行政区行政会议是协助行政长官决策的机构。"},{"i":55,"n":"第五十五条","txt":"香港特别行政区行政会议的成员由行政长官从行政机关的主要官员、立法会议员和社会人士中委任，其任免由行政长官决定。行政会议成员的任期应不超过委任他的行政长官的任期。"},{"i":56,"n":"第五十六条","txt":"香港特别行政区行政会议由行政长官主持。"},{"i":57,"n":"第五十七条","txt":"香港特别行政区设立廉政公署，独立工作，对行政长官负责。"},{"i":58,"n":"第五十八条","txt":"香港特别行政区设立审计署，独立工作，对行政长官负责。"},{"i":59,"n":"第五十九条","txt":"香港特别行政区政府是香港特别行政区行政机关。"},{"i":60,"n":"第六十条","txt":"香港特别行政区政府的首长是香港特别行政区行政长官。"},{"i":61,"n":"第六十一条","txt":"香港特别行政区的主要官员由在香港通常居住连续满十五年并在外国无居留权的香港特别行政区永久性居民中的中国公民担任。"},{"i":62,"n":"第六十二条","txt":"香港特别行政区政府行使下列职权："},{"i":63,"n":"第六十三条","txt":"香港特别行政区律政司主管刑事检察工作，不受任何干涉。"},{"i":64,"n":"第六十四条","txt":"香港特别行政区政府必须遵守法律，对香港特别行政区立法会负责：执行立法会通过并已生效的法律；定期向立法会作施政报告；答复立法会议员的质询；征税和公共开支须经立法会批准。"},{"i":65,"n":"第六十五条","txt":"原由行政机关设立咨询组织的制度继续保留。"},{"i":66,"n":"第六十六条","txt":"香港特别行政区立法会是香港特别行政区的立法机关。"},{"i":67,"n":"第六十七条","txt":"香港特别行政区立法会由在外国无居留权的香港特别行政区永久性居民中的中国公民组成。但非中国籍的香港特别行政区永久性居民和在外国有居留权的香港特别行政区永久性居民也可以当选为香港特别行政区立法会议员，其所占比例不得超过立法会全体议员的百分之二十。"},{"i":68,"n":"第六十八条","txt":"香港特别行政区立法会由选举产生。"},{"i":69,"n":"第六十九条","txt":"香港特别行政区立法会除第一届任期为两年外，每届任期四年。"},{"i":70,"n":"第七十条","txt":"香港特别行政区立法会如经行政长官依本法规定解散，须于三个月内依本法第六十八条的规定，重行选举产生。"},{"i":71,"n":"第七十一条","txt":"香港特别行政区立法会主席由立法会议员互选产生。"},{"i":72,"n":"第七十二条","txt":"香港特别行政区立法会主席行使下列职权："},{"i":73,"n":"第七十三条","txt":"香港特别行政区立法会行使下列职权："},{"i":74,"n":"第七十四条","txt":"香港特别行政区立法会议员根据本法规定并依照法定程序提出法律草案，凡不涉及公共开支或政治体制或政府运作者，可由立法会议员个别或联名提出。凡涉及政府政策者，在提出前必须得到行政长官的书面同意。"},{"i":75,"n":"第七十五条","txt":"香港特别行政区立法会举行会议的法定人数为不少于全体议员的二分之一。"},{"i":76,"n":"第七十六条","txt":"香港特别行政区立法会通过的法案，须经行政长官签署、公布，方能生效。"},{"i":77,"n":"第七十七条","txt":"香港特别行政区立法会议员在立法会的会议上发言，不受法律追究。"},{"i":78,"n":"第七十八条","txt":"香港特别行政区立法会议员在出席会议时和赴会途中不受逮捕。"},{"i":79,"n":"第七十九条","txt":"香港特别行政区立法会议员如有下列情况之一，由立法会主席宣告其丧失立法会议员的资格："},{"i":80,"n":"第八十条","txt":"香港特别行政区各级法院是香港特别行政区的司法机关，行使香港特别行政区的审判权。"},{"i":81,"n":"第八十一条","txt":"香港特别行政区设立终审法院、高等法院、区域法院、裁判署法庭和其他专门法庭。高等法院设上诉法庭和原讼法庭。"},{"i":82,"n":"第八十二条","txt":"香港特别行政区的终审权属于香港特别行政区终审法院。终审法院可根据需要邀请其他普通法适用地区的法官参加审判。"},{"i":83,"n":"第八十三条","txt":"香港特别行政区各级法院的组织和职权由法律规定。"},{"i":84,"n":"第八十四条","txt":"香港特别行政区法院依照本法第十八条所规定的适用于香港特别行政区的法律审判案件，其他普通法适用地区的司法判例可作参考。"},{"i":85,"n":"第八十五条","txt":"香港特别行政区法院独立进行审判，不受任何干涉，司法人员履行审判职责的行为不受法律追究。"},{"i":86,"n":"第八十六条","txt":"原在香港实行的陪审制度的原则予以保留。"},{"i":87,"n":"第八十七条","txt":"香港特别行政区的刑事诉讼和民事诉讼中保留原在香港适用的原则和当事人享有的权利。"},{"i":88,"n":"第八十八条","txt":"香港特别行政区法院的法官，根据当地法官和法律界及其他方面知名人士组成的独立委员会推荐，由行政长官任命。"},{"i":89,"n":"第八十九条","txt":"香港特别行政区法院的法官只有在无力履行职责或行为不检的情况下，行政长官才可根据终审法院首席法官任命的不少于三名当地法官组成的审议庭的建议，予以免职。"},{"i":90,"n":"第九十条","txt":"香港特别行政区终审法院和高等法院的首席法官，应由在外国无居留权的香港特别行政区永久性居民中的中国公民担任。"},{"i":91,"n":"第九十一条","txt":"香港特别行政区法官以外的其他司法人员原有的任免制度继续保持。"},{"i":92,"n":"第九十二条","txt":"香港特别行政区的法官和其他司法人员，应根据其本人的司法和专业才能选用，并可从其他普通法适用地区聘用。"},{"i":93,"n":"第九十三条","txt":"香港特别行政区成立前在香港任职的法官和其他司法人员均可留用，其年资予以保留，薪金、津贴、福利待遇和服务条件不低于原来的标准。"},{"i":94,"n":"第九十四条","txt":"香港特别行政区政府可参照原在香港实行的办法，作出有关当地和外来的律师在香港特别行政区工作和执业的规定。"},{"i":95,"n":"第九十五条","txt":"香港特别行政区可与全国其他地区的司法机关通过协商依法进行司法方面的联系和相互提供协助。"},{"i":96,"n":"第九十六条","txt":"在中央人民政府协助或授权下，香港特别行政区政府可与外国就司法互助关系作出适当安排。"},{"i":97,"n":"第九十七条","txt":"香港特别行政区可设立非政权性的区域组织，接受香港特别行政区政府就有关地区管理和其他事务的咨询，或负责提供文化、康乐、环境卫生等服务。"},{"i":98,"n":"第九十八条","txt":"区域组织的职权和组成方法由法律规定。"},{"i":99,"n":"第九十九条","txt":"在香港特别行政区政府各部门任职的公务人员必须是香港特别行政区永久性居民。本法第一百零一条对外籍公务人员另有规定者或法律规定某一职级以下者不在此限。"},{"i":100,"n":"第一百条","txt":"香港特别行政区成立前在香港政府各部门，包括警察部门任职的公务人员均可留用，其年资予以保留，薪金、津贴、福利待遇和服务条件不低于原来的标准。"},{"i":101,"n":"第一百零一条","txt":"香港特别行政区政府可任用原香港公务人员中的或持有香港特别行政区永久性居民身份证的英籍和其他外籍人士担任政府部门的各级公务人员，但下列各职级的官员必须由在外国无居留权的香港特别行政区永久性居民中的中国公民担任：各司司长、副司长，各局局长，廉政专员，审计署署长，警务处处长，入境事务处处长，海关关长。"},{"i":102,"n":"第一百零二条","txt":"对退休或符合规定离职的公务人员，包括香港特别行政区成立前退休或符合规定离职的公务人员，不论其所属国籍或居住地点，香港特别行政区政府按不低于原来的标准向他们或其家属支付应得的退休金、酬金、津贴和福利费。"},{"i":103,"n":"第一百零三条","txt":"公务人员应根据其本人的资格、经验和才能予以任用和提升，香港原有关于公务人员的招聘、雇用、考核、纪律、培训和管理的制度，包括负责公务人员的任用、薪金、服务条件的专门机构，除有关给予外籍人员特权待遇的规定外，予以保留。"},{"i":104,"n":"第一百零四条","txt":"香港特别行政区行政长官、主要官员、行政会议成员、立法会议员、各级法院法官和其他司法人员在就职时必须依法宣誓拥护中华人民共和国香港特别行政区基本法，效忠中华人民共和国香港特别行政区。"},{"i":105,"n":"第一百零五条","txt":"香港特别行政区依法保护私人和法人财产的取得、使用、处置和继承的权利，以及依法征用私人和法人财产时被征用财产的所有人得到补偿的权利。"},{"i":106,"n":"第一百零六条","txt":"香港特别行政区保持财政独立。"},{"i":107,"n":"第一百零七条","txt":"香港特别行政区的财政预算以量入为出为原则，力求收支平衡，避免赤字，并与本地生产总值的增长率相适应。"},{"i":108,"n":"第一百零八条","txt":"香港特别行政区实行独立的税收制度。"},{"i":109,"n":"第一百零九条","txt":"香港特别行政区政府提供适当的经济和法律环境，以保持香港的国际金融中心地位。"},{"i":110,"n":"第一百一十条","txt":"香港特别行政区的货币金融制度由法律规定。"},{"i":111,"n":"第一百一十一条","txt":"港元为香港特别行政区法定货币，继续流通。"},{"i":112,"n":"第一百一十二条","txt":"香港特别行政区不实行外汇管制政策。港币自由兑换。继续开放外汇、黄金、证券、期货等市场。"},{"i":113,"n":"第一百一十三条","txt":"香港特别行政区的外汇基金，由香港特别行政区政府管理和支配，主要用于调节港元汇价。"},{"i":114,"n":"第一百一十四条","txt":"香港特别行政区保持自由港地位，除法律另有规定外，不征收关税。"},{"i":115,"n":"第一百一十五条","txt":"香港特别行政区实行自由贸易政策，保障货物、无形财产和资本的流动自由。"},{"i":116,"n":"第一百一十六条","txt":"香港特别行政区为单独的关税地区。"},{"i":117,"n":"第一百一十七条","txt":"香港特别行政区根据当时的产地规则，可对产品签发产地来源证。"},{"i":118,"n":"第一百一十八条","txt":"香港特别行政区政府提供经济和法律环境，鼓励各项投资、技术进步并开发新兴产业。"},{"i":119,"n":"第一百一十九条","txt":"香港特别行政区政府制定适当政策，促进和协调制造业、商业、旅游业、房地产业、运输业、公用事业、服务性行业、渔农业等各行业的发展，并注意环境保护。"},{"i":120,"n":"第一百二十条","txt":"香港特别行政区成立以前已批出、决定、或续期的超越一九九七年六月三十日年期的所有土地契约和与土地契约有关的一切权利，均按香港特别行政区的法律继续予以承认和保护。"},{"i":121,"n":"第一百二十一条","txt":"从一九八五年五月二十七日至一九九七年六月三十日期间批出的，或原没有续期权利而获得续期的，超出一九九七年六月三十日年期而不超过二零四七年六月三十日的一切土地契约，承租人从一九九七年七月一日起不补地价，但需每年缴纳相当于当日该土地应课差饷租值百分之三的租金。此后，随应课差饷租值的改变而调整租金。"},{"i":122,"n":"第一百二十二条","txt":"原旧批约地段、乡村屋地、丁屋地和类似的农村土地，如该土地在一九八四年六月三十日的承租人，或在该日以后批出的丁屋地承租人，其父系为一八九八年在香港的原有乡村居民，只要该土地的承租人仍为该人或其合法父系继承人，原定租金维持不变。"},{"i":123,"n":"第一百二十三条","txt":"香港特别行政区成立以后满期而没有续期权利的土地契约，由香港特别行政区自行制定法律和政策处理。"},{"i":124,"n":"第一百二十四条","txt":"香港特别行政区保持原在香港实行的航运经营和管理体制，包括有关海员的管理制度。"},{"i":125,"n":"第一百二十五条","txt":"香港特别行政区经中央人民政府授权继续进行船舶登记，并根据香港特别行政区的法律以“中国香港”的名义颁发有关证件。"},{"i":126,"n":"第一百二十六条","txt":"除外国军用船只进入香港特别行政区须经中央人民政府特别许可外，其他船舶可根据香港特别行政区法律进出其港口。"},{"i":127,"n":"第一百二十七条","txt":"香港特别行政区的私营航运及与航运有关的企业和私营集装箱码头，可继续自由经营。"},{"i":128,"n":"第一百二十八条","txt":"香港特别行政区政府应提供条件和采取措施，以保持香港的国际和区域航空中心的地位。"},{"i":129,"n":"第一百二十九条","txt":"香港特别行政区继续实行原在香港实行的民用航空管理制度，并按中央人民政府关于飞机国籍标志和登记标志的规定，设置自己的飞机登记册。"},{"i":130,"n":"第一百三十条","txt":"香港特别行政区自行负责民用航空的日常业务和技术管理，包括机场管理，在香港特别行政区飞行情报区内提供空中交通服务，和履行国际民用航空组织的区域性航行规划程序所规定的其他职责。"},{"i":131,"n":"第一百三十一条","txt":"中央人民政府经同香港特别行政区政府磋商作出安排，为在香港特别行政区注册并以香港为主要营业地的航空公司和中华人民共和国的其他航空公司，提供香港特别行政区和中华人民共和国其他地区之间的往返航班。"},{"i":132,"n":"第一百三十二条","txt":"凡涉及中华人民共和国其他地区同其他国家和地区的往返并经停香港特别行政区的航班，和涉及香港特别行政区同其他国家和地区的往返并经停中华人民共和国其他地区航班的民用航空运输协定，由中央人民政府签订。"},{"i":133,"n":"第一百三十三条","txt":"香港特别行政区政府经中央人民政府具体授权可："},{"i":134,"n":"第一百三十四条","txt":"中央人民政府授权香港特别行政区政府："},{"i":135,"n":"第一百三十五条","txt":"香港特别行政区成立前在香港注册并以香港为主要营业地的航空公司和与民用航空有关的行业，可继续经营。"},{"i":136,"n":"第一百三十六条","txt":"香港特别行政区政府在原有教育制度的基础上，自行制定有关教育的发展和改进的政策，包括教育体制和管理、教学语言、经费分配、考试制度、学位制度和承认学历等政策。"},{"i":137,"n":"第一百三十七条","txt":"各类院校均可保留其自主性并享有学术自由，可继续从香港特别行政区以外招聘教职员和选用教材。宗教组织所办的学校可继续提供宗教教育，包括开设宗教课程。"},{"i":138,"n":"第一百三十八条","txt":"香港特别行政区政府自行制定发展中西医药和促进医疗卫生服务的政策。社会团体和私人可依法提供各种医疗卫生服务。"},{"i":139,"n":"第一百三十九条","txt":"香港特别行政区政府自行制定科学技术政策，以法律保护科学技术的研究成果、专利和发明创造。"},{"i":140,"n":"第一百四十条","txt":"香港特别行政区政府自行制定文化政策，以法律保护作者在文学艺术创作中所获得的成果和合法权益。"},{"i":141,"n":"第一百四十一条","txt":"香港特别行政区政府不限制宗教信仰自由，不干预宗教组织的内部事务，不限制与香港特别行政区法律没有抵触的宗教活动。"},{"i":142,"n":"第一百四十二条","txt":"香港特别行政区政府在保留原有的专业制度的基础上，自行制定有关评审各种专业的执业资格的办法。"},{"i":143,"n":"第一百四十三条","txt":"香港特别行政区政府自行制定体育政策。民间体育团体可依法继续存在和发展。"},{"i":144,"n":"第一百四十四条","txt":"香港特别行政区政府保持原在香港实行的对教育、医疗卫生、文化、艺术、康乐、体育、社会福利、社会工作等方面的民间团体机构的资助政策。原在香港各资助机构任职的人员均可根据原有制度继续受聘。"},{"i":145,"n":"第一百四十五条","txt":"香港特别行政区政府在原有社会福利制度的基础上，根据经济条件和社会需要，自行制定其发展、改进的政策。"},{"i":146,"n":"第一百四十六条","txt":"香港特别行政区从事社会服务的志愿团体在不抵触法律的情况下可自行决定其服务方式。"},{"i":147,"n":"第一百四十七条","txt":"香港特别行政区自行制定有关劳工的法律和政策。"},{"i":148,"n":"第一百四十八条","txt":"香港特别行政区的教育、科学、技术、文化、艺术、体育、专业、医疗卫生、劳工、社会福利、社会工作等方面的民间团体和宗教组织同内地相应的团体和组织的关系，应以互不隶属、互不干涉和互相尊重的原则为基础。"},{"i":149,"n":"第一百四十九条","txt":"香港特别行政区的教育、科学、技术、文化、艺术、体育、专业、医疗卫生、劳工、社会福利、社会工作等方面的民间团体和宗教组织可同世界各国、各地区及国际的有关团体和组织保持和发展关系，各该团体和组织可根据需要冠用“中国香港”的名义，参与有关活动。"},{"i":150,"n":"第一百五十条","txt":"香港特别行政区政府的代表，可作为中华人民共和国政府代表团的成员，参加由中央人民政府进行的同香港特别行政区直接有关的外交谈判。"},{"i":151,"n":"第一百五十一条","txt":"香港特别行政区可在经济、贸易、金融、航运、通讯、旅游、文化、体育等领域以“中国香港”的名义，单独地同世界各国、各地区及有关国际组织保持和发展关系，签订和履行有关协议。"},{"i":152,"n":"第一百五十二条","txt":"对以国家为单位参加的、同香港特别行政区有关的、适当领域的国际组织和国际会议，香港特别行政区政府可派遣代表作为中华人民共和国代表团的成员或以中央人民政府和上述有关国际组织或国际会议允许的身份参加，并以“中国香港”的名义发表意见。"},{"i":153,"n":"第一百五十三条","txt":"中华人民共和国缔结的国际协议，中央人民政府可根据香港特别行政区的情况和需要，在征询香港特别行政区政府的意见后，决定是否适用于香港特别行政区。"},{"i":154,"n":"第一百五十四条","txt":"中央人民政府授权香港特别行政区政府依照法律给持有香港特别行政区永久性居民身份证的中国公民签发中华人民共和国香港特别行政区护照，给在香港特别行政区的其他合法居留者签发中华人民共和国香港特别行政区的其他旅行证件。上述护照和证件，前往各国和各地区有效，并载明持有人有返回香港特别行政区的权利。"},{"i":155,"n":"第一百五十五条","txt":"中央人民政府协助或授权香港特别行政区政府与各国或各地区缔结互免签证协议。"},{"i":156,"n":"第一百五十六条","txt":"香港特别行政区可根据需要在外国设立官方或半官方的经济和贸易机构，报中央人民政府备案。"},{"i":157,"n":"第一百五十七条","txt":"外国在香港特别行政区设立领事机构或其他官方、半官方机构，须经中央人民政府批准。"},{"i":158,"n":"第一百五十八条","txt":"本法的解释权属于全国人民代表大会常务委员会。"},{"i":159,"n":"第一百五十九条","txt":"本法的修改权属于全国人民代表大会。"},{"i":160,"n":"第一百六十条","txt":"香港特别行政区成立时，香港原有法律除由全国人民代表大会常务委员会宣布为同本法抵触者外，采用为香港特别行政区法律，如以后发现有的法律与本法抵触，可依照本法规定的程序修改或停止生效。"}],"xianggangtebiexingzhengquweihuguojiaanquanfa":[{"i":1,"n":"第一条","txt":"为坚定不移并全面准确贯彻“一国两制”、“港人治港”、高度自治的方针，维护国家安全，防范、制止和惩治与香港特别行政区有关的分裂国家、颠覆国家政权、组织实施恐怖活动和勾结外国或者境外势力危害国家安全等犯罪，保持香港特别行政区的繁荣和稳定，保障香港特别行政区居民的合法权益，根据中华人民共和国宪法、中华人民共和国香港特别行政区基本法和全国人民代表大会关于建立健全香港特别行政区维护国家安全的法律制度和执行机制的决定，制定本法。"},{"i":2,"n":"第二条","txt":"关于香港特别行政区法律地位的香港特别行政区基本法第一条和第十二条规定是香港特别行政区基本法的根本性条款。香港特别行政区任何机构、组织和个人行使权利和自由，不得违背香港特别行政区基本法第一条和第十二条的规定。"},{"i":3,"n":"第三条","txt":"中央人民政府对香港特别行政区有关的国家安全事务负有根本责任。"},{"i":4,"n":"第四条","txt":"香港特别行政区维护国家安全应当尊重和保障人权，依法保护香港特别行政区居民根据香港特别行政区基本法和《公民权利和政治权利国际公约》、《经济、社会与文化权利的国际公约》适用于香港的有关规定享有的包括言论、新闻、出版的自由，结社、集会、游行、示威的自由在内的权利和自由。"},{"i":5,"n":"第五条","txt":"防范、制止和惩治危害国家安全犯罪，应当坚持法治原则。法律规定为犯罪行为的，依照法律定罪处刑；法律没有规定为犯罪行为的，不得定罪处刑。"},{"i":6,"n":"第六条","txt":"维护国家主权、统一和领土完整是包括香港同胞在内的全中国人民的共同义务。"},{"i":7,"n":"第七条","txt":"香港特别行政区应当尽早完成香港特别行政区基本法规定的维护国家安全立法，完善相关法律。"},{"i":8,"n":"第八条","txt":"香港特别行政区执法、司法机关应当切实执行本法和香港特别行政区现行法律有关防范、制止和惩治危害国家安全行为和活动的规定，有效维护国家安全。"},{"i":9,"n":"第九条","txt":"香港特别行政区应当加强维护国家安全和防范恐怖活动的工作。对学校、社会团体、媒体、网络等涉及国家安全的事宜，香港特别行政区政府应当采取必要措施，加强宣传、指导、监督和管理。"},{"i":10,"n":"第十条","txt":"香港特别行政区应当通过学校、社会团体、媒体、网络等开展国家安全教育，提高香港特别行政区居民的国家安全意识和守法意识。"},{"i":11,"n":"第十一条","txt":"香港特别行政区行政长官应当就香港特别行政区维护国家安全事务向中央人民政府负责，并就香港特别行政区履行维护国家安全职责的情况提交年度报告。"},{"i":12,"n":"第十二条","txt":"香港特别行政区设立维护国家安全委员会，负责香港特别行政区维护国家安全事务，承担维护国家安全的主要责任，并接受中央人民政府的监督和问责。"},{"i":13,"n":"第十三条","txt":"香港特别行政区维护国家安全委员会由行政长官担任主席，成员包括政务司长、财政司长、律政司长、保安局局长、警务处处长、本法第十六条规定的警务处维护国家安全部门的负责人、入境事务处处长、海关关长和行政长官办公室主任。"},{"i":14,"n":"第十四条","txt":"香港特别行政区维护国家安全委员会的职责为："},{"i":15,"n":"第十五条","txt":"香港特别行政区维护国家安全委员会设立国家安全事务顾问，由中央人民政府指派，就香港特别行政区维护国家安全委员会履行职责相关事务提供意见。国家安全事务顾问列席香港特别行政区维护国家安全委员会会议。"},{"i":16,"n":"第十六条","txt":"香港特别行政区政府警务处设立维护国家安全的部门，配备执法力量。"},{"i":17,"n":"第十七条","txt":"警务处维护国家安全部门的职责为："},{"i":18,"n":"第十八条","txt":"香港特别行政区律政司设立专门的国家安全犯罪案件检控部门，负责危害国家安全犯罪案件的检控工作和其他相关法律事务。该部门检控官由律政司长征得香港特别行政区维护国家安全委员会同意后任命。"},{"i":19,"n":"第十九条","txt":"经行政长官批准，香港特别行政区政府财政司长应当从政府一般收入中拨出专门款项支付关于维护国家安全的开支并核准所涉及的人员编制，不受香港特别行政区现行有关法律规定的限制。财政司长须每年就该款项的控制和管理向立法会提交报告。"},{"i":20,"n":"第二十条","txt":"任何人组织、策划、实施或者参与实施以下旨在分裂国家、破坏国家统一行为之一的，不论是否使用武力或者以武力相威胁，即属犯罪："},{"i":21,"n":"第二十一条","txt":"任何人煽动、协助、教唆、以金钱或者其他财物资助他人实施本法第二十条规定的犯罪的，即属犯罪。情节严重的，处五年以上十年以下有期徒刑；情节较轻的，处五年以下有期徒刑、拘役或者管制。"},{"i":22,"n":"第二十二条","txt":"任何人组织、策划、实施或者参与实施以下以武力、威胁使用武力或者其他非法手段旨在颠覆国家政权行为之一的，即属犯罪："},{"i":23,"n":"第二十三条","txt":"任何人煽动、协助、教唆、以金钱或者其他财物资助他人实施本法第二十二条规定的犯罪的，即属犯罪。情节严重的，处五年以上十年以下有期徒刑；情节较轻的，处五年以下有期徒刑、拘役或者管制。"},{"i":24,"n":"第二十四条","txt":"为胁迫中央人民政府、香港特别行政区政府或者国际组织或者威吓公众以图实现政治主张，组织、策划、实施、参与实施或者威胁实施以下造成或者意图造成严重社会危害的恐怖活动之一的，即属犯罪："},{"i":25,"n":"第二十五条","txt":"组织、领导恐怖活动组织的，即属犯罪，处无期徒刑或者十年以上有期徒刑，并处没收财产；积极参加的，处三年以上十年以下有期徒刑，并处罚金；其他参加的，处三年以下有期徒刑、拘役或者管制，可以并处罚金。"},{"i":26,"n":"第二十六条","txt":"为恐怖活动组织、恐怖活动人员、恐怖活动实施提供培训、武器、信息、资金、物资、劳务、运输、技术或者场所等支持、协助、便利，或者制造、非法管有爆炸性、毒害性、放射性、传染病病原体等物质以及以其他形式准备实施恐怖活动的，即属犯罪。情节严重的，处五年以上十年以下有期徒刑，并处罚金或者没收财产；其他情形，处五年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":27,"n":"第二十七条","txt":"宣扬恐怖主义、煽动实施恐怖活动的，即属犯罪。情节严重的，处五年以上十年以下有期徒刑，并处罚金或者没收财产；其他情形，处五年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":28,"n":"第二十八条","txt":"本节规定不影响依据香港特别行政区法律对其他形式的恐怖活动犯罪追究刑事责任并采取冻结财产等措施。"},{"i":29,"n":"第二十九条","txt":"为外国或者境外机构、组织、人员窃取、刺探、收买、非法提供涉及国家安全的国家秘密或者情报的；请求外国或者境外机构、组织、人员实施，与外国或者境外机构、组织、人员串谋实施，或者直接或者间接接受外国或者境外机构、组织、人员的指使、控制、资助或者其他形式的支援实施以下行为之一的，均属犯罪："},{"i":30,"n":"第三十条","txt":"为实施本法第二十条、第二十二条规定的犯罪，与外国或者境外机构、组织、人员串谋，或者直接或者间接接受外国或者境外机构、组织、人员的指使、控制、资助或者其他形式的支援的，依照本法第二十条、第二十二条的规定从重处罚。"},{"i":31,"n":"第三十一条","txt":"公司、团体等法人或者非法人组织实施本法规定的犯罪的，对该组织判处罚金。"},{"i":32,"n":"第三十二条","txt":"因实施本法规定的犯罪而获得的资助、收益、报酬等违法所得以及用于或者意图用于犯罪的资金和工具，应当予以追缴、没收。"},{"i":33,"n":"第三十三条","txt":"有以下情形的，对有关犯罪行为人、犯罪嫌疑人、被告人可以从轻、减轻处罚；犯罪较轻的，可以免除处罚："},{"i":34,"n":"第三十四条","txt":"不具有香港特别行政区永久性居民身份的人实施本法规定的犯罪的，可以独立适用或者附加适用驱逐出境。"},{"i":35,"n":"第三十五条","txt":"任何人经法院判决犯危害国家安全罪行的，即丧失作为候选人参加香港特别行政区举行的立法会、区议会选举或者出任香港特别行政区任何公职或者行政长官选举委员会委员的资格；曾经宣誓或者声明拥护中华人民共和国香港特别行政区基本法、效忠中华人民共和国香港特别行政区的立法会议员、政府官员及公务人员、行政会议成员、法官及其他司法人员、区议员，即时丧失该等职务，并丧失参选或者出任上述职务的资格。"},{"i":36,"n":"第三十六条","txt":"任何人在香港特别行政区内实施本法规定的犯罪的，适用本法。犯罪的行为或者结果有一项发生在香港特别行政区内的，就认为是在香港特别行政区内犯罪。"},{"i":37,"n":"第三十七条","txt":"香港特别行政区永久性居民或者在香港特别行政区成立的公司、团体等法人或者非法人组织在香港特别行政区以外实施本法规定的犯罪的，适用本法。"},{"i":38,"n":"第三十八条","txt":"不具有香港特别行政区永久性居民身份的人在香港特别行政区以外针对香港特别行政区实施本法规定的犯罪的，适用本法。"},{"i":39,"n":"第三十九条","txt":"本法施行以后的行为，适用本法定罪处刑。"},{"i":40,"n":"第四十条","txt":"香港特别行政区对本法规定的犯罪案件行使管辖权，但本法第五十五条规定的情形除外。"},{"i":41,"n":"第四十一条","txt":"香港特别行政区管辖危害国家安全犯罪案件的立案侦查、检控、审判和刑罚的执行等诉讼程序事宜，适用本法和香港特别行政区本地法律。"},{"i":42,"n":"第四十二条","txt":"香港特别行政区执法、司法机关在适用香港特别行政区现行法律有关羁押、审理期限等方面的规定时，应当确保危害国家安全犯罪案件公正、及时办理，有效防范、制止和惩治危害国家安全犯罪。"},{"i":43,"n":"第四十三条","txt":"香港特别行政区政府警务处维护国家安全部门办理危害国家安全犯罪案件时，可以采取香港特别行政区现行法律准予警方等执法部门在调查严重犯罪案件时采取的各种措施，并可以采取以下措施："},{"i":44,"n":"第四十四条","txt":"香港特别行政区行政长官应当从裁判官、区域法院法官、高等法院原讼法庭法官、上诉法庭法官以及终审法院法官中指定若干名法官，也可从暂委或者特委法官中指定若干名法官，负责处理危害国家安全犯罪案件。行政长官在指定法官前可征询香港特别行政区维护国家安全委员会和终审法院首席法官的意见。上述指定法官任期一年。"},{"i":45,"n":"第四十五条","txt":"除本法另有规定外，裁判法院、区域法院、高等法院和终审法院应当按照香港特别行政区的其他法律处理就危害国家安全犯罪案件提起的刑事检控程序。"},{"i":46,"n":"第四十六条","txt":"对高等法院原讼法庭进行的就危害国家安全犯罪案件提起的刑事检控程序，律政司长可基于保护国家秘密、案件具有涉外因素或者保障陪审员及其家人的人身安全等理由，发出证书指示相关诉讼毋须在有陪审团的情况下进行审理。凡律政司长发出上述证书，高等法院原讼法庭应当在没有陪审团的情况下进行审理，并由三名法官组成审判庭。"},{"i":47,"n":"第四十七条","txt":"香港特别行政区法院在审理案件中遇有涉及有关行为是否涉及国家安全或者有关证据材料是否涉及国家秘密的认定问题，应取得行政长官就该等问题发出的证明书，上述证明书对法院有约束力。"},{"i":48,"n":"第四十八条","txt":"中央人民政府在香港特别行政区设立维护国家安全公署。中央人民政府驻香港特别行政区维护国家安全公署依法履行维护国家安全职责，行使相关权力。"},{"i":49,"n":"第四十九条","txt":"驻香港特别行政区维护国家安全公署的职责为："},{"i":50,"n":"第五十条","txt":"驻香港特别行政区维护国家安全公署应当严格依法履行职责，依法接受监督，不得侵害任何个人和组织的合法权益。"},{"i":51,"n":"第五十一条","txt":"驻香港特别行政区维护国家安全公署的经费由中央财政保障。"},{"i":52,"n":"第五十二条","txt":"驻香港特别行政区维护国家安全公署应当加强与中央人民政府驻香港特别行政区联络办公室、外交部驻香港特别行政区特派员公署、中国人民解放军驻香港部队的工作联系和工作协同。"},{"i":53,"n":"第五十三条","txt":"驻香港特别行政区维护国家安全公署应当与香港特别行政区维护国家安全委员会建立协调机制，监督、指导香港特别行政区维护国家安全工作。"},{"i":54,"n":"第五十四条","txt":"驻香港特别行政区维护国家安全公署、外交部驻香港特别行政区特派员公署会同香港特别行政区政府采取必要措施，加强对外国和国际组织驻香港特别行政区机构、在香港特别行政区的外国和境外非政府组织和新闻机构的管理和服务。"},{"i":55,"n":"第五十五条","txt":"有以下情形之一的，经香港特别行政区政府或者驻香港特别行政区维护国家安全公署提出，并报中央人民政府批准，由驻香港特别行政区维护国家安全公署对本法规定的危害国家安全犯罪案件行使管辖权："},{"i":56,"n":"第五十六条","txt":"根据本法第五十五条规定管辖有关危害国家安全犯罪案件时，由驻香港特别行政区维护国家安全公署负责立案侦查，最高人民检察院指定有关检察机关行使检察权，最高人民法院指定有关法院行使审判权。"},{"i":57,"n":"第五十七条","txt":"根据本法第五十五条规定管辖案件的立案侦查、审查起诉、审判和刑罚的执行等诉讼程序事宜，适用《中华人民共和国刑事诉讼法》等相关法律的规定。"},{"i":58,"n":"第五十八条","txt":"根据本法第五十五条规定管辖案件时，犯罪嫌疑人自被驻香港特别行政区维护国家安全公署第一次讯问或者采取强制措施之日起，有权委托律师作为辩护人。辩护律师可以依法为犯罪嫌疑人、被告人提供法律帮助。"},{"i":59,"n":"第五十九条","txt":"根据本法第五十五条规定管辖案件时，任何人如果知道本法规定的危害国家安全犯罪案件情况，都有如实作证的义务。"},{"i":60,"n":"第六十条","txt":"驻香港特别行政区维护国家安全公署及其人员依据本法执行职务的行为，不受香港特别行政区管辖。"},{"i":61,"n":"第六十一条","txt":"驻香港特别行政区维护国家安全公署依据本法规定履行职责时，香港特别行政区政府有关部门须提供必要的便利和配合，对妨碍有关执行职务的行为依法予以制止并追究责任。"},{"i":62,"n":"第六十二条","txt":"香港特别行政区本地法律规定与本法不一致的，适用本法规定。"},{"i":63,"n":"第六十三条","txt":"办理本法规定的危害国家安全犯罪案件的有关执法、司法机关及其人员或者办理其他危害国家安全犯罪案件的香港特别行政区执法、司法机关及其人员，应当对办案过程中知悉的国家秘密、商业秘密和个人隐私予以保密。"},{"i":64,"n":"第六十四条","txt":"香港特别行政区适用本法时，本法规定的“有期徒刑”“无期徒刑”“没收财产”和“罚金”分别指“监禁”“终身监禁”“充公犯罪所得”和“罚款”，“拘役”参照适用香港特别行政区相关法律规定的“监禁”“入劳役中心”“入教导所”，“管制”参照适用香港特别行政区相关法律规定的“社会服务令”“入感化院”，“吊销执照或者营业许可证”指香港特别行政区相关法律规定的“取消注册或者注册豁免，或者取消牌照”。"},{"i":65,"n":"第六十五条","txt":"本法的解释权属于全国人民代表大会常务委员会。"},{"i":66,"n":"第六十六条","txt":"本法自公布之日起施行。"}],"xianggangtebiexingzhengquzhujunfa":[{"i":1,"n":"第一条","txt":"为了保障中央人民政府派驻香港特别行政区负责防务的军队依法履行职责，维护国家的主权、统一、领土完整和香港的安全，根据宪法和香港特别行政区基本法，制定本法。"},{"i":2,"n":"第二条","txt":"中央人民政府派驻香港特别行政区负责防务的军队，由中国人民解放军陆军、海军、空军部队组成，称中国人民解放军驻香港部队（以下称香港驻军）。"},{"i":3,"n":"第三条","txt":"香港驻军由中华人民共和国中央军事委员会领导，其员额根据香港特别行政区防务的需要确定。"},{"i":4,"n":"第四条","txt":"香港驻军费用由中央人民政府负担。"},{"i":5,"n":"第五条","txt":"香港驻军履行下列防务职责："},{"i":6,"n":"第六条","txt":"全国人民代表大会常务委员会决定宣布战争状态或者因香港特别行政区内发生香港特别行政区政府不能控制的危及国家统一或者安全的动乱而决定香港特别行政区进入紧急状态时，香港驻军根据中央人民政府决定在香港特别行政区实施的全国性法律的规定履行职责。"},{"i":7,"n":"第七条","txt":"香港驻军的飞行器、舰船等武器装备和物资以及持有香港驻军制发的证件或者证明文件的执行职务的人员和车辆，不受香港特别行政区执法人员检查、搜查和扣押。"},{"i":8,"n":"第八条","txt":"香港驻军人员对妨碍其执行职务的行为，可以依照在香港特别行政区实施的法律的规定采取措施予以制止。"},{"i":9,"n":"第九条","txt":"香港驻军不干预香港特别行政区的地方事务。"},{"i":10,"n":"第十条","txt":"香港特别行政区政府应当支持香港驻军履行防务职责，保障香港驻军和香港驻军人员的合法权益。"},{"i":11,"n":"第十一条","txt":"香港驻军进行训练、演习等军事活动，涉及香港特别行政区公共利益的，应当事先通报香港特别行政区政府。"},{"i":12,"n":"第十二条","txt":"香港驻军和香港特别行政区政府共同保护香港特别行政区内的军事设施。"},{"i":13,"n":"第十三条","txt":"香港驻军的军事用地，经中央人民政府批准不再用于防务目的的，无偿交由香港特别行政区政府处理。"},{"i":14,"n":"第十四条","txt":"香港特别行政区政府根据香港特别行政区基本法的规定，在必要时可以向中央人民政府请求香港驻军协助维持社会治安和救助灾害。"},{"i":15,"n":"第十五条","txt":"香港驻军和香港特别行政区政府应当建立必要的联系，协商处理与驻军有关的事宜。"},{"i":16,"n":"第十六条","txt":"香港驻军人员应当履行下列义务："},{"i":17,"n":"第十七条","txt":"香港驻军人员不得参加香港的政治组织、宗教组织和社会团体。"},{"i":18,"n":"第十八条","txt":"香港驻军和香港驻军人员不得以任何形式从事营利性经营活动。香港驻军人员并不得从事与军人职责不相称的其他任何活动。"},{"i":19,"n":"第十九条","txt":"香港驻军人员违反全国性的法律和香港特别行政区的法律的，依法追究法律责任。"},{"i":20,"n":"第二十条","txt":"香港驻军人员犯罪的案件由军事司法机关管辖；但是，香港驻军人员非执行职务的行为，侵犯香港居民、香港驻军以外的其他人的人身权、财产权以及其他违反香港特别行政区法律构成犯罪的案件，由香港特别行政区法院以及有关的执法机关管辖。"},{"i":21,"n":"第二十一条","txt":"香港特别行政区执法人员依法拘捕的涉嫌犯罪的人员，查明是香港驻军人员的，应当移交香港驻军羁押。被羁押的人员所涉及的案件，依照本法第二十条的规定确定管辖。"},{"i":22,"n":"第二十二条","txt":"香港驻军人员被香港特别行政区法院判处剥夺或者限制人身自由的刑罚的，依照香港特别行政区的法律规定送交执行；但是，香港特别行政区有关执法机关与军事司法机关对执行的地点另行协商确定的除外。"},{"i":23,"n":"第二十三条","txt":"香港驻军人员违反香港特别行政区的法律，侵害香港居民、香港驻军以外的其他人的民事权利的，当事人可以通过协商、调解解决；不愿通过协商、调解解决或者协商、调解不成的，被侵权人可以向法院提起诉讼。香港驻军人员非执行职务的行为引起的民事侵权案件，由香港特别行政区法院管辖；执行职务的行为引起的民事侵权案件，由中华人民共和国最高人民法院管辖，侵权行为的损害赔偿适用香港特别行政区法律。"},{"i":24,"n":"第二十四条","txt":"香港驻军的机关或者单位在香港特别行政区与香港居民、香港驻军以外的其他人发生合同纠纷时，当事人可以通过协商、调解解决。当事人不愿通过协商、调解解决或者协商、调解不成的，可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，向仲裁机构申请仲裁。当事人没有在合同中订立仲裁条款，事后又没有达成书面仲裁协议的，可以向香港特别行政区法院提起诉讼；但是，当事人对提起诉讼的法院另有约定的除外。"},{"i":25,"n":"第二十五条","txt":"在香港特别行政区法院的诉讼活动中，香港驻军对香港驻军人员身份、执行职务的行为等事实发出的证明文件为有效证据。但是，相反证据成立的除外。"},{"i":26,"n":"第二十六条","txt":"香港驻军的国防等国家行为不受香港特别行政区法院管辖。"},{"i":27,"n":"第二十七条","txt":"香港特别行政区法院作出的判决、裁定涉及香港驻军的机关或者单位的财产执行的，香港驻军的机关或者单位必须履行；但是，香港特别行政区法院不得对香港驻军的武器装备、物资和其他财产实施强制执行。"},{"i":28,"n":"第二十八条","txt":"军事司法机关可以与香港特别行政区法院和有关执法机关通过协商进行司法方面的联系和相互提供协助。"},{"i":29,"n":"第二十九条","txt":"本法的解释权属于全国人民代表大会常务委员会。"},{"i":30,"n":"第三十条","txt":"本法自1997年7月1日起施行。"}],"zhongguorenminjiefangjunxuanjuquanguorenmindaibiao1634f3":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国宪法》和《中华人民共和国全国人民代表大会和地方各级人民代表大会选举法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"人民解放军军人和参加军队选举的其他人员依照本办法选举全国人民代表大会和县级以上地方各级人民代表大会代表。"},{"i":3,"n":"第三条","txt":"人民解放军及人民解放军团级以上单位设立选举委员会。"},{"i":4,"n":"第四条","txt":"连和其他基层单位的军人委员会，主持本单位的选举工作。"},{"i":5,"n":"第五条","txt":"人民解放军军人、文职人员，军队管理的离休、退休人员和其他人员，参加军队选举。"},{"i":6,"n":"第六条","txt":"驻地方工厂、铁路、水运、科研等单位的军代表，在地方院校学习的军队人员，可以参加地方选举。"},{"i":7,"n":"第七条","txt":"本办法第五条所列人员，凡年满十八周岁，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都具有选民资格，享有选举权和被选举权。"},{"i":8,"n":"第八条","txt":"人民解放军选举委员会的组成人员，由全国人民代表大会常务委员会批准。其他各级选举委员会的组成人员，由上一级选举委员会批准。"},{"i":9,"n":"第九条","txt":"人民解放军选举委员会由十一至十九人组成，设主任一人，副主任一至三人，委员若干人。其他各级选举委员会由七至十七人组成，设主任一人，副主任一至二人，委员若干人。"},{"i":10,"n":"第十条","txt":"团级以上单位的选举委员会组织、指导所属单位的选举，办理下列事项："},{"i":11,"n":"第十一条","txt":"选举委员会下设办公室，具体承办本级有关选举的日常工作。"},{"i":12,"n":"第十二条","txt":"人民解放军应选全国人民代表大会代表的名额，由全国人民代表大会常务委员会决定。"},{"i":13,"n":"第十三条","txt":"中央军事委员会机关部门和战区、军兵种、军事科学院、国防大学、国防科技大学等单位应选全国人民代表大会代表的名额，由人民解放军选举委员会分配。中央军事委员会直属机构参加其代管部门的选举。"},{"i":14,"n":"第十四条","txt":"各地驻军应选县级以上地方各级人民代表大会代表的名额，由驻地各该级人民代表大会常务委员会决定。"},{"i":15,"n":"第十五条","txt":"驻军选举县级人民代表大会代表，由驻该行政区域的军人和参加军队选举的其他人员按选区直接选举产生。选区按该行政区域内驻军各单位的分布情况划分。"},{"i":16,"n":"第十六条","txt":"驻军应选的设区的市、自治州、省、自治区、直辖市人民代表大会代表，由团级以上单位召开军人代表大会选举产生。"},{"i":17,"n":"第十七条","txt":"人民解放军师级以上单位的军人代表大会代表，由下级军人代表大会选举产生。下级单位不召开军人代表大会的，由军人大会选举产生。"},{"i":18,"n":"第十八条","txt":"人民解放军选举全国和县级以上地方各级人民代表大会代表，候选人按选区或者选举单位提名产生。"},{"i":19,"n":"第十九条","txt":"人民解放军选举全国和县级以上地方各级人民代表大会代表实行差额选举，代表候选人的人数应多于应选代表的名额。"},{"i":20,"n":"第二十条","txt":"由选民直接选举的，代表候选人由选举委员会或者军人委员会汇总后，将代表候选人名单以及代表候选人的基本情况在选举日的十五日以前公布，并交各该选区的选民反复讨论、协商，确定正式代表候选人名单。如果所提代表候选人的人数超过本办法第十九条规定的最高差额比例，由选举委员会或者军人委员会交各该选区的选民讨论、协商，根据较多数选民的意见，确定正式代表候选人名单；对正式代表候选人不能形成较为一致意见的，进行预选，根据预选时得票多少的顺序，确定正式代表候选人名单。正式代表候选人名单以及代表候选人的基本情况应当在选举日的七日以前公布。"},{"i":21,"n":"第二十一条","txt":"军人代表大会在选举全国和县级以上地方各级人民代表大会代表时，代表候选人不限于本级军人代表大会代表。"},{"i":22,"n":"第二十二条","txt":"选举委员会或者军人委员会应当介绍代表候选人的情况。"},{"i":23,"n":"第二十三条","txt":"直接选举时，各选区应当召开军人大会进行选举，或者按照方便选民投票的原则设立投票站进行选举。驻地分散或者行动不便的选民，可以在流动票箱投票。投票选举由军人委员会或者选举委员会主持。"},{"i":24,"n":"第二十四条","txt":"人民解放军选举全国和县级以上地方各级人民代表大会代表，一律采用无记名投票的方法。选举时应当设有秘密写票处。"},{"i":25,"n":"第二十五条","txt":"选民如果在选举期间外出，经军人委员会或者选举委员会同意，可以书面委托其他选民代为投票。每一选民接受的委托不得超过三人，并应当按照委托人的意愿代为投票。"},{"i":26,"n":"第二十六条","txt":"选举人对代表候选人可以投赞成票，可以投反对票，可以另选其他任何选民，也可以弃权。"},{"i":27,"n":"第二十七条","txt":"投票结束后，由选民推选的或者军人代表大会代表推选的监票、计票人员和选举委员会或者军人委员会的人员将投票人数和票数加以核对，作出记录，并由监票人签字。"},{"i":28,"n":"第二十八条","txt":"每次选举所投的票数，多于投票人数的无效，等于或者少于投票人数的有效。"},{"i":29,"n":"第二十九条","txt":"直接选举时，参加投票的选民超过选区全体选民的半数，选举有效。代表候选人获得参加投票的选民过半数的选票时，始得当选。"},{"i":30,"n":"第三十条","txt":"获得过半数选票的代表候选人的人数超过应选代表名额时，以得票多的当选。如遇票数相等不能确定当选人时，应就票数相等的候选人再次投票，以得票多的当选。"},{"i":31,"n":"第三十一条","txt":"选举结果由选举委员会或者军人委员会根据本办法确定是否有效，并予以宣布。"},{"i":32,"n":"第三十二条","txt":"人民解放军选出的全国和县级以上地方各级人民代表大会代表，受选民和原选举单位的监督。选民或者选举单位都有权罢免自己选出的代表。"},{"i":33,"n":"第三十三条","txt":"对于县级人民代表大会代表，原选区选民十人以上联名，可以向旅、团级选举委员会书面提出罢免要求。"},{"i":34,"n":"第三十四条","txt":"军人代表大会举行会议时，团级以上单位的选举委员会可以提出对由该级军人代表大会选出的人民代表大会代表的罢免案。罢免案应当写明罢免理由。"},{"i":35,"n":"第三十五条","txt":"罢免代表采用无记名投票的表决方式。"},{"i":36,"n":"第三十六条","txt":"罢免县级人民代表大会代表，须经原选区过半数的选民通过。"},{"i":37,"n":"第三十七条","txt":"人民解放军选出的设区的市、自治州、省、自治区、直辖市和全国人民代表大会代表，可以向原选举单位的选举委员会书面提出辞职。人民解放军选出的县级人民代表大会代表，可以向原选区的选举委员会或者军人委员会书面提出辞职。接受辞职，须经军人代表大会或者军人大会全体人员的过半数通过，并报送各该级人民代表大会常务委员会和军队上一级选举委员会备案。"},{"i":38,"n":"第三十八条","txt":"代表在任期内因故出缺，由原选区或者原选举单位补选。"},{"i":39,"n":"第三十九条","txt":"人民解放军的选举经费，由军费开支。"},{"i":40,"n":"第四十条","txt":"人民武装警察部队选举全国人民代表大会和县级以上地方各级人民代表大会代表，适用本办法。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyuxid6dd45":[],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyuza5899a4":[],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyupi51ae06":[],"fanfenlieguojiafa":[{"i":1,"n":"第一条","txt":"为了反对和遏制“台独”分裂势力分裂国家，促进祖国和平统一，维护台湾海峡地区和平稳定，维护国家主权和领土完整，维护中华民族的根本利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"世界上只有一个中国，大陆和台湾同属一个中国，中国的主权和领土完整不容分割。维护国家主权和领土完整是包括台湾同胞在内的全中国人民的共同义务。"},{"i":3,"n":"第三条","txt":"台湾问题是中国内战的遗留问题。"},{"i":4,"n":"第四条","txt":"完成统一祖国的大业是包括台湾同胞在内的全中国人民的神圣职责。"},{"i":5,"n":"第五条","txt":"坚持一个中国原则，是实现祖国和平统一的基础。"},{"i":6,"n":"第六条","txt":"国家采取下列措施，维护台湾海峡地区和平稳定，发展两岸关系："},{"i":7,"n":"第七条","txt":"国家主张通过台湾海峡两岸平等的协商和谈判，实现和平统一。协商和谈判可以有步骤、分阶段进行，方式可以灵活多样。"},{"i":8,"n":"第八条","txt":"“台独”分裂势力以任何名义、任何方式造成台湾从中国分裂出去的事实，或者发生将会导致台湾从中国分裂出去的重大事变，或者和平统一的可能性完全丧失，国家得采取非和平方式及其他必要措施，捍卫国家主权和领土完整。"},{"i":9,"n":"第九条","txt":"依照本法规定采取非和平方式及其他必要措施并组织实施时，国家尽最大可能保护台湾平民和在台湾的外国人的生命财产安全和其他正当权益，减少损失；同时，国家依法保护台湾同胞在中国其他地区的权利和利益。"},{"i":10,"n":"第十条","txt":"本法自公布之日起施行。"}]};
